window.LMS_DATA = {"meta":{"generated_from":"AI Roles Skills Taxonomy, Oct 20 2026, Nugen IT Services","built_at":"2026-10-20 14:21 UTC","build_id":"2026-10-20_1421_UTC","topic_count":584,"ok_count":403},"tiers":{"1":{"title":"Tier 1 — Shared core (AI Engineer base)","blurb":"Everything in this tier is assumed by Tiers 2 and 3. It is the AI Engineer baseline."},"2":{"title":"Tier 2 — AI Architect (adds)","blurb":"The Architect owns the decisions and boundaries; Tier 1 is implemented by engineers under them."},"3":{"title":"Tier 3 — Forward Deployed Engineer (adds)","blurb":"The FDE takes Tier 1 into a specific customer's systems, data, security posture and people."}},"role_paths":{"all":{"title":"Everything","desc":"All three tiers, no trimming.","rules":{}},"llm-app":{"title":"LLM-app AI Engineer","desc":"Tier 1 minus ML-fundamentals depth; distributed training and feature stores dropped.","rules":{"tier2":"skip","tier3":"skip","ml-fundamentals":"background","caveat":"skip"}},"ml-heavy":{"title":"ML-heavy AI Engineer","desc":"Tier 1 in full.","rules":{"tier2":"skip","tier3":"skip"}},"architect":{"title":"AI Architect","desc":"Tier 1 breadth + Tier 2.","rules":{"tier3":"skip"}},"fde":{"title":"Forward Deployed Engineer","desc":"Tier 1 + Tier 3, with Tier 2 Reliability and Security as background reading.","rules":{"tier2":"skip","reliability":"background","security-governance-compliance":"background"}}},"modules":[{"id":"ml-fundamentals","tier":1,"order":0,"title":"ML fundamentals","intro":null,"topics":[{"id":"supervised-vs-unsupervised-vs-self-supervised-learning","key":"ml-fundamentals/supervised-vs-unsupervised-vs-self-supervised-learning","module":"ml-fundamentals","name":"Supervised vs unsupervised vs self-supervised learning","taxonomy_name":"supervised vs unsupervised vs self-supervised learning","kind":"concept","difficulty":"intro","est_minutes":12,"related":["ml-fundamentals/classification","ml-fundamentals/regression","ml-fundamentals/clustering","ml-fundamentals/loss-functions","training-adaptation/pre-training","training-adaptation/supervised-fine-tuning","training-adaptation/data-labeling","rag-retrieval/embedding-models"],"tldr":"The three paradigms differ in exactly one thing: where the training signal comes from. Supervised\nlearning pays humans for (input, label) pairs. Unsupervised learning has inputs only and optimises a\nproperty of the data itself, such as how tightly points group. Self-supervised learning manufactures\nlabels from the input (predict the hidden next token, the masked word, the matching caption), so the\nsignal is free and unlimited. Modern LLMs exist because self-supervision turned the whole internet into\ntraining labels, with human supervision added only at the end.","review":"fact-checked","status":"ok"},{"id":"classification","key":"ml-fundamentals/classification","module":"ml-fundamentals","name":"Classification","taxonomy_name":"classification","kind":"concept","difficulty":"intro","est_minutes":13,"related":["ml-fundamentals/regression","ml-fundamentals/loss-functions","ml-fundamentals/confusion-matrix","ml-fundamentals/precision-recall-f1","ml-fundamentals/roc-auc","ml-fundamentals/calibration","ml-fundamentals/class-imbalance","model-internals/softmax"],"tldr":"Classification predicts which of a fixed set of categories an input belongs to. A classifier produces a\nscore per class (logits), converts scores to probabilities (sigmoid or softmax), and a separate decision\nrule, a threshold or argmax, turns probabilities into a label. Keeping scoring and deciding apart matters\nbecause the threshold encodes the business cost of each kind of mistake. Every token an LLM emits is a\nclassification over its vocabulary, so this is the most common problem shape in AI engineering.","review":"fact-checked","status":"ok"},{"id":"regression","key":"ml-fundamentals/regression","module":"ml-fundamentals","name":"Regression","taxonomy_name":"regression","kind":"concept","difficulty":"intro","est_minutes":12,"related":["ml-fundamentals/classification","ml-fundamentals/loss-functions","ml-fundamentals/gradient-descent","ml-fundamentals/train-test-leakage","training-adaptation/overfitting","python-for-ai/scikit-learn-basics","infra-capacity-economics/quality-latency-cost-optimization"],"tldr":"Regression predicts a continuous quantity: latency in milliseconds, cost in dollars, a quality score.\nThe model outputs a number and the loss measures its distance from the truth; choosing squared versus\nabsolute error is choosing whether you estimate the conditional mean or the median, and how much a few\nextreme points steer the fit. In AI systems regression appears as reward models, latency and cost\npredictors, judge scores and value heads, and it fails in the same ways least squares always has:\nextrapolation, leverage points and leakage.","review":"fact-checked","status":"ok"},{"id":"clustering","key":"ml-fundamentals/clustering","module":"ml-fundamentals","name":"Clustering","taxonomy_name":"clustering","kind":"concept","difficulty":"core","est_minutes":13,"related":["ml-fundamentals/supervised-vs-unsupervised-vs-self-supervised-learning","ml-fundamentals/classification","model-internals/embeddings","rag-retrieval/embedding-models","rag-retrieval/embedding-dimension-and-normalization","rag-retrieval/similarity-search","training-adaptation/data-curation","customer-data-evaluation/representative-test-case-sampling"],"tldr":"Clustering groups items by similarity without labels. It answers \"what kinds of things are in this\ndata?\" when nobody has defined the kinds yet. In AI engineering it mostly runs on embeddings: discovering\nintents in chat logs, deduplicating training data, choosing diverse evaluation samples, finding failure\nmodes. The algorithm matters less than two choices made before it runs, the distance metric and the\nquestion you want answered; k-means, hierarchical and density-based methods differ mainly in what cluster\nshapes they assume.","review":"fact-checked","status":"ok"},{"id":"loss-functions","key":"ml-fundamentals/loss-functions","module":"ml-fundamentals","name":"Loss functions (cross-entropy, contrastive)","taxonomy_name":"loss functions (cross-entropy, contrastive)","kind":"concept","difficulty":"core","est_minutes":16,"related":["ml-fundamentals/classification","ml-fundamentals/regression","ml-fundamentals/gradient-descent","ml-fundamentals/backpropagation","model-internals/softmax","model-internals/perplexity","rag-retrieval/embedding-models","multimodal/clip"],"tldr":"A loss function is the differentiable stand-in for what you actually want; its gradient is the only\nsignal the model ever receives. Cross-entropy, −log p(correct answer), is the loss for anything that\npredicts a probability distribution, including every token an LLM emits, because it is maximum\nlikelihood and its gradient through softmax is simply prediction minus target. Contrastive losses teach\nembeddings by asking \"which candidate is the match\", and the modern form, InfoNCE, is cross-entropy over\nsimilarity scores.","review":"fact-checked","status":"ok"},{"id":"gradient-descent","key":"ml-fundamentals/gradient-descent","module":"ml-fundamentals","name":"Gradient descent","taxonomy_name":"gradient descent","kind":"concept","difficulty":"core","est_minutes":14,"related":["ml-fundamentals/loss-functions","ml-fundamentals/backpropagation","ml-fundamentals/optimizers","ml-fundamentals/learning-rate-schedulers","ml-fundamentals/batch-size","ml-fundamentals/warmup","training-adaptation/learning-rate","training-adaptation/overfitting"],"tldr":"Gradient descent minimises a loss by repeatedly moving the parameters a small step against the\ngradient: θ ← θ − η∇L(θ). It is the only practical way to fit models with millions to billions of\nparameters, because the gradient costs about as much as a forward pass regardless of parameter count.\nStochastic (mini-batch) gradient descent uses a noisy estimate from a few examples, trading precision per\nstep for many more steps per second, and that noise turns out to help rather than hurt.","review":"fact-checked","status":"ok"},{"id":"backpropagation","key":"ml-fundamentals/backpropagation","module":"ml-fundamentals","name":"Backpropagation","taxonomy_name":"backpropagation","kind":"concept","difficulty":"core","est_minutes":15,"related":["ml-fundamentals/gradient-descent","ml-fundamentals/loss-functions","ml-fundamentals/optimizers","ml-fundamentals/gradient-clipping","ml-fundamentals/residual-connections","ml-fundamentals/normalization","training-adaptation/gradient-checkpointing","python-for-ai/pytorch"],"tldr":"Backpropagation computes the gradient of a scalar loss with respect to every parameter in one backward\nsweep, by applying the chain rule from the loss back through the recorded computation graph. It costs a\nsmall constant multiple of the forward pass no matter how many parameters there are, which is the only\nreason training billion-parameter models is possible. The price is memory: the backward pass needs the\nforward activations, so training memory scales with batch × sequence length × depth, not just with\nparameter count.","review":"fact-checked","status":"ok"},{"id":"optimizers","key":"ml-fundamentals/optimizers","module":"ml-fundamentals","name":"Optimizers (Adam, AdamW)","taxonomy_name":"optimizers (Adam, AdamW)","kind":"concept","difficulty":"core","est_minutes":15,"related":["ml-fundamentals/gradient-descent","ml-fundamentals/backpropagation","ml-fundamentals/learning-rate-schedulers","ml-fundamentals/warmup","ml-fundamentals/gradient-clipping","ml-fundamentals/mixed-precision","training-adaptation/learning-rate","training-adaptation/peft"],"tldr":"An optimizer turns gradients into parameter updates. Plain SGD applies one learning rate to every\nparameter, which fails when gradient scales differ by orders of magnitude across a network. Adam keeps a\nrunning mean (momentum) and a running mean square of each parameter's gradient and divides one by the\nroot of the other, so every parameter moves by roughly the learning rate whatever its gradient scale.\nAdamW applies weight decay directly to the weights instead of through the gradient, and is the default\nfor transformers.","review":"fact-checked","status":"ok"},{"id":"learning-rate-schedulers","key":"ml-fundamentals/learning-rate-schedulers","module":"ml-fundamentals","name":"Learning-rate schedulers","taxonomy_name":"learning-rate schedulers","kind":"concept","difficulty":"core","est_minutes":14,"related":["ml-fundamentals/warmup","ml-fundamentals/optimizers","ml-fundamentals/gradient-descent","ml-fundamentals/batch-size","ml-fundamentals/gradient-accumulation","training-adaptation/learning-rate","training-adaptation/checkpointing"],"tldr":"A fixed learning rate is a compromise: large enough to make progress early, it is too noisy to settle\ninto a good minimum late. A scheduler changes the learning rate over the run, ramping up briefly, holding\nor slowly decaying, then annealing down, so the optimizer takes big steps while the loss surface is\nforgiving and small ones when it is not. The schedule is defined over total optimizer steps, so it must be\nplanned together with batch size and training length.","review":"fact-checked","status":"ok"},{"id":"warmup","key":"ml-fundamentals/warmup","module":"ml-fundamentals","name":"Warmup","taxonomy_name":"warmup","kind":"practice","difficulty":"core","est_minutes":11,"related":["ml-fundamentals/learning-rate-schedulers","ml-fundamentals/optimizers","ml-fundamentals/gradient-clipping","ml-fundamentals/normalization","ml-fundamentals/batch-size","training-adaptation/learning-rate"],"tldr":"Warmup ramps the learning rate from near zero to its peak over the first few hundred or thousand\noptimizer steps. It exists because the first steps are the most dangerous: weights are random, gradients\nare large and poorly conditioned, and Adam's running variance estimates are built from almost no data,\nso a full-size step can throw the model into a region it never recovers from. A short ramp costs almost\nnothing and removes most early-training divergence.","review":"fact-checked","status":"ok"},{"id":"gradient-clipping","key":"ml-fundamentals/gradient-clipping","module":"ml-fundamentals","name":"Gradient clipping","taxonomy_name":"gradient clipping","kind":"practice","difficulty":"core","est_minutes":11,"related":["ml-fundamentals/backpropagation","ml-fundamentals/optimizers","ml-fundamentals/warmup","ml-fundamentals/mixed-precision","ml-fundamentals/gradient-accumulation","ml-fundamentals/learning-rate-schedulers","training-adaptation/distributed-training"],"tldr":"Gradient clipping caps the size of the update computed from one batch: if the global L2 norm of all\ngradients exceeds a threshold, every gradient is scaled down by the same factor so the norm equals the\nthreshold. The direction is preserved; only the step length is bounded. It exists because a single rare\nbatch can produce a gradient tens of times larger than usual, and one such step can undo thousands of\ngood ones or corrupt the optimizer's running statistics for the rest of the run.","review":"fact-checked","status":"ok"},{"id":"batch-size","key":"ml-fundamentals/batch-size","module":"ml-fundamentals","name":"Batch size","taxonomy_name":"batch size","kind":"concept","difficulty":"core","est_minutes":15,"related":["ml-fundamentals/gradient-descent","ml-fundamentals/gradient-accumulation","ml-fundamentals/learning-rate-schedulers","ml-fundamentals/warmup","ml-fundamentals/mixed-precision","training-adaptation/gradient-checkpointing","training-adaptation/distributed-training","infra-capacity-economics/gpu-utilization-and-memory-bandwidth"],"tldr":"Batch size is how many examples (for LLMs, how many tokens) contribute to one gradient estimate. A\nlarger batch gives a less noisy gradient and better hardware utilization, so each step is worth more and\ncosts less per example, but only up to a point: past the *critical batch size* set by gradient noise,\nextra examples per step stop reducing the number of steps needed and simply burn data. Batch size,\nlearning rate and step count are therefore one coupled decision, not three.","review":"fact-checked","status":"ok"},{"id":"gradient-accumulation","key":"ml-fundamentals/gradient-accumulation","module":"ml-fundamentals","name":"Gradient accumulation","taxonomy_name":"gradient accumulation","kind":"practice","difficulty":"core","est_minutes":11,"related":["ml-fundamentals/batch-size","ml-fundamentals/gradient-clipping","ml-fundamentals/learning-rate-schedulers","ml-fundamentals/warmup","ml-fundamentals/mixed-precision","ml-fundamentals/optimizers","training-adaptation/gradient-checkpointing","training-adaptation/distributed-training"],"tldr":"Gradient accumulation runs several small micro-batches and lets their gradients add up before one\noptimizer step. Because the gradient of a mean loss is linear in the examples, the sum equals the\ngradient of the larger batch, so the optimizer sees the batch the recipe asked for while GPU memory only\never holds one micro-batch of activations. It costs no memory and changes nothing in the optimization,\nbut it buys no speed: every micro-batch still runs.","review":"fact-checked","status":"ok"},{"id":"mixed-precision","key":"ml-fundamentals/mixed-precision","module":"ml-fundamentals","name":"Mixed precision","taxonomy_name":"mixed precision","kind":"practice","difficulty":"core","est_minutes":15,"related":["ml-fundamentals/gradient-clipping","ml-fundamentals/gradient-accumulation","ml-fundamentals/normalization","ml-fundamentals/optimizers","ml-fundamentals/batch-size","training-adaptation/quantization","serving-inference/gpu-memory-optimization","infra-capacity-economics/gpu-utilization-and-memory-bandwidth"],"tldr":"Mixed precision runs the expensive parts of training (the matrix multiplications) in a 16-bit float while\nkeeping an fp32 copy of the weights for the update. Tensor cores are many times faster at 16 bits,\nactivations take half the memory and bandwidth, and the fp32 master copy stops tiny updates from being\nrounded away. fp16 has range problems that need loss scaling; bf16 has fp32's range and skips that\nmachinery at a precision cost, so it is the default where hardware allows.","review":"fact-checked","status":"ok"},{"id":"normalization","key":"ml-fundamentals/normalization","module":"ml-fundamentals","name":"Normalization (LayerNorm, RMSNorm)","taxonomy_name":"normalization (LayerNorm, RMSNorm)","kind":"concept","difficulty":"core","est_minutes":14,"related":["ml-fundamentals/residual-connections","ml-fundamentals/warmup","ml-fundamentals/mixed-precision","ml-fundamentals/backpropagation","ml-fundamentals/batch-size","model-internals/transformer","model-internals/self-attention"],"tldr":"Normalization layers rescale each token's activation vector to a fixed scale before it enters a sublayer,\nso what attention and the MLP see does not depend on what every earlier layer happened to do. LayerNorm\nsubtracts the mean and divides by the standard deviation over the feature dimension; RMSNorm skips the\nmean and divides by the root mean square, which is cheaper and works as well. Where the norm sits\nrelative to the residual (Pre-LN versus Post-LN) decides how stable training is.","review":"fact-checked","status":"ok"},{"id":"residual-connections","key":"ml-fundamentals/residual-connections","module":"ml-fundamentals","name":"Residual connections","taxonomy_name":"residual connections","kind":"concept","difficulty":"core","est_minutes":12,"related":["ml-fundamentals/normalization","ml-fundamentals/backpropagation","ml-fundamentals/gradient-clipping","ml-fundamentals/warmup","model-internals/transformer","model-internals/self-attention","training-adaptation/peft"],"tldr":"A residual connection adds a layer's input to its output, `y = x + F(x)`, so each layer learns a\ncorrection to the signal rather than a replacement for it. It exists because plain deep stacks get harder\nto optimize as depth grows: the identity path gives gradients a route that products of layer Jacobians\ncannot shrink, and makes \"do nothing\" the starting point for every layer. In a transformer this shared\npath is the residual stream that every attention head and MLP reads and writes.","review":"fact-checked","status":"ok"},{"id":"dropout-regularization","key":"ml-fundamentals/dropout-regularization","module":"ml-fundamentals","name":"Dropout / regularization","taxonomy_name":"dropout / regularization","kind":"concept","difficulty":"core","est_minutes":14,"related":["ml-fundamentals/optimizers","ml-fundamentals/normalization","ml-fundamentals/residual-connections","ml-fundamentals/loss-functions","training-adaptation/overfitting","training-adaptation/peft","training-adaptation/train-val-test-split"],"tldr":"Regularization deliberately makes a model fit its training data *worse* so it generalizes *better*:\na penalty on weight size, noise injected during training, or stopping early. Dropout is the noise\nversion: during training each activation is zeroed with probability *p* and the survivors are scaled\nby 1/(1−p), so no unit can rely on another being present; at inference nothing is dropped. Whether\nyou want it depends on the data regime: small fine-tuning sets, yes; single-epoch pretraining on\ntrillions of tokens, usually no.","review":"fact-checked","status":"ok"},{"id":"train-test-leakage","key":"ml-fundamentals/train-test-leakage","module":"ml-fundamentals","name":"Train/test leakage","taxonomy_name":"train/test leakage","kind":"concept","difficulty":"core","est_minutes":13,"related":["training-adaptation/train-val-test-split","training-adaptation/overfitting","evals/dataset-contamination","evals/golden-dataset","data-architecture/feature-stores","data-architecture/data-lineage","customer-data-evaluation/golden-dataset-creation-with-client-smes"],"tldr":"Leakage is any path by which information that will not be available at prediction time, or that\nbelongs to the evaluation set, reaches the model or the metric. It makes offline numbers lie in the\noptimistic direction, which is the worst direction: you ship something that collapses in production.\nIt rarely looks like a bug. It looks like a feature that is \"surprisingly predictive\", a scaler fitted\nbefore the split, a random split of time-ordered data, or a golden set the prompt was tuned against.","review":"fact-checked","status":"ok"},{"id":"class-imbalance","key":"ml-fundamentals/class-imbalance","module":"ml-fundamentals","name":"Class imbalance","taxonomy_name":"class imbalance","kind":"concept","difficulty":"core","est_minutes":15,"related":["ml-fundamentals/confusion-matrix","ml-fundamentals/precision-recall-f1","ml-fundamentals/roc-auc","ml-fundamentals/calibration","ml-fundamentals/loss-functions","ml-fundamentals/train-test-leakage","training-adaptation/synthetic-data-generation","customer-data-evaluation/production-feedback-classification"],"tldr":"When one class is rare, the default recipe of accuracy as the metric, an unweighted loss and a 0.5\nthreshold quietly optimises for \"say the common class\". Imbalance is less a data problem than a cost\nproblem that the defaults get wrong. Fix the evaluation first (confusion matrix, precision–recall,\nstratified splits), then the decision threshold, and only then reach for class weights, resampling or\nfocal loss, remembering that each of those distorts the probabilities you may need later.","review":"fact-checked","status":"ok"},{"id":"calibration","key":"ml-fundamentals/calibration","module":"ml-fundamentals","name":"Calibration","taxonomy_name":"calibration","kind":"concept","difficulty":"core","est_minutes":15,"related":["ml-fundamentals/roc-auc","ml-fundamentals/class-imbalance","ml-fundamentals/loss-functions","ml-fundamentals/confusion-matrix","model-internals/sampling-strategies","evals/judge-calibration-and-bias","system-design/model-routing-cascading","agents/human-in-the-loop"],"tldr":"A model is calibrated when its stated confidence matches its hit rate: of everything it calls \"90%\",\nabout 90% should be right. Ranking metrics like AUC do not need this; decisions do: cost-based\nthresholds, abstaining, escalating to a human or a bigger model, combining scores. Modern neural\nnetworks are usually overconfident, so you measure calibration on held-out data (reliability diagram,\nECE, Brier score) and fix it after training, most often with temperature scaling.","review":"fact-checked","status":"ok"},{"id":"precision-recall-f1","key":"ml-fundamentals/precision-recall-f1","module":"ml-fundamentals","name":"Precision / recall / F1","taxonomy_name":"precision / recall / F1","kind":"metric","difficulty":"intro","est_minutes":14,"related":["ml-fundamentals/confusion-matrix","ml-fundamentals/roc-auc","ml-fundamentals/class-imbalance","ml-fundamentals/calibration","rag-retrieval/recall-vs-precision-trade-off","evals/retrieval-evaluation","evals/hallucination-evaluation","safety-security/input-output-guardrails"],"tldr":"Precision asks \"of what I flagged, how much was right\"; recall asks \"of what was there, how much did I\nfind\". They pull against each other through the decision threshold, so a scorer is a curve of\n(precision, recall) pairs, not a point. F1 is the harmonic mean at one chosen point: a single number\nthat is only meaningful once you have decided the two error types cost about the same, which in\nproduction they rarely do.","review":"fact-checked","status":"ok"},{"id":"roc-auc","key":"ml-fundamentals/roc-auc","module":"ml-fundamentals","name":"ROC-AUC","taxonomy_name":"ROC-AUC","kind":"metric","difficulty":"core","est_minutes":14,"related":["ml-fundamentals/confusion-matrix","ml-fundamentals/precision-recall-f1","ml-fundamentals/class-imbalance","ml-fundamentals/calibration","evals/model-evaluation","evals/llm-as-a-judge","rag-retrieval/reranking","system-design/model-routing-cascading"],"tldr":"ROC-AUC measures how well a scorer *ranks* positives above negatives across every threshold at once:\nit equals the probability that a randomly chosen positive outscores a randomly chosen negative. It is\nthreshold-free and unaffected by class prevalence, which makes it the right number for comparing\nscorers and the wrong number for judging a deployed classifier on rare positives, where it hides the\nfalse-alarm volume and says nothing about whether the scores are calibrated probabilities.","review":"fact-checked","status":"ok"},{"id":"confusion-matrix","key":"ml-fundamentals/confusion-matrix","module":"ml-fundamentals","name":"Confusion matrix","taxonomy_name":"confusion matrix","kind":"concept","difficulty":"intro","est_minutes":12,"related":["ml-fundamentals/classification","ml-fundamentals/precision-recall-f1","ml-fundamentals/roc-auc","ml-fundamentals/class-imbalance","ml-fundamentals/calibration","evals/error-analysis","evals/llm-as-a-judge","safety-security/content-moderation"],"tldr":"A confusion matrix is the raw count of what the classifier said against what was true, one cell per\n(actual, predicted) pair. Every single-number classification metric is a ratio of its cells, so any one\nnumber throws away what the table shows: which class is mistaken for which, and in which direction.\nRead the table first and choose the metric second, because the right metric depends on which cell's\nerrors are expensive, and that is a product decision.","review":"fact-checked","status":"ok"}]},{"id":"model-internals","tier":1,"order":1,"title":"Model internals","intro":null,"topics":[{"id":"transformer","key":"model-internals/transformer","module":"model-internals","name":"Transformer","taxonomy_name":"transformer","kind":"concept","difficulty":"core","est_minutes":16,"related":["model-internals/attention-mechanism","model-internals/self-attention","model-internals/multi-head-attention","model-internals/positional-encoding","model-internals/llm-architecture","model-internals/embeddings","ml-fundamentals/residual-connections","ml-fundamentals/normalization"],"tldr":"A transformer is a stack of identical blocks. Each block first lets every position pull information from\nother positions through attention, then transforms each position on its own with a feed-forward network,\nwith residual connections and normalization holding the stack together. It replaced recurrence because\nall positions of a sequence are processed in parallel as one matrix multiplication and any two positions\nare a single attention step apart, which made training on web-scale text affordable. Nearly every\ncurrent LLM is a decoder-only variant of this design.","review":"fact-checked","status":"ok"},{"id":"attention-mechanism","key":"model-internals/attention-mechanism","module":"model-internals","name":"Attention mechanism","taxonomy_name":"attention mechanism","kind":"concept","difficulty":"intro","est_minutes":12,"related":["model-internals/self-attention","model-internals/multi-head-attention","model-internals/transformer","model-internals/softmax","model-internals/embeddings","rag-retrieval/similarity-search"],"tldr":"Attention is a differentiable lookup. A query is compared against a set of keys, the similarity scores\nare turned into weights that sum to one with a softmax, and the output is the weighted sum of the\nmatching values. It exists because squeezing a variable-length input into one fixed-size vector throws\ninformation away; attention lets each step of a computation reach back and pull exactly the parts of\nthe input it needs, with the notion of \"matching\" learned end to end.","review":"fact-checked","status":"ok"},{"id":"self-attention","key":"model-internals/self-attention","module":"model-internals","name":"Self-attention","taxonomy_name":"self-attention","kind":"concept","difficulty":"core","est_minutes":14,"related":["model-internals/attention-mechanism","model-internals/multi-head-attention","model-internals/kv-cache","model-internals/positional-encoding","model-internals/flashattention","model-internals/context-window","serving-inference/prefill-vs-decode"],"tldr":"Self-attention is attention in which queries, keys and values all come from the same sequence: every\ntoken asks every other token it is allowed to see for information and builds its new representation\nfrom the answers. It is the only operation in a transformer that moves information between positions,\nit runs as one matrix multiplication over all positions at once, and it costs O(n²) in sequence length,\nwhich is where context limits, the KV cache and FlashAttention all come from.","review":"fact-checked","status":"ok"},{"id":"multi-head-attention","key":"model-internals/multi-head-attention","module":"model-internals","name":"Multi-head attention","taxonomy_name":"multi-head attention","kind":"concept","difficulty":"core","est_minutes":12,"related":["model-internals/self-attention","model-internals/attention-mechanism","model-internals/grouped-query-attention","model-internals/flashattention","model-internals/kv-cache","model-internals/transformer","serving-inference/tensor-parallelism-at-inference"],"tldr":"Multi-head attention runs several attention operations in parallel, each in its own lower-dimensional\nprojection of the input, and concatenates the results. One softmax can express only one weighting over\nthe sequence per position; with *h* heads a position can look in *h* places for *h* different reasons at\nonce. Because the model width is split across heads (d_k = d_model / h), the parameter count and FLOPs\nmatch a single wide head, while the attention-probability memory and the natural unit for sharding both\nscale with *h*.","review":"fact-checked","status":"ok"},{"id":"grouped-query-attention","key":"model-internals/grouped-query-attention","module":"model-internals","name":"Grouped-query attention (GQA)","taxonomy_name":"grouped-query attention (GQA)","kind":"concept","difficulty":"core","est_minutes":12,"related":["model-internals/multi-head-attention","model-internals/kv-cache","model-internals/llm-architecture","serving-inference/kv-cache-memory-estimation","serving-inference/tensor-parallelism-at-inference","serving-inference/tpot","infra-capacity-economics/gpu-utilization-and-memory-bandwidth"],"tldr":"Grouped-query attention lets several query heads share one key/value head, a middle point between full\nmulti-head attention (one KV head per query head) and multi-query attention (one for all). It exists\nbecause decoding is bound by reading the KV cache from GPU memory, and that cache scales with the number\nof KV heads: going from 32 to 8 shrinks it fourfold at a quality cost small enough that Llama 2 70B,\nLlama 3 and Mistral all adopted it.","review":"fact-checked","status":"ok"},{"id":"flashattention","key":"model-internals/flashattention","module":"model-internals","name":"FlashAttention","taxonomy_name":"FlashAttention","kind":"concept","difficulty":"advanced","est_minutes":15,"related":["model-internals/self-attention","model-internals/multi-head-attention","model-internals/context-window","serving-inference/pagedattention","serving-inference/gpu-memory-optimization","infra-capacity-economics/gpu-utilization-and-memory-bandwidth","ml-fundamentals/mixed-precision","python-for-ai/pytorch"],"tldr":"FlashAttention computes exactly the same softmax attention as the textbook formula but never writes the\nn×n score matrix to GPU memory. It streams blocks of keys and values through the fast on-chip SRAM,\nkeeps a running softmax per query row, and stores only O(n) extra state. Attention was slow not because\nof its FLOPs but because of reading and writing that n² matrix in high-bandwidth memory, so an IO-aware\nkernel gives large wall-clock speedups and makes long contexts fit in memory at all.","review":"fact-checked","status":"ok"},{"id":"positional-encoding","key":"model-internals/positional-encoding","module":"model-internals","name":"Positional encoding (RoPE)","taxonomy_name":"positional encoding (RoPE)","kind":"concept","difficulty":"core","est_minutes":15,"related":["model-internals/self-attention","model-internals/context-window","model-internals/kv-cache","model-internals/transformer","rag-retrieval/long-context-vs-rag","rag-retrieval/lost-in-the-middle","prompting/context-engineering"],"tldr":"Self-attention treats its input as a set, so a transformer needs an explicit signal for token order.\nEarly models added a sinusoid or learned vector per absolute position to the embeddings. RoPE instead\nrotates each query and key by an angle proportional to its position, so their dot product depends only\non their distance apart. That relative property, zero parameters and clean interaction with the KV cache\nmade RoPE the default in open LLMs, and context extension is mostly about stretching those angles.","review":"fact-checked","status":"ok"},{"id":"tokenization","key":"model-internals/tokenization","module":"model-internals","name":"Tokenization (BPE, SentencePiece)","taxonomy_name":"tokenization (BPE, SentencePiece)","kind":"concept","difficulty":"core","est_minutes":14,"related":["model-internals/embeddings","model-internals/context-window","model-internals/logits","python-for-ai/tiktoken","observability/token-cost-tracking","prompting/structured-outputs-json-mode","rag-retrieval/chunking-strategies"],"tldr":"A tokenizer turns text into the integer ids a model consumes. Byte-pair encoding, the dominant method,\nbuilds a vocabulary of frequent subword chunks by repeatedly merging the most common adjacent pair, so\ncommon words become one token and rare words split into pieces without ever being out of vocabulary.\nSentencePiece is a toolkit that trains BPE or unigram models on raw text with whitespace as an ordinary\nsymbol, making it language-independent. Tokens are the unit of cost, context and many odd model\nbehaviours.","review":"fact-checked","status":"ok"},{"id":"embeddings","key":"model-internals/embeddings","module":"model-internals","name":"Embeddings","taxonomy_name":"embeddings","kind":"concept","difficulty":"core","est_minutes":14,"related":["model-internals/tokenization","model-internals/transformer","model-internals/positional-encoding","model-internals/logits","rag-retrieval/embedding-models","rag-retrieval/similarity-search","rag-retrieval/embedding-dimension-and-normalization","ml-fundamentals/loss-functions"],"tldr":"An embedding is a learned dense vector that stands in for a discrete thing (a token, a sentence) so a\nnetwork can do arithmetic on it. Inside an LLM, the embedding table turns token ids into the vectors\nthe transformer consumes, and its transpose turns hidden states back into logits. Outside the LLM, an\nembedding *model* compresses whole passages into vectors whose distance tracks meaning, which is what\nmakes semantic search possible. Same word, two different training objectives.","review":"fact-checked","status":"ok"},{"id":"llm-architecture","key":"model-internals/llm-architecture","module":"model-internals","name":"LLM architecture (encoder–decoder vs decoder-only)","taxonomy_name":"LLM architecture (encoder–decoder vs decoder-only)","kind":"concept","difficulty":"core","est_minutes":15,"related":["model-internals/transformer","model-internals/attention-mechanism","model-internals/self-attention","model-internals/kv-cache","model-internals/context-window","training-adaptation/pre-training","rag-retrieval/reranking","multimodal/speech-to-text"],"tldr":"The original transformer had two stacks: an encoder that reads the input bidirectionally and a decoder\nthat writes the output token by token while cross-attending to the encoder. Modern chat LLMs keep only\nthe decoder and treat prompt and answer as one causal stream, because one stack with one next-token\nobjective scales on raw text, handles multi-turn chat by appending, and reuses its KV cache.\nEncoder–decoder still wins for fixed, read-heavy inputs with short outputs, such as translation and\nspeech recognition.","review":"fact-checked","status":"ok"},{"id":"context-window","key":"model-internals/context-window","module":"model-internals","name":"Context window","taxonomy_name":"context window","kind":"concept","difficulty":"intro","est_minutes":13,"related":["model-internals/kv-cache","model-internals/positional-encoding","model-internals/tokenization","model-internals/self-attention","prompting/prompt-caching","prompting/context-engineering","rag-retrieval/long-context-vs-rag","rag-retrieval/lost-in-the-middle"],"tldr":"The context window is the maximum number of tokens a model can attend over in one request: system\nprompt, conversation history, retrieved documents, tool results and the answer all share it. It is\nfinite because attention cost grows with length, the KV cache grows with length, and positional\nencodings are only trained up to some length. The model has no memory beyond it, so everything the\nmodel \"knows\" about this conversation has to fit, and managing that budget is a core engineering job.","review":"fact-checked","status":"ok"},{"id":"kv-cache","key":"model-internals/kv-cache","module":"model-internals","name":"KV cache","taxonomy_name":"KV cache","kind":"concept","difficulty":"core","est_minutes":14,"related":["model-internals/self-attention","model-internals/grouped-query-attention","model-internals/context-window","serving-inference/kv-cache-memory-estimation","serving-inference/pagedattention","serving-inference/prefix-caching"],"tldr":"A decoder-only transformer generates one token at a time, and every new token must attend to every\nearlier token. The KV cache stores the key and value vectors already computed for earlier positions so\neach step only computes attention for the new token instead of recomputing the whole prefix. It turns\ngenerating *n* tokens from O(n²) token-forward-passes into O(n), at the cost of GPU memory that grows with\nsequence length, which is why memory, not compute, usually limits how many requests a server can run.","review":"fact-checked","status":"ok"},{"id":"logits","key":"model-internals/logits","module":"model-internals","name":"Logits","taxonomy_name":"logits","kind":"concept","difficulty":"intro","est_minutes":12,"related":["model-internals/softmax","model-internals/sampling-strategies","model-internals/embeddings","ml-fundamentals/loss-functions","ml-fundamentals/calibration","serving-inference/structured-constrained-generation","prompting/structured-outputs-json-mode"],"tldr":"Logits are the raw, unnormalized scores a language model produces for every vocabulary entry at a\nposition, one real number per token, before softmax turns them into probabilities. They are the model's\nlast honest output: everything you can do to steer generation without retraining (temperature, logit\nbias, banning tokens, grammar-constrained decoding) is an edit to this vector, and everything you can\nmeasure about confidence (logprobs, perplexity) is read from it.","review":"fact-checked","status":"ok"},{"id":"softmax","key":"model-internals/softmax","module":"model-internals","name":"Softmax","taxonomy_name":"softmax","kind":"concept","difficulty":"intro","est_minutes":12,"related":["model-internals/logits","model-internals/attention-mechanism","model-internals/sampling-strategies","model-internals/flashattention","ml-fundamentals/loss-functions","ml-fundamentals/calibration","ml-fundamentals/classification"],"tldr":"Softmax turns a vector of arbitrary real scores into a probability distribution:\n`p_i = exp(z_i / T) / Σ_j exp(z_j / T)`. It is differentiable, order-preserving, invariant to shifting\nall scores, and its sharpness is controlled by the temperature *T*. An LLM uses it twice: inside every\nattention head to weight positions, and at the output to turn logits into next-token probabilities.\nIts properties, including \"never exactly zero\" and \"must sum to one\", explain sampling behaviour,\nattention sinks and several numerical bugs.","review":"fact-checked","status":"ok"},{"id":"sampling-strategies","key":"model-internals/sampling-strategies","module":"model-internals","name":"Sampling strategies (temperature, top-k / top-p, greedy vs beam)","taxonomy_name":"sampling strategies (temperature, top-k / top-p, greedy vs beam)","kind":"concept","difficulty":"core","est_minutes":15,"related":["model-internals/logits","model-internals/softmax","model-internals/hallucination","model-internals/perplexity","agent-reliability/deterministic-replay-and-reproducibility","serving-inference/structured-constrained-generation","prompting/structured-outputs-json-mode","evals/model-evaluation"],"tldr":"A language model emits a probability distribution over the whole vocabulary at each step; a sampling\nstrategy decides which token to take. Greedy always takes the most likely token and tends to loop; beam\nsearch keeps several candidate sequences and maximizes total likelihood, which suits translation but\nproduces bland, repetitive open-ended text. Sampling draws from the distribution after reshaping it with\ntemperature and truncating the tail with top-k or top-p, trading determinism for diversity. The right\nsetting depends on whether the task has one correct answer.","review":"fact-checked","status":"ok"},{"id":"speculative-decoding","key":"model-internals/speculative-decoding","module":"model-internals","name":"Speculative decoding","taxonomy_name":"speculative decoding","kind":"concept","difficulty":"advanced","est_minutes":16,"related":["model-internals/kv-cache","model-internals/sampling-strategies","model-internals/small-language-models","model-internals/logits","serving-inference/prefill-vs-decode","serving-inference/inference-optimization","serving-inference/tpot","infra-capacity-economics/gpu-utilization-and-memory-bandwidth"],"tldr":"Decoding is memory-bandwidth bound: each step reads all the weights to produce one token while the\nGPU's arithmetic units sit mostly idle. Speculative decoding uses that idle compute: a cheap draft model\nguesses several tokens ahead and the large model verifies all of them in one forward pass. A\nrejection-sampling rule keeps the output distribution exactly the large model's, so it is a pure\nlatency optimization whose gain depends on how often the draft is right.","review":"fact-checked","status":"ok"},{"id":"mixture-of-experts","key":"model-internals/mixture-of-experts","module":"model-internals","name":"Mixture of experts (MoE)","taxonomy_name":"mixture of experts (MoE)","kind":"concept","difficulty":"core","est_minutes":16,"related":["model-internals/transformer","model-internals/llm-architecture","model-internals/scaling-laws","model-internals/kv-cache","serving-inference/gpu-memory-optimization","training-adaptation/distributed-training","infra-capacity-economics/gpu-sizing"],"tldr":"A mixture-of-experts transformer replaces the dense feed-forward block in each layer with several\nparallel \"expert\" FFNs plus a small router that sends each token to only one or two of them. The model\ntherefore holds many more parameters than it uses for any given token: quality tracks total parameters\nwhile compute per token tracks active parameters. The price is that every expert must sit in memory,\nrouting must be kept balanced during training, and the serving arithmetic changes with batch size.","review":"fact-checked","status":"ok"},{"id":"small-language-models","key":"model-internals/small-language-models","module":"model-internals","name":"Small language models (SLMs)","taxonomy_name":"small language models (SLMs)","kind":"concept","difficulty":"core","est_minutes":15,"related":["model-internals/scaling-laws","model-internals/hallucination","model-internals/kv-cache","system-design/slm-vs-llm-trade-offs","system-design/model-routing-cascading","training-adaptation/knowledge-distillation","training-adaptation/quantization","infra-capacity-economics/edge-ai-deployment"],"tldr":"\"Small language model\" has no fixed boundary; in practice it means a model of roughly 0.5–10B parameters\nthat runs on one consumer GPU, a CPU or a phone. SLMs matter because most production tasks are narrow,\ncost and latency scale with parameter count, and modern recipes (training on far more tokens than\ncompute-optimal, distillation from large teachers, curated data) make small models far stronger than their\nsize once implied. They trade breadth of knowledge and multi-step reasoning for speed, cost, privacy and\ncheap fine-tuning.","review":"fact-checked","status":"ok"},{"id":"scaling-laws","key":"model-internals/scaling-laws","module":"model-internals","name":"Scaling laws","taxonomy_name":"scaling laws","kind":"concept","difficulty":"core","est_minutes":16,"related":["model-internals/small-language-models","model-internals/mixture-of-experts","model-internals/perplexity","model-internals/reasoning-models-test-time-compute","training-adaptation/pre-training","training-adaptation/data-curation","infra-capacity-economics/cost-modeling"],"tldr":"Scaling laws are empirical power-law fits that predict a language model's pre-training loss from its\nparameter count N, training tokens D and compute C. They exist because frontier runs cost too much to try\nblindly: fitting the curve on small runs tells you how to split a budget between model size and data.\nKaplan showed loss falls smoothly along each axis; Chinchilla corrected the split to about 20 tokens per\nparameter; practice has since moved to over-training smaller models because serving cost scales with N.","review":"fact-checked","status":"ok"},{"id":"perplexity","key":"model-internals/perplexity","module":"model-internals","name":"Perplexity","taxonomy_name":"perplexity","kind":"metric","difficulty":"core","est_minutes":12,"related":["ml-fundamentals/loss-functions","model-internals/tokenization","model-internals/logits","model-internals/softmax","model-internals/scaling-laws","evals/model-evaluation","evals/dataset-contamination","serving-inference/quantization-quality-evaluation"],"tldr":"Perplexity is the exponential of a language model's average per-token cross-entropy on a text:\n`exp(mean of −log p(token))`. It reads as the effective number of equally likely choices the model faces at\neach token, so lower is better. It measures the pre-training objective directly and is interpretable, which\nmakes it the standard tool for tracking training, comparing checkpoints, checking quantisation and filtering\ndata. It is tokenizer-dependent and says nothing about instruction-following or factual correctness.","review":"fact-checked","status":"ok"},{"id":"hallucination","key":"model-internals/hallucination","module":"model-internals","name":"Hallucination","taxonomy_name":"hallucination","kind":"concept","difficulty":"core","est_minutes":16,"related":["model-internals/sampling-strategies","model-internals/small-language-models","ml-fundamentals/calibration","evals/hallucination-evaluation","evals/faithfulness-groundedness","evals/judge-calibration-and-bias","rag-retrieval/citations-grounding","agents/tool-schemas-and-argument-validation"],"tldr":"Hallucination is fluent, confident output that is not supported by the model's input or by reality. It is\na consequence of how language models work, not a bug awaiting a patch: they are trained to produce the\nmost probable continuation, not to know what they know, and sampling, long-tail knowledge gaps and rewards\nfor confident answers all push toward plausible fabrication. Manage it like any error rate: measure it,\nground the model in evidence, verify claims, and make abstention a valid output.","review":"fact-checked","status":"ok"},{"id":"reasoning-models-test-time-compute","key":"model-internals/reasoning-models-test-time-compute","module":"model-internals","name":"Reasoning models / test-time compute","taxonomy_name":"reasoning models / test-time compute","kind":"concept","difficulty":"core","est_minutes":18,"related":["prompting/chain-of-thought","model-internals/sampling-strategies","model-internals/scaling-laws","model-internals/kv-cache","training-adaptation/grpo","training-adaptation/knowledge-distillation","agents/reflection-self-critique","system-design/model-routing-cascading"],"tldr":"Test-time compute means spending more inference computation on a query to get a better answer: a longer\nchain of thought, several sampled attempts with a vote or verifier, or search over partial solutions.\nReasoning models are LLMs trained, mostly with reinforcement learning on verifiable tasks, to do this\ninternally in a long thinking trace before answering. A transformer does fixed computation per token, so\nhard problems need more tokens, and extra inference compute often buys more accuracy per dollar than a\nbigger model.","review":"fact-checked","status":"ok"}]},{"id":"training-adaptation","tier":1,"order":2,"title":"Training & adaptation","intro":null,"topics":[{"id":"pre-training","key":"training-adaptation/pre-training","module":"training-adaptation","name":"Pre-training","taxonomy_name":"pre-training","kind":"concept","difficulty":"core","est_minutes":16,"related":["training-adaptation/post-training","training-adaptation/supervised-fine-tuning","training-adaptation/data-curation","training-adaptation/distributed-training","model-internals/scaling-laws","model-internals/tokenization","model-internals/perplexity","ml-fundamentals/loss-functions"],"tldr":"Pre-training turns a randomly initialised transformer into a model that knows language, facts and\nreasoning patterns by making it predict the next token over trillions of tokens of text. It is\nself-supervised because the text provides its own labels, which is why it can use the whole internet\ninstead of a hand-labelled set. It consumes almost all of the compute and produces a *base model* that\ncompletes text but does not yet follow instructions; every later stage adapts that base.","review":"fact-checked","status":"ok"},{"id":"post-training","key":"training-adaptation/post-training","module":"training-adaptation","name":"Post-training","taxonomy_name":"post-training","kind":"concept","difficulty":"core","est_minutes":14,"related":["training-adaptation/pre-training","training-adaptation/supervised-fine-tuning","training-adaptation/instruction-tuning","training-adaptation/rlhf","training-adaptation/dpo","training-adaptation/grpo","training-adaptation/catastrophic-forgetting","evals/model-evaluation"],"tldr":"Post-training is everything done to a pre-trained base model to make it useful and safe: supervised\nfine-tuning on demonstrations, preference optimisation (RLHF, DPO) on comparisons, and increasingly\nreinforcement learning on verifiable rewards. It uses a tiny fraction of pre-training's compute but\ndecides almost everything a user experiences: whether the model answers, how it formats, what it\nrefuses, how it reasons and how it calls tools. The stages are ordered because each one needs the\nbehaviour the previous one installed.","review":"fact-checked","status":"ok"},{"id":"supervised-fine-tuning","key":"training-adaptation/supervised-fine-tuning","module":"training-adaptation","name":"Supervised fine-tuning (SFT)","taxonomy_name":"supervised fine-tuning (SFT)","kind":"concept","difficulty":"core","est_minutes":16,"related":["training-adaptation/instruction-tuning","training-adaptation/post-training","training-adaptation/peft","training-adaptation/catastrophic-forgetting","training-adaptation/overfitting","training-adaptation/data-curation","training-adaptation/learning-rate","training-adaptation/fine-tune-vs-rag-vs-prompt-decision"],"tldr":"SFT continues training a pre-trained model on prompt-response demonstrations with the same next-token\nloss as pre-training, but computed only on the response tokens. It is the cheapest and most predictable\nway to install a format, a persona or a domain style, because the model is told exactly what to say.\nIts limit is that it can only imitate: it cannot express \"this answer is better than that one\", which\nis why preference methods follow it.","review":"fact-checked","status":"ok"},{"id":"instruction-tuning","key":"training-adaptation/instruction-tuning","module":"training-adaptation","name":"Instruction tuning","taxonomy_name":"instruction tuning","kind":"concept","difficulty":"core","est_minutes":14,"related":["training-adaptation/supervised-fine-tuning","training-adaptation/post-training","training-adaptation/synthetic-data-generation","training-adaptation/data-curation","prompting/zero-shot","prompting/few-shot","prompting/prompt-templates","prompting/chain-of-thought"],"tldr":"Instruction tuning is SFT with a particular data design: many different tasks, each written as a\nnatural-language instruction with its answer, so the model learns the general skill \"read an\ninstruction, do what it says\" rather than any one task. The payoff is zero-shot generalisation to\ninstructions it never saw. Task diversity, not examples per task, is what drives it, which is why\nbuilding the mixture is most of the work.","review":"fact-checked","status":"ok"},{"id":"rlhf","key":"training-adaptation/rlhf","module":"training-adaptation","name":"RLHF","taxonomy_name":"RLHF","kind":"concept","difficulty":"advanced","est_minutes":18,"related":["training-adaptation/dpo","training-adaptation/grpo","training-adaptation/supervised-fine-tuning","training-adaptation/post-training","training-adaptation/data-labeling","evals/pairwise-comparison","evals/inter-annotator-agreement","evals/llm-as-a-judge"],"tldr":"RLHF turns human judgements of \"which answer is better\" into a trained reward model, then uses\nreinforcement learning (usually PPO) to push the language model toward responses that score highly,\nwhile a KL penalty keeps it close to the supervised starting point. It exists because quality is easier\nto compare than to write down, and because a learned reward can be optimised far beyond the examples\npeople could author. Its central hazard is that the policy learns to exploit the reward model's errors.","review":"fact-checked","status":"ok"},{"id":"dpo","key":"training-adaptation/dpo","module":"training-adaptation","name":"DPO","taxonomy_name":"DPO","kind":"concept","difficulty":"advanced","est_minutes":17,"related":["training-adaptation/rlhf","training-adaptation/grpo","training-adaptation/supervised-fine-tuning","training-adaptation/post-training","training-adaptation/overfitting","evals/pairwise-comparison","evals/llm-as-a-judge","ml-fundamentals/loss-functions"],"tldr":"DPO trains a model on preference pairs with a plain classification-style loss, no reward model and no\nRL loop. It works because the KL-constrained objective RLHF optimises has a closed-form solution in\nwhich the reward is a function of the policy itself, so the reward model can be substituted out of the\nBradley–Terry loss. You get most of RLHF's effect for the cost of an SFT run, but offline: the pairs\ndescribe some earlier model's outputs, not the policy's current ones.","review":"fact-checked","status":"ok"},{"id":"grpo","key":"training-adaptation/grpo","module":"training-adaptation","name":"GRPO","taxonomy_name":"GRPO","kind":"concept","difficulty":"advanced","est_minutes":17,"related":["training-adaptation/rlhf","training-adaptation/dpo","training-adaptation/post-training","training-adaptation/synthetic-data-generation","model-internals/reasoning-models-test-time-compute","prompting/chain-of-thought","evals/pass-k","evals/task-specific-acceptance-criteria"],"tldr":"GRPO is a policy-gradient method that drops PPO's value model: for each prompt it samples a group of\nresponses, scores them, and uses the group's mean and spread as the baseline, so each advantage is\n\"how much better than its siblings\". It keeps PPO's clipped update and a KL term to a\nreference. It exists because a critic the size of the policy is costly and unstable for sequence-level\nrewards, and it is the usual choice for training open reasoning models with verifiable rewards.","review":"fact-checked","status":"ok"},{"id":"peft","key":"training-adaptation/peft","module":"training-adaptation","name":"PEFT (LoRA, QLoRA)","taxonomy_name":"PEFT (LoRA, QLoRA)","kind":"concept","difficulty":"core","est_minutes":16,"related":["training-adaptation/supervised-fine-tuning","training-adaptation/quantization","training-adaptation/catastrophic-forgetting","training-adaptation/gradient-checkpointing","training-adaptation/tooling","python-for-ai/hugging-face","serving-inference/engines","ml-fundamentals/optimizers"],"tldr":"Full fine-tuning updates every weight, so a 7B model needs on the order of 100 GB of GPU memory for\nweights, gradients and optimizer state. PEFT freezes the base model and trains a small set of extra\nparameters instead. LoRA learns each weight update as the product of two thin matrices; QLoRA also stores\nthe frozen base in 4-bit so the job fits one consumer GPU. You keep most of full fine-tuning's quality and\nget adapters you can swap at serving time.","review":"fact-checked","status":"ok"},{"id":"knowledge-distillation","key":"training-adaptation/knowledge-distillation","module":"training-adaptation","name":"Knowledge distillation","taxonomy_name":"knowledge distillation","kind":"concept","difficulty":"core","est_minutes":15,"related":["training-adaptation/supervised-fine-tuning","training-adaptation/synthetic-data-generation","training-adaptation/pruning","training-adaptation/quantization","model-internals/small-language-models","model-internals/logits","system-design/slm-vs-llm-trade-offs","evals/model-evaluation"],"tldr":"A large model knows more than its top-1 answer shows: the full next-token distribution encodes which\nalternatives are plausible and which are absurd. Knowledge distillation trains a smaller student to match a\nlarger teacher's outputs, either its soft probability distributions or its generated text, instead of only\nthe one-hot labels in the data. Each example then carries far more signal, which is why a distilled model\nusually beats the same architecture trained on the labels alone.","review":"fact-checked","status":"ok"},{"id":"quantization","key":"training-adaptation/quantization","module":"training-adaptation","name":"Quantization (INT8/INT4, GPTQ, AWQ, GGUF)","taxonomy_name":"quantization (INT8/INT4, GPTQ, AWQ, GGUF)","kind":"concept","difficulty":"core","est_minutes":18,"related":["training-adaptation/peft","training-adaptation/pruning","serving-inference/quantization-quality-evaluation","serving-inference/engines","serving-inference/gpu-memory-optimization","infra-capacity-economics/gpu-utilization-and-memory-bandwidth","infra-capacity-economics/edge-ai-deployment","ml-fundamentals/mixed-precision"],"tldr":"Quantization stores weights, and sometimes activations, in fewer bits than the 16-bit training format:\nINT8, INT4 or small floats. It pays off because LLM decoding is limited by bytes read per token, not by\narithmetic, so fewer bytes per weight means a model that fits cheaper hardware and decodes faster. GPTQ\nand AWQ are calibration-based recipes for choosing 4-bit values that minimise each layer's output error;\nGGUF is the llama.cpp file format for shipping such models to CPUs and laptops.","review":"fact-checked","status":"ok"},{"id":"pruning","key":"training-adaptation/pruning","module":"training-adaptation","name":"Pruning","taxonomy_name":"pruning","kind":"concept","difficulty":"advanced","est_minutes":14,"related":["training-adaptation/quantization","training-adaptation/knowledge-distillation","model-internals/small-language-models","model-internals/multi-head-attention","model-internals/mixture-of-experts","serving-inference/inference-optimization","infra-capacity-economics/gpu-utilization-and-memory-bandwidth"],"tldr":"Pruning removes parameters a trained network barely uses, individual weights, attention heads, MLP\nneurons or whole layers, and then repairs the damage with a short fine-tune or distillation from the\noriginal. It exists because large models are heavily over-parameterised, so much of the compute spent at\ninference moves the output very little. The catch is that only structured removal (whole rows, heads,\nlayers, or the hardware-supported 2:4 pattern) turns into real speed and memory wins on GPUs; scattered\nzeros mostly do not.","review":"fact-checked","status":"ok"},{"id":"model-merging","key":"training-adaptation/model-merging","module":"training-adaptation","name":"Model merging","taxonomy_name":"model merging","kind":"concept","difficulty":"advanced","est_minutes":15,"related":["training-adaptation/peft","training-adaptation/supervised-fine-tuning","training-adaptation/catastrophic-forgetting","training-adaptation/tooling","evals/regression-tests","system-design/model-portfolio","llmops-platform/model-registry","safety-security/supply-chain-security-for-models-and-datasets"],"tldr":"Model merging combines several fine-tuned checkpoints of one base model into a single set of weights by\narithmetic on the parameters: averaging, adding scaled task vectors, or trimming and sign-voting the\ndeltas. No training is involved. It works because fine-tunes that start from the same initialisation\nstay in a connected low-loss region, so their deltas behave roughly additively. You get one model carrying\nseveral skills at the serving cost of one, paying with task interference that no gradient step corrects.","review":"fact-checked","status":"ok"},{"id":"data-curation","key":"training-adaptation/data-curation","module":"training-adaptation","name":"Data curation","taxonomy_name":"data curation","kind":"practice","difficulty":"core","est_minutes":16,"related":["training-adaptation/data-labeling","training-adaptation/synthetic-data-generation","training-adaptation/train-val-test-split","training-adaptation/supervised-fine-tuning","ml-fundamentals/train-test-leakage","evals/dataset-contamination","data-architecture/training-data-pipelines","safety-security/pii-redaction"],"tldr":"Data curation is the deliberate selection, cleaning, deduplication, decontamination and mixing of what a\nmodel trains on. It exists because gradient descent learns whatever is in the batch, boilerplate,\nduplicates, leaked test sets and labelling noise included, and no architecture or hyperparameter choice\nrecovers what bad data teaches. For fine-tuning, a few thousand carefully chosen examples routinely beat a\nhundred thousand scraped ones; for pretraining, filtering and deduplication are worth more than extra\ntokens.","review":"fact-checked","status":"ok"},{"id":"synthetic-data-generation","key":"training-adaptation/synthetic-data-generation","module":"training-adaptation","name":"Synthetic data generation","taxonomy_name":"synthetic data generation","kind":"practice","difficulty":"core","est_minutes":16,"related":["training-adaptation/data-curation","training-adaptation/knowledge-distillation","training-adaptation/supervised-fine-tuning","training-adaptation/dpo","evals/golden-dataset","evals/llm-as-a-judge","customer-data-evaluation/golden-dataset-creation-with-client-smes","data-architecture/model-and-dataset-provenance"],"tldr":"Synthetic data generation uses a model, a program or a simulator to manufacture training or evaluation\nexamples instead of collecting them from people. It exists because the examples you need, rare failure\ncases, verified reasoning traces, formats the public web lacks, are expensive or impossible to gather at\nscale. Its value is decided by verification: generated examples are only as good as the filter that\nchooses which survive, and training repeatedly on unfiltered model output collapses the distribution.","review":"fact-checked","status":"ok"},{"id":"data-labeling","key":"training-adaptation/data-labeling","module":"training-adaptation","name":"Data labeling","taxonomy_name":"data labeling","kind":"practice","difficulty":"core","est_minutes":14,"related":["training-adaptation/data-curation","training-adaptation/supervised-fine-tuning","training-adaptation/synthetic-data-generation","training-adaptation/rlhf","training-adaptation/train-val-test-split","evals/inter-annotator-agreement","evals/rubrics","evals/golden-dataset"],"tldr":"A fine-tuned model learns the labeling function, including every inconsistency and shortcut the labelers\nhad. Data labeling turns raw inputs into targets (classes, spans, demonstrations, preferences) in a way\nwhose quality you can measure, chiefly by having several people label the same items and computing\nagreement. At fine-tuning scale a few thousand examples carry the whole signal, so each bad label is a\nmeasurable share of what the model becomes.","status":"ok"},{"id":"train-val-test-split","key":"training-adaptation/train-val-test-split","module":"training-adaptation","name":"Train / validation / test split","taxonomy_name":"train/val/test split","kind":"practice","difficulty":"intro","est_minutes":12,"related":["ml-fundamentals/train-test-leakage","training-adaptation/data-curation","training-adaptation/data-labeling","training-adaptation/overfitting","training-adaptation/supervised-fine-tuning","evals/golden-dataset","evals/dataset-contamination","llmops-platform/drift"],"tldr":"Weights are fit on the training set. Every decision made while looking at a score (learning rate, epochs,\nwhich checkpoint to keep) is fit on the validation set. The test set is read once, at the end, to estimate\nwhat the chosen model does on data nobody tuned against. Three sets exist because a score you optimised\nagainst is no longer an unbiased estimate, and the cut must follow the unit the model must generalise\nacross (conversation, user, document, time), not rows.","status":"ok"},{"id":"epochs","key":"training-adaptation/epochs","module":"training-adaptation","name":"Epochs","taxonomy_name":"epochs","kind":"concept","difficulty":"intro","est_minutes":11,"related":["training-adaptation/learning-rate","training-adaptation/overfitting","training-adaptation/checkpointing","training-adaptation/supervised-fine-tuning","training-adaptation/pre-training","ml-fundamentals/batch-size","ml-fundamentals/gradient-accumulation","ml-fundamentals/learning-rate-schedulers"],"tldr":"An epoch is one full pass of the optimiser over the training set. It exists because minibatch training\nconsumes data piecewise, and \"every example seen once\" is the natural unit for reshuffling, evaluating\nand stopping. More epochs means more optimizer steps over the same examples: necessary when the set is\nsmall, harmful once the model starts memorising. For LLMs the unit flips with scale: pretraining counts\ntokens and rarely completes one pass, while fine-tuning counts epochs and usually needs only a few.","status":"ok"},{"id":"learning-rate","key":"training-adaptation/learning-rate","module":"training-adaptation","name":"Learning rate","taxonomy_name":"learning rate","kind":"concept","difficulty":"core","est_minutes":14,"related":["ml-fundamentals/learning-rate-schedulers","ml-fundamentals/warmup","ml-fundamentals/optimizers","ml-fundamentals/gradient-descent","ml-fundamentals/batch-size","ml-fundamentals/gradient-clipping","training-adaptation/peft","training-adaptation/catastrophic-forgetting"],"tldr":"The learning rate is the optimiser's step size: how far parameters move per update along the gradient\n(SGD) or the per-coordinate-normalised gradient (Adam). It is the most sensitive hyperparameter because a\ngradient gives direction, not a safe distance: too large and the loss oscillates or diverges, too small\nand the run crawls and ends worse. In LLM work, peak, warmup and decay are chosen together; fine-tuning\nuses rates far below pretraining to stay near the pretrained solution.","status":"ok"},{"id":"overfitting","key":"training-adaptation/overfitting","module":"training-adaptation","name":"Overfitting","taxonomy_name":"overfitting","kind":"concept","difficulty":"core","est_minutes":13,"related":["training-adaptation/train-val-test-split","training-adaptation/epochs","training-adaptation/catastrophic-forgetting","training-adaptation/checkpointing","training-adaptation/peft","ml-fundamentals/dropout-regularization","ml-fundamentals/train-test-leakage","evals/dataset-contamination"],"tldr":"Overfitting is a model fitting the particulars of its training examples (label noise, phrasing) instead\nof the pattern that transfers to new data. The signature is training loss that keeps falling while\nheld-out loss stalls and then rises. It happens because a network with far more parameters than examples\ncan memorise anything; the remedies are more or cleaner data, fewer steps, less trainable capacity,\nregularisation and early stopping. Fine-tuning a small set for many epochs is the commonest way engineers\noverfit an LLM.","status":"ok"},{"id":"catastrophic-forgetting","key":"training-adaptation/catastrophic-forgetting","module":"training-adaptation","name":"Catastrophic forgetting","taxonomy_name":"catastrophic forgetting","kind":"concept","difficulty":"core","est_minutes":14,"related":["training-adaptation/overfitting","training-adaptation/supervised-fine-tuning","training-adaptation/peft","training-adaptation/rlhf","training-adaptation/model-merging","training-adaptation/learning-rate","training-adaptation/data-curation","evals/regression-tests"],"tldr":"Fine-tuning computes gradients of the new loss only; nothing stops them overwriting the weights that\nencoded older capabilities, so the model forgets what it is not being trained on. For an LLM, a fine-tune\non your task can silently lose general instruction following, reasoning or safety behaviour, because your\nevaluation measures only your task. Defences: mix in general data, keep the update small, isolate it in\nadapters, pull back toward the original weights, and gate every fine-tune on a general regression suite.","status":"ok"},{"id":"checkpointing","key":"training-adaptation/checkpointing","module":"training-adaptation","name":"Checkpointing","taxonomy_name":"checkpointing","kind":"practice","difficulty":"core","est_minutes":14,"related":["training-adaptation/gradient-checkpointing","training-adaptation/distributed-training","training-adaptation/overfitting","training-adaptation/tooling","llmops-platform/experiment-tracking","llmops-platform/model-registry","llmops-platform/rollback","agent-reliability/durable-execution-and-checkpointing"],"tldr":"Checkpointing saves the complete training state (weights, optimizer moments, scheduler, RNG and data\nposition) to durable storage at intervals, so a run can resume after a failure, be rolled back, and be\nselected from: the best checkpoint on validation is early stopping made concrete. Long runs fail, at\ncluster scale they fail often, and a full training checkpoint of a 7B model is on the order of 100 GB,\nso frequency, format, sharding and retention are engineering decisions. It is unrelated to gradient\ncheckpointing, which recomputes activations to save memory.","status":"ok"},{"id":"gradient-checkpointing","key":"training-adaptation/gradient-checkpointing","module":"training-adaptation","name":"Gradient checkpointing","taxonomy_name":"gradient checkpointing","kind":"concept","difficulty":"core","est_minutes":14,"related":["training-adaptation/checkpointing","training-adaptation/peft","training-adaptation/distributed-training","training-adaptation/tooling","ml-fundamentals/backpropagation","ml-fundamentals/mixed-precision","ml-fundamentals/gradient-accumulation","model-internals/flashattention"],"tldr":"Despite the name, gradient checkpointing has nothing to do with saving a model to disk; it is activation\nrecomputation. Backprop needs every layer's forward activations, and at long sequence lengths those\noutweigh the weights. Checkpointing keeps only each block's input, discards the rest, and recomputes a\nblock's internals during backward. You pay roughly one extra forward pass of compute to shrink activation\nmemory from \"all layers\" to \"all block inputs plus one block\", which is what lets long-context fine-tunes\nfit on one GPU.","review":"fact-checked","status":"ok"},{"id":"fine-tune-vs-rag-vs-prompt-decision","key":"training-adaptation/fine-tune-vs-rag-vs-prompt-decision","module":"training-adaptation","name":"Fine-tune vs RAG vs prompt decision","taxonomy_name":"fine-tune vs RAG vs prompt decision","kind":"decision","difficulty":"core","est_minutes":15,"related":["training-adaptation/supervised-fine-tuning","training-adaptation/peft","training-adaptation/catastrophic-forgetting","training-adaptation/knowledge-distillation","rag-retrieval/long-context-vs-rag","prompting/few-shot","prompting/prompt-caching","evals/golden-dataset"],"tldr":"The three levers change different objects. A prompt changes the input of one request and costs nothing\nto try. RAG puts knowledge the model does not have into the input at request time, with freshness,\naccess control and citations. Fine-tuning changes the weights, which is the right tool for behaviour,\nformat, skill and per-request cost, and a poor tool for injecting facts. Decide by naming the gap\n(knowledge, behaviour or economics) and climb prompt → RAG → fine-tune only when evals show the cheaper\nrung is not enough.","review":"fact-checked","status":"ok"},{"id":"tooling","key":"training-adaptation/tooling","module":"training-adaptation","name":"Tooling (Unsloth, Axolotl, TRL)","taxonomy_name":"tooling (Unsloth, Axolotl, TRL)","kind":"tool","difficulty":"core","est_minutes":13,"related":["training-adaptation/peft","training-adaptation/supervised-fine-tuning","training-adaptation/dpo","training-adaptation/grpo","training-adaptation/gradient-checkpointing","training-adaptation/distributed-training","training-adaptation/quantization","python-for-ai/hugging-face"],"tldr":"Fine-tuning an LLM is the same loop almost every time: load the model, maybe quantise it, attach LoRA,\nformat chat data, train with a known loss, save the adapter. TRL (Hugging Face) provides those loops as\ntrainers (SFT, DPO, GRPO, PPO, reward). Axolotl wraps them in a YAML file so a run is reproducible and\nmulti-GPU is a config flag. Unsloth rewrites the kernels so the same LoRA/QLoRA run is faster and lighter\non one GPU. Pick by how much control, reproducibility or raw speed you need.","review":"fact-checked","status":"ok"},{"id":"distributed-training","key":"training-adaptation/distributed-training","module":"training-adaptation","name":"Distributed training (data / tensor / pipeline parallelism, FSDP, DeepSpeed)","taxonomy_name":"distributed training (data / tensor / pipeline parallelism, FSDP, DeepSpeed)","kind":"concept","difficulty":"advanced","est_minutes":18,"related":["training-adaptation/pre-training","training-adaptation/gradient-checkpointing","training-adaptation/peft","training-adaptation/tooling","ml-fundamentals/batch-size","ml-fundamentals/mixed-precision","infra-capacity-economics/gpu-infrastructure","infra-capacity-economics/gpu-utilization-and-memory-bandwidth"],"tldr":"Caveat: this topic matters only for training-heavy roles; for LLM-application roles, learn the vocabulary\nand skip the practice. One GPU cannot hold a large model's training state (about 16 bytes per parameter\nwith Adam in mixed precision) or finish pretraining in calendar time. Data parallelism splits the batch,\ntensor parallelism splits each matrix, pipeline parallelism splits the layers, and FSDP or DeepSpeed ZeRO\nshard the replicated state so data parallelism stops wasting memory. The interconnect decides which\ncombination is affordable.","caveat":"only if the JD is training-heavy; drop for LLM-app roles","review":"fact-checked","status":"ok"}]},{"id":"prompting","tier":1,"order":3,"title":"Prompting","intro":null,"topics":[{"id":"prompt-engineering","key":"prompting/prompt-engineering","module":"prompting","name":"Prompt engineering","taxonomy_name":"prompt engineering","kind":"practice","difficulty":"intro","est_minutes":12,"related":["prompting/system-prompt","prompting/few-shot","prompting/chain-of-thought","prompting/prompt-templates","prompting/context-engineering","evals/eval-driven-development","training-adaptation/fine-tune-vs-rag-vs-prompt-decision","customer-data-evaluation/domain-prompt-engineering"],"tldr":"A language model is a conditional distribution over next tokens; everything it does is determined by\nthe tokens in front of it. Prompt engineering is the practice of specifying a task through that input\n(instructions, context, examples, output format) and iterating against a measured eval set, because an\nunder-specified prompt makes the model average over every plausible interpretation. It is the cheapest\nlever you own: seconds per iteration, no training data, no redeploy. This lesson orients the module;\neach technique has its own deep lesson.","status":"ok"},{"id":"system-prompt","key":"prompting/system-prompt","module":"prompting","name":"System prompt","taxonomy_name":"system prompt","kind":"concept","difficulty":"intro","est_minutes":12,"related":["prompting/prompt-engineering","prompting/prompt-templates","prompting/prompt-caching","prompting/prompt-injection","prompting/context-engineering","training-adaptation/instruction-tuning","serving-inference/prefix-caching","safety-security/prompt-injection"],"tldr":"A deployed chat has two authors: the operator who built the product and the user typing into it. The\nsystem prompt is the operator's channel: text in a dedicated role at the start of the context, which\npost-training taught the model to treat as standing policy over what users say. It is a learned prior,\nnot enforcement, so it shapes behaviour reliably but guarantees nothing; and as a stable prefix it is the\npart of the prompt that caching makes nearly free.","status":"ok"},{"id":"zero-shot","key":"prompting/zero-shot","module":"prompting","name":"Zero-shot prompting","taxonomy_name":"zero-shot","kind":"pattern","difficulty":"intro","est_minutes":10,"related":["prompting/few-shot","prompting/chain-of-thought","prompting/prompt-engineering","prompting/system-prompt","prompting/structured-outputs-json-mode","training-adaptation/instruction-tuning","model-internals/sampling-strategies","evals/golden-dataset"],"tldr":"Zero-shot prompting describes the task in words and includes no demonstrations. It works because\ninstruction tuning trained the model on thousands of tasks phrased as instructions, so a clearly\ndescribed new task is in distribution even though the model never saw an example of it. It is the\ndefault starting point: the shortest prompt, no example-induced bias, easiest to maintain. It fails where\nthe specification cannot be written down precisely, which is exactly where examples earn their tokens.","status":"ok"},{"id":"few-shot","key":"prompting/few-shot","module":"prompting","name":"Few-shot prompting","taxonomy_name":"few-shot","kind":"pattern","difficulty":"core","est_minutes":14,"related":["prompting/zero-shot","prompting/prompt-engineering","prompting/prompt-caching","prompting/prompt-templates","prompting/chain-of-thought","training-adaptation/fine-tune-vs-rag-vs-prompt-decision","rag-retrieval/embedding-models","evals/golden-dataset"],"tldr":"Few-shot prompting puts input → output demonstrations in the prompt. The model performs in-context\nlearning: conditioning on the examples shifts its output distribution toward their format, label space\nand style without any weight update. It is how you specify what is easier to show than to say. The price\nis tokens on every call and a set of biases the examples bring with them: order, label frequency and\ncopied surface detail.","status":"ok"},{"id":"chain-of-thought","key":"prompting/chain-of-thought","module":"prompting","name":"Chain-of-thought prompting","taxonomy_name":"chain-of-thought","kind":"pattern","difficulty":"core","est_minutes":14,"related":["prompting/zero-shot","prompting/few-shot","prompting/react","prompting/structured-outputs-json-mode","model-internals/reasoning-models-test-time-compute","model-internals/sampling-strategies","evals/pass-k","agents/reflection-self-critique"],"tldr":"Chain-of-thought (CoT) has the model write intermediate reasoning before its final answer. It works\nbecause a transformer spends a fixed amount of computation per generated token, so a problem that needs\nmany dependent steps cannot be solved inside one token; writing the steps out buys more sequential\ncomputation and lets the sequence carry state. Gains are large on arithmetic, logic and multi-step\nplanning, near zero on lookups, and the written chain is not guaranteed to be the real cause of the\nanswer.","status":"ok"},{"id":"react","key":"prompting/react","module":"prompting","name":"ReAct (reason + act)","taxonomy_name":"ReAct","kind":"pattern","difficulty":"core","est_minutes":15,"related":["prompting/chain-of-thought","prompting/function-tool-calling","prompting/prompt-injection","agents/agent-loop","agents/tool-calling","agents/planning","agent-reliability/max-step-budgets","agent-reliability/loop-detection"],"tldr":"ReAct interleaves reasoning and acting in one loop: the model writes a thought, picks a tool call, the\nharness runs it and appends the observation, and the model reasons again over fresh evidence. It exists\nbecause chain-of-thought alone cannot look anything up, so its errors compound, while action-only agents\npick tools without a stated reason and cannot revise a plan. Native tool calling is ReAct with the\nparsing moved into the API; the loop, budget and safety checks remain yours.","status":"ok"},{"id":"prompt-templates","key":"prompting/prompt-templates","module":"prompting","name":"Prompt templates","taxonomy_name":"prompt templates","kind":"practice","difficulty":"core","est_minutes":12,"related":["prompting/prompt-engineering","prompting/system-prompt","prompting/few-shot","prompting/prompt-versioning","prompting/prompt-caching","prompting/prompt-injection","python-for-ai/pydantic","llmops-platform/prompt-registry"],"tldr":"A prompt template separates the fixed instructions from the per-request variables and renders them into\nthe message structure the API expects. It exists because a prompt is code that runs on data: string\nconcatenation mixes the two, breaks on stray braces and delimiters, cannot be unit-tested or versioned,\nand silently destroys cache hits by putting variable text before stable text. There are two template\nlayers, yours and the model's chat template, and you need to understand both.","status":"ok"},{"id":"prompt-versioning","key":"prompting/prompt-versioning","module":"prompting","name":"Prompt versioning","taxonomy_name":"prompt versioning","kind":"practice","difficulty":"core","est_minutes":12,"related":["prompting/prompt-templates","prompting/prompt-caching","llmops-platform/prompt-registry","llmops-platform/ci-cd-for-prompts-and-models","llmops-platform/rollback","evals/regression-tests","evals/golden-dataset","observability/tracing"],"tldr":"A prompt is behaviour-defining code that happens to be prose, so it needs what code already has:\nimmutable versions, an identifier recorded on every call, review, an eval before promotion and a\none-step rollback. Without that, a quality regression cannot be tied to a change, a user complaint\ncannot be reproduced, and \"the prompt in production\" is whatever someone last pasted from a playground.","status":"ok"},{"id":"prompt-caching","key":"prompting/prompt-caching","module":"prompting","name":"Prompt caching","taxonomy_name":"prompt caching","kind":"concept","difficulty":"core","est_minutes":14,"related":["prompting/system-prompt","prompting/prompt-templates","prompting/prompt-versioning","prompting/context-engineering","model-internals/kv-cache","serving-inference/prefix-caching","serving-inference/ttft","observability/token-cost-tracking"],"tldr":"Every request re-runs prefill over the whole prompt, yet in most applications most of the prompt\n(system instructions, tool definitions, few-shot examples, a long reference document) is identical from\none request to the next. Prompt caching stores the model's internal state for a prefix and reuses it\nwhen a later request starts with the same bytes, cutting input cost and time-to-first-token. It only\nworks on exact prefixes, so the layout of your prompt decides whether you get the discount.","status":"ok"},{"id":"structured-outputs-json-mode","key":"prompting/structured-outputs-json-mode","module":"prompting","name":"Structured outputs / JSON mode","taxonomy_name":"structured outputs / JSON mode","kind":"concept","difficulty":"core","est_minutes":14,"related":["prompting/function-tool-calling","prompting/prompt-templates","prompting/chain-of-thought","serving-inference/structured-constrained-generation","agents/tool-schemas-and-argument-validation","agents/typed-tool-contracts","safety-security/output-validation","evals/regression-tests"],"tldr":"Downstream code needs a parseable object with known keys and types, but a language model emits free\ntext. JSON mode guarantees syntactically valid JSON; structured outputs go further and guarantee\nconformance to a schema you supply, by constraining which tokens the model may emit at each step. This\nremoves a class of parse failures, not a class of wrong answers: schema-valid output can still be wrong,\nso semantic validation and evals remain your job.","status":"ok"},{"id":"function-tool-calling","key":"prompting/function-tool-calling","module":"prompting","name":"Function / tool calling","taxonomy_name":"function / tool calling","kind":"concept","difficulty":"core","est_minutes":15,"related":["prompting/structured-outputs-json-mode","prompting/react","prompting/prompt-caching","prompting/prompt-injection","agents/agent-loop","agents/tool-calling","agents/tool-schemas-and-argument-validation","agents/model-context-protocol"],"tldr":"A language model can only emit tokens: it cannot look anything up, change any state or do reliable\narithmetic. Function calling (tool calling) is a trained protocol in which you describe functions with a\nname, description and JSON schema, the model emits a structured request to call one with arguments, your\ncode executes it and returns the result, and the model continues. The model never runs anything. The\n\"call\" is a message; execution, permissions and error handling are yours.","status":"ok"},{"id":"context-engineering","key":"prompting/context-engineering","module":"prompting","name":"Context engineering","taxonomy_name":"context engineering","kind":"practice","difficulty":"core","est_minutes":15,"related":["prompting/system-prompt","prompting/prompt-caching","prompting/few-shot","model-internals/context-window","rag-retrieval/lost-in-the-middle","rag-retrieval/long-context-vs-rag","agents/context-compaction-summarization","agents/agent-memory"],"tldr":"The context window is the model's entire working memory for one call: finite, billed per token and\nattended to unevenly. Context engineering is deciding, for every call, what goes in, in what order, in\nwhat form and under what budget: instructions, tool definitions, retrieved documents, memory, history and\ntool results. Prompt engineering writes the instructions; context engineering manages everything around\nthem, and in multi-step systems that is where quality and cost are decided.","status":"ok"},{"id":"prompt-injection","key":"prompting/prompt-injection","module":"prompting","name":"Prompt injection","taxonomy_name":"prompt injection","kind":"concept","difficulty":"core","est_minutes":15,"related":["prompting/jailbreaks","prompting/system-prompt","prompting/function-tool-calling","prompting/context-engineering","safety-security/prompt-injection","safety-security/input-output-guardrails","security-governance-compliance/prompt-injection-defense","agents/approval-gates-for-consequential-actions"],"tldr":"Prompt injection is text in the model's context, placed there by someone other than the operator, that\nthe model treats as instructions. It works because a transformer has no privileged channel: system\nprompt, user message, retrieved page and tool result are all tokens in one sequence, and\ninstruction-following training makes the model obey instruction-shaped text wherever it appears. No\nprompt wording fixes this; containment means limiting what the model can do and see, which the\nsecurity modules cover in depth.","status":"ok"},{"id":"jailbreaks","key":"prompting/jailbreaks","module":"prompting","name":"Jailbreaks","taxonomy_name":"jailbreaks","kind":"concept","difficulty":"core","est_minutes":13,"related":["prompting/prompt-injection","prompting/system-prompt","safety-security/input-output-guardrails","safety-security/content-moderation","safety-security/llama-guard","evals/red-teaming","evals/adversarial-evaluation","security-governance-compliance/threat-modeling"],"tldr":"A jailbreak is an input crafted to make a model do what its safety training or its operator's policy\nforbids. It works because refusal is a learned behaviour competing with helpfulness and instruction\nfollowing, and because training never covers every framing. For an application builder the practical\nthreat is usually policy-level, getting your bot to leave its lane, leak its prompt or promise a refund,\nand the defence is the same as for injection: do not make the prompt the boundary.","status":"ok"}]},{"id":"rag-retrieval","tier":1,"order":4,"title":"RAG & retrieval","intro":null,"topics":[{"id":"chunking-strategies","key":"rag-retrieval/chunking-strategies","module":"rag-retrieval","name":"Chunking strategies (fixed, recursive, semantic)","taxonomy_name":"chunking strategies (fixed, recursive, semantic)","kind":"concept","difficulty":"core","est_minutes":14,"related":["rag-retrieval/chunk-overlap","rag-retrieval/retrieval-granularity","rag-retrieval/document-parsing","rag-retrieval/parent-document-retrieval","rag-retrieval/contextual-retrieval","rag-retrieval/embedding-models","model-internals/tokenization","python-for-ai/tiktoken"],"tldr":"An embedding model turns a span of text into one vector, so a whole document becomes a blurry average\nin which the specific passage a question needs is drowned out, and most encoders truncate long inputs\nanyway. Chunking cuts documents into retrievable units before embedding. Fixed-size splitting is\npredictable but blind to structure; recursive splitting tries natural boundaries (paragraph, line,\nsentence) before falling back to hard cuts; semantic splitting places boundaries where adjacent\nsentences stop being about the same thing. The strategy defines what \"a hit\" means downstream.","status":"ok"},{"id":"chunk-overlap","key":"rag-retrieval/chunk-overlap","module":"rag-retrieval","name":"Chunk overlap","taxonomy_name":"chunk overlap","kind":"concept","difficulty":"intro","est_minutes":10,"related":["rag-retrieval/chunking-strategies","rag-retrieval/retrieval-granularity","rag-retrieval/parent-document-retrieval","rag-retrieval/contextual-retrieval","rag-retrieval/lost-in-the-middle","data-architecture/vector-store-sizing","python-for-ai/tiktoken"],"tldr":"Overlap makes consecutive chunks share their last and first few tokens, so a sentence or reference\nthat straddles a boundary appears whole in at least one chunk instead of being half in each. It is a\ncheap hedge against boundary damage, paid for with a larger index and near-duplicate results that must\nbe deduplicated at query time. It does not replace good boundaries; structure-aware splitting and\nparent retrieval fix the root cause that overlap only patches.","status":"ok"},{"id":"retrieval-granularity","key":"rag-retrieval/retrieval-granularity","module":"rag-retrieval","name":"Retrieval granularity","taxonomy_name":"retrieval granularity","kind":"decision","difficulty":"core","est_minutes":12,"related":["rag-retrieval/chunking-strategies","rag-retrieval/chunk-overlap","rag-retrieval/parent-document-retrieval","rag-retrieval/contextual-retrieval","rag-retrieval/lost-in-the-middle","rag-retrieval/reranking","rag-retrieval/recall-vs-precision-trade-off","model-internals/context-window"],"tldr":"Granularity is the size of the unit you retrieve: sentence, proposition, passage, section or whole\ndocument. Small units make sharp vectors and precise matches but starve the generator of context;\nlarge units carry context but blur the vector and crowd the prompt. The resolving move is to separate\nthe unit you *match on* from the unit you *return*: index small, return the enclosing parent. The\nright pair depends on the question type and the context budget, and should be measured, not assumed.","status":"ok"},{"id":"embedding-models","key":"rag-retrieval/embedding-models","module":"rag-retrieval","name":"Embedding models","taxonomy_name":"embedding models","kind":"concept","difficulty":"core","est_minutes":15,"related":["model-internals/embeddings","rag-retrieval/embedding-dimension-and-normalization","rag-retrieval/embedding-pipelines","rag-retrieval/similarity-search","rag-retrieval/dense-vs-sparse-retrieval","rag-retrieval/reranking","python-for-ai/sentence-transformers","evals/retrieval-evaluation"],"tldr":"An embedding model is an encoder trained so that texts with similar meaning land close together in a\nfixed-size vector space. It exists because keyword search cannot see that \"money back\" and \"refund\"\nmean the same thing, and because scoring every document against the query with a full cross-attention\nmodel is too slow. A bi-encoder embeds documents once, ahead of time, so retrieval becomes a\nnearest-neighbour lookup. The price is that the model must be chosen, prefixed and versioned\nconsistently, or the index is silently wrong.","status":"ok"},{"id":"embedding-dimension-and-normalization","key":"rag-retrieval/embedding-dimension-and-normalization","module":"rag-retrieval","name":"Embedding dimension & normalization","taxonomy_name":"embedding dimension & normalization","kind":"concept","difficulty":"core","est_minutes":13,"related":["rag-retrieval/embedding-models","rag-retrieval/similarity-search","rag-retrieval/ann-indexes","rag-retrieval/vector-databases","data-architecture/vector-store-sizing","ml-fundamentals/normalization","training-adaptation/quantization","model-internals/embeddings"],"tldr":"The dimension of an embedding is how many floats each vector holds, and it sets the storage, memory and\nper-comparison cost of the whole index linearly. L2-normalizing vectors to unit length makes cosine\nsimilarity equal to the dot product and makes Euclidean ranking identical to both, so the metric choice\nstops mattering and scores stop rewarding long, verbose chunks. Matryoshka-trained models let you\ntruncate dimensions after the fact; quantization shrinks the bytes per dimension. Both trade a little\nrecall for a lot of memory.","status":"ok"},{"id":"embedding-pipelines","key":"rag-retrieval/embedding-pipelines","module":"rag-retrieval","name":"Embedding pipelines","taxonomy_name":"embedding pipelines","kind":"pattern","difficulty":"core","est_minutes":14,"related":["rag-retrieval/chunking-strategies","rag-retrieval/embedding-models","rag-retrieval/vector-databases","rag-retrieval/freshness-document-deletion-index-consistency","rag-retrieval/document-parsing","data-architecture/ingestion-pipelines","data-architecture/embedding-versioning-re-indexing-strategy","fastapi-for-ai/job-queues-and-durable-workers"],"tldr":"An embedding pipeline is the job that turns source documents into indexed vectors and keeps them that\nway: parse, chunk, enrich, embed, upsert, and later update and delete. It exists because the \"loop over\nfiles and call the API\" script fails the moment a document changes, a batch half-fails, or the model is\nupgraded. The design goals are idempotency (same input, same chunk id, no duplicates), incremental\nupdates, and strict parity between how text is embedded at index time and at query time.","status":"ok"},{"id":"vector-databases","key":"rag-retrieval/vector-databases","module":"rag-retrieval","name":"Vector databases (pgvector, Qdrant, Pinecone, Weaviate, Milvus, Chroma)","taxonomy_name":"vector databases (pgvector, Qdrant, Pinecone, Weaviate, Milvus, Chroma)","kind":"tool","difficulty":"core","est_minutes":16,"related":["rag-retrieval/ann-indexes","rag-retrieval/similarity-search","rag-retrieval/metadata-filtering","rag-retrieval/hybrid-search","rag-retrieval/embedding-pipelines","data-architecture/vector-database-architecture","data-architecture/vector-store-sizing","system-design/build-vs-buy"],"tldr":"A vector database stores embeddings with their metadata and answers \"the k nearest vectors to this one,\nsubject to these filters\" fast enough for a request path. It exists because brute-force scanning\nmillions of vectors is too slow and a bare ANN library (FAISS, hnswlib) has no persistence, updates,\nfiltering or multi-tenancy. pgvector adds this inside Postgres; Qdrant, Weaviate and Milvus are dedicated\nopen-source engines; Pinecone is fully managed; Chroma is the embedded prototyping option. The choice is\nmostly about operations and scale, not retrieval quality.","status":"ok"},{"id":"similarity-search","key":"rag-retrieval/similarity-search","module":"rag-retrieval","name":"Similarity search (cosine, dot product)","taxonomy_name":"similarity search (cosine, dot product)","kind":"concept","difficulty":"core","est_minutes":13,"related":["rag-retrieval/embedding-models","rag-retrieval/embedding-dimension-and-normalization","rag-retrieval/ann-indexes","rag-retrieval/vector-databases","rag-retrieval/dense-vs-sparse-retrieval","model-internals/embeddings"],"tldr":"Dense retrieval reduces to one operation: score a query vector against every stored vector and keep the\ntop k. Dot product and cosine are the two scores that matter; cosine is the dot product of unit-length\nvectors, and squared Euclidean distance is the same quantity rearranged. The right choice is whichever\nthe embedding model was trained against, because training shaped the geometry. Pick the wrong one and\nrankings degrade silently, with no error to catch.","status":"ok"},{"id":"ann-indexes","key":"rag-retrieval/ann-indexes","module":"rag-retrieval","name":"ANN indexes (HNSW, IVF)","taxonomy_name":"ANN indexes (HNSW, IVF)","kind":"concept","difficulty":"core","est_minutes":17,"related":["rag-retrieval/similarity-search","rag-retrieval/vector-databases","rag-retrieval/metadata-filtering","rag-retrieval/recall-vs-precision-trade-off","data-architecture/vector-database-architecture","data-architecture/vector-store-sizing","evals/retrieval-evaluation"],"tldr":"Exact nearest-neighbor search reads every vector per query, which stops fitting a latency budget\nsomewhere in the millions. Approximate nearest neighbor (ANN) indexes give up a few percent of recall for\nsublinear search. HNSW builds a layered proximity graph and walks it greedily; IVF clusters the space\nwith k-means and scans only the closest clusters, often with product quantization to shrink the vectors.\nThe knobs (ef, nprobe) move you along a recall–latency curve you must measure, not assume.","status":"ok"},{"id":"dense-vs-sparse-retrieval","key":"rag-retrieval/dense-vs-sparse-retrieval","module":"rag-retrieval","name":"Dense vs sparse retrieval","taxonomy_name":"dense vs sparse retrieval","kind":"concept","difficulty":"core","est_minutes":14,"related":["rag-retrieval/bm25-internals","rag-retrieval/inverted-indexes","rag-retrieval/hybrid-search","rag-retrieval/embedding-models","rag-retrieval/similarity-search","rag-retrieval/retrieval-failure-diagnosis","model-internals/tokenization"],"tldr":"Sparse retrieval represents text as a vocabulary-sized vector that is almost all zeros (which words\nappear, weighted by BM25) and finds matches through an inverted index. Dense retrieval represents text as\na few hundred learned floats and finds matches by vector similarity. Sparse is exact about terms and blind\nto meaning; dense is fluent about meaning and unreliable about exact terms. Neither dominates, which is\nwhy production systems usually run both and fuse the results.","status":"ok"},{"id":"bm25-internals","key":"rag-retrieval/bm25-internals","module":"rag-retrieval","name":"BM25 internals","taxonomy_name":"BM25 internals","kind":"concept","difficulty":"core","est_minutes":15,"related":["rag-retrieval/inverted-indexes","rag-retrieval/dense-vs-sparse-retrieval","rag-retrieval/hybrid-search","rag-retrieval/retrieval-failure-diagnosis","model-internals/tokenization","evals/retrieval-evaluation"],"tldr":"BM25 scores a document for a query by summing, over query terms, a rarity weight (IDF) times a\nterm-frequency term that saturates and is normalized by document length. Each piece fixes a specific\nfailure of raw term counting: IDF stops common words dominating, saturation stops a term repeated 50\ntimes beating one repeated 5 times by 10×, and length normalization stops long documents winning by\nhaving more words. Two parameters, k1 and b, set how strong those corrections are.","status":"ok"},{"id":"inverted-indexes","key":"rag-retrieval/inverted-indexes","module":"rag-retrieval","name":"Inverted indexes","taxonomy_name":"inverted indexes","kind":"concept","difficulty":"core","est_minutes":13,"related":["rag-retrieval/bm25-internals","rag-retrieval/dense-vs-sparse-retrieval","rag-retrieval/hybrid-search","rag-retrieval/metadata-filtering","rag-retrieval/freshness-document-deletion-index-consistency","backend-fundamentals/database-design"],"tldr":"An inverted index flips the document→words mapping into words→documents: for every term, a sorted\nposting list of the documents that contain it, with counts and positions. A query then touches only the\nlists for its terms instead of every document, which is what makes lexical search over hundreds of\nmillions of documents answerable in milliseconds on a CPU. The design choices (sorted ids, compression,\nimmutable segments, skip pointers) all exist to make those list scans fast and updates safe.","status":"ok"},{"id":"hybrid-search","key":"rag-retrieval/hybrid-search","module":"rag-retrieval","name":"Hybrid search (BM25 + dense)","taxonomy_name":"hybrid search (BM25 + dense)","kind":"pattern","difficulty":"core","est_minutes":14,"related":["rag-retrieval/dense-vs-sparse-retrieval","rag-retrieval/bm25-internals","rag-retrieval/reranking","rag-retrieval/recall-vs-precision-trade-off","rag-retrieval/vector-databases","rag-retrieval/metadata-filtering","evals/retrieval-evaluation"],"tldr":"Hybrid search runs a lexical retriever (BM25) and a dense retriever (embeddings) on the same query and\nmerges their results, because the two fail on different queries: BM25 misses paraphrase, dense misses\nexact identifiers and out-of-domain jargon. The hard part is the merge: BM25 and cosine scores live on\nunrelated scales, so you fuse by rank (reciprocal rank fusion) or normalize per query before a weighted\nsum, and verify the gain with recall@k on labeled queries.","status":"ok"},{"id":"reranking","key":"rag-retrieval/reranking","module":"rag-retrieval","name":"Reranking (cross-encoder)","taxonomy_name":"reranking (cross-encoder)","kind":"pattern","difficulty":"core","est_minutes":15,"related":["rag-retrieval/hybrid-search","rag-retrieval/similarity-search","rag-retrieval/recall-vs-precision-trade-off","rag-retrieval/lost-in-the-middle","rag-retrieval/embedding-models","model-internals/self-attention","evals/retrieval-evaluation","infra-capacity-economics/latency-budgets"],"tldr":"A bi-encoder must compress each passage into one vector before it ever sees the query, so it cannot\nmodel how specific query words interact with specific passage words. A cross-encoder reads query and\npassage together in a single transformer pass and scores the pair directly, which is far more accurate\nand far too slow to run over a corpus. Reranking resolves that: a cheap retriever pulls a few dozen\ncandidates, the cross-encoder reorders them, and only the top few reach the prompt.","status":"ok"},{"id":"recall-vs-precision-trade-off","key":"rag-retrieval/recall-vs-precision-trade-off","module":"rag-retrieval","name":"Recall vs precision trade-off","taxonomy_name":"recall vs precision trade-off","kind":"concept","difficulty":"core","est_minutes":13,"related":["ml-fundamentals/precision-recall-f1","rag-retrieval/reranking","rag-retrieval/hybrid-search","rag-retrieval/lost-in-the-middle","rag-retrieval/retrieval-failure-diagnosis","rag-retrieval/chunking-strategies","evals/retrieval-evaluation","evals/golden-dataset"],"tldr":"Recall is the share of the answer-bearing passages you actually retrieved; precision is the share of what\nyou retrieved that is answer-bearing. Widening top-k raises recall and lowers precision at once, and in\nRAG both failures hurt: a missing passage means the model cannot answer, a noisy context means it may\nanswer from the wrong passage. The standard resolution is to stage retrieval: cheap and wide for recall\nfirst, expensive and narrow for precision second, each measured with its own metric.","status":"ok"},{"id":"query-rewriting","key":"rag-retrieval/query-rewriting","module":"rag-retrieval","name":"Query rewriting","taxonomy_name":"query rewriting","kind":"pattern","difficulty":"core","est_minutes":13,"related":["rag-retrieval/query-decomposition","rag-retrieval/hyde","rag-retrieval/hybrid-search","rag-retrieval/bm25-internals","rag-retrieval/metadata-filtering","rag-retrieval/retrieval-failure-diagnosis","prompting/context-engineering","prompting/prompt-injection"],"tldr":"The text a user types is written for a human, not for an index: it is short, refers to earlier turns,\nuses different words from the documents, and often buries one useful identifier in a wall of paste.\nQuery rewriting inserts an LLM step between the user and the retriever that turns the raw input into\none or more retrieval-friendly queries, because fixing the key at query time is far cheaper than\nre-indexing the corpus to tolerate every way a human might ask.","status":"ok"},{"id":"query-decomposition","key":"rag-retrieval/query-decomposition","module":"rag-retrieval","name":"Query decomposition","taxonomy_name":"query decomposition","kind":"pattern","difficulty":"core","est_minutes":13,"related":["rag-retrieval/query-rewriting","rag-retrieval/multi-hop-retrieval","rag-retrieval/agentic-rag","rag-retrieval/recall-vs-precision-trade-off","agents/task-decomposition","agents/parallel-tool-calls","evals/retrieval-evaluation"],"tldr":"A compound question (\"compare the refund windows of the Standard and Enterprise plans for EU customers\")\nembeds as one blurry point and its top-k is dominated by whichever half the index matches best, so the\nother half never reaches the prompt. Query decomposition has an LLM split the question into focused,\nstandalone sub-questions, retrieves for each (in parallel when they are independent), and answers from\nthe merged evidence or from per-sub-question answers. Independent parts fan out; dependent parts chain,\nwhich is multi-hop retrieval.","status":"ok"},{"id":"multi-hop-retrieval","key":"rag-retrieval/multi-hop-retrieval","module":"rag-retrieval","name":"Multi-hop retrieval","taxonomy_name":"multi-hop retrieval","kind":"pattern","difficulty":"advanced","est_minutes":15,"related":["rag-retrieval/query-decomposition","rag-retrieval/agentic-rag","rag-retrieval/graphrag","rag-retrieval/knowledge-graphs","rag-retrieval/reranking","prompting/react","agents/agent-loop","evals/retrieval-evaluation"],"tldr":"Some questions cannot be answered from any single passage because the second fact is only findable once\nyou know the first: \"who manages the author of the report for incident 4812?\" needs the author's name\nbefore \"manager of Alice\" is even a query. One-shot retrieval finds the first hop at best, since the\nterms that would retrieve the second do not exist yet. Multi-hop retrieval interleaves retrieving and\nreading: retrieve, extract the bridging fact, form the next query, repeat under a hop limit, then answer.","status":"ok"},{"id":"hyde","key":"rag-retrieval/hyde","module":"rag-retrieval","name":"HyDE (Hypothetical Document Embeddings)","taxonomy_name":"HyDE","kind":"pattern","difficulty":"core","est_minutes":12,"related":["rag-retrieval/query-rewriting","rag-retrieval/dense-vs-sparse-retrieval","rag-retrieval/embedding-models","rag-retrieval/similarity-search","rag-retrieval/hybrid-search","rag-retrieval/reranking","model-internals/hallucination","model-internals/embeddings"],"tldr":"HyDE asks an LLM to write a plausible answer passage first, embeds that hypothetical instead of (or\nalongside) the question, and retrieves the real passages nearest to it. It exists because a short\nquestion and a long answer are different kinds of text in different regions of embedding space; a\nhypothetical answer lands in the answer region even when its facts are wrong, because the encoder keeps\ntopic and vocabulary and washes out detail. It costs one generation per query.","status":"ok"},{"id":"parent-document-retrieval","key":"rag-retrieval/parent-document-retrieval","module":"rag-retrieval","name":"Parent-document retrieval","taxonomy_name":"parent-document retrieval","kind":"pattern","difficulty":"core","est_minutes":13,"related":["rag-retrieval/chunking-strategies","rag-retrieval/retrieval-granularity","rag-retrieval/chunk-overlap","rag-retrieval/contextual-retrieval","rag-retrieval/lost-in-the-middle","rag-retrieval/citations-grounding","rag-retrieval/recall-vs-precision-trade-off","rag-retrieval/freshness-document-deletion-index-consistency"],"tldr":"The best unit for matching a query is small, because a sentence or short paragraph embeds as a sharp\nkey; the best unit for answering is larger, because the surrounding section carries the definitions,\ntable headers and caveats the passage depends on. Parent-document retrieval separates the two: index\nsmall child chunks, each linked to a larger parent, search on the children, and hand the generator the\nparents. You get the recall of small chunks and the context of big ones, paying in context tokens.","status":"ok"},{"id":"contextual-retrieval","key":"rag-retrieval/contextual-retrieval","module":"rag-retrieval","name":"Contextual retrieval","taxonomy_name":"contextual retrieval","kind":"pattern","difficulty":"core","est_minutes":14,"related":["rag-retrieval/chunking-strategies","rag-retrieval/parent-document-retrieval","rag-retrieval/hybrid-search","rag-retrieval/bm25-internals","rag-retrieval/reranking","rag-retrieval/embedding-pipelines","prompting/prompt-caching","data-architecture/embedding-versioning-re-indexing-strategy"],"tldr":"Chunking destroys context: \"revenue grew 3% over the previous quarter\" no longer says which company or\nwhich quarter, so neither its embedding nor its BM25 terms can match a query that names them. Contextual\nretrieval fixes the index rather than the query: at ingestion an LLM reads the whole document plus each\nchunk and writes a short context that is prepended to the chunk before embedding and before BM25\nindexing. It costs one LLM call per chunk, made affordable by prompt caching, and adds no query-time\nlatency.","status":"ok"},{"id":"metadata-filtering","key":"rag-retrieval/metadata-filtering","module":"rag-retrieval","name":"Metadata filtering","taxonomy_name":"metadata filtering","kind":"pattern","difficulty":"core","est_minutes":14,"related":["rag-retrieval/ann-indexes","rag-retrieval/vector-databases","rag-retrieval/acl-aware-retrieval","rag-retrieval/hybrid-search","rag-retrieval/query-rewriting","rag-retrieval/embedding-pipelines","rag-retrieval/freshness-document-deletion-index-consistency","data-architecture/vector-database-architecture"],"tldr":"An embedding encodes what a chunk is about, not which tenant owns it, when it was written or which\nproduct version it describes. Metadata filtering stores those structured attributes next to each vector\nand applies them as hard predicates *inside* the search, because applying them afterwards to an\napproximate top-k returns too few results, or none, as soon as the predicate is selective. The\nengineering question is where the predicate runs: before the ANN walk, during it, or after it.","status":"ok"},{"id":"acl-aware-retrieval","key":"rag-retrieval/acl-aware-retrieval","module":"rag-retrieval","name":"ACL-aware retrieval","taxonomy_name":"ACL-aware retrieval","kind":"pattern","difficulty":"advanced","est_minutes":16,"related":["rag-retrieval/metadata-filtering","safety-security/cross-tenant-data-leakage","backend-fundamentals/authentication-vs-authorization","enterprise-integration/rbac-abac-mapping-to-customer-identity","system-design/tenant-isolation","agents/mcp-authentication-authorization-transport-security","scoping/data-access-and-permissions-discovery","rag-retrieval/freshness-document-deletion-index-consistency"],"tldr":"An enterprise index flattens documents with very different permissions into one searchable bag, yet\neach answer must draw only on documents the asking user could open themselves. ACL-aware retrieval turns\nthe authenticated identity into a hard predicate over each chunk's allowed principals inside the search,\nbecause the model cannot be trusted to withhold what it has already read and filtering after generation\nis too late. The hard parts are capturing permissions at ingestion, expanding groups at query time, and\nkeeping both fresh.","status":"ok"},{"id":"lost-in-the-middle","key":"rag-retrieval/lost-in-the-middle","module":"rag-retrieval","name":"Lost-in-the-middle","taxonomy_name":"lost-in-the-middle","kind":"concept","difficulty":"core","est_minutes":13,"related":["model-internals/context-window","model-internals/attention-mechanism","model-internals/positional-encoding","rag-retrieval/reranking","rag-retrieval/recall-vs-precision-trade-off","rag-retrieval/long-context-vs-rag","prompting/context-engineering","agents/context-compaction-summarization"],"tldr":"Language models do not read a long prompt uniformly: information at the beginning and the end is used\nfar more reliably than information in the middle, the U-shaped curve measured by the lost-in-the-middle\nexperiments. For RAG, retrieving more chunks can lower answer quality even when the right chunk is\npresent, since every extra chunk is a distractor that pushes the evidence toward the middle. So retrieve\nfewer and better, place the strongest evidence at the edges, and put the question last.","status":"ok"},{"id":"citations-grounding","key":"rag-retrieval/citations-grounding","name":"citations / grounding","module":"rag-retrieval","status":"missing"},{"id":"citation-correctness","key":"rag-retrieval/citation-correctness","name":"citation correctness","module":"rag-retrieval","status":"missing"},{"id":"graphrag","key":"rag-retrieval/graphrag","name":"GraphRAG","module":"rag-retrieval","status":"missing"},{"id":"knowledge-graphs","key":"rag-retrieval/knowledge-graphs","name":"knowledge graphs","module":"rag-retrieval","status":"missing"},{"id":"freshness-document-deletion-index-consistency","key":"rag-retrieval/freshness-document-deletion-index-consistency","module":"rag-retrieval","name":"Freshness, document deletion and index consistency","taxonomy_name":"freshness / document deletion / index consistency","kind":"practice","difficulty":"core","est_minutes":15,"related":["rag-retrieval/embedding-pipelines","rag-retrieval/metadata-filtering","rag-retrieval/acl-aware-retrieval","rag-retrieval/vector-databases","rag-retrieval/ann-indexes","data-architecture/embedding-versioning-re-indexing-strategy","enterprise-integration/incremental-synchronization-and-cdc","data-architecture/data-retention-and-deletion-architecture"],"tldr":"A retrieval index is a derived copy of the source documents, and it starts going stale the moment it is\nbuilt. Freshness is how long a source change takes to become visible in retrieval; deletion is removing\nevery derived artifact of a document when the source goes away; consistency is never serving a mix of\nold and new versions of the same document. All three reduce to one discipline: stable document identity,\nversioned chunk ids, write-new-then-delete-old, and a reconciliation job for whatever the incremental\npath missed.","status":"ok"},{"id":"retrieval-failure-diagnosis","key":"rag-retrieval/retrieval-failure-diagnosis","name":"retrieval failure diagnosis","module":"rag-retrieval","status":"missing"},{"id":"long-context-vs-rag","key":"rag-retrieval/long-context-vs-rag","name":"long-context vs RAG","module":"rag-retrieval","status":"missing"},{"id":"agentic-rag","key":"rag-retrieval/agentic-rag","name":"agentic RAG","module":"rag-retrieval","status":"missing"},{"id":"document-parsing","key":"rag-retrieval/document-parsing","name":"document parsing (OCR, layout, tables)","module":"rag-retrieval","status":"missing"}]},{"id":"agents","tier":1,"order":5,"title":"Agents","intro":null,"topics":[{"id":"agent-loop","key":"agents/agent-loop","module":"agents","name":"Agent loop","taxonomy_name":"agent loop","kind":"concept","difficulty":"core","est_minutes":14,"related":["agents/tool-calling","agents/workflows-vs-agents","agents/state-machines","agents/context-compaction-summarization","agent-reliability/max-step-budgets","agent-reliability/stopping-conditions-termination","agent-reliability/loop-detection","prompting/react"],"tldr":"An agent is a loop, not a model. The model proposes an action as a structured tool call, your code\n(the harness) executes it, the result is appended to the transcript, and the model is called again with\neverything so far, until it stops asking for actions or a budget runs out. The model only ever chooses\nthe next step; the loop is what lets it observe the consequence of each step and correct course, which\nis exactly what one-shot generation cannot do.","status":"ok"},{"id":"tool-calling","key":"agents/tool-calling","module":"agents","name":"Tool calling","taxonomy_name":"tool calling","kind":"concept","difficulty":"core","est_minutes":13,"related":["agents/agent-loop","agents/tool-schemas-and-argument-validation","agents/tool-selection-accuracy","agents/tool-result-interpretation","agents/parallel-tool-calls","agents/model-context-protocol","prompting/function-tool-calling","prompting/structured-outputs-json-mode"],"tldr":"Tool calling lets a model request an action instead of describing one. Given declared tools (a name, a\ndescription and a JSON Schema for the arguments), the model emits a structured call, your code executes\nit and returns the result, and the model continues with that result in context. It exists because models\ncannot reach live data or cause effects, and because parsing actions out of free text is unreliable; a\ntrained structured format turns \"text that looks like a command\" into a typed request.","status":"ok"},{"id":"tool-schemas-and-argument-validation","key":"agents/tool-schemas-and-argument-validation","module":"agents","name":"Tool schemas & argument validation","taxonomy_name":"tool schemas & argument validation","kind":"practice","difficulty":"core","est_minutes":13,"related":["agents/tool-calling","agents/typed-tool-contracts","agents/tool-selection-accuracy","python-for-ai/pydantic","prompting/structured-outputs-json-mode","serving-inference/structured-constrained-generation","safety-security/output-validation","agent-reliability/tool-call-success-rate"],"tldr":"The input schema is the model's entire specification of a tool's arguments, and validation at the\nharness boundary is where the model's mistakes are caught before they become side effects. Design\nschemas small, flat and explicit (types, enums, required fields, descriptions that state units and\nformats); validate in layers, shape, then meaning, then permission; and send failures back as error\nresults the model can act on, because a model that sees \"amount must be in cents\" fixes itself, while\na 500 from your handler ends the run.","status":"ok"},{"id":"typed-tool-contracts","key":"agents/typed-tool-contracts","module":"agents","name":"Typed tool contracts","taxonomy_name":"typed tool contracts","kind":"pattern","difficulty":"core","est_minutes":12,"related":["agents/tool-schemas-and-argument-validation","agents/tool-result-interpretation","agents/model-context-protocol","python-for-ai/pydantic","python-for-ai/contract-testing","agent-reliability/tool-adapters-service-interfaces","agent-reliability/idempotent-tool-execution","backend-fundamentals/api-versioning-and-backward-compatibility"],"tldr":"A typed tool contract defines a tool once, as types: an input model, an output model, an enumerated set\nof error kinds, and metadata about side effects. Everything else is derived from it: the JSON Schema the\nmodel sees, the handler's signature, the serialization of results, the tests. Because the schema and the\nhandler share one source of truth they cannot drift apart, and because the output is typed the model\nreads results of a stable shape instead of whatever the upstream API happened to return.","status":"ok"},{"id":"tool-selection-accuracy","key":"agents/tool-selection-accuracy","module":"agents","name":"Tool selection accuracy","taxonomy_name":"tool selection accuracy","kind":"metric","difficulty":"core","est_minutes":12,"related":["agents/tool-calling","agents/tool-schemas-and-argument-validation","agents/model-context-protocol","agent-reliability/tool-call-success-rate","agent-reliability/agent-trajectory-evaluation","evals/error-analysis","evals/golden-dataset","prompting/context-engineering"],"tldr":"Tool selection accuracy is the fraction of decision points at which the model chooses the right tool,\nincluding choosing *no* tool, with arguments that are valid and correct. It falls as the tool count\ngrows and as descriptions overlap, and it is the first agent metric worth instrumenting, because a wrong\nselection wastes a step at best and causes a wrong side effect at worst, and because it isolates the one\ndecision the model makes at every step from everything else that can go wrong in a run.","status":"ok"},{"id":"tool-result-interpretation","key":"agents/tool-result-interpretation","module":"agents","name":"Tool-result interpretation","taxonomy_name":"tool-result interpretation","kind":"concept","difficulty":"core","est_minutes":13,"related":["agents/tool-calling","agents/typed-tool-contracts","agents/parallel-tool-calls","agents/context-compaction-summarization","safety-security/prompt-injection","prompting/prompt-injection","prompting/context-engineering","agent-reliability/tool-call-success-rate"],"tldr":"A tool result is a prompt the model reads. Its shape decides whether the model correctly understands\nsuccess, failure, \"nothing found\" and \"more available\", and whether it mistakes content inside the\nresult for instructions. So results are designed for the reader: an explicit status, counts and\ntruncation markers, units in field names, only the fields the task needs, errors flagged as errors, and\nanything that came from outside the system labelled as data that cannot issue commands.","status":"ok"},{"id":"parallel-tool-calls","key":"agents/parallel-tool-calls","module":"agents","name":"Parallel tool calls","taxonomy_name":"parallel tool calls","kind":"pattern","difficulty":"core","est_minutes":12,"related":["agents/tool-calling","agents/agent-loop","agents/typed-tool-contracts","python-for-ai/asyncio","python-for-ai/async-cancellation-and-exception-propagation","agent-reliability/idempotent-tool-execution","backend-fundamentals/pagination-rate-limits-api-quotas","serving-inference/throughput-vs-latency"],"tldr":"A model can emit several tool calls in a single turn. The harness runs the independent ones\nconcurrently and returns all of their results together in one message, which removes a full model\nround trip per call and cuts latency for independent reads. The model decides what to batch, but only\nthe harness knows which tools are safe to run at the same time, so it must schedule, cap concurrency,\nisolate failures and keep the result message intact.","status":"ok"},{"id":"model-context-protocol","key":"agents/model-context-protocol","module":"agents","name":"Model Context Protocol (MCP)","taxonomy_name":"Model Context Protocol (MCP)","kind":"tool","difficulty":"core","est_minutes":14,"related":["agents/mcp-authentication-authorization-transport-security","agents/a2a-protocol","agents/tool-calling","agents/typed-tool-contracts","agents/tool-selection-accuracy","python-for-ai/mcp-python-sdk","node-ts-for-ai/mcp-typescript-sdk","agent-reliability/tool-permissions-and-least-privilege"],"tldr":"MCP is an open protocol, released by Anthropic in late 2024, that standardizes how an AI application\nconnects to external capability servers. A server exposes tools, resources and prompts over JSON-RPC;\nany MCP-capable host can discover and call them, so an integration is written once instead of once\nper framework. It solves the plumbing of connecting models to systems; it does not remove the need for\nauthentication, trust decisions about third-party servers, or keeping the tool set small.","status":"ok"},{"id":"mcp-authentication-authorization-transport-security","key":"agents/mcp-authentication-authorization-transport-security","module":"agents","name":"MCP authentication / authorization / transport security","taxonomy_name":"MCP authentication / authorization / transport security","kind":"concept","difficulty":"advanced","est_minutes":18,"related":["agents/model-context-protocol","agents/a2a-protocol","backend-fundamentals/oauth-2-0-oidc","backend-fundamentals/authentication-vs-authorization","agent-reliability/tool-permissions-and-least-privilege","safety-security/tool-privilege-escalation","safety-security/prompt-injection","fastapi-for-ai/api-keys-oauth2-jwt"],"tldr":"MCP defines how a host talks to a tool server (JSON-RPC over stdio or Streamable HTTP) but a tool\ncall is only safe if the server knows *who* is asking and *what* they may do. For local stdio servers\nthe operating-system process boundary is the security model. For remote HTTP servers the spec layers\nOAuth 2.1 on top: discovery, PKCE, audience-bound tokens, scopes. The model is never the trust\nboundary; a prompt-injected agent will ask for anything, so every check must live below it.","status":"ok"},{"id":"a2a-protocol","key":"agents/a2a-protocol","module":"agents","name":"A2A protocol (Agent2Agent)","taxonomy_name":"A2A protocol","kind":"concept","difficulty":"core","est_minutes":14,"related":["agents/model-context-protocol","agents/mcp-authentication-authorization-transport-security","agents/multi-agent-patterns","agent-reliability/structured-event-streams","agent-reliability/conversation-execution-identifiers","backend-fundamentals/rest-graphql-api-design","serving-inference/streaming"],"tldr":"A2A is an open protocol (announced by Google in 2025, later moved to the Linux Foundation) for one\nagent to discover another agent, hand it a task, and follow that task to completion over HTTP without\nseeing inside it. Where MCP connects an agent to *tools* with fixed schemas, A2A connects an agent to\n*other agents* that are opaque, long-running and may ask clarifying questions. Its core objects are the\nAgent Card for discovery and the Task with a state machine for the work itself.","status":"ok"},{"id":"planning","key":"agents/planning","module":"agents","name":"Planning","taxonomy_name":"planning","kind":"concept","difficulty":"core","est_minutes":15,"related":["agents/agent-loop","agents/task-decomposition","agents/reflection-self-critique","agents/workflows-vs-agents","agents/state-machines","prompting/react","prompting/chain-of-thought","agent-reliability/max-step-budgets"],"tldr":"Planning is how an agent decides *which* actions to take and in *what order* before, or while,\ntaking them. A purely reactive loop picks the next step from whatever is in context and drifts on long\ntasks; an explicit plan gives the loop a target to measure progress against and a place to replan when\nan action fails. The design choice is where planning happens: interleaved with actions, up front, as a\nsearch over alternatives, or hierarchically, and each choice trades tokens for robustness.","status":"ok"},{"id":"task-decomposition","key":"agents/task-decomposition","module":"agents","name":"Task decomposition","taxonomy_name":"task decomposition","kind":"pattern","difficulty":"core","est_minutes":13,"related":["agents/planning","agents/multi-agent-patterns","agents/parallel-tool-calls","agents/workflows-vs-agents","rag-retrieval/query-decomposition","prompting/chain-of-thought","agent-reliability/max-step-budgets","model-internals/context-window"],"tldr":"Task decomposition splits a large job into subtasks that each fit comfortably in one model call's\nattention, can be verified on their own, and expose a small, explicit interface to the rest. Planning\ndecides the *order* of work; decomposition decides its *shape*: granularity, dependencies and\ncontracts. Done well it unlocks parallelism, cheaper models per piece and isolated failures. Done badly\nit multiplies coordination overhead and loses context at every boundary.","status":"ok"},{"id":"reflection-self-critique","key":"agents/reflection-self-critique","module":"agents","name":"Reflection / self-critique","taxonomy_name":"reflection / self-critique","kind":"pattern","difficulty":"core","est_minutes":14,"related":["agents/agent-loop","agents/planning","agents/multi-agent-patterns","agents/tool-result-interpretation","agent-reliability/agent-trajectory-evaluation","evals/hallucination-evaluation","prompting/chain-of-thought"],"tldr":"Reflection is a generate–critique–revise loop: the agent produces an attempt, evaluates it against a\ngoal or rubric, and tries again using what it learned. It pays off when the critique brings *new\ninformation*: a failing test, a tool error, a verifier's verdict, or a fresh context with a rubric.\nPure \"look again and fix your mistakes\" with no new signal is unreliable and can turn right answers\ninto wrong ones, so the design question is always where the critique's evidence comes from.","status":"ok"},{"id":"multi-agent-patterns","key":"agents/multi-agent-patterns","module":"agents","name":"Multi-agent patterns (orchestrator-worker, handoffs)","taxonomy_name":"multi-agent patterns (orchestrator-worker, handoffs)","kind":"pattern","difficulty":"core","est_minutes":16,"related":["agents/task-decomposition","agents/planning","agents/reflection-self-critique","agents/a2a-protocol","agents/state-machines","agents/workflows-vs-agents","agent-reliability/conversation-execution-identifiers","observability/distributed-tracing-across-services"],"tldr":"Multi-agent systems split work across several model loops, each with its own context, prompt and\ntools. **Orchestrator-worker**: one agent plans, delegates subtasks to parallel workers and\nsynthesises their structured results. **Handoffs**: one active agent at a time, with control passed\nto a specialist when the conversation needs its tools. The gain is context isolation and\nspecialisation; the cost is coordination, multiplied tokens and harder debugging, so a single\nwell-built agent is the default until it runs out of room.","status":"ok"},{"id":"agent-memory","key":"agents/agent-memory","module":"agents","name":"Agent memory (short-term, long-term, episodic)","taxonomy_name":"agent memory (short-term, long-term, episodic)","kind":"concept","difficulty":"core","est_minutes":15,"related":["agents/memory-retrieval-update-deletion-policies","agents/context-compaction-summarization","agents/agent-loop","model-internals/context-window","prompting/context-engineering","rag-retrieval/vector-databases","agent-reliability/state-persistence-and-conversation-recovery","agents/reflection-self-critique"],"tldr":"A language model is stateless: it \"remembers\" only what is in the current context window. Agent\nmemory decides what goes into that window and what lives outside it. **Short-term** memory is the\nwindow itself, managed by truncation and compaction. **Long-term** memory survives sessions and holds\nsemantic facts and procedures. **Episodic** memory records specific timestamped events so the agent\nrecalls what happened, not just what is true. Memory is RAG over the agent's own history, plus a\nwrite path.","status":"ok"},{"id":"memory-retrieval-update-deletion-policies","key":"agents/memory-retrieval-update-deletion-policies","module":"agents","name":"Memory retrieval / update / deletion policies","taxonomy_name":"memory retrieval / update / deletion policies","kind":"practice","difficulty":"advanced","est_minutes":14,"related":["agents/agent-memory","agents/context-compaction-summarization","rag-retrieval/metadata-filtering","rag-retrieval/freshness-document-deletion-index-consistency","data-architecture/data-retention-and-deletion-architecture","agent-runtime-architecture/multi-tenant-state-isolation","safety-security/pii-redaction","safety-security/prompt-injection"],"tldr":"A memory store without policies degrades into a pile of stale, contradictory and occasionally\npoisoned text. Three policies keep it useful and lawful: a **retrieval** policy that decides which\nmemories enter the context (scoped, scored by relevance, recency and importance, within a budget); an\n**update** policy that decides whether new information adds, supersedes or is ignored, with provenance;\nand a **deletion** policy that expires, caps and erases memories on schedule and on request, across\nevery copy including indexes and backups.","status":"ok"},{"id":"context-compaction-summarization","key":"agents/context-compaction-summarization","module":"agents","name":"Context compaction / summarization","taxonomy_name":"context compaction / summarization","kind":"pattern","difficulty":"core","est_minutes":14,"related":["agents/agent-loop","agents/agent-memory","agents/memory-retrieval-update-deletion-policies","model-internals/context-window","prompting/prompt-caching","prompting/context-engineering","rag-retrieval/lost-in-the-middle","agent-reliability/state-persistence-and-conversation-recovery"],"tldr":"An agent's transcript grows by one action and one observation per step, and every step re-sends all\nof it. Left alone it hits the context limit, costs O(n²) tokens over a run, and degrades reasoning well\nbefore the hard limit. Compaction replaces older material with something shorter: pruned tool outputs,\na structured summary, or a pointer to state kept outside the context. The hard part is not shortening;\nit is deciding what must survive so the agent keeps solving the task it was given.","status":"ok"},{"id":"state-machines","key":"agents/state-machines","module":"agents","name":"State machines","taxonomy_name":"state machines","kind":"pattern","difficulty":"core","est_minutes":13,"related":["agents/agent-loop","agents/workflows-vs-agents","agents/frameworks","agents/approval-gates-for-consequential-actions","agent-reliability/durable-execution-and-checkpointing","agent-reliability/state-and-checkpoint-stores","agent-reliability/stopping-conditions-termination","system-design/workflow-orchestration"],"tldr":"A bare agent loop has one state, \"running\", and all control lives in the model's head. A state machine\nmakes phases explicit: named states, the tools and transitions allowed in each, guards the harness\nchecks, and terminal states every path must reach. The model still chooses, but only among transitions\nthe machine permits, so an invariant like \"never deploy before tests pass\" is enforced in code, and the\npair (state, data) can be checkpointed and resumed after a crash.","status":"ok"},{"id":"human-in-the-loop","key":"agents/human-in-the-loop","module":"agents","name":"Human-in-the-loop","taxonomy_name":"human-in-the-loop","kind":"pattern","difficulty":"core","est_minutes":13,"related":["agents/approval-gates-for-consequential-actions","agents/state-machines","safety-security/excessive-agency","agent-runtime-architecture/approval-and-authorization-boundaries","customer-data-evaluation/shadow-mode-validation","customer-data-evaluation/sme-review-and-annotation-guidelines","customer-data-evaluation/production-feedback-classification","evals/offline-vs-online-evaluation"],"tldr":"Human-in-the-loop means placing a person at chosen points of an agent's run: before an action (approve\nor edit), during it (steer, clarify) or after it (review a sample, correct, label). It exists because\nmodels err too often for some actions and because the person holds authority and information the agent\nlacks. Human attention is the scarcest resource, so the design problem is where it buys the most risk\nreduction and how to keep each decision cheap, informed and genuine rather than a rubber stamp.","status":"ok"},{"id":"approval-gates-for-consequential-actions","key":"agents/approval-gates-for-consequential-actions","module":"agents","name":"Approval gates for consequential actions","taxonomy_name":"approval gates for consequential actions","kind":"pattern","difficulty":"core","est_minutes":14,"related":["agents/human-in-the-loop","agents/tool-calling","agents/state-machines","agent-reliability/idempotent-tool-execution","agent-reliability/tool-permissions-and-least-privilege","agent-reliability/durable-execution-and-checkpointing","agent-runtime-architecture/approval-and-authorization-boundaries","safety-security/excessive-agency"],"tldr":"An approval gate is a checkpoint the harness places between the model proposing an action and the tool\nexecuting it, for actions classified as consequential: irreversible, costly, externally visible or\nsecurity-relevant. It works because it lives in the tool executor, where the model cannot bypass it,\nrather than in the prompt. A working gate needs four parts: a classifier of which calls are\nconsequential, a durable pause, an approval bound to the exact arguments by an authorized person, and a\nresume path that executes exactly once.","status":"ok"},{"id":"sandboxing","key":"agents/sandboxing","module":"agents","name":"Sandboxing","taxonomy_name":"sandboxing","kind":"pattern","difficulty":"core","est_minutes":14,"related":["agents/computer-use","agents/approval-gates-for-consequential-actions","agent-reliability/tool-permissions-and-least-privilege","agent-runtime-architecture/secrets-and-credential-isolation","safety-security/prompt-injection","safety-security/tool-privilege-escalation","safety-security/data-leakage","backend-fundamentals/secrets-management"],"tldr":"A sandbox is an execution boundary around an agent's actions, limiting what the code it runs and the\ntools it calls can reach: filesystem, network, credentials, processes, CPU, memory and time. It exists\nbecause an agent's actions are untrusted input: the model is probabilistic and prompt-injectable, and it\nruns with whatever access you gave it. The goal is bounded blast radius: a wrong or hijacked action can\nwaste a container, not leak a database. Isolation strength, startup latency and compatibility trade\nagainst each other.","status":"ok"},{"id":"computer-use","key":"agents/computer-use","module":"agents","name":"Computer use","taxonomy_name":"computer use","kind":"concept","difficulty":"core","est_minutes":13,"related":["agents/sandboxing","agents/tool-calling","agents/approval-gates-for-consequential-actions","agents/context-compaction-summarization","agent-reliability/max-step-budgets","multimodal/vision-language-models","safety-security/prompt-injection"],"tldr":"Computer use is an agent that perceives a screen through screenshots and acts through the generic input\nprimitives every application accepts: mouse, keyboard, scroll. It exists because much real work lives\nin GUIs with no API. It is the most general tool and the least efficient: each step costs a\nscreenshot's worth of vision tokens plus a round trip, actions are coordinate-based, and errors compound\nacross dozens of steps. Prefer APIs or DOM access where they exist, use computer use for the long tail,\nand sandbox it.","status":"ok"},{"id":"workflows-vs-agents","key":"agents/workflows-vs-agents","module":"agents","name":"Workflows vs agents","taxonomy_name":"workflows vs agents","kind":"decision","difficulty":"intro","est_minutes":12,"related":["agents/agent-loop","agents/state-machines","agents/frameworks","agents/planning","agents/approval-gates-for-consequential-actions","agent-reliability/max-step-budgets","agent-reliability/agent-trajectory-evaluation","system-design/workflow-orchestration"],"tldr":"A workflow is LLM calls orchestrated along paths your code defines; an agent is a loop in which the\nmodel decides the next step from what it observes. The choice is about path predictability: if you can\ndraw the flowchart, build the workflow, because it is cheaper, bounded and unit-testable. Reach for an\nagent when the next step depends on observations you cannot foresee. Most production systems are\nworkflows with agentic islands, not the other way round.","status":"ok"},{"id":"frameworks","key":"agents/frameworks","module":"agents","name":"Frameworks (LangGraph, LangChain, LlamaIndex, Pydantic AI, DSPy)","taxonomy_name":"frameworks (LangGraph, LangChain, LlamaIndex, Pydantic AI, DSPy)","kind":"tool","difficulty":"core","est_minutes":15,"related":["agents/agent-loop","agents/state-machines","agents/workflows-vs-agents","agents/typed-tool-contracts","agent-reliability/durable-execution-and-checkpointing","python-for-ai/pydantic","prompting/prompt-engineering","rag-retrieval/embedding-pipelines"],"tldr":"Agent frameworks package the plumbing around model calls: control flow, state, tool wiring, retries,\npersistence, observability. LangChain is the broad integration layer; LangGraph is a typed\nstate-machine runtime for agents; LlamaIndex is the data and retrieval framework with agent workflows\non top; Pydantic AI is a small, type-first agent library; DSPy replaces hand-written prompts with\ndeclarative modules compiled against a metric. Each trades speed for abstraction you must understand,\nso choose by the plumbing problem you actually have.","status":"ok"}]},{"id":"agent-reliability","tier":1,"order":6,"title":"Agent reliability & runtime","intro":null,"topics":[{"id":"stopping-conditions-termination","key":"agent-reliability/stopping-conditions-termination","module":"agent-reliability","name":"Stopping conditions / termination","taxonomy_name":"stopping conditions / termination","kind":"concept","difficulty":"core","est_minutes":13,"related":["agent-reliability/max-step-budgets","agent-reliability/loop-detection","agent-reliability/durable-execution-and-checkpointing","agents/agent-loop","agents/state-machines","agents/human-in-the-loop","safety-security/excessive-agency"],"tldr":"An agent loop is `while True: call model; run tools`. Nothing in it ends on its own, so termination\nhas to be designed. A stopping condition is a function over the run's state that returns continue,\ndone or abort, combining the model's own \"I am finished\" signal with programmatic goal checks and hard\nresource limits. It has to be built this way because a model deciding alone stops too early, too late\nor never, and each failure looks like success unless the outcome is labelled.","status":"ok"},{"id":"max-step-budgets","key":"agent-reliability/max-step-budgets","module":"agent-reliability","name":"Max-step budgets","taxonomy_name":"max-step budgets","kind":"pattern","difficulty":"core","est_minutes":12,"related":["agent-reliability/stopping-conditions-termination","agent-reliability/loop-detection","agent-reliability/durable-execution-and-checkpointing","agents/agent-loop","observability/token-cost-tracking","infra-capacity-economics/latency-budgets","serving-inference/timeouts"],"tldr":"A max-step budget caps how many model calls (and, more usefully, how many tokens, seconds and\ndollars) one run may spend before the harness stops it. It is a backstop against runs that never\nterminate, not a target: set it from the step distribution of successful runs so it rarely fires,\nwarn the model before it fires so it can hand back a labelled partial result, and treat every\nexhaustion as a stuck-agent signal worth investigating.","status":"ok"},{"id":"loop-detection","key":"agent-reliability/loop-detection","module":"agent-reliability","name":"Loop detection","taxonomy_name":"loop detection","kind":"pattern","difficulty":"core","est_minutes":13,"related":["agent-reliability/stopping-conditions-termination","agent-reliability/max-step-budgets","agent-reliability/audit-logs-execution-traces","agents/agent-loop","agents/reflection-self-critique","agents/tool-result-interpretation"],"tldr":"Agents get stuck in loops: the same tool call with the same arguments, a two-state oscillation, or a\nstretch of actions that produces no new information. Budgets eventually stop them, but only after\nburning the whole allowance. Loop detection watches the action stream for exact repeats, short cycles\nand no-progress runs, and responds with an escalation ladder (tell the model, block the call, force a\nreplan, abort) because the cheapest fix is usually to make the repetition visible to the model.","status":"ok"},{"id":"durable-execution-and-checkpointing","key":"agent-reliability/durable-execution-and-checkpointing","module":"agent-reliability","name":"Durable execution & checkpointing","taxonomy_name":"durable execution & checkpointing","kind":"concept","difficulty":"core","est_minutes":15,"related":["agent-reliability/state-persistence-and-conversation-recovery","agent-reliability/state-and-checkpoint-stores","agent-reliability/idempotent-tool-execution","agent-reliability/conversation-execution-identifiers","reliability/durable-workflow-execution","backend-fundamentals/background-jobs-durable-workers","system-design/workflow-orchestration"],"tldr":"An agent run is a long, multi-step program whose process can die at any moment (deploys, OOMs, spot\npreemption) and whose steps cost real money and cause real side effects. Durable execution means the\nrun's progress outlives the process; checkpointing is the mechanism: persist state at step boundaries\nso a resume continues from the last boundary instead of from scratch. The hard part is the boundary\naround side effects, which is why checkpointing is inseparable from idempotent tools.","status":"ok"},{"id":"state-persistence-and-conversation-recovery","key":"agent-reliability/state-persistence-and-conversation-recovery","module":"agent-reliability","name":"State persistence & conversation recovery","taxonomy_name":"state persistence & conversation recovery","kind":"pattern","difficulty":"core","est_minutes":13,"related":["agent-reliability/durable-execution-and-checkpointing","agent-reliability/state-and-checkpoint-stores","agent-reliability/conversation-execution-identifiers","agents/agent-memory","agents/context-compaction-summarization","system-design/memory-architecture","fastapi-for-ai/cancellation-on-client-disconnect"],"tldr":"Conversation state (the transcript a user returns to) and execution state (one in-flight agent run)\nhave different lifetimes and must be persisted separately. Store the transcript as an append-only,\nsequence-numbered event log that is the source of truth, and derive the model's context from it as a\nview. Recovery then means reconnecting clients catch up from their last sequence number, interrupted\nturns are repaired into a well-formed history, and the user never sees a dangling or duplicated turn.","status":"ok"},{"id":"state-and-checkpoint-stores","key":"agent-reliability/state-and-checkpoint-stores","module":"agent-reliability","name":"State & checkpoint stores","taxonomy_name":"state & checkpoint stores","kind":"decision","difficulty":"core","est_minutes":13,"related":["agent-reliability/durable-execution-and-checkpointing","agent-reliability/state-persistence-and-conversation-recovery","backend-fundamentals/redis","backend-fundamentals/postgresql-transactions-and-isolation-levels","backend-fundamentals/nosql","agent-runtime-architecture/multi-tenant-state-isolation","data-architecture/data-retention-and-deletion-architecture"],"tldr":"Where agent state lives determines how fast each step is, what survives a crash, and how you isolate\ntenants and delete data. The decision weighs per-step write latency against durability, blob size\nagainst query needs, and short TTLs against audit retention. A sound default is a relational store\n(Postgres) for run records, events and small snapshots, object storage for large tool outputs, and\nRedis only for ephemeral leases and stream buffers, with a tenant id on every row.","status":"ok"},{"id":"conversation-execution-identifiers","key":"agent-reliability/conversation-execution-identifiers","module":"agent-reliability","name":"Conversation / execution identifiers","taxonomy_name":"conversation / execution identifiers","kind":"concept","difficulty":"core","est_minutes":11,"related":["agent-reliability/state-persistence-and-conversation-recovery","agent-reliability/idempotent-tool-execution","agent-reliability/durable-execution-and-checkpointing","agent-reliability/audit-logs-execution-traces","observability/distributed-tracing-across-services","agent-runtime-architecture/multi-tenant-state-isolation","fastapi-for-ai/idempotency-keys"],"tldr":"An agent system needs a hierarchy of identifiers, not one \"session id\": tenant and user for scope,\nconversation id for the long-lived transcript, turn id for one user request, run id for one execution\nattempt of that turn, step and tool-call ids within it, plus trace ids for cross-service correlation.\nEach id answers a different question (resume what, dedupe what, bill whom, trace which), and\nconflating them is why retries double-act and logs cannot be joined.","status":"ok"},{"id":"idempotent-tool-execution","key":"agent-reliability/idempotent-tool-execution","module":"agent-reliability","name":"Idempotent tool execution","taxonomy_name":"idempotent tool execution","kind":"pattern","difficulty":"core","est_minutes":14,"related":["agent-reliability/durable-execution-and-checkpointing","agent-reliability/conversation-execution-identifiers","serving-inference/idempotency","fastapi-for-ai/idempotency-keys","system-design/exactly-once-processing-limitations","system-design/outbox-inbox-patterns","enterprise-integration/retry-deduplication-reconciliation","agents/approval-gates-for-consequential-actions"],"tldr":"Agents retry constantly: the model retries after errors, the harness retries after timeouts, the\ndurable runtime re-executes after crashes, and each retry of a side-effecting tool risks a duplicate.\nExactly-once execution across a network boundary is impossible, so the design target is at-least-once\nexecution with idempotent effects: classify tools, derive a deterministic idempotency key per call,\npass it downstream or dedupe locally, and gate what cannot be made idempotent behind approvals or an\noutbox.","status":"ok"},{"id":"tool-permissions-and-least-privilege","key":"agent-reliability/tool-permissions-and-least-privilege","module":"agent-reliability","name":"Tool permissions & least privilege","taxonomy_name":"tool permissions & least privilege","kind":"practice","difficulty":"core","est_minutes":14,"related":["agent-reliability/idempotent-tool-execution","agent-reliability/audit-logs-execution-traces","agent-reliability/tool-adapters-service-interfaces","safety-security/excessive-agency","safety-security/tool-privilege-escalation","safety-security/prompt-injection","agent-runtime-architecture/approval-and-authorization-boundaries","agent-runtime-architecture/secrets-and-credential-isolation"],"tldr":"An agent's tools are the only way its text turns into effects, and its text can be steered by anything\nin its context, including data it was asked to read. Least privilege means each run gets exactly the\ntools, arguments, identities and credentials the task needs, enforced in the runtime rather than\nrequested in the prompt, so that a wrong or hijacked decision has a bounded blast radius instead of the\ndeveloper's full access.","status":"ok"},{"id":"tool-adapters-service-interfaces","key":"agent-reliability/tool-adapters-service-interfaces","module":"agent-reliability","name":"Tool adapters / service interfaces","taxonomy_name":"tool adapters / service interfaces","kind":"pattern","difficulty":"core","est_minutes":13,"related":["agent-reliability/tool-permissions-and-least-privilege","agent-reliability/idempotent-tool-execution","agent-reliability/tool-call-success-rate","agents/typed-tool-contracts","agents/tool-schemas-and-argument-validation","agents/model-context-protocol","agent-runtime-architecture/cross-language-api-contracts","serving-inference/retry-strategies"],"tldr":"The model speaks in small typed tool calls; real services speak HTTP with auth, pagination, rate limits\nand 40-field responses. A tool adapter is the layer that owns that translation: it validates arguments,\nenforces policy, injects credentials, applies timeouts, retries and idempotency, and turns every outcome,\nincluding failure, into a compact structured result the model can reason about. Keeping that layer\nexplicit is what makes tools testable, swappable and safe.","status":"ok"},{"id":"structured-event-streams","key":"agent-reliability/structured-event-streams","module":"agent-reliability","name":"Structured event streams","taxonomy_name":"structured event streams","kind":"pattern","difficulty":"core","est_minutes":14,"related":["agent-reliability/durable-execution-and-checkpointing","agent-reliability/state-persistence-and-conversation-recovery","agent-reliability/audit-logs-execution-traces","agent-reliability/deterministic-replay-and-reproducibility","agent-reliability/conversation-execution-identifiers","serving-inference/streaming","fastapi-for-ai/server-sent-events","system-design/event-driven-architecture"],"tldr":"An agent run is not a function call that returns a string; it is a sequence of things that happened:\nmodel requests, token deltas, tool calls, permission decisions, results, retries, completions. Emitting\nthose as one ordered, typed, versioned stream of events, and deriving the UI, the persisted state, the\ntrace and the eval trajectory from that stream, replaces four drifting ad hoc formats with one source of\ntruth that can be replayed.","status":"ok"},{"id":"audit-logs-execution-traces","key":"agent-reliability/audit-logs-execution-traces","module":"agent-reliability","name":"Audit logs / execution traces","taxonomy_name":"audit logs / execution traces","kind":"practice","difficulty":"core","est_minutes":14,"related":["agent-reliability/structured-event-streams","agent-reliability/deterministic-replay-and-reproducibility","agent-reliability/tool-permissions-and-least-privilege","agent-reliability/conversation-execution-identifiers","observability/tracing","observability/spans","observability/opentelemetry","observability/langfuse"],"tldr":"An execution trace answers \"what did the agent do and why\" for engineers debugging a run; an audit log\nanswers \"who did what with whose authority\" for security, compliance and incident response. They share\nthe same facts, best derived from one event stream, but differ in what they must contain, how long they\nlive, who can read them and whether they may ever be altered. Build both on purpose, not one as an\nafterthought of the other.","status":"ok"},{"id":"deterministic-replay-and-reproducibility","key":"agent-reliability/deterministic-replay-and-reproducibility","module":"agent-reliability","name":"Deterministic replay & reproducibility","taxonomy_name":"deterministic replay & reproducibility","kind":"concept","difficulty":"advanced","est_minutes":15,"related":["agent-reliability/durable-execution-and-checkpointing","agent-reliability/structured-event-streams","agent-reliability/audit-logs-execution-traces","agent-reliability/agent-trajectory-evaluation","llmops-platform/reproducible-evaluations","model-internals/sampling-strategies","reliability/durable-workflow-execution","evals/pass-k"],"tldr":"You cannot reproduce an agent run by rerunning it: the model samples, providers change, tools return\nlive data, and one different token changes every later step. Reproducibility therefore comes in three\ngrades: exact replay from a recording of every non-deterministic boundary, best-effort re-execution with\npinned model, seed and temperature, and statistical reproduction over many runs. Design the runtime so the\norchestration logic is deterministic and every effect is recorded, and the first grade is always\navailable.","status":"ok"},{"id":"agent-trajectory-evaluation","key":"agent-reliability/agent-trajectory-evaluation","module":"agent-reliability","name":"Agent trajectory evaluation","taxonomy_name":"agent trajectory evaluation","kind":"practice","difficulty":"core","est_minutes":15,"related":["agent-reliability/task-completion-rate","agent-reliability/tool-call-success-rate","agent-reliability/structured-event-streams","agent-reliability/deterministic-replay-and-reproducibility","agents/tool-selection-accuracy","evals/llm-as-a-judge","evals/pass-k","evals/eval-harness"],"tldr":"Scoring an agent on its final answer alone misses most of what can go wrong: it may have reached the\nanswer by a forbidden action, by forty steps instead of four, or by luck. Trajectory evaluation scores\nthe whole path, the sequence of model decisions, tool calls and observations, against outcome checks,\nprocess checks and policy checks, over many runs per task, so you learn not just whether the agent\nsucceeded but where and why it fails.","status":"ok"},{"id":"task-completion-rate","key":"agent-reliability/task-completion-rate","module":"agent-reliability","name":"Task completion rate","taxonomy_name":"task completion rate","kind":"metric","difficulty":"core","est_minutes":12,"related":["agent-reliability/agent-trajectory-evaluation","agent-reliability/tool-call-success-rate","agent-reliability/max-step-budgets","evals/pass-k","evals/task-specific-acceptance-criteria","evals/offline-vs-online-evaluation","infra-capacity-economics/unit-economics-per-successful-task","reliability/slas-slos"],"tldr":"Task completion rate is the fraction of tasks an agent finishes successfully, judged against a defined\nsuccess criterion rather than its own claim of being done. It is the number product, finance and customers\ncare about, and it is only as good as three definitions behind it: what a task is, what counts as\ncomplete, and what goes in the denominator. Report it with an interval, segmented by task type, and\nalongside pass^k for unattended use.","status":"ok"},{"id":"tool-call-success-rate","key":"agent-reliability/tool-call-success-rate","module":"agent-reliability","name":"Tool-call success rate","taxonomy_name":"tool-call success rate","kind":"metric","difficulty":"core","est_minutes":12,"related":["agent-reliability/task-completion-rate","agent-reliability/tool-adapters-service-interfaces","agent-reliability/agent-trajectory-evaluation","agent-reliability/idempotent-tool-execution","agents/tool-schemas-and-argument-validation","agents/tool-selection-accuracy","serving-inference/retry-strategies","observability/monitoring"],"tldr":"Tool-call success rate is the fraction of tool invocations that succeed, and it is only useful when\n\"succeed\" is split into layers: the call was well-formed, it was permitted, it executed without an\ninfrastructure error, and it achieved what the model intended. Because a task is a chain of calls,\nper-call failure compounds: ten steps at 95% is about 60% end to end. The metric localizes failures to\nmodel, policy, tool or environment, which task completion rate cannot.","status":"ok"}]},{"id":"evals","tier":1,"order":7,"title":"Evals","intro":null,"topics":[{"id":"model-evaluation","key":"evals/model-evaluation","module":"evals","name":"Model evaluation","taxonomy_name":"model evaluation","kind":"concept","difficulty":"intro","est_minutes":14,"related":["evals/golden-dataset","evals/eval-harness","evals/benchmarking","evals/llm-as-a-judge","evals/task-specific-acceptance-criteria","evals/offline-vs-online-evaluation","evals/error-analysis","llmops-platform/evaluation-frameworks"],"tldr":"Model evaluation is the discipline of producing a number you can trust about whether a model, or a\nsystem built on one, does the job. It splits into two questions that are constantly confused:\n*capability* evaluation (\"what can this model do in general\", answered by benchmarks) and\n*application* evaluation (\"does my prompt + retrieval + model do my task on my data\", answered by a\ngolden dataset and task-specific graders). Without it, every prompt or model change is a guess\njudged by whoever looked at the demo last.","status":"ok"},{"id":"golden-dataset","key":"evals/golden-dataset","module":"evals","name":"Golden dataset (eval dataset)","taxonomy_name":"golden dataset (eval dataset)","kind":"concept","difficulty":"core","est_minutes":15,"related":["evals/model-evaluation","evals/task-specific-acceptance-criteria","evals/regression-tests","evals/inter-annotator-agreement","evals/dataset-contamination","llmops-platform/golden-dataset-strategy","customer-data-evaluation/golden-dataset-creation-with-client-smes","training-adaptation/train-val-test-split"],"tldr":"A golden dataset is a curated, versioned set of inputs paired with outputs or labels that the people\nwho own the task have agreed are correct. It is the fixed reference every eval number is computed\nagainst, so without it two prompts, two models or two weeks cannot be compared. \"Golden\" means\n*agreed and authoritative*, not perfect or large: a few hundred well-chosen, well-labeled items beat\nten thousand scraped ones, provided they are stratified across the cases that matter and kept out of\nprompts and training data.","status":"ok"},{"id":"eval-harness","key":"evals/eval-harness","module":"evals","name":"Eval harness","taxonomy_name":"eval harness","kind":"pattern","difficulty":"core","est_minutes":15,"related":["evals/golden-dataset","evals/llm-as-a-judge","evals/regression-tests","evals/pass-k","evals/tooling","llmops-platform/reproducible-evaluations","llmops-platform/ci-cd-for-prompts-and-models","backend-fundamentals/ci-cd"],"tldr":"An eval harness is the code that takes a versioned dataset, runs every item through the system under\ntest with pinned configuration, grades the raw outputs, aggregates scores per slice with confidence\nintervals, and writes a report that can be compared with any previous run. It exists because\nevaluation done in notebooks is not repeatable, so Tuesday's number cannot be compared with Friday's;\nthe harness is what turns evaluation into an engineering artifact with the status of a test suite.","status":"ok"},{"id":"task-specific-acceptance-criteria","key":"evals/task-specific-acceptance-criteria","module":"evals","name":"Task-specific acceptance criteria","taxonomy_name":"task-specific acceptance criteria","kind":"practice","difficulty":"core","est_minutes":14,"related":["evals/golden-dataset","evals/rubrics","evals/error-analysis","evals/regression-tests","evals/eval-harness","customer-data-evaluation/acceptance-testing-against-customer-kpis","llmops-platform/evaluation-gates-for-production-releases","system-design/nfrs"],"tldr":"Task-specific acceptance criteria turn \"the model should work well\" into explicit, checkable\nstatements about one task's outputs: format, required and forbidden content, correctness against\nreferences, behaviour on edge cases, and operational limits such as latency and cost, each with a\nthreshold and a scope. They exist because generic scores (a BLEU value, a 4.2/5 helpfulness rating,\na leaderboard rank) cannot tell you whether a contract-clause extractor is safe to ship; only\ncriteria derived from that task's actual failure modes can.","status":"ok"},{"id":"benchmarking","key":"evals/benchmarking","module":"evals","name":"Benchmarking (MMLU, HumanEval, SWE-bench, GPQA)","taxonomy_name":"benchmarking (MMLU, HumanEval, SWE-bench, GPQA)","kind":"concept","difficulty":"core","est_minutes":16,"related":["evals/model-evaluation","evals/dataset-contamination","evals/pass-k","evals/golden-dataset","system-design/model-selection","model-internals/reasoning-models-test-time-compute","agent-reliability/task-completion-rate"],"tldr":"A benchmark is a fixed dataset with a fixed scoring rule, so models can be compared on the same\ntask. MMLU measures broad knowledge by multiple choice, HumanEval measures Python function synthesis\nby unit tests, SWE-bench measures resolving real GitHub issues, and GPQA measures expert science\nreasoning that web search cannot shortcut. Benchmarks exist so model comparison is not anecdote, but\neach measures something narrow, saturates and leaks into training data: treat a leaderboard as a\nscreening filter, never as evidence your task will work.","status":"ok"},{"id":"dataset-contamination","key":"evals/dataset-contamination","module":"evals","name":"Dataset contamination","taxonomy_name":"dataset contamination","kind":"concept","difficulty":"core","est_minutes":14,"related":["evals/benchmarking","evals/golden-dataset","ml-fundamentals/train-test-leakage","training-adaptation/pre-training","training-adaptation/data-curation","training-adaptation/synthetic-data-generation","data-architecture/model-and-dataset-provenance"],"tldr":"Dataset contamination is the presence of evaluation items, their paraphrases or solutions in a\nmodel's training data, so a score measures memorization instead of capability. It is train/test\nleakage at LLM scale, made unavoidable by training on web crawls that contain the benchmarks used to\ngrade the result. It matters because the inflation is uneven across models and tasks, so contaminated\ncomparisons pick the wrong model, and because your own golden dataset is contaminated as easily\nthrough few-shot prompts and fine-tuning data.","status":"ok"},{"id":"llm-as-a-judge","key":"evals/llm-as-a-judge","module":"evals","name":"LLM-as-a-judge","taxonomy_name":"LLM-as-a-judge","kind":"pattern","difficulty":"core","est_minutes":16,"related":["evals/judge-calibration-and-bias","evals/rubrics","evals/pairwise-comparison","evals/inter-annotator-agreement","evals/faithfulness-groundedness","evals/eval-harness","prompting/chain-of-thought","prompting/structured-outputs-json-mode"],"tldr":"LLM-as-a-judge uses a model, given a rubric, the output to assess and often a reference or a second\noutput, to grade in place of a human reviewer. It exists because open-ended outputs have no\nexact-match answer and human grading does not scale to hundreds of items per prompt iteration. It is\nonly as good as its measured agreement with human labels on your task, because judges carry known\nbiases (position, verbosity, self-preference) and grade confidently, right or wrong.","status":"ok"},{"id":"judge-calibration-and-bias","key":"evals/judge-calibration-and-bias","module":"evals","name":"Judge calibration & bias","taxonomy_name":"judge calibration & bias","kind":"practice","difficulty":"core","est_minutes":16,"related":["evals/llm-as-a-judge","evals/rubrics","evals/pairwise-comparison","evals/inter-annotator-agreement","evals/golden-dataset","ml-fundamentals/calibration"],"tldr":"An LLM judge is a measuring instrument with its own systematic errors: it tends to prefer the answer\nshown first, the longer answer, the answer written in its own style, and it bunches scores near the top\nof the scale. Calibration means measuring those errors against human labels *before* trusting the judge;\nbias mitigation is the set of protocol changes (position swapping, length control, rubrics, reference\nanswers, judges from a different model family) that shrink them. Skip this and a judge score measures the\njudge, not your system.","status":"ok"},{"id":"rubrics","key":"evals/rubrics","module":"evals","name":"Rubrics","taxonomy_name":"rubrics","kind":"practice","difficulty":"intro","est_minutes":13,"related":["evals/llm-as-a-judge","evals/judge-calibration-and-bias","evals/inter-annotator-agreement","evals/task-specific-acceptance-criteria","evals/error-analysis","customer-data-evaluation/sme-review-and-annotation-guidelines"],"tldr":"A rubric turns \"is this output good?\" into a list of specific, observable criteria with defined levels,\nso two humans, or a human and an LLM judge, score the same output the same way. It exists because an\nunanchored score (\"rate quality 1–10\") measures the grader more than the output. Good rubrics come from\nobserved failure modes, prefer binary checks over wide scales, make catastrophic criteria gating rather\nthan averaged, and are versioned like code.","status":"ok"},{"id":"pairwise-comparison","key":"evals/pairwise-comparison","module":"evals","name":"Pairwise comparison","taxonomy_name":"pairwise comparison","kind":"concept","difficulty":"core","est_minutes":15,"related":["evals/llm-as-a-judge","evals/judge-calibration-and-bias","evals/a-b-testing","evals/benchmarking","training-adaptation/rlhf","training-adaptation/dpo"],"tldr":"Instead of asking \"how good is this answer on a 1–10 scale?\", pairwise comparison asks \"which of these\ntwo answers is better?\". Relative judgments are more consistent for both humans and LLM judges because\nthey need no shared absolute scale. Many verdicts are aggregated into a win rate against a fixed\nbaseline, or into a ranking of several systems with a Bradley–Terry model (the method behind Chatbot\nArena), and the same pairs are the raw material of preference training (RLHF, DPO).","status":"ok"},{"id":"inter-annotator-agreement","key":"evals/inter-annotator-agreement","module":"evals","name":"Inter-annotator agreement","taxonomy_name":"inter-annotator agreement","kind":"metric","difficulty":"core","est_minutes":14,"related":["evals/golden-dataset","evals/rubrics","evals/judge-calibration-and-bias","training-adaptation/data-labeling","customer-data-evaluation/labeling-sessions","customer-data-evaluation/sme-review-and-annotation-guidelines"],"tldr":"Inter-annotator agreement (IAA) measures how consistently independent humans label the same items. It\nmatters because labels are the ground truth every eval and every judge is scored against: if two experts\nagree only 70% of the time, no model can be shown to be more than roughly 70% \"right\", and the guideline,\nnot the model, is the problem. Chance-corrected statistics (Cohen's κ, Fleiss' κ, Krippendorff's α) are\nused instead of raw agreement because raw agreement is inflated whenever one label dominates.","status":"ok"},{"id":"pass-k","key":"evals/pass-k","module":"evals","name":"pass@k","taxonomy_name":"pass@k","kind":"metric","difficulty":"core","est_minutes":14,"related":["evals/benchmarking","evals/eval-harness","evals/regression-tests","evals/dataset-contamination","model-internals/sampling-strategies","agent-reliability/agent-trajectory-evaluation"],"tldr":"pass@k is the probability that at least one of k sampled solutions passes a correctness check, averaged\nover problems. It exists for tasks with an executable oracle, where one greedy sample understates what\na model can do if you can sample and verify. Estimate it from n ≥ k samples with the unbiased\ncombinatorial estimator, not by plugging a pooled pass rate into a formula. For k > 1 it is an *oracle*\nnumber: what a perfect verifier could extract, not what a user sees on one try.","status":"ok"},{"id":"retrieval-evaluation","key":"evals/retrieval-evaluation","module":"evals","name":"Retrieval evaluation (recall@k, MRR, NDCG)","taxonomy_name":"retrieval evaluation (recall@k, MRR, NDCG)","kind":"metric","difficulty":"core","est_minutes":16,"related":["rag-retrieval/recall-vs-precision-trade-off","rag-retrieval/reranking","rag-retrieval/retrieval-failure-diagnosis","rag-retrieval/hybrid-search","evals/golden-dataset","evals/faithfulness-groundedness","ml-fundamentals/precision-recall-f1"],"tldr":"A RAG answer can only be as good as the passages the retriever puts in front of the model, so the\nretriever is measured on its own against queries with known relevant documents. recall@k asks whether\nthe relevant passages made it into the top k the generator will see; MRR asks how high the first\nrelevant hit was; NDCG asks whether the ranking is right when relevance comes in grades. Choosing k to\nmatch the context budget and building honest relevance judgments matter more than the formulas.","status":"ok"},{"id":"faithfulness-groundedness","key":"evals/faithfulness-groundedness","module":"evals","name":"Faithfulness / groundedness","taxonomy_name":"faithfulness / groundedness","kind":"metric","difficulty":"core","est_minutes":15,"related":["evals/hallucination-evaluation","evals/retrieval-evaluation","evals/llm-as-a-judge","evals/tooling","rag-retrieval/citations-grounding","rag-retrieval/citation-correctness","model-internals/hallucination"],"tldr":"Faithfulness (groundedness) measures whether every claim in a generated answer is supported by the\ncontext the model was given, not whether the claim is true. It exists because a RAG system can produce\nfluent, even correct, answers its retrieved documents do not support, and those break when the documents\nchange. It is computed by splitting the answer into atomic claims and checking each against the context\nwith an entailment model or an LLM judge; it needs no reference answer, so it runs on production traffic.","status":"ok"},{"id":"hallucination-evaluation","key":"evals/hallucination-evaluation","module":"evals","name":"Hallucination evaluation","taxonomy_name":"hallucination evaluation","kind":"practice","difficulty":"core","est_minutes":16,"related":["evals/faithfulness-groundedness","model-internals/hallucination","rag-retrieval/citation-correctness","evals/llm-as-a-judge","evals/judge-calibration-and-bias","evals/golden-dataset","ml-fundamentals/calibration"],"tldr":"Hallucination evaluation measures how often a system asserts things that are not supported by its\nevidence or are false in the world. Whole-response grading hides it, because a fluent answer with one\ninvented figure still reads as correct. So the practice breaks outputs into atomic claims, verifies each\nagainst a reference (retrieved context, a trusted corpus, or consistency across samples), and reports\nclaim precision, response-level hallucination rate and abstention behaviour per slice, including the\nunanswerable and false-premise cases where fabrication concentrates.","status":"ok"},{"id":"regression-tests","key":"evals/regression-tests","module":"evals","name":"Regression tests","taxonomy_name":"regression tests","kind":"practice","difficulty":"core","est_minutes":15,"related":["evals/golden-dataset","evals/eval-harness","evals/eval-driven-development","evals/pass-k","llmops-platform/ci-cd-for-prompts-and-models","llmops-platform/evaluation-gates-for-production-releases","customer-data-evaluation/customer-specific-regression-suites","prompting/prompt-versioning"],"tldr":"A regression test for an AI system re-runs a pinned set of inputs with known expected behaviour every\ntime the prompt, model, retriever or tools change, and fails the change if cases that used to pass now\nfail. It exists because LLM changes are non-local: a prompt edit that fixes one case silently breaks\nothers, and the provider can change the model behind the same name. The engineering problem is telling\na real regression from sampling noise, which is why comparisons are per item and paired, not aggregate.","status":"ok"},{"id":"metamorphic-testing","key":"evals/metamorphic-testing","module":"evals","name":"Metamorphic testing","taxonomy_name":"metamorphic testing","kind":"concept","difficulty":"core","est_minutes":14,"related":["evals/property-based-testing","evals/regression-tests","evals/adversarial-evaluation","evals/judge-calibration-and-bias","evals/pairwise-comparison","evals/golden-dataset","rag-retrieval/lost-in-the-middle"],"tldr":"Metamorphic testing checks a system without knowing the right answer. Instead of asserting that an output\nequals an expected value, you transform the input in a way whose effect is predictable (paraphrase: same\nanswer; add an irrelevant paragraph: same answer; swap two options: the choice swaps) and assert that\nrelation between the two outputs. It exists because most LLM inputs have no label, and relation\nviolations are cheap to generate and expose brittleness a golden set, which sees each item once in one\nform, cannot.","status":"ok"},{"id":"property-based-testing","key":"evals/property-based-testing","module":"evals","name":"Property-based testing","taxonomy_name":"property-based testing","kind":"practice","difficulty":"core","est_minutes":14,"related":["python-for-ai/property-based-testing","evals/metamorphic-testing","evals/regression-tests","rag-retrieval/chunking-strategies","prompting/structured-outputs-json-mode","safety-security/output-validation","python-for-ai/pytest"],"tldr":"Property-based testing replaces hand-picked examples with a generator that produces hundreds of random\ninputs and a property that must hold for every one; when a case fails, the framework shrinks it to the\nsmallest input that still fails. In AI systems the deterministic scaffolding (chunkers, token budgeters,\nprompt renderers, tool-argument parsers, output validators) is where silent bugs live, and nobody writes\nthe example that breaks it. Properties on model outputs are possible too, at the price of one model call\nper generated example.","status":"ok"},{"id":"adversarial-evaluation","key":"evals/adversarial-evaluation","module":"evals","name":"Adversarial evaluation","taxonomy_name":"adversarial evaluation","kind":"practice","difficulty":"core","est_minutes":16,"related":["evals/red-teaming","prompting/prompt-injection","prompting/jailbreaks","safety-security/input-output-guardrails","safety-security/rag-poisoning","evals/metamorphic-testing","evals/regression-tests","evals/judge-calibration-and-bias"],"tldr":"Adversarial evaluation measures how a system behaves on inputs chosen to make it fail: jailbreaks,\ninstructions injected through retrieved content, perturbed or out-of-distribution inputs, and outputs\ncrafted to fool the grader. Red teaming discovers such inputs; adversarial evaluation turns them into a\nversioned suite with an attack success rate per class, run every release and reported next to the\nover-refusal rate on benign inputs. It exists because average-case evals say nothing about the worst\ncase, which is what attackers find.","status":"ok"},{"id":"offline-vs-online-evaluation","key":"evals/offline-vs-online-evaluation","module":"evals","name":"Offline vs online evaluation","taxonomy_name":"offline vs online evaluation","kind":"decision","difficulty":"core","est_minutes":14,"related":["evals/a-b-testing","evals/golden-dataset","evals/llm-as-a-judge","customer-data-evaluation/shadow-mode-validation","llmops-platform/canary-shadow-deployments","llmops-platform/evaluation-gates-for-production-releases","observability/monitoring","llmops-platform/drift"],"tldr":"Offline evaluation scores a system on a fixed dataset before it meets users; online evaluation measures\nit on live traffic through user behaviour, sampled judging of real traces, or controlled experiments.\nOffline is fast, cheap, reproducible and safe but only as good as its dataset and graders; online is the\ntruth about outcomes but slow, noisy, risky and confounded. Neither replaces the other: offline gates\nwhat ships, online tells you whether offline measured the right thing, and sampled online traffic\nrefills the offline set.","status":"ok"},{"id":"a-b-testing","key":"evals/a-b-testing","module":"evals","name":"A/B testing","taxonomy_name":"A/B testing","kind":"practice","difficulty":"core","est_minutes":16,"related":["evals/offline-vs-online-evaluation","evals/pairwise-comparison","llmops-platform/canary-shadow-deployments","llmops-platform/rollback","llmops-platform/experiment-tracking","observability/monitoring","scoping/success-metrics-kpis","enterprise-integration/tenant-specific-configuration-and-feature-flags"],"tldr":"An A/B test randomly assigns users (or sessions) to the current system or a candidate and compares a\npre-declared outcome metric, so a difference can be attributed to the change rather than to time,\ntraffic mix or luck. It is the only online method that gives a causal answer, and it exists because\noffline scores and before-and-after dashboards cannot. The discipline is in the design: the\nrandomisation unit, one primary metric with guardrails, a sample size fixed in advance, and no peeking.","status":"ok"},{"id":"error-analysis","key":"evals/error-analysis","module":"evals","name":"Error analysis","taxonomy_name":"error analysis","kind":"practice","difficulty":"core","est_minutes":15,"related":["evals/golden-dataset","evals/eval-harness","evals/llm-as-a-judge","evals/inter-annotator-agreement","evals/eval-driven-development","evals/regression-tests","rag-retrieval/retrieval-failure-diagnosis","customer-data-evaluation/production-feedback-classification"],"tldr":"Error analysis is the practice of reading a sample of your system's real traces one at a time, writing\ndown what went wrong in each, grouping those notes into a short taxonomy of failure modes, and counting\nthem. It exists because an aggregate score says *that* the system fails, never *why* or *where*. The\ncounts tell you which fix buys the most, and each stable failure mode becomes a metric and a set of\ngolden items, so the eval suite grows from observed failures rather than imagined ones.","status":"ok"},{"id":"red-teaming","key":"evals/red-teaming","module":"evals","name":"Red teaming","taxonomy_name":"red teaming","kind":"practice","difficulty":"core","est_minutes":16,"related":["evals/adversarial-evaluation","evals/regression-tests","evals/tooling","prompting/jailbreaks","safety-security/prompt-injection","safety-security/owasp-top-10-for-llms","safety-security/excessive-agency","security-governance-compliance/ai-incident-response"],"tldr":"Red teaming is a deliberate, goal-driven attempt to make your AI system do what it must not: leak data\nor the system prompt, follow injected instructions, produce harmful content, take an unauthorised\naction, or assert a policy that does not exist. It exists because ordinary evals measure the behaviour\nyou asked for on inputs you expected, while the costly failures are on inputs an adversary chooses.\nEvery successful attack becomes a permanent regression test, and the exercise repeats with every model,\nprompt or tool change.","status":"ok"},{"id":"eval-driven-development","key":"evals/eval-driven-development","module":"evals","name":"Eval-driven development","taxonomy_name":"eval-driven development","kind":"practice","difficulty":"core","est_minutes":15,"related":["evals/golden-dataset","evals/eval-harness","evals/error-analysis","evals/regression-tests","evals/task-specific-acceptance-criteria","evals/offline-vs-online-evaluation","llmops-platform/ci-cd-for-prompts-and-models","prompting/prompt-versioning"],"tldr":"Eval-driven development treats the eval suite as the executable specification of an LLM feature:\nwrite the acceptance criteria and a seed golden set before building, judge every change by the eval's\nnumbers rather than by a demo, and grow the suite from the failures each round of error analysis\nfinds. It exists because prompt, retrieval and model changes have non-local effects that \"it looked\nfine in the playground\" cannot detect, and because a bug without a failing eval item is never\nreliably fixed.","status":"ok"},{"id":"tooling","key":"evals/tooling","module":"evals","name":"Tooling (Promptfoo, RAGAS, DeepEval, Braintrust, LangSmith, Langfuse)","taxonomy_name":"tooling (Promptfoo, RAGAS, DeepEval, Braintrust, LangSmith, Langfuse)","kind":"tool","difficulty":"core","est_minutes":16,"related":["evals/eval-harness","evals/llm-as-a-judge","evals/judge-calibration-and-bias","evals/retrieval-evaluation","evals/faithfulness-groundedness","observability/langfuse","observability/langsmith","llmops-platform/evaluation-frameworks"],"tldr":"Every eval tool implements the same pipeline: dataset → run the system → grade → store and compare.\nThey differ in where that state lives and which graders come prebuilt. Promptfoo, RAGAS and DeepEval\nare libraries you run locally (config-driven prompt×model matrices, RAG metrics, pytest-style tests);\nBraintrust, LangSmith and Langfuse are platforms that keep traces, datasets and experiments on a server\nand attach evaluators to production traffic. Choose by where your traces already live and how much of\nthe grading logic you need to own.","status":"ok"}]},{"id":"serving-inference","tier":1,"order":8,"title":"Serving & inference","intro":null,"topics":[{"id":"model-serving","key":"serving-inference/model-serving","module":"serving-inference","name":"Model serving","taxonomy_name":"model serving","kind":"concept","difficulty":"intro","est_minutes":12,"related":["serving-inference/engines","serving-inference/prefill-vs-decode","serving-inference/continuous-batching","serving-inference/throughput-vs-latency","serving-inference/streaming","infra-capacity-economics/shared-vs-isolated-model-serving-infrastructure","infra-capacity-economics/serverless-gpus","model-internals/kv-cache"],"tldr":"Model serving is everything between a trained checkpoint and an HTTP response: loading weights onto\naccelerators, turning requests into token streams, scheduling many of them onto one GPU, and exposing\nlatency and throughput you can reason about. LLM serving is harder than classic ML serving because each\nrequest is a stateful loop of unknown length whose working set (the KV cache) grows while it runs, so the\nscheduler, not the model, decides what the hardware actually delivers.","review":"fact-checked","status":"ok"},{"id":"inference-optimization","key":"serving-inference/inference-optimization","module":"serving-inference","name":"Inference optimization","taxonomy_name":"inference optimization","kind":"concept","difficulty":"core","est_minutes":16,"related":["serving-inference/prefill-vs-decode","serving-inference/continuous-batching","serving-inference/prefix-caching","serving-inference/quantization-quality-evaluation","serving-inference/tensor-parallelism-at-inference","model-internals/speculative-decoding","model-internals/flashattention","training-adaptation/quantization"],"tldr":"Inference optimization is the set of levers that make a fixed model cheaper or faster to run. Almost all\nof them work by attacking one of two bottlenecks: decode is bound by memory bandwidth (every token\nre-reads the weights and the KV cache), prefill is bound by compute. Knowing which bound you are hitting\ntells you which lever can possibly help, which is why the roofline model, not a list of tricks, is the\nthing to learn.","review":"fact-checked","status":"ok"},{"id":"prefill-vs-decode","key":"serving-inference/prefill-vs-decode","module":"serving-inference","name":"Prefill vs decode","taxonomy_name":"prefill vs decode","kind":"concept","difficulty":"core","est_minutes":14,"related":["model-internals/kv-cache","serving-inference/ttft","serving-inference/tpot","serving-inference/continuous-batching","serving-inference/prefix-caching","serving-inference/inference-optimization","infra-capacity-economics/gpu-utilization-and-memory-bandwidth"],"tldr":"Every LLM request runs in two phases with opposite hardware profiles. Prefill processes the whole prompt in\none pass: thousands of tokens per weight read, compute-bound, and it sets time-to-first-token. Decode then\nproduces one token per step: one token per weight read, memory-bandwidth-bound, and it sets time per\noutput token. Because the phases stress different resources, mixing them on one GPU causes interference,\nand most scheduling techniques exist to manage that collision.","review":"fact-checked","status":"ok"},{"id":"kv-cache-memory-estimation","key":"serving-inference/kv-cache-memory-estimation","module":"serving-inference","name":"KV-cache memory estimation","taxonomy_name":"KV-cache memory estimation","kind":"practice","difficulty":"core","est_minutes":14,"related":["model-internals/kv-cache","model-internals/grouped-query-attention","serving-inference/gpu-memory-optimization","serving-inference/kv-cache-paging-and-eviction","serving-inference/batching-and-concurrency-limits","infra-capacity-economics/gpu-sizing","infra-capacity-economics/capacity-planning"],"tldr":"KV-cache memory is the number that turns \"we have an 80 GB GPU\" into \"we can serve N concurrent requests\nof length L\". It is a short multiplication you can do from a model's config file: bytes per token equals\n2 × layers × KV heads × head dimension × bytes per element, times tokens, times concurrent sequences.\nLearning to do it quickly, and knowing what the formula leaves out, is how you avoid both out-of-memory\nsurprises and paying for GPUs that sit half empty.","review":"fact-checked","status":"ok"},{"id":"kv-cache-paging-and-eviction","key":"serving-inference/kv-cache-paging-and-eviction","module":"serving-inference","name":"KV-cache paging & eviction","taxonomy_name":"KV-cache paging & eviction","kind":"concept","difficulty":"core","est_minutes":15,"related":["serving-inference/pagedattention","serving-inference/kv-cache-memory-estimation","serving-inference/prefix-caching","serving-inference/continuous-batching","serving-inference/cpu-offloading","model-internals/kv-cache","model-internals/context-window"],"tldr":"Paging stores each request's KV cache in fixed-size blocks mapped through a per-request block table, the\nway an operating system pages virtual memory, so sequences of unknown length can grow without reserving\ntheir maximum up front and without fragmenting the pool. Eviction is what happens when the pool still runs\nout: the scheduler preempts whole sequences (recompute or swap them out) or drops reusable cached prefixes,\nand a separate family of approximate methods discards tokens inside a sequence at a quality cost.","review":"fact-checked","status":"ok"},{"id":"prefix-caching","key":"serving-inference/prefix-caching","module":"serving-inference","name":"Prefix caching","taxonomy_name":"prefix caching","kind":"pattern","difficulty":"core","est_minutes":14,"related":["prompting/prompt-caching","serving-inference/kv-cache-paging-and-eviction","serving-inference/prefill-vs-decode","serving-inference/ttft","serving-inference/caching","model-internals/kv-cache","prompting/system-prompt","agents/agent-loop"],"tldr":"Prefix caching keeps the KV cache of a prompt prefix alive after the request that computed it finishes, so\nthe next request starting with the same tokens skips prefill for that part. It is exact because K and V\nat a position depend only on the tokens before it. A shared system prompt, few-shot block or chat history\nbecomes a one-time cost instead of a per-request one, cutting time-to-first-token and compute, but only\nwhen prompts share a byte-identical beginning.","review":"fact-checked","status":"ok"},{"id":"continuous-batching","key":"serving-inference/continuous-batching","module":"serving-inference","name":"Continuous batching","taxonomy_name":"continuous batching","kind":"concept","difficulty":"core","est_minutes":15,"related":["serving-inference/batching-and-concurrency-limits","serving-inference/prefill-vs-decode","serving-inference/kv-cache-paging-and-eviction","serving-inference/throughput-vs-latency","serving-inference/tpot","serving-inference/engines","ml-fundamentals/batch-size","infra-capacity-economics/queueing-theory"],"tldr":"Continuous batching schedules at the granularity of a single decode iteration instead of a whole request:\nevery step, finished sequences leave the batch and waiting ones join, so the GPU runs a full batch\ncontinuously rather than idling while the longest request in a static batch finishes. It is what makes\nbandwidth-bound decode efficient, because one read of the weights then serves dozens of tokens, and it\nis the reason modern engines report throughput an order of magnitude above naive servers.","review":"fact-checked","status":"ok"},{"id":"pagedattention","key":"serving-inference/pagedattention","module":"serving-inference","name":"PagedAttention","taxonomy_name":"PagedAttention","kind":"concept","difficulty":"core","est_minutes":14,"related":["model-internals/kv-cache","serving-inference/kv-cache-memory-estimation","serving-inference/kv-cache-paging-and-eviction","serving-inference/prefix-caching","serving-inference/continuous-batching","serving-inference/gpu-memory-optimization","serving-inference/engines"],"tldr":"PagedAttention stores each request's KV cache in fixed-size blocks (16 tokens is the usual size)\naddressed through a per-request block table, instead of one contiguous buffer reserved for the maximum\nlength. Output lengths are unknown when a request arrives, so contiguous allocation must over-reserve\nand wastes most of the memory; paging allocates blocks on demand, removes external fragmentation, and\nlets requests share blocks. Decode is memory-bound, so the memory you recover becomes more concurrent\nrequests, which is where vLLM's throughput gains come from.","review":"fact-checked","status":"ok"},{"id":"batching-and-concurrency-limits","key":"serving-inference/batching-and-concurrency-limits","module":"serving-inference","name":"Batching & concurrency limits","taxonomy_name":"batching & concurrency limits","kind":"practice","difficulty":"core","est_minutes":15,"related":["serving-inference/continuous-batching","serving-inference/prefill-vs-decode","serving-inference/throughput-vs-latency","serving-inference/tpot","serving-inference/ttft","serving-inference/backpressure","serving-inference/rate-limiting","infra-capacity-economics/queueing-theory"],"tldr":"Decode is memory-bandwidth bound: each step streams the whole weight set through the GPU once, no\nmatter how many sequences are in the batch, so batching multiplies throughput almost for free until the\nGPU becomes compute-bound or the KV cache fills. Concurrency limits exist because past that knee each\nadded request raises everyone's latency, and because unbounded admission ends in preemption thrash or\nOOM. The work is to find the knee for your traffic shape and enforce it at the engine, the gateway and\nthe client.","review":"fact-checked","status":"ok"},{"id":"tensor-parallelism-at-inference","key":"serving-inference/tensor-parallelism-at-inference","module":"serving-inference","name":"Tensor parallelism at inference","taxonomy_name":"tensor parallelism at inference","kind":"concept","difficulty":"advanced","est_minutes":16,"related":["training-adaptation/distributed-training","model-internals/grouped-query-attention","model-internals/kv-cache","model-internals/mixture-of-experts","serving-inference/gpu-memory-optimization","serving-inference/engines","infra-capacity-economics/gpu-infrastructure","infra-capacity-economics/a100-h100-l4-selection"],"tldr":"Tensor parallelism (TP) splits every weight matrix across N GPUs so each holds 1/N of the parameters and\nKV cache and does 1/N of each layer's arithmetic, stitched together by an all-reduce after attention and\nafter the MLP in every layer. At inference it is how you fit a model larger than one GPU and pool memory\nbandwidth for faster decode, but it pays off only over a fast intra-node interconnect, because decode\nsends hundreds of tiny all-reduces per token.","review":"fact-checked","status":"ok"},{"id":"cpu-offloading","key":"serving-inference/cpu-offloading","module":"serving-inference","name":"CPU offloading","taxonomy_name":"CPU offloading","kind":"pattern","difficulty":"core","est_minutes":14,"related":["serving-inference/gpu-memory-optimization","serving-inference/kv-cache-paging-and-eviction","serving-inference/throughput-vs-latency","serving-inference/engines","training-adaptation/quantization","infra-capacity-economics/gpu-utilization-and-memory-bandwidth","infra-capacity-economics/edge-ai-deployment"],"tldr":"CPU offloading keeps part of a model's weights or KV cache in host RAM (or on NVMe) and brings it to the\nGPU when needed, trading scarce GPU memory for PCIe bandwidth. PCIe moves data roughly 50–100× slower\nthan GPU memory, and decode touches every weight every token, so offloading weights makes interactive\nlatency collapse unless the offloaded share is tiny or batches are huge. It is a tool for fitting,\noffline throughput and tiering idle KV cache, not for low-latency serving.","review":"fact-checked","status":"ok"},{"id":"quantization-quality-evaluation","key":"serving-inference/quantization-quality-evaluation","module":"serving-inference","name":"Quantization quality evaluation","taxonomy_name":"quantization quality evaluation","kind":"practice","difficulty":"core","est_minutes":15,"related":["training-adaptation/quantization","model-internals/perplexity","evals/golden-dataset","evals/regression-tests","evals/llm-as-a-judge","evals/benchmarking","serving-inference/gpu-memory-optimization","llmops-platform/evaluation-gates-for-production-releases"],"tldr":"Quantization buys memory and speed with precision, and the only honest way to know what it cost is to\nmeasure the quantized model against its own full-precision baseline on the work you actually serve.\nPerplexity and per-token KL divergence are cheap, sensitive early signals; task-level evals on your golden\nset, run with identical prompts and decoding, are the acceptance test. Degradation is uneven: long\ncontext, multi-step math, code, strict output formats and low-resource languages break first, so\naggregate numbers hide the failures that matter.","review":"fact-checked","status":"ok"},{"id":"structured-constrained-generation","key":"serving-inference/structured-constrained-generation","module":"serving-inference","name":"Structured / constrained generation","taxonomy_name":"structured / constrained generation","kind":"pattern","difficulty":"core","est_minutes":15,"related":["prompting/structured-outputs-json-mode","prompting/function-tool-calling","python-for-ai/outlines","python-for-ai/instructor","python-for-ai/pydantic","model-internals/logits","model-internals/tokenization","agents/tool-schemas-and-argument-validation"],"tldr":"Structured generation makes a model's output conform to a schema, regex, grammar or fixed set of\nchoices. The reliable way is constrained decoding: at every step the engine masks the logits of tokens\nthat would violate the grammar, so the sampler can only pick valid continuations and the output parses\nby construction. That removes the parse-and-retry loop, but it guarantees shape, not truth, costs a\ngrammar compile step, and can subtly change what the model says, so schema design still matters.","review":"fact-checked","status":"ok"},{"id":"gpu-memory-optimization","key":"serving-inference/gpu-memory-optimization","module":"serving-inference","name":"GPU memory optimization (VRAM math)","taxonomy_name":"GPU memory optimization (VRAM math)","kind":"practice","difficulty":"core","est_minutes":16,"related":["model-internals/kv-cache","serving-inference/kv-cache-memory-estimation","serving-inference/pagedattention","serving-inference/tensor-parallelism-at-inference","serving-inference/cpu-offloading","training-adaptation/quantization","model-internals/flashattention","infra-capacity-economics/gpu-sizing"],"tldr":"GPU memory at inference is a ledger with four lines: weights, KV cache, activation and workspace peaks,\nand runtime overhead plus fragmentation. Write it down (`weights = params × bytes_per_param`, `KV =\n2 × layers × kv_heads × head_dim × bytes × tokens_in_flight`), subtract from usable VRAM, and every\ntuning knob, from quantization and model choice to context caps, concurrency caps, tensor parallelism\nand chunked prefill, is just a term you are shrinking. Guessing instead of computing is how both\nout-of-memory pages and 20%-utilized GPUs happen.","review":"fact-checked","status":"ok"},{"id":"streaming","key":"serving-inference/streaming","module":"serving-inference","name":"Streaming (SSE)","taxonomy_name":"streaming (SSE)","kind":"pattern","difficulty":"core","est_minutes":15,"related":["serving-inference/ttft","serving-inference/tpot","serving-inference/cancellation","serving-inference/timeouts","serving-inference/backpressure","fastapi-for-ai/streamingresponse","fastapi-for-ai/websockets","agent-reliability/structured-event-streams"],"tldr":"A 500-token answer at 20 ms per token takes 10 s to finish, but the first token exists after a few\nhundred milliseconds. Streaming sends each token as it is decoded, so the latency a user feels becomes\ntime-to-first-token rather than total time. Server-Sent Events (SSE) is the usual transport because it\nis plain one-directional HTTP that proxies and provider APIs already speak. The price: errors, usage\nand tool calls arrive piecemeal, and nothing between GPU and browser may buffer.","review":"fact-checked","status":"ok"},{"id":"ttft","key":"serving-inference/ttft","module":"serving-inference","name":"TTFT (time to first token)","taxonomy_name":"TTFT","kind":"metric","difficulty":"core","est_minutes":14,"related":["serving-inference/prefill-vs-decode","serving-inference/streaming","serving-inference/tpot","serving-inference/prefix-caching","serving-inference/continuous-batching","serving-inference/batching-and-concurrency-limits","observability/latency-percentiles","infra-capacity-economics/latency-budgets"],"tldr":"Time to first token (TTFT) is the delay between sending a request and receiving the first generated\ntoken. It is made of queueing wait plus prefill, the single compute-bound pass over the whole prompt,\nso it grows with prompt length and with load, not with answer length. In a streaming UI it is the\nlatency users actually feel. You cut it with shorter prompts, prefix caching, admission control and\nscheduling; faster decode tricks such as speculative decoding do nothing for it.","review":"fact-checked","status":"ok"},{"id":"tpot","key":"serving-inference/tpot","module":"serving-inference","name":"TPOT (time per output token)","taxonomy_name":"TPOT","kind":"metric","difficulty":"core","est_minutes":14,"related":["serving-inference/ttft","serving-inference/tokens-sec","serving-inference/prefill-vs-decode","serving-inference/continuous-batching","model-internals/kv-cache","model-internals/speculative-decoding","infra-capacity-economics/gpu-utilization-and-memory-bandwidth","serving-inference/tensor-parallelism-at-inference"],"tldr":"Time per output token (TPOT) is the average gap between successive tokens once generation has\nstarted: `(t_last − t_first) / (n_out − 1)`. Each decode step must read the whole model's weights plus\nthe KV cache from GPU memory, so TPOT has a floor of bytes-read divided by memory bandwidth, and it\nbarely rises when more requests share the step. That is why batching is almost free for throughput,\nwhy quantisation and tensor parallelism speed up single streams, and why a faster-FLOPs GPU alone\ndoes not.","review":"fact-checked","status":"ok"},{"id":"tokens-sec","key":"serving-inference/tokens-sec","module":"serving-inference","name":"Tokens per second","taxonomy_name":"tokens/sec","kind":"metric","difficulty":"core","est_minutes":13,"related":["serving-inference/tpot","serving-inference/throughput-vs-latency","serving-inference/continuous-batching","serving-inference/batching-and-concurrency-limits","infra-capacity-economics/capacity-planning","infra-capacity-economics/gpu-utilization-and-memory-bandwidth","infra-capacity-economics/unit-economics-per-successful-task","evals/benchmarking"],"tldr":"\"Tokens per second\" names two different numbers: the decode speed of one stream (roughly `1 / TPOT`,\nwhat a user sees) and the aggregate output of a whole server (all concurrent streams summed, what you\npay for). They move in opposite directions as concurrency rises. A quoted figure means nothing\nwithout which tokens (input, output or both), the concurrency, prompt and output lengths, hardware,\nprecision and percentile. Use it for capacity and cost per token; never compare it across tokenizers.","review":"fact-checked","status":"ok"},{"id":"throughput-vs-latency","key":"serving-inference/throughput-vs-latency","module":"serving-inference","name":"Throughput vs latency","taxonomy_name":"throughput vs latency","kind":"decision","difficulty":"core","est_minutes":15,"related":["serving-inference/continuous-batching","serving-inference/batching-and-concurrency-limits","serving-inference/tokens-sec","serving-inference/tpot","serving-inference/ttft","infra-capacity-economics/queueing-theory","infra-capacity-economics/quality-latency-cost-optimization","reliability/slas-slos"],"tldr":"A decode step costs about the same whether it advances one sequence or thirty-two, because its time\nis dominated by reading the weights once. Packing more requests into each step therefore multiplies\nthroughput almost for free, until compute or KV memory saturates, but every added request lengthens\neach step and the queue in front of it, so per-request latency rises. No setting maximises both. You\npick an operating point on that curve per workload and enforce it with concurrency limits, admission\ncontrol and SLOs.","review":"fact-checked","status":"ok"},{"id":"timeouts","key":"serving-inference/timeouts","module":"serving-inference","name":"Timeouts","taxonomy_name":"timeouts","kind":"practice","difficulty":"core","est_minutes":14,"related":["serving-inference/streaming","serving-inference/cancellation","serving-inference/retry-strategies","serving-inference/fallbacks","fastapi-for-ai/timeouts","reliability/circuit-breakers","infra-capacity-economics/latency-budgets","system-design/synchronous-vs-asynchronous-execution"],"tldr":"LLM calls last from under a second to several minutes, and the duration depends on an output length\nnobody knows in advance plus queueing nobody controls. A single flat timeout therefore either kills\nlegitimate work or lets hung connections hold resources for minutes. Use layered timers (connect,\nfirst token, idle gap between chunks, total deadline derived from `max_tokens × TPOT`), propagate\nthe remaining budget downstream, pair every expiry with cancellation, and audit the default timeouts\nof every proxy between you and the model.","review":"fact-checked","status":"ok"},{"id":"cancellation","key":"serving-inference/cancellation","module":"serving-inference","name":"Cancellation","taxonomy_name":"cancellation","kind":"pattern","difficulty":"core","est_minutes":14,"related":["serving-inference/timeouts","serving-inference/streaming","serving-inference/backpressure","serving-inference/continuous-batching","fastapi-for-ai/cancellation-on-client-disconnect","python-for-ai/async-cancellation-and-exception-propagation","node-ts-for-ai/abortcontroller-and-cancellation","agents/agent-loop"],"tldr":"A generation nobody is waiting for still occupies a decode slot, KV-cache memory and your token\nbudget until it reaches `max_tokens`. Cancellation carries \"stop\" from the trigger (closed tab, stop\nbutton, superseding message, timeout, losing hedge) through every hop: browser, your API, HTTP\nclient, provider or engine, so the engine aborts the sequence and frees its memory. It works only if\neach layer notices the disconnect and closes the next connection; streaming makes that observable,\nnon-streaming hides it.","review":"fact-checked","status":"ok"},{"id":"backpressure","key":"serving-inference/backpressure","module":"serving-inference","name":"Backpressure","taxonomy_name":"backpressure","kind":"pattern","difficulty":"core","est_minutes":14,"related":["serving-inference/batching-and-concurrency-limits","serving-inference/timeouts","serving-inference/cancellation","serving-inference/rate-limiting","reliability/backpressure-and-load-shedding","infra-capacity-economics/queueing-theory","fastapi-for-ai/backpressure","node-ts-for-ai/streams-and-backpressure"],"tldr":"Backpressure is how an overloaded stage tells the stage feeding it to slow down, instead of silently\nbuffering work until memory or latency blows up. An inference server has a hard ceiling set by KV-cache\nmemory and decode bandwidth, so it must bound how much it admits, measure how long work waits, and reject\nthe rest quickly with a 429 or 503 and a `Retry-After`. Without it a traffic spike becomes slow timeouts\nfor everyone instead of fast rejections for some.","review":"fact-checked","status":"ok"},{"id":"fallbacks","key":"serving-inference/fallbacks","module":"serving-inference","name":"Fallbacks","taxonomy_name":"fallbacks","kind":"pattern","difficulty":"core","est_minutes":13,"related":["system-design/model-fallback-strategies","reliability/circuit-breakers","system-design/graceful-degradation","serving-inference/retry-strategies","serving-inference/timeouts","serving-inference/idempotency","system-design/ai-gateway","system-design/model-routing-cascading"],"tldr":"A fallback is a pre-decided alternative path taken when the primary one fails or is too slow: the same\nmodel on another endpoint or region, a smaller model, a cached or templated answer, or an honest\n\"unavailable\". It exists because LLM dependencies fail partially and often, and retrying a broken target\nonly burns the latency budget. The hard parts are deciding fast, keeping the alternative behaviourally\ncompatible, and not letting everyone's fallback crush the backup.","review":"fact-checked","status":"ok"},{"id":"retry-strategies","key":"serving-inference/retry-strategies","module":"serving-inference","name":"Retry strategies","taxonomy_name":"retry strategies","kind":"pattern","difficulty":"core","est_minutes":13,"related":["serving-inference/timeouts","serving-inference/idempotency","serving-inference/rate-limiting","serving-inference/fallbacks","reliability/circuit-breakers","node-ts-for-ai/api-clients-with-retries-and-circuit-breakers","enterprise-integration/retry-deduplication-reconciliation"],"tldr":"A retry re-issues a request that failed for a reason likely to be transient. Done well, it classifies the\nerror, waits with exponential backoff plus jitter, honours `Retry-After`, caps attempts and total time,\nkeeps a global retry budget and relies on idempotency; it then absorbs the steady trickle of 429s, 5xx\nand connection resets that LLM APIs produce. Done naively, retrying everything immediately at every\nlayer, it turns a brief provider hiccup into a self-inflicted outage.","review":"fact-checked","status":"ok"},{"id":"rate-limiting","key":"serving-inference/rate-limiting","module":"serving-inference","name":"Rate limiting","taxonomy_name":"rate limiting","kind":"pattern","difficulty":"core","est_minutes":14,"related":["serving-inference/backpressure","serving-inference/retry-strategies","serving-inference/batching-and-concurrency-limits","fastapi-for-ai/rate-limiting","infra-capacity-economics/api-provider-quotas-and-regional-limits","reliability/tenant-level-quotas-and-noisy-neighbor-isolation","backend-fundamentals/pagination-rate-limits-api-quotas","system-design/ai-gateway"],"tldr":"Rate limiting bounds how much work a caller may submit per unit of time. In LLM systems it points two\nways: inbound, so one tenant or one runaway loop cannot consume the GPU or the provider quota everyone\nshares; outbound, so your fleet stays under provider limits that are counted in requests *and* tokens per\nminute. The LLM twist is that a request's cost is unknown until it finishes, so limiters reserve on an\nestimate and settle on the actual.","review":"fact-checked","status":"ok"},{"id":"idempotency","key":"serving-inference/idempotency","module":"serving-inference","name":"Idempotency","taxonomy_name":"idempotency","kind":"concept","difficulty":"core","est_minutes":13,"related":["serving-inference/retry-strategies","serving-inference/timeouts","fastapi-for-ai/idempotency-keys","agent-reliability/idempotent-tool-execution","system-design/exactly-once-processing-limitations","system-design/outbox-inbox-patterns","enterprise-integration/retry-deduplication-reconciliation"],"tldr":"An operation is idempotent when doing it twice has the same effect as doing it once. LLM systems need\nthis because retries, timeouts, at-least-once queues and agent re-execution all produce duplicates, and\nduplicates cost money (a second generation), corrupt state (a second reply in a chat) or act twice on the\nworld (a second email). The standard mechanism is a client-chosen idempotency key stored with the outcome,\nso a repeat returns the saved result instead of redoing the work.","review":"fact-checked","status":"ok"},{"id":"caching","key":"serving-inference/caching","module":"serving-inference","name":"Caching (semantic, prompt)","taxonomy_name":"caching (semantic, prompt)","kind":"concept","difficulty":"core","est_minutes":16,"related":["serving-inference/prefix-caching","prompting/prompt-caching","model-internals/kv-cache","serving-inference/ttft","system-design/caching-strategy-and-cache-invalidation","fastapi-for-ai/redis-caching","observability/token-cost-tracking","infra-capacity-economics/cost-optimization"],"tldr":"LLM caching comes in three layers that are routinely conflated. An exact-match response cache skips\ngeneration when an identical request repeats. A semantic cache skips generation when a *similar enough*\nrequest repeats, judged by embedding distance. Prompt caching reuses the KV cache of a shared prompt\nprefix so prefill is not recomputed, but the answer is still generated fresh. They save different things,\nfail in different ways and need different keys, so \"add a cache\" is not one decision.","review":"fact-checked","status":"ok"},{"id":"engines","key":"serving-inference/engines","module":"serving-inference","name":"Engines (vLLM, SGLang, TGI, TensorRT-LLM, Ollama, llama.cpp)","taxonomy_name":"engines (vLLM, SGLang, TGI, TensorRT-LLM, Ollama, llama.cpp)","kind":"tool","difficulty":"core","est_minutes":16,"related":["serving-inference/model-serving","serving-inference/continuous-batching","serving-inference/pagedattention","serving-inference/prefix-caching","serving-inference/structured-constrained-generation","training-adaptation/quantization","system-design/self-host-vs-api","infra-capacity-economics/gpu-sizing"],"tldr":"An inference engine loads weights onto hardware and turns requests into tokens; it owns batching,\nKV-cache memory, kernels, quantization and the serving API. The six named here split into two families:\ndatacenter servers built around continuous batching and paged KV cache for many concurrent users (vLLM,\nSGLang, TGI, TensorRT-LLM) and local runtimes built for portability and small footprints (llama.cpp, and\nOllama, which wraps it). Choose by hardware, concurrency and how much operational effort you can afford.","review":"fact-checked","status":"ok"}]},{"id":"observability","tier":1,"order":9,"title":"Observability","intro":null,"topics":[{"id":"tracing","key":"observability/tracing","module":"observability","name":"Tracing","taxonomy_name":"tracing","kind":"concept","difficulty":"intro","est_minutes":13,"related":["observability/spans","observability/distributed-tracing-across-services","observability/opentelemetry","observability/langfuse","agent-reliability/audit-logs-execution-traces","evals/error-analysis"],"tldr":"A trace is the complete, timed record of one request as it moves through an LLM application: the\nuser turn at the root, and under it every retrieval, model call, tool call and retry as nested spans.\nIt exists because LLM systems fail *semantically* (a wrong answer, a bad tool choice) rather than by\ncrashing, so you need to see exactly what each step received and produced, in order and with timing.\nLogs tell you something happened; a trace tells you what caused what on this request.","review":"fact-checked","status":"ok"},{"id":"spans","key":"observability/spans","module":"observability","name":"Spans","taxonomy_name":"spans","kind":"concept","difficulty":"core","est_minutes":12,"related":["observability/tracing","observability/distributed-tracing-across-services","observability/opentelemetry","observability/latency-percentiles","node-ts-for-ai/opentelemetry-instrumentation","serving-inference/ttft"],"tldr":"A span is the unit a trace is built from: one named operation with a start time, an end time, a\nparent, a status and a set of attributes, plus optional timestamped events. Traces are only as useful\nas their spans, so the real skill is choosing span boundaries that match the questions you will ask,\nand recording the attributes (model, tokens, chunk ids, tool arguments) that let a span be filtered,\naggregated and understood on its own.","review":"fact-checked","status":"ok"},{"id":"distributed-tracing-across-services","key":"observability/distributed-tracing-across-services","module":"observability","name":"Distributed tracing across services","taxonomy_name":"distributed tracing across services","kind":"concept","difficulty":"core","est_minutes":14,"related":["observability/tracing","observability/spans","observability/opentelemetry","system-design/ai-gateway","agents/model-context-protocol","agent-reliability/conversation-execution-identifiers","llmops-platform/observability-stack"],"tldr":"One user turn in a production LLM system typically crosses several processes: an API gateway, an\norchestrator, a retrieval service, a model gateway, tool servers, perhaps a queue. In-process span\ncontext dies at each boundary, so distributed tracing *propagates* the trace id and parent span id\nwith every call (the W3C `traceparent` header for HTTP, message metadata for queues) and each service\ncontinues the same tree. Without it you get disconnected fragments and cannot attribute latency or\nfailure to the hop that actually mattered.","review":"fact-checked","status":"ok"},{"id":"logging","key":"observability/logging","module":"observability","name":"Logging","taxonomy_name":"logging","kind":"practice","difficulty":"intro","est_minutes":12,"related":["observability/tracing","observability/monitoring","python-for-ai/logging-structlog","fastapi-for-ai/structured-logging","agent-reliability/audit-logs-execution-traces","safety-security/pii-redaction","data-architecture/data-retention-and-deletion-architecture"],"tldr":"Logging records discrete events as structured, searchable records: timestamp, level, event name, the\ntrace and request ids that tie each line to the rest of the system, and event-specific fields. In LLM\napps, logs hold what traces and metrics should not: rendered prompts, raw completions before parsing,\ntool arguments and results, guardrail decisions and provider errors, redacted and retained by policy.\nThe design work is deciding what to log, at which level, in what shape, and how to bind it to the\nrequest.","review":"fact-checked","status":"ok"},{"id":"monitoring","key":"observability/monitoring","module":"observability","name":"Monitoring","taxonomy_name":"monitoring","kind":"practice","difficulty":"core","est_minutes":14,"related":["observability/latency-percentiles","observability/token-cost-tracking","observability/logging","reliability/slas-slos","llmops-platform/model-monitoring","llmops-platform/drift","deployment/health-checks"],"tldr":"Monitoring turns the stream of individual requests into aggregate signals (rates, errors, latency\ndistributions, saturation, plus LLM-specific quality and cost signals), compares them with targets,\nand pages someone when they drift. A trace explains one request; monitoring says whether the system is\nhealthy now. The LLM-specific difficulty is that the worst failures (wrong answers, prompt\nregressions, silent model changes) return HTTP 200, so you must monitor proxies and sampled quality\nscores, not just errors.","review":"fact-checked","status":"ok"},{"id":"token-cost-tracking","key":"observability/token-cost-tracking","module":"observability","name":"Token / cost tracking","taxonomy_name":"token / cost tracking","kind":"practice","difficulty":"core","est_minutes":14,"related":["observability/monitoring","observability/spans","infra-capacity-economics/cost-modeling","infra-capacity-economics/cost-allocation-by-tenant-and-feature","prompting/prompt-caching","python-for-ai/tiktoken","model-internals/tokenization","agent-reliability/max-step-budgets"],"tldr":"LLM spend is metered per token, priced differently for input, output and cached tokens, and varies\nby model, so the only way to know what a feature, tenant or agent run costs is to record the\nprovider's reported usage on every call and multiply by the price in force at that moment. Track it\nat span level, roll it up by the dimensions you make decisions on, and alert on budgets; retries,\nagent loops and growing conversation history make cost non-linear in requests, so per-request\naverages mislead.","review":"fact-checked","status":"ok"},{"id":"latency-percentiles","key":"observability/latency-percentiles","module":"observability","name":"Latency percentiles (p50/p95/p99)","taxonomy_name":"latency percentiles (p50/p95/p99)","kind":"metric","difficulty":"core","est_minutes":15,"related":["observability/monitoring","observability/tracing","serving-inference/ttft","serving-inference/throughput-vs-latency","reliability/slas-slos","infra-capacity-economics/queueing-theory","infra-capacity-economics/latency-budgets"],"tldr":"Latency is a distribution, not a number. A handful of slow requests drags the mean up while most users\nnever see them, and a long tail hides behind a healthy-looking average. A percentile reports the value\nbelow which p% of requests finish: p50 is the typical experience, p95 and p99 are the tail that users\nnotice and that fan-out amplifies. For LLM systems, measure percentiles per phase (time to first token,\nper-token, end to end) and compute them by merging histograms, never by averaging percentiles.","review":"fact-checked","status":"ok"},{"id":"opentelemetry","key":"observability/opentelemetry","module":"observability","name":"OpenTelemetry","taxonomy_name":"OpenTelemetry","kind":"tool","difficulty":"core","est_minutes":16,"related":["observability/tracing","observability/spans","observability/distributed-tracing-across-services","observability/logging","observability/arize-phoenix","observability/langfuse","fastapi-for-ai/opentelemetry-instrumentation","node-ts-for-ai/opentelemetry-instrumentation"],"tldr":"OpenTelemetry (OTel) is the CNCF vendor-neutral standard for *producing* telemetry: one API and SDK per\nlanguage for traces, metrics and logs, one wire protocol (OTLP), one context-propagation format (W3C\nTrace Context) and one vocabulary of attribute names. It exists so instrumentation is written once and\nthe backend (Jaeger, Tempo, Datadog, Langfuse, Phoenix) becomes a configuration choice. For LLM\napplications it is the plumbing under most tracing tools, and the way an LLM span lands in the same trace\nas the HTTP, queue and database spans around it.","review":"fact-checked","status":"ok"},{"id":"langfuse","key":"observability/langfuse","module":"observability","name":"Langfuse","taxonomy_name":"Langfuse","kind":"tool","difficulty":"core","est_minutes":15,"related":["observability/tracing","observability/token-cost-tracking","observability/opentelemetry","observability/langsmith","observability/arize-phoenix","evals/tooling","evals/llm-as-a-judge","prompting/prompt-versioning"],"tldr":"Langfuse is an open-source, self-hostable LLM engineering platform. It records nested observations\n(spans, generations, events) carrying the rendered prompt, the completion, token usage and cost, grouped\ninto traces, sessions and users, and closes the loop with scores (user feedback, human annotation,\nLLM-as-a-judge), datasets and experiments, and versioned prompt management. Choose it for the\ntrace-to-eval-to-prompt loop in one framework-independent tool that can run in your own infrastructure.","review":"fact-checked","status":"ok"},{"id":"langsmith","key":"observability/langsmith","module":"observability","name":"LangSmith","taxonomy_name":"LangSmith","kind":"tool","difficulty":"core","est_minutes":15,"related":["observability/tracing","observability/langfuse","observability/arize-phoenix","observability/opentelemetry","agents/frameworks","evals/tooling","evals/golden-dataset","agent-reliability/agent-trajectory-evaluation"],"tldr":"LangSmith is LangChain Inc.'s closed-source platform for tracing, evaluating and monitoring LLM\napplications, hosted with enterprise self-hosting available. It records every unit of work as a run\n(LLM, chain, tool, retriever) in a tree with inputs, outputs, tokens, latency and cost, attaches feedback\nand online evaluators, and runs offline experiments against datasets. Any Python or JavaScript code can\nsend traces through `@traceable`, but it is the natural choice for LangChain and LangGraph apps, where\ntracing is an environment-variable switch.","review":"fact-checked","status":"ok"},{"id":"arize-phoenix","key":"observability/arize-phoenix","module":"observability","name":"Arize Phoenix","taxonomy_name":"Arize Phoenix","kind":"tool","difficulty":"core","est_minutes":15,"related":["observability/opentelemetry","observability/tracing","observability/langfuse","observability/langsmith","evals/tooling","evals/hallucination-evaluation","evals/retrieval-evaluation","rag-retrieval/retrieval-failure-diagnosis"],"tldr":"Arize Phoenix is a self-hostable (source-available, Elastic License 2.0) LLM observability and evaluation\ntool built directly on OpenTelemetry: applications send ordinary OTel spans annotated with OpenInference conventions (LLM,\nretriever, tool, agent span kinds) and Phoenix stores, visualises and evaluates them. Its strengths are\ningestion without a proprietary SDK, an evaluation library that runs LLM-as-a-judge over traces as\nDataFrames and writes verdicts back onto spans, and embedding visualisation for retrieval failures. Arize\nAX is the separate commercial platform.","review":"fact-checked","status":"ok"}]},{"id":"safety-security","tier":1,"order":10,"title":"Safety & security","intro":null,"topics":[{"id":"input-output-guardrails","key":"safety-security/input-output-guardrails","module":"safety-security","name":"Input / output guardrails","taxonomy_name":"input / output guardrails","kind":"pattern","difficulty":"core","est_minutes":16,"related":["safety-security/prompt-injection","safety-security/output-validation","safety-security/content-moderation","safety-security/pii-redaction","safety-security/llama-guard","safety-security/nemo-guardrails","customer-data-evaluation/per-customer-guardrails","evals/red-teaming"],"tldr":"A language model is a probabilistic component whose behaviour you cannot fully specify in a prompt, so\nthe system around it needs deterministic checkpoints. Input guardrails inspect what reaches the model\n(injection patterns, scope, PII, size); output guardrails inspect what leaves it (structure, policy,\nleakage, tool calls) and decide to allow, block, rewrite, retry or escalate. They exist because a\nsystem prompt is an instruction, not an enforcement boundary, and the cost of a wrong output is paid\noutside the model.","review":"fact-checked","status":"ok"},{"id":"output-validation","key":"safety-security/output-validation","module":"safety-security","name":"Output validation (Pydantic, Instructor, Outlines)","taxonomy_name":"output validation (Pydantic, Instructor, Outlines)","kind":"practice","difficulty":"core","est_minutes":16,"related":["python-for-ai/pydantic","python-for-ai/instructor","python-for-ai/outlines","prompting/structured-outputs-json-mode","serving-inference/structured-constrained-generation","agents/tool-schemas-and-argument-validation","safety-security/input-output-guardrails","node-ts-for-ai/runtime-schema-validation"],"tldr":"A model's output is a string until something proves otherwise. Output validation turns it into typed\ndata your code can trust. Pydantic defines the contract and rejects what does not fit; Instructor wraps\nthe model call so a validation failure becomes a retry with the error fed back; Outlines constrains\ndecoding so the model cannot emit a token that breaks the schema. Choose by where you can intervene:\nafter the fact, in the loop, or inside decoding. Shape can be guaranteed; meaning must be checked.","review":"fact-checked","status":"ok"},{"id":"pii-redaction","key":"safety-security/pii-redaction","module":"safety-security","name":"PII redaction","taxonomy_name":"PII redaction","kind":"practice","difficulty":"core","est_minutes":15,"related":["security-governance-compliance/pii-protection-dlp","safety-security/data-leakage","safety-security/input-output-guardrails","observability/tracing","observability/logging","data-architecture/data-retention-and-deletion-architecture","rag-retrieval/acl-aware-retrieval"],"tldr":"PII redaction finds personal identifiers in text and replaces them before the text reaches a place it\nshould not: a third-party model, a log, a trace, a vector index, or another user's screen. It matters\nmore in LLM systems than in ordinary apps because they copy text into far more places, each a new\nretention point. Reversible pseudonymisation, typed placeholders with a short-lived mapping, keeps the\nmodel useful while raw values stay inside your boundary.","review":"fact-checked","status":"ok"},{"id":"content-moderation","key":"safety-security/content-moderation","module":"safety-security","name":"Content moderation","taxonomy_name":"content moderation","kind":"practice","difficulty":"core","est_minutes":14,"related":["safety-security/llama-guard","safety-security/input-output-guardrails","prompting/jailbreaks","evals/red-teaming","ml-fundamentals/classification","customer-data-evaluation/per-customer-guardrails"],"tldr":"Content moderation classifies text (increasingly images too) against a harm taxonomy such as hate,\nharassment, sexual content, self-harm, violence and illegal activity, then routes it: allow, block,\nsafe-complete or escalate. In LLM systems it runs in both directions, because users send harmful content\nand models generate it, and on retrieved content, because that is input too. It is a classification\nproblem with policy attached: thresholds and actions are a product decision, not a property of the model.","review":"fact-checked","status":"ok"},{"id":"prompt-injection","key":"safety-security/prompt-injection","module":"safety-security","name":"Prompt injection (direct, indirect)","taxonomy_name":"prompt injection (direct, indirect)","kind":"concept","difficulty":"core","est_minutes":18,"related":["prompting/prompt-injection","prompting/jailbreaks","security-governance-compliance/prompt-injection-defense","safety-security/rag-poisoning","safety-security/excessive-agency","safety-security/input-output-guardrails","agents/mcp-authentication-authorization-transport-security","agents/approval-gates-for-consequential-actions"],"tldr":"Prompt injection is untrusted text being treated as instructions. It happens because a transformer has\none input stream and no hardware distinction between what the developer said and what a document says.\nIn direct injection the user writes the attack. In indirect injection the attack sits in content the\nmodel reads, a web page, an email, a PDF, a tool result, and the user is the victim. There is no\nparameterised query to make it go away; defence is reducing privilege, isolating untrusted content and\ncontrolling what outputs can do.","review":"fact-checked","status":"ok"},{"id":"rag-poisoning","key":"safety-security/rag-poisoning","module":"safety-security","name":"RAG poisoning","taxonomy_name":"RAG poisoning","kind":"concept","difficulty":"core","est_minutes":15,"related":["safety-security/prompt-injection","rag-retrieval/acl-aware-retrieval","rag-retrieval/freshness-document-deletion-index-consistency","rag-retrieval/citations-grounding","data-architecture/ingestion-pipelines","data-architecture/data-lineage","safety-security/supply-chain-security-for-models-and-datasets","rag-retrieval/retrieval-failure-diagnosis"],"tldr":"RAG makes your corpus part of the prompt, so whoever can write to the corpus can write to the prompt.\nPoisoning takes two forms: instructions hidden inside documents (indirect prompt injection delivered by\nretrieval) and knowledge corruption, where crafted documents are built to be retrieved for target\nquestions and to steer the answer. The defences live mostly on the write path and in the ingestion\npipeline: provenance, trust tiers, sanitisation, access control, and monitoring of what retrieval returns.","review":"fact-checked","status":"ok"},{"id":"excessive-agency","key":"safety-security/excessive-agency","module":"safety-security","name":"Excessive agency","taxonomy_name":"excessive agency","kind":"concept","difficulty":"core","est_minutes":16,"related":["safety-security/tool-privilege-escalation","agents/approval-gates-for-consequential-actions","agents/human-in-the-loop","agent-reliability/tool-permissions-and-least-privilege","agents/sandboxing","agent-runtime-architecture/approval-and-authorization-boundaries","safety-security/owasp-top-10-for-llms","agent-reliability/max-step-budgets"],"tldr":"Excessive agency is an LLM system that can do more than its task needs: too many functions, too much\npermission, or too much autonomy. Then a bad decision, from a hallucinated intent, an injected\ninstruction or an ambiguous request, becomes real damage. The fix is not a smarter model but a smaller\nblast radius: minimal tools, credentials scoped to the user and enforced outside the model, and human\ncheckpoints before irreversible or external actions.","review":"fact-checked","status":"ok"},{"id":"tool-privilege-escalation","key":"safety-security/tool-privilege-escalation","module":"safety-security","name":"Tool privilege escalation","taxonomy_name":"tool privilege escalation","kind":"concept","difficulty":"core","est_minutes":15,"related":["safety-security/excessive-agency","safety-security/prompt-injection","agent-reliability/tool-permissions-and-least-privilege","agents/approval-gates-for-consequential-actions","agents/sandboxing","agent-runtime-architecture/secrets-and-credential-isolation","agents/mcp-authentication-authorization-transport-security","backend-fundamentals/rbac"],"tldr":"An agent's privilege is the union of everything its tools can do, and the model that picks the next tool\ncall can be steered by anyone whose text reaches its context. Tool privilege escalation is a low-trust\ninput (a user, a fetched page, a retrieved document) exercising a high-trust capability (a service\naccount, a shell, a payment API) through the model. The fix is not a sterner system prompt but making\neach tool call carry only the authority of the principal who asked.","review":"fact-checked","status":"ok"},{"id":"cross-tenant-data-leakage","key":"safety-security/cross-tenant-data-leakage","module":"safety-security","name":"Cross-tenant data leakage","taxonomy_name":"cross-tenant data leakage","kind":"concept","difficulty":"core","est_minutes":15,"related":["system-design/tenant-isolation","system-design/multi-tenancy","rag-retrieval/acl-aware-retrieval","rag-retrieval/metadata-filtering","agent-runtime-architecture/multi-tenant-state-isolation","safety-security/data-leakage","system-design/caching-strategy-and-cache-invalidation","reliability/tenant-level-quotas-and-noisy-neighbor-isolation"],"tldr":"Cross-tenant leakage is tenant A's data appearing in tenant B's answer. It happens because an LLM\npipeline copies data into stores the database's row-level security never sees: vector indexes, semantic\nand prefix caches, conversation memory, traces, sometimes the weights themselves. The fix is one\nserver-derived tenant identity threaded as a hard, pre-applied filter through every store and proven by\nnegative tests, not a prompt telling the model to use only this customer's documents.","review":"fact-checked","status":"ok"},{"id":"data-leakage","key":"safety-security/data-leakage","module":"safety-security","name":"Data leakage","taxonomy_name":"data leakage","kind":"concept","difficulty":"core","est_minutes":15,"related":["safety-security/pii-redaction","safety-security/cross-tenant-data-leakage","safety-security/prompt-injection","security-governance-compliance/pii-protection-dlp","security-governance-compliance/data-classification","ml-fundamentals/train-test-leakage","observability/logging","agent-runtime-architecture/secrets-and-credential-isolation"],"tldr":"Data leakage in an LLM system is any path by which information crosses a boundary it should not: into a\nthird-party API, into another user's answer, into model weights, or out through a tool call or rendered\nlink. It is distinct from ML train/test leakage. Channels multiply because an LLM app copies data into\nprompts, caches, traces, embeddings and weights, and the model repeats whatever it has seen. So minimise\nwhat enters, control what leaves, and assume no boundary exists inside the prompt.","review":"fact-checked","status":"ok"},{"id":"supply-chain-security-for-models-and-datasets","key":"safety-security/supply-chain-security-for-models-and-datasets","module":"safety-security","name":"Supply-chain security for models & datasets","taxonomy_name":"supply-chain security for models & datasets","kind":"practice","difficulty":"core","est_minutes":16,"related":["python-for-ai/safetensors","python-for-ai/hugging-face","python-for-ai/security-scanning-and-dependency-auditing","data-architecture/model-and-dataset-provenance","llmops-platform/model-registry","safety-security/rag-poisoning","security-governance-compliance/model-governance","evals/dataset-contamination"],"tldr":"A model checkpoint or dataset pulled from a public hub is a dependency with worse properties than a\nlibrary: it can execute code when loaded (pickle), it can carry behaviour you cannot read in a diff\n(backdoored weights), and its training data may have been poisoned before anyone you trust touched it.\nSupply-chain security treats models and datasets like any other build artifact, pinned, hashed, scanned,\nsigned, quarantined and loaded with the least capability, because you cannot review ten billion floats\nfor intent.","review":"fact-checked","status":"ok"},{"id":"owasp-top-10-for-llms","key":"safety-security/owasp-top-10-for-llms","module":"safety-security","name":"OWASP Top 10 for LLMs","taxonomy_name":"OWASP Top 10 for LLMs","kind":"concept","difficulty":"intro","est_minutes":13,"related":["safety-security/prompt-injection","safety-security/excessive-agency","safety-security/supply-chain-security-for-models-and-datasets","safety-security/rag-poisoning","safety-security/data-leakage","safety-security/output-validation","security-governance-compliance/threat-modeling","deployment/security-questionnaires"],"tldr":"The OWASP Top 10 for LLM Applications lists the most consequential risk classes in systems that embed a\nlanguage model, shaped like the web Top 10 so security teams, vendors and auditors share a vocabulary.\nIts value is the framing: the model is an untrusted component that follows instructions found in data,\nso every classic boundary (input validation, output encoding, least privilege, supply chain, resource\nlimits) must be redrawn around the prompt. This lesson is the map; the deep lessons are elsewhere in\nthis module.","review":"fact-checked","status":"ok"},{"id":"llama-guard","key":"safety-security/llama-guard","module":"safety-security","name":"Llama Guard","taxonomy_name":"Llama Guard","kind":"tool","difficulty":"core","est_minutes":13,"related":["safety-security/content-moderation","safety-security/input-output-guardrails","safety-security/nemo-guardrails","safety-security/prompt-injection","python-for-ai/hugging-face","customer-data-evaluation/per-customer-guardrails"],"tldr":"Llama Guard is Meta's family of open-weight content-safety classifiers, made by fine-tuning a Llama model\nto read a safety policy, a user prompt and optionally the assistant's reply, and generate `safe` or\n`unsafe` plus the violated category codes. Because the policy is text in the prompt rather than a fixed\nlabel head, categories can be edited without retraining. It is a moderation model, not a prompt-injection,\nPII or hallucination detector, and every check costs a full LLM forward pass.","review":"fact-checked","status":"ok"},{"id":"nemo-guardrails","key":"safety-security/nemo-guardrails","module":"safety-security","name":"NeMo Guardrails","taxonomy_name":"NeMo Guardrails","kind":"tool","difficulty":"core","est_minutes":14,"related":["safety-security/input-output-guardrails","safety-security/llama-guard","safety-security/content-moderation","safety-security/prompt-injection","safety-security/pii-redaction","safety-security/output-validation","agents/state-machines","customer-data-evaluation/per-customer-guardrails"],"tldr":"NeMo Guardrails is NVIDIA's open-source toolkit that sits between your application and the LLM and runs\nprogrammable \"rails\" at five points: input, dialogue flow, retrieved chunks, tool execution, and output.\nRails are declared in Colang and YAML rather than scattered through code, and dialogue rails map free\ntext to canonical intents via an embedding index of example utterances (plus a short LLM call by\ndefault), so policy becomes explicit flows. It orchestrates classifiers such as Llama Guard and Presidio\nrather than being one.","review":"fact-checked","status":"ok"}]},{"id":"multimodal","tier":1,"order":11,"title":"Multimodal","intro":null,"topics":[{"id":"vision-language-models","key":"multimodal/vision-language-models","module":"multimodal","name":"Vision-language models","taxonomy_name":"vision-language models","kind":"concept","difficulty":"core","est_minutes":15,"related":["multimodal/clip","multimodal/image-embeddings","multimodal/ocr","multimodal/document-understanding","model-internals/transformer","model-internals/context-window","prompting/structured-outputs-json-mode","agents/computer-use"],"tldr":"A vision-language model (VLM) lets a language model take images as input by turning each image into a\nsequence of \"visual tokens\" that sit in the same embedding space as text tokens. A pretrained vision\nencoder produces patch features, a small connector projects them into the LLM's input space, and the\nLLM attends over image and text jointly. It exists because describing an image as text first throws\naway exactly the details the question will turn out to need.","review":"fact-checked","status":"ok"},{"id":"clip","key":"multimodal/clip","module":"multimodal","name":"CLIP","taxonomy_name":"CLIP","kind":"concept","difficulty":"core","est_minutes":15,"related":["multimodal/image-embeddings","multimodal/vision-language-models","model-internals/embeddings","rag-retrieval/similarity-search","rag-retrieval/embedding-models","ml-fundamentals/supervised-vs-unsupervised-vs-self-supervised-learning","prompting/zero-shot"],"tldr":"CLIP trains an image encoder and a text encoder together so that an image and its caption land close\nin one shared vector space, using a contrastive loss over large batches of (image, text) pairs scraped\nfrom the web. Because the labels are free-form text rather than a fixed class list, the result can\nclassify, search and filter images by *description*, zero-shot, and its encoders became the standard\nvisual front end for vision-language models and multimodal search.","review":"fact-checked","status":"ok"},{"id":"image-embeddings","key":"multimodal/image-embeddings","module":"multimodal","name":"Image embeddings","taxonomy_name":"image embeddings","kind":"concept","difficulty":"core","est_minutes":14,"related":["multimodal/clip","multimodal/vision-language-models","multimodal/document-understanding","model-internals/embeddings","rag-retrieval/similarity-search","rag-retrieval/ann-indexes","rag-retrieval/embedding-dimension-and-normalization","data-architecture/embedding-versioning-re-indexing-strategy"],"tldr":"An image embedding is a fixed-length vector produced by a neural encoder such that visually or\nsemantically similar images have nearby vectors, usually under cosine similarity. It exists because\npixels are not comparable (two photos of the same object differ in every pixel) and labels are\nexpensive; an embedding turns images into something a vector index can search, cluster and deduplicate.\nWhich encoder you pick decides what \"similar\" means.","review":"fact-checked","status":"ok"},{"id":"ocr","key":"multimodal/ocr","module":"multimodal","name":"OCR","taxonomy_name":"OCR","kind":"concept","difficulty":"core","est_minutes":14,"related":["multimodal/document-understanding","multimodal/vision-language-models","rag-retrieval/document-parsing","data-architecture/document-processing-pipelines","enterprise-integration/client-document-parsing","rag-retrieval/chunking-strategies","prompting/prompt-injection"],"tldr":"OCR turns pixels that depict text into text: it finds where text is, recognises the characters in each\nregion, and returns strings with positions and confidences. It exists because a large share of\nenterprise information lives in scans, photos and image-only PDFs that have no text layer, and every\ndownstream step, search, extraction, RAG, LLM reasoning, needs characters rather than pixels. The hard\nparts are layout, image quality and knowing when the output is wrong.","review":"fact-checked","status":"ok"},{"id":"speech-to-text","key":"multimodal/speech-to-text","module":"multimodal","name":"Speech-to-text (Whisper)","taxonomy_name":"speech-to-text (Whisper)","kind":"concept","difficulty":"core","est_minutes":16,"related":["multimodal/tts","multimodal/vision-language-models","model-internals/transformer","model-internals/tokenization","serving-inference/streaming","fastapi-for-ai/websockets","infra-capacity-economics/latency-budgets","safety-security/pii-redaction"],"tldr":"Speech-to-text (automatic speech recognition, ASR) converts audio into a transcript. Whisper is an\nencoder-decoder transformer that reads a log-Mel spectrogram of a 30-second window and generates text\ntokens, trained on roughly 680,000 hours of weakly labelled web audio so it transcribes, identifies\nlanguages and translates robustly across accents and noise without per-domain tuning. It exists because\nearlier systems needed carefully aligned data per language and domain and broke outside their training\nconditions.","review":"fact-checked","status":"ok"},{"id":"tts","key":"multimodal/tts","module":"multimodal","name":"TTS (text-to-speech)","taxonomy_name":"TTS","kind":"concept","difficulty":"core","est_minutes":15,"related":["multimodal/speech-to-text","serving-inference/streaming","fastapi-for-ai/websockets","infra-capacity-economics/latency-budgets","prompting/structured-outputs-json-mode","model-internals/tokenization"],"tldr":"Text-to-speech turns a string into a waveform. Modern systems normalise the text, predict a compact\nacoustic representation (a mel-spectrogram or neural-codec tokens) with prosody, and then a vocoder or\ncodec decoder turns that into audio. It exists because the output side of every voice product, agents,\naccessibility, IVR, narration, needs speech that is intelligible, natural and generated fast enough to\nfeel conversational, and concatenating recorded fragments cannot do that for arbitrary text.","review":"fact-checked","status":"ok"},{"id":"document-understanding","key":"multimodal/document-understanding","module":"multimodal","name":"Document understanding","taxonomy_name":"document understanding","kind":"concept","difficulty":"advanced","est_minutes":16,"related":["multimodal/ocr","multimodal/vision-language-models","multimodal/image-embeddings","rag-retrieval/document-parsing","data-architecture/document-processing-pipelines","enterprise-integration/client-document-parsing","prompting/structured-outputs-json-mode","evals/golden-dataset"],"tldr":"Document understanding is turning pages (invoices, contracts, forms, reports) into structured,\nverifiable information: classified, with fields extracted, tables recovered and questions answered.\nIt exists because text alone is not the document; meaning lives in layout, position and tables, and\nOCR-plus-regex pipelines break on every new template. The modern mechanism is a model that reads text,\nposition and pixels together, wrapped in a pipeline that validates and routes what it cannot verify.","review":"fact-checked","status":"ok"}]},{"id":"backend-fundamentals","tier":1,"order":12,"title":"Backend fundamentals","intro":null,"topics":[{"id":"python","key":"backend-fundamentals/python","module":"backend-fundamentals","name":"Python","taxonomy_name":"Python","kind":"tool","difficulty":"intro","est_minutes":10,"related":["python-for-ai/async-await","python-for-ai/gil","python-for-ai/asyncio-vs-threads-vs-multiprocessing","python-for-ai/pydantic","python-for-ai/type-hints","python-for-ai/uv-poetry-pip","backend-fundamentals/fastapi","backend-fundamentals/node-js-typescript"],"tldr":"This is an orientation lesson; the deep dive is the `python-for-ai` module. Python is the default\nlanguage of AI backends not because it is fast but because every model library, tokenizer and\nprovider SDK is Python-first, and because an AI service spends almost all of its time waiting on a\nmodel rather than executing Python. `asyncio` turns that waiting into cheap concurrency; the GIL\nonly bites on CPU-bound pure-Python work, which you push to native libraries or other processes.","note":"Python as the AI backend language; deep dive lives in the python-for-ai module","status":"ok"},{"id":"fastapi","key":"backend-fundamentals/fastapi","module":"backend-fundamentals","name":"FastAPI","taxonomy_name":"FastAPI","kind":"tool","difficulty":"intro","est_minutes":11,"related":["fastapi-for-ai/asgi-lifecycle","fastapi-for-ai/async-endpoints","fastapi-for-ai/pydantic-request-response-models","fastapi-for-ai/dependency-injection","fastapi-for-ai/streamingresponse","fastapi-for-ai/openapi-docs","backend-fundamentals/python","backend-fundamentals/rest-graphql-api-design"],"tldr":"This is an orientation lesson; the deep dive is the `fastapi-for-ai` module. FastAPI is the default\nframework for Python AI services because it is async-native (ASGI, built on Starlette), uses Pydantic\nmodels as the single source of truth for validation, serialisation and OpenAPI docs, and makes\nstreaming and dependency injection first-class: exactly what an endpoint that waits seconds on a\nmodel needs. Its sharp edge: one blocking call inside an `async def` handler stalls every request on\nthat worker.","note":"why FastAPI for AI services; deep dive lives in the fastapi-for-ai module","status":"ok"},{"id":"node-js-typescript","key":"backend-fundamentals/node-js-typescript","module":"backend-fundamentals","name":"Node.js / TypeScript","taxonomy_name":"Node.js / TypeScript","kind":"tool","difficulty":"intro","est_minutes":11,"related":["node-ts-for-ai/event-loop-and-microtask-queue","node-ts-for-ai/runtime-schema-validation","node-ts-for-ai/streams-and-backpressure","node-ts-for-ai/worker-threads-for-cpu-bound-tasks","node-ts-for-ai/vercel-ai-sdk","node-ts-for-ai/mcp-typescript-sdk","backend-fundamentals/python","agent-runtime-architecture/cross-language-api-contracts"],"tldr":"This is an orientation lesson; the deep dive is the `node-ts-for-ai` module. Node.js with TypeScript\nis where the product edge of an AI system lives: the web app, streaming chat routes, the\nbackend-for-frontend, serverless functions, MCP servers and agent glue. It shares the frontend's\nlanguage and its event loop proxies many concurrent streams cheaply. It is a poor home for inference,\nevals and data work, so most stacks put TypeScript at the edge and Python at the core, joined by an\nHTTP contract.","note":"where Node/TS fits in AI systems; deep dive lives in node-ts-for-ai","status":"ok"},{"id":"rest-graphql-api-design","key":"backend-fundamentals/rest-graphql-api-design","module":"backend-fundamentals","name":"REST / GraphQL API design","taxonomy_name":"REST / GraphQL API design","kind":"decision","difficulty":"core","est_minutes":15,"related":["backend-fundamentals/api-versioning-and-backward-compatibility","backend-fundamentals/pagination-rate-limits-api-quotas","fastapi-for-ai/openapi-docs","fastapi-for-ai/server-sent-events","fastapi-for-ai/httpexception-handling","serving-inference/idempotency","serving-inference/streaming","agent-runtime-architecture/cross-language-api-contracts"],"tldr":"An API is a contract that outlives the code behind it. REST models a system as resources addressed by\nURLs and manipulated with HTTP methods whose semantics (safe, idempotent, cacheable) every proxy,\ncache and SDK already understands. GraphQL models it as a typed graph that clients query through one\nendpoint for exactly the shape they need. Choose REST for service-to-service and model-facing\nendpoints (simple, cacheable, streamable, tool-callable); choose GraphQL when many client shapes read\none rich domain and over- and under-fetching is the real pain.","status":"ok"},{"id":"api-and-sdk-integration","key":"backend-fundamentals/api-and-sdk-integration","module":"backend-fundamentals","name":"API & SDK integration","taxonomy_name":"API & SDK integration","kind":"practice","difficulty":"core","est_minutes":14,"related":["python-for-ai/openai-sdk","python-for-ai/anthropic-sdk","python-for-ai/httpx","python-for-ai/tenacity","serving-inference/retry-strategies","serving-inference/timeouts","reliability/circuit-breakers","node-ts-for-ai/api-clients-with-retries-and-circuit-breakers"],"tldr":"Most of an AI system is glue to APIs you do not control. An SDK is a vendor-maintained HTTP client\nthat bakes in auth, typed models, retries, pagination and stream parsing; use it, but know what it\ndoes with timeouts, retries and versions, because its defaults suit the average caller, not your\nlatency budget. The durable skill is a thin integration layer with explicit timeouts, a retry policy,\nidempotency, an error taxonomy and observability, whether or not an SDK sits underneath.","status":"ok"},{"id":"api-versioning-and-backward-compatibility","key":"backend-fundamentals/api-versioning-and-backward-compatibility","module":"backend-fundamentals","name":"API versioning & backward compatibility","taxonomy_name":"API versioning & backward compatibility","kind":"practice","difficulty":"core","est_minutes":14,"related":["backend-fundamentals/rest-graphql-api-design","fastapi-for-ai/openapi-contract-testing","fastapi-for-ai/routers","python-for-ai/contract-testing","data-architecture/data-contracts","llmops-platform/model-lifecycle-and-deprecation-policy","prompting/prompt-versioning","agent-runtime-architecture/cross-language-api-contracts"],"tldr":"Once someone else's code depends on your API, every change is a negotiation with clients you cannot\nredeploy. Backward compatibility means additive changes by default (new optional fields, new\nendpoints) and tolerant readers on both sides; versioning is the escape hatch for the rare breaking\nchange, expressed in the path, a header or a pinned date, with an announced deprecation and sunset.\nIn AI systems the same discipline covers model snapshots, prompt versions and tool schemas.","status":"ok"},{"id":"pagination-rate-limits-api-quotas","key":"backend-fundamentals/pagination-rate-limits-api-quotas","module":"backend-fundamentals","name":"Pagination, rate limits & API quotas","taxonomy_name":"pagination / rate limits / API quotas","kind":"concept","difficulty":"core","est_minutes":16,"related":["backend-fundamentals/rest-graphql-api-design","backend-fundamentals/api-and-sdk-integration","backend-fundamentals/redis","backend-fundamentals/sql","fastapi-for-ai/rate-limiting","serving-inference/retry-strategies","infra-capacity-economics/api-provider-quotas-and-regional-limits","reliability/tenant-level-quotas-and-noisy-neighbor-isolation"],"tldr":"Three bounds every API needs, at three time scales. Pagination bounds one response, because an\nunbounded list is a memory and latency bomb on both ends. Rate limits bound requests (or tokens) per\nsecond or minute, because capacity is shared and bursts must be shed before they cascade. Quotas bound\ntotal consumption per day or month, because calls cost money and tenants need entitlements. You design\nall three as a provider and handle all three as a consumer; for LLM traffic the binding limit is\nusually tokens per minute.","status":"ok"},{"id":"webhook-signature-verification-and-replay-protection","key":"backend-fundamentals/webhook-signature-verification-and-replay-protection","module":"backend-fundamentals","name":"Webhook signature verification & replay protection","taxonomy_name":"webhook signature verification & replay protection","kind":"practice","difficulty":"core","est_minutes":15,"related":["backend-fundamentals/api-and-sdk-integration","backend-fundamentals/message-queues","backend-fundamentals/secrets-management","backend-fundamentals/authentication-vs-authorization","enterprise-integration/webhooks","enterprise-integration/retry-deduplication-reconciliation","fastapi-for-ai/idempotency-keys","system-design/exactly-once-processing-limitations"],"tldr":"A webhook endpoint is a public URL that anyone on the internet can POST to, so the payload proves\nnothing by itself. Providers therefore sign each delivery: an HMAC-SHA256 over a timestamp and the raw\nbody using a secret only you and they hold, which you recompute and compare in constant time. A\nsignature alone stays valid forever, so replay protection adds a timestamp window and deduplication by\nevent id, and because providers retry on any failure, the handler has to be idempotent anyway.","status":"ok"},{"id":"database-design","key":"backend-fundamentals/database-design","module":"backend-fundamentals","name":"Database design","taxonomy_name":"database design","kind":"concept","difficulty":"core","est_minutes":16,"related":["backend-fundamentals/sql","backend-fundamentals/nosql","backend-fundamentals/postgresql-transactions-and-isolation-levels","fastapi-for-ai/sqlalchemy-sqlmodel","fastapi-for-ai/alembic-migrations","system-design/multi-tenancy","agent-reliability/state-and-checkpoint-stores","rag-retrieval/vector-databases"],"tldr":"A schema is the one part of a system that outlives every version of the code, so it has to encode the\nfacts that must stay true (keys, constraints, ownership) rather than the shape of today's screens.\nNormalize so each fact lives in one place and cannot drift, then denormalize deliberately where a measured\nread path needs it. Design indexes from the queries you will actually run, not from the columns you have.","status":"ok"},{"id":"sql","key":"backend-fundamentals/sql","module":"backend-fundamentals","name":"SQL","taxonomy_name":"SQL","kind":"concept","difficulty":"core","est_minutes":16,"related":["backend-fundamentals/database-design","backend-fundamentals/postgresql-transactions-and-isolation-levels","backend-fundamentals/nosql","fastapi-for-ai/sqlalchemy-sqlmodel","node-ts-for-ai/postgresql-transactions-and-migrations","observability/token-cost-tracking","rag-retrieval/hybrid-search"],"tldr":"SQL is declarative: you state which rows and columns you want, and a cost-based planner chooses the join\norder, scan type and algorithm. That separation is why one query can survive a 1000× growth in data if the\nright index exists, and why the same query collapses when it does not. Thinking in sets rather than loops,\nand reading the plan rather than guessing, is the whole skill.","status":"ok"},{"id":"nosql","key":"backend-fundamentals/nosql","module":"backend-fundamentals","name":"NoSQL","taxonomy_name":"NoSQL","kind":"concept","difficulty":"core","est_minutes":16,"related":["backend-fundamentals/database-design","backend-fundamentals/sql","backend-fundamentals/redis","system-design/data-consistency","system-design/distributed-systems","agent-reliability/state-and-checkpoint-stores","rag-retrieval/vector-databases"],"tldr":"NoSQL stores give up general joins and cross-record transactions so that data can be partitioned across\nmany machines by a key and served with predictable latency at any size. The price is that you must design\nthe data around the exact queries you will run, and accept weaker consistency on some reads. Choose one\nfor a known, narrow access pattern at scale, not because \"schemaless\" sounds easier.","status":"ok"},{"id":"redis","key":"backend-fundamentals/redis","module":"backend-fundamentals","name":"Redis","taxonomy_name":"Redis","kind":"tool","difficulty":"core","est_minutes":15,"related":["fastapi-for-ai/redis-caching","node-ts-for-ai/redis","backend-fundamentals/nosql","backend-fundamentals/message-queues","backend-fundamentals/background-jobs-durable-workers","fastapi-for-ai/rate-limiting","system-design/caching-strategy-and-cache-invalidation","serving-inference/caching"],"tldr":"Redis is an in-memory data-structure server: strings, hashes, lists, sets, sorted sets and streams,\naddressed by key, with every command executed atomically on a single thread. That combination makes it\nthe default place for the fast, shared, short-lived state a backend needs (caches, rate limits, locks,\nsessions, queues) at the cost of memory-sized data and durability that is weaker than a database unless\nyou configure and accept the trade.","status":"ok"},{"id":"postgresql-transactions-and-isolation-levels","key":"backend-fundamentals/postgresql-transactions-and-isolation-levels","module":"backend-fundamentals","name":"PostgreSQL transactions & isolation levels","taxonomy_name":"PostgreSQL transactions & isolation levels","kind":"concept","difficulty":"core","est_minutes":18,"related":["backend-fundamentals/database-design","backend-fundamentals/sql","backend-fundamentals/background-jobs-durable-workers","fastapi-for-ai/async-database-access-and-connection-pooling","fastapi-for-ai/idempotency-keys","node-ts-for-ai/postgresql-transactions-and-migrations","system-design/data-consistency","system-design/saga-pattern-and-distributed-transactions"],"tldr":"A transaction makes a group of statements atomic and durable; the isolation level decides what each\ntransaction may see of the others while they run. PostgreSQL implements isolation with multi-version\nconcurrency control, so readers never block writers, and the default READ COMMITTED level is fast but\npermits lost updates and write skew in read-modify-write code. You fix those with explicit row locks,\natomic updates, or SERIALIZABLE plus a retry loop.","status":"ok"},{"id":"message-queues","key":"backend-fundamentals/message-queues","module":"backend-fundamentals","name":"Message queues (Kafka, SQS, RabbitMQ)","taxonomy_name":"message queues (Kafka, SQS, RabbitMQ)","kind":"concept","difficulty":"core","est_minutes":18,"related":["backend-fundamentals/background-jobs-durable-workers","backend-fundamentals/redis","system-design/event-driven-architecture","system-design/outbox-inbox-patterns","system-design/exactly-once-processing-limitations","fastapi-for-ai/job-queues-and-durable-workers","reliability/backpressure-and-load-shedding","infra-capacity-economics/queueing-theory"],"tldr":"A message queue puts a durable buffer between the code that produces work and the code that does it, so\nthe two no longer have to be up, fast, or scaled the same way at the same moment. Every real broker\ndelivers at least once, so consumers must be idempotent. Kafka is a replayable partitioned log, SQS is a\nmanaged queue with no replay, and RabbitMQ is a flexible-routing broker; the choice follows from whether\nyou need ordering, replay, routing or just a simple buffer.","status":"ok"},{"id":"background-jobs-durable-workers","key":"backend-fundamentals/background-jobs-durable-workers","module":"backend-fundamentals","name":"Background jobs / durable workers","taxonomy_name":"background jobs / durable workers","kind":"pattern","difficulty":"core","est_minutes":17,"related":["backend-fundamentals/message-queues","backend-fundamentals/redis","backend-fundamentals/postgresql-transactions-and-isolation-levels","fastapi-for-ai/job-queues-and-durable-workers","node-ts-for-ai/bullmq-and-durable-jobs","system-design/outbox-inbox-patterns","reliability/durable-workflow-execution","agent-reliability/durable-execution-and-checkpointing"],"tldr":"A background job is work a request handler hands off so it can respond now. A *durable* worker is one\nwhere the job's existence, state and progress live in a store that outlives both the process that\nenqueued it and the process running it, so a deploy or crash never loses the work. Durability is bought\nwith a lease-and-acknowledge protocol, which means a job can run twice, so every job body must be\nidempotent.","status":"ok"},{"id":"authentication-vs-authorization","key":"backend-fundamentals/authentication-vs-authorization","module":"backend-fundamentals","name":"Authentication vs authorization","taxonomy_name":"authentication vs authorization","kind":"concept","difficulty":"intro","est_minutes":14,"related":["backend-fundamentals/oauth-2-0-oidc","backend-fundamentals/rbac","fastapi-for-ai/api-keys-oauth2-jwt","enterprise-integration/sso-iam-integration","enterprise-integration/rbac-abac-mapping-to-customer-identity","agent-runtime-architecture/approval-and-authorization-boundaries","agents/mcp-authentication-authorization-transport-security","rag-retrieval/acl-aware-retrieval"],"tldr":"Authentication turns a credential into a verified *principal*: who is making this request.\nAuthorization decides whether that principal may perform *this action* on *this resource*. They are\ndifferent questions, answered at different points in the request, with different failure codes: 401\nmeans \"I do not know who you are\", 403 means \"I know, and no\". Most serious access-control bugs come\nfrom doing the first and assuming it implies the second.","status":"ok"},{"id":"oauth-2-0-oidc","key":"backend-fundamentals/oauth-2-0-oidc","module":"backend-fundamentals","name":"OAuth 2.0 / OIDC","taxonomy_name":"OAuth 2.0 / OIDC","kind":"concept","difficulty":"core","est_minutes":16,"related":["backend-fundamentals/authentication-vs-authorization","backend-fundamentals/rbac","backend-fundamentals/secrets-management","fastapi-for-ai/api-keys-oauth2-jwt","enterprise-integration/sso-iam-integration","enterprise-integration/saml-sso","agents/mcp-authentication-authorization-transport-security"],"tldr":"OAuth 2.0 is a delegated-authorization framework: an application obtains a scoped, expiring\naccess token to call an API on a user's behalf without ever seeing the user's password. OpenID Connect\n(OIDC) is a thin identity layer on top that adds a signed ID token so the application also learns *who*\nlogged in. OAuth answers \"may this app do X for this user\"; OIDC answers \"who is this user\". Most login\nbugs come from confusing the tokens that answer each question.","status":"ok"},{"id":"rbac","key":"backend-fundamentals/rbac","module":"backend-fundamentals","name":"RBAC","taxonomy_name":"RBAC","kind":"concept","difficulty":"core","est_minutes":14,"related":["backend-fundamentals/authentication-vs-authorization","backend-fundamentals/oauth-2-0-oidc","backend-fundamentals/kubernetes","enterprise-integration/rbac-abac-mapping-to-customer-identity","enterprise-integration/scim-provisioning","agent-reliability/tool-permissions-and-least-privilege","safety-security/tool-privilege-escalation","agent-runtime-architecture/approval-and-authorization-boundaries"],"tldr":"Role-based access control puts one layer of indirection, the role, between who a caller is and what\nthey may do: permissions attach to roles, callers are assigned roles within a scope, and a request is\nallowed only if some role of the caller grants that permission there. It exists because assigning\npermissions directly to users does not survive growth: the assignment table explodes, access reviews\nbecome impossible and offboarding leaks. The same check must bound what an agent may do for a user.","status":"ok"},{"id":"secrets-management","key":"backend-fundamentals/secrets-management","module":"backend-fundamentals","name":"Secrets management","taxonomy_name":"secrets management","kind":"practice","difficulty":"core","est_minutes":15,"related":["agent-runtime-architecture/secrets-and-credential-isolation","backend-fundamentals/oauth-2-0-oidc","backend-fundamentals/ci-cd","backend-fundamentals/kubernetes","backend-fundamentals/docker","deployment/terraform","python-for-ai/security-scanning-and-dependency-auditing","safety-security/prompt-injection"],"tldr":"A secret is any value whose disclosure lets someone act as your system: database passwords,\nmodel-provider API keys, signing keys, OAuth client secrets. Secrets management keeps them out of code,\nimages, logs and prompts; stores them encrypted in a purpose-built store; delivers them to workloads\nthat authenticate with a platform identity rather than yet another secret; and makes them short-lived,\nscoped and rotatable. The goal is not perfect hiding but a small blast radius when, not if, one leaks.","status":"ok"},{"id":"docker","key":"backend-fundamentals/docker","module":"backend-fundamentals","name":"Docker","taxonomy_name":"Docker","kind":"tool","difficulty":"core","est_minutes":15,"related":["backend-fundamentals/kubernetes","backend-fundamentals/ci-cd","backend-fundamentals/secrets-management","node-ts-for-ai/docker-ci-cd-deployment","python-for-ai/lockfiles-and-dependency-pinning","python-for-ai/uv-poetry-pip","fastapi-for-ai/graceful-shutdown-and-worker-draining","infra-capacity-economics/gpu-infrastructure"],"tldr":"Docker packages an application with its exact filesystem (OS libraries, interpreter, CUDA runtime,\nyour code) into an immutable, content-addressed image, and runs it as an isolated process on the\nhost's kernel using Linux namespaces and cgroups. It exists because \"install these dependencies on the\nserver\" is not reproducible; the image makes the build the unit of deployment, so what passed CI is\nbyte-for-byte what runs in production. For AI services the image pins the CUDA and torch stack, which\nis where most environment drift lives.","status":"ok"},{"id":"kubernetes","key":"backend-fundamentals/kubernetes","module":"backend-fundamentals","name":"Kubernetes","taxonomy_name":"Kubernetes","kind":"tool","difficulty":"core","est_minutes":17,"related":["backend-fundamentals/docker","backend-fundamentals/ci-cd","backend-fundamentals/secrets-management","fastapi-for-ai/health-readiness-endpoints","fastapi-for-ai/graceful-shutdown-and-worker-draining","infra-capacity-economics/keda-autoscaling","infra-capacity-economics/ray-kuberay","infra-capacity-economics/gpu-infrastructure"],"tldr":"Kubernetes runs containers across a fleet of machines by reconciling declared desired state (\"three\nreplicas of this image, one GPU each, ready when `/ready` returns 200\") against what is actually\nrunning. It exists because once there are more containers than one person can place by hand,\nscheduling, self-healing, rolling updates, service discovery and scaling have to be a platform rather\nthan scripts. For AI services, its contract of resource requests, probes and graceful termination is\nwhat makes GPU-bound, slow-starting, long-streaming workloads deployable without dropping requests.","status":"ok"},{"id":"ci-cd","key":"backend-fundamentals/ci-cd","module":"backend-fundamentals","name":"CI/CD","taxonomy_name":"CI/CD","kind":"practice","difficulty":"core","est_minutes":15,"related":["backend-fundamentals/docker","backend-fundamentals/kubernetes","backend-fundamentals/secrets-management","llmops-platform/ci-cd-for-prompts-and-models","llmops-platform/evaluation-gates-for-production-releases","llmops-platform/canary-shadow-deployments","llmops-platform/rollback","node-ts-for-ai/docker-ci-cd-deployment"],"tldr":"Continuous integration means every change is merged to the main line often and verified by an\nautomated build and test run on a clean machine; continuous delivery means every verified build\nbecomes one immutable artifact that can reach production through a repeatable, automated path, and\ncontinuous deployment removes the final button. The pipeline replaces trust in laptops with evidence\nand makes releases small and routine enough that failure is cheap to detect and reverse. For AI\nsystems it must gate prompts and models too, whose tests are evaluations.","status":"ok"}]},{"id":"python-for-ai","tier":1,"order":13,"title":"Python for AI","intro":null,"topics":[{"id":"type-hints","key":"python-for-ai/type-hints","module":"python-for-ai","name":"Type hints","taxonomy_name":"type hints","kind":"concept","difficulty":"intro","est_minutes":14,"related":["python-for-ai/mypy","python-for-ai/protocols-generics-structural-typing","python-for-ai/typeddict-literal-enum","python-for-ai/pydantic","python-for-ai/dataclasses","agents/typed-tool-contracts","node-ts-for-ai/typescript-strict-mode-and-advanced-types"],"tldr":"Type hints are annotations on parameters, return values and variables that describe what a value\nis expected to be. The interpreter stores them and ignores them; static checkers (mypy, pyright)\nand runtime libraries (Pydantic, FastAPI, dataclasses) read them. They exist because AI code is\nmostly glue between untyped JSON, provider SDKs and your own functions, and the cheapest place to\ncatch a shape mismatch is before the code runs, not after a thirty-minute batch job fails.","status":"ok"},{"id":"protocols-generics-structural-typing","key":"python-for-ai/protocols-generics-structural-typing","module":"python-for-ai","name":"Protocols, generics and structural typing","taxonomy_name":"Protocols / generics / structural typing","kind":"concept","difficulty":"core","est_minutes":16,"related":["python-for-ai/type-hints","python-for-ai/dependency-injection-and-interface-boundaries","python-for-ai/decorators","python-for-ai/mypy","python-for-ai/test-doubles-mocks-fixtures","agent-reliability/tool-adapters-service-interfaces","node-ts-for-ai/typescript-strict-mode-and-advanced-types"],"tldr":"A Protocol says \"anything with these methods is acceptable\", so a type checker can verify duck\ntyping without inheritance. Generics let you write a function or class once and have the checker\ntrack the element type through it, so `first(xs: list[Message])` is known to return a `Message`.\nTogether they are how you type the swappable parts of an AI system (embedders, LLM clients, vector\nstores, retry decorators) without forcing third-party classes into your class hierarchy.","status":"ok"},{"id":"typeddict-literal-enum","key":"python-for-ai/typeddict-literal-enum","module":"python-for-ai","name":"TypedDict, Literal and Enum","taxonomy_name":"TypedDict / Literal / Enum","kind":"concept","difficulty":"core","est_minutes":14,"related":["python-for-ai/type-hints","python-for-ai/pydantic","python-for-ai/dataclasses","python-for-ai/json-jsonl","agents/tool-schemas-and-argument-validation","prompting/structured-outputs-json-mode","agents/state-machines"],"tldr":"`TypedDict` types a plain dict with fixed keys, for JSON-shaped data you do not want to wrap in\nobjects. `Literal` restricts a value to a small fixed set of constants at zero runtime cost. `Enum`\nturns such a set into real runtime objects with identity, iteration and methods. AI code is full of\nwire-format dicts and tiny closed vocabularies (roles, finish reasons, tool names), and the type\nchecker can only protect those if you name them; these three are how you do it.","status":"ok"},{"id":"pydantic","key":"python-for-ai/pydantic","module":"python-for-ai","name":"Pydantic","taxonomy_name":"Pydantic","kind":"tool","difficulty":"core","est_minutes":16,"related":["python-for-ai/type-hints","python-for-ai/dataclasses","python-for-ai/typeddict-literal-enum","python-for-ai/pydantic-settings","python-for-ai/instructor","fastapi-for-ai/pydantic-request-response-models","prompting/structured-outputs-json-mode","agents/tool-schemas-and-argument-validation"],"tldr":"Pydantic turns type-annotated classes into validators, parsers, serializers and JSON Schema\ngenerators. You declare the shape once as a `BaseModel`; untrusted input (API payloads, LLM output,\nconfig files) is validated into typed objects with structured error reports, and the same class\nemits the JSON Schema you hand to a model for structured output or tool calling. It exists because\nAI systems are mostly untrusted JSON crossing boundaries, and type hints alone do nothing at runtime.","status":"ok"},{"id":"dataclasses","key":"python-for-ai/dataclasses","module":"python-for-ai","name":"dataclasses","taxonomy_name":"dataclasses","kind":"concept","difficulty":"intro","est_minutes":13,"related":["python-for-ai/type-hints","python-for-ai/pydantic","python-for-ai/object-model-and-mutability","python-for-ai/typeddict-literal-enum","python-for-ai/memory-and-performance-profiling","agent-reliability/state-and-checkpoint-stores"],"tldr":"`@dataclass` generates `__init__`, `__repr__`, `__eq__` and optionally ordering, hashing and\n`__slots__` from a class's annotated fields, so a record type is five lines instead of thirty. It\nexists because AI code is full of small structured records (generation configs, agent steps,\nretrieved chunks) that need equality, readable reprs and sometimes immutability, and hand-writing\nthose methods is where bugs and inconsistencies creep in. It validates nothing; that is Pydantic's\njob.","status":"ok"},{"id":"object-model-and-mutability","key":"python-for-ai/object-model-and-mutability","module":"python-for-ai","name":"Object model and mutability","taxonomy_name":"object model & mutability","kind":"concept","difficulty":"core","est_minutes":16,"related":["python-for-ai/dataclasses","python-for-ai/memory-and-performance-profiling","python-for-ai/race-conditions-and-synchronization-primitives","python-for-ai/numpy","python-for-ai/pytorch","python-for-ai/decorators","agent-reliability/idempotent-tool-execution"],"tldr":"In Python a variable is a name bound to an object, never a box holding a value, and assignment never\ncopies. Objects are either mutable (list, dict, set, most classes, arrays and tensors) or immutable\n(int, str, tuple, frozenset). Nearly every \"the value changed by itself\" bug in AI code is aliasing: two\nnames, a default argument, a class attribute or a slice sharing one mutable object. Knowing which\noperations rebind a name and which mutate the object is the difference between a leak across tenants\nand a correct program.","status":"ok"},{"id":"exceptions-and-custom-exception-hierarchies","key":"python-for-ai/exceptions-and-custom-exception-hierarchies","module":"python-for-ai","name":"Exceptions and custom exception hierarchies","taxonomy_name":"exceptions & custom exception hierarchies","kind":"concept","difficulty":"core","est_minutes":15,"related":["python-for-ai/tenacity","python-for-ai/async-cancellation-and-exception-propagation","python-for-ai/logging-structlog","python-for-ai/context-managers-resource-cleanup","serving-inference/retry-strategies","fastapi-for-ai/httpexception-handling","system-design/model-fallback-strategies"],"tldr":"Exceptions carry a failure up the call stack until something that knows what to do catches it. A\ncustom hierarchy organises failures by *how they should be handled* (retry, shrink the input,\nre-prompt, give up) rather than by where they came from, so callers catch one base class or one\nprecise leaf and never string-match messages. It is what keeps a rate limit from being treated like\nan invalid API key, and a bug in your own code from being retried at provider prices.","status":"ok"},{"id":"async-await","key":"python-for-ai/async-await","module":"python-for-ai","name":"async / await","taxonomy_name":"async / await","kind":"concept","difficulty":"core","est_minutes":16,"related":["python-for-ai/asyncio","python-for-ai/async-cancellation-and-exception-propagation","python-for-ai/race-conditions-and-synchronization-primitives","python-for-ai/asyncio-vs-threads-vs-multiprocessing","python-for-ai/gil","python-for-ai/httpx","fastapi-for-ai/async-endpoints","serving-inference/streaming"],"tldr":"`async def` defines a coroutine, a function that can pause at `await` while it waits for I/O and\nlet other coroutines run on the same thread. An event loop schedules them. It exists because AI\nworkloads are dominated by waiting on slow network calls (model providers, vector stores, tools),\noften many at once, and a single thread that interleaves thousands of waits is cheaper and simpler\nthan a thread per call. It does nothing for CPU-bound work, and one blocking call stalls everything.","status":"ok"},{"id":"asyncio","key":"python-for-ai/asyncio","module":"python-for-ai","name":"asyncio","taxonomy_name":"asyncio","kind":"concept","difficulty":"core","est_minutes":16,"related":["python-for-ai/async-await","python-for-ai/async-cancellation-and-exception-propagation","python-for-ai/race-conditions-and-synchronization-primitives","python-for-ai/asyncio-vs-threads-vs-multiprocessing","python-for-ai/httpx","fastapi-for-ai/async-endpoints","node-ts-for-ai/event-loop-and-microtask-queue"],"tldr":"An AI service spends almost all of its wall-clock time waiting: on an LLM provider, a vector database,\na tool endpoint. asyncio lets one thread interleave thousands of those waits by running coroutines on\nan event loop that only resumes a coroutine when the thing it awaited is ready. You get high\nconcurrency for I/O at near-zero per-task cost, in exchange for a strict contract: nothing on the loop\nmay block, or everything stalls.","status":"ok"},{"id":"async-cancellation-and-exception-propagation","key":"python-for-ai/async-cancellation-and-exception-propagation","name":"async cancellation & exception propagation","module":"python-for-ai","status":"missing"},{"id":"race-conditions-and-synchronization-primitives","key":"python-for-ai/race-conditions-and-synchronization-primitives","name":"race conditions & synchronization primitives (asyncio.Lock, Semaphore)","module":"python-for-ai","status":"missing"},{"id":"asyncio-vs-threads-vs-multiprocessing","key":"python-for-ai/asyncio-vs-threads-vs-multiprocessing","name":"asyncio vs threads vs multiprocessing","module":"python-for-ai","status":"missing"},{"id":"gil","key":"python-for-ai/gil","name":"GIL","module":"python-for-ai","status":"missing"},{"id":"generators","key":"python-for-ai/generators","name":"generators","module":"python-for-ai","status":"missing"},{"id":"decorators","key":"python-for-ai/decorators","name":"decorators","module":"python-for-ai","status":"missing"},{"id":"context-managers-resource-cleanup","key":"python-for-ai/context-managers-resource-cleanup","name":"context managers / resource cleanup","module":"python-for-ai","status":"missing"},{"id":"dependency-injection-and-interface-boundaries","key":"python-for-ai/dependency-injection-and-interface-boundaries","module":"python-for-ai","name":"Dependency injection & interface boundaries","taxonomy_name":"dependency injection & interface boundaries","kind":"pattern","difficulty":"core","est_minutes":15,"related":["python-for-ai/protocols-generics-structural-typing","python-for-ai/test-doubles-mocks-fixtures","python-for-ai/package-structure-and-import-design","python-for-ai/pydantic-settings","fastapi-for-ai/dependency-injection","node-ts-for-ai/dependency-injection","agent-reliability/tool-adapters-service-interfaces"],"tldr":"Dependency injection means a component receives the things it depends on (an LLM client, a vector\nstore, a clock) from outside instead of importing or constructing them itself. An interface boundary\nnames that dependency as a small `Protocol` in your own vocabulary rather than the vendor's. Together\nthey make AI code testable without network calls, swappable across providers, and honest about what it\nneeds, at the price of one layer of indirection that you must keep thin.","status":"ok"},{"id":"package-structure-and-import-design","key":"python-for-ai/package-structure-and-import-design","name":"package structure & import design","module":"python-for-ai","status":"missing"},{"id":"tenacity","key":"python-for-ai/tenacity","name":"tenacity","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"logging-structlog","key":"python-for-ai/logging-structlog","name":"logging / structlog","module":"python-for-ai","status":"missing"},{"id":"memory-and-performance-profiling","key":"python-for-ai/memory-and-performance-profiling","name":"memory & performance profiling","module":"python-for-ai","status":"missing"},{"id":"uv-poetry-pip","key":"python-for-ai/uv-poetry-pip","name":"uv / poetry / pip","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"lockfiles-and-dependency-pinning","key":"python-for-ai/lockfiles-and-dependency-pinning","name":"lockfiles & dependency pinning","module":"python-for-ai","status":"missing"},{"id":"security-scanning-and-dependency-auditing","key":"python-for-ai/security-scanning-and-dependency-auditing","name":"security scanning & dependency auditing (pip-audit, Bandit)","module":"python-for-ai","status":"missing"},{"id":"pytest","key":"python-for-ai/pytest","module":"python-for-ai","name":"pytest","taxonomy_name":"pytest","kind":"tool","difficulty":"intro","est_minutes":14,"related":["python-for-ai/pytest-asyncio","python-for-ai/test-doubles-mocks-fixtures","python-for-ai/property-based-testing","python-for-ai/integration-and-end-to-end-testing","python-for-ai/ruff","backend-fundamentals/ci-cd","evals/regression-tests"],"tldr":"pytest is the de facto Python test runner: plain `assert` statements that print the values involved\nwhen they fail, fixtures that inject setup by argument name, parametrization that turns one function\ninto a table of cases, and a hook system that asyncio, Hypothesis, xdist and coverage tools plug into.\nIt exists because unittest's class-and-method ceremony and opaque assertion failures made tests\nexpensive to write and slow to debug; pytest makes the cheap path the correct one.","status":"ok"},{"id":"pytest-asyncio","key":"python-for-ai/pytest-asyncio","name":"pytest-asyncio","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"test-doubles-mocks-fixtures","key":"python-for-ai/test-doubles-mocks-fixtures","name":"test doubles / mocks / fixtures","module":"python-for-ai","status":"missing"},{"id":"property-based-testing","key":"python-for-ai/property-based-testing","name":"property-based testing (Hypothesis)","module":"python-for-ai","status":"missing"},{"id":"contract-testing","key":"python-for-ai/contract-testing","name":"contract testing","module":"python-for-ai","status":"missing"},{"id":"integration-and-end-to-end-testing","key":"python-for-ai/integration-and-end-to-end-testing","name":"integration & end-to-end testing","module":"python-for-ai","status":"missing"},{"id":"mypy","key":"python-for-ai/mypy","name":"mypy","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"ruff","key":"python-for-ai/ruff","name":"ruff","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"python-dotenv","key":"python-for-ai/python-dotenv","name":"python-dotenv","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"pydantic-settings","key":"python-for-ai/pydantic-settings","name":"pydantic-settings","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"json-jsonl","key":"python-for-ai/json-jsonl","name":"JSON / JSONL","module":"python-for-ai","status":"missing"},{"id":"numpy","key":"python-for-ai/numpy","name":"numpy","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"pandas","key":"python-for-ai/pandas","name":"pandas","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"polars","key":"python-for-ai/polars","name":"polars","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"pyarrow","key":"python-for-ai/pyarrow","name":"pyarrow","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"scikit-learn-basics","key":"python-for-ai/scikit-learn-basics","name":"scikit-learn basics","module":"python-for-ai","status":"missing"},{"id":"pytorch","key":"python-for-ai/pytorch","name":"PyTorch (tensors, autograd, nn.Module, DataLoader, device)","module":"python-for-ai","status":"missing"},{"id":"hugging-face","key":"python-for-ai/hugging-face","name":"Hugging Face (transformers, datasets, tokenizers, accelerate, PEFT, TRL)","module":"python-for-ai","status":"missing"},{"id":"sentence-transformers","key":"python-for-ai/sentence-transformers","name":"sentence-transformers","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"tiktoken","key":"python-for-ai/tiktoken","name":"tiktoken","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"safetensors","key":"python-for-ai/safetensors","name":"safetensors","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"openai-sdk","key":"python-for-ai/openai-sdk","name":"OpenAI SDK","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"anthropic-sdk","key":"python-for-ai/anthropic-sdk","name":"Anthropic SDK","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"litellm","key":"python-for-ai/litellm","name":"LiteLLM","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"instructor","key":"python-for-ai/instructor","name":"Instructor","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"outlines","key":"python-for-ai/outlines","name":"Outlines","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"mcp-python-sdk","key":"python-for-ai/mcp-python-sdk","name":"MCP Python SDK","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"httpx","key":"python-for-ai/httpx","name":"httpx","kind_hint":"tool","module":"python-for-ai","status":"missing"},{"id":"jupyter","key":"python-for-ai/jupyter","name":"Jupyter","kind_hint":"tool","module":"python-for-ai","status":"missing"}]},{"id":"fastapi-for-ai","tier":1,"order":14,"title":"FastAPI for AI","intro":null,"topics":[{"id":"asgi-lifecycle","key":"fastapi-for-ai/asgi-lifecycle","module":"fastapi-for-ai","name":"ASGI lifecycle","taxonomy_name":"ASGI lifecycle","kind":"concept","difficulty":"core","est_minutes":14,"related":["fastapi-for-ai/lifespan","fastapi-for-ai/middleware-ordering","fastapi-for-ai/uvicorn-gunicorn-workers","fastapi-for-ai/graceful-shutdown-and-worker-draining","fastapi-for-ai/cancellation-on-client-disconnect","python-for-ai/asyncio","backend-fundamentals/fastapi"],"tldr":"ASGI is the contract between an async server (Uvicorn, Hypercorn) and your application: the app is a\nsingle `async def app(scope, receive, send)` that the server calls once per connection, plus one special\n`lifespan` connection per process for startup and shutdown. Everything FastAPI does at runtime —\nlifespan, middleware, streaming, disconnect detection, per-worker state — is a move in this message\nprotocol, so knowing the sequence explains behaviour that otherwise looks like magic.","status":"ok"},{"id":"middleware-ordering","key":"fastapi-for-ai/middleware-ordering","module":"fastapi-for-ai","name":"Middleware ordering","taxonomy_name":"middleware ordering","kind":"concept","difficulty":"core","est_minutes":13,"related":["fastapi-for-ai/asgi-lifecycle","fastapi-for-ai/cors","fastapi-for-ai/api-keys-oauth2-jwt","fastapi-for-ai/structured-logging","fastapi-for-ai/httpexception-handling","fastapi-for-ai/opentelemetry-instrumentation","fastapi-for-ai/streamingresponse"],"tldr":"Middleware in FastAPI is a stack of ASGI apps wrapped around each other: a request walks down the stack\nand the response walks back up. `app.add_middleware()` inserts at the *outside*, so the last one added\nruns first on the way in and last on the way out. Order decides whether a 401 carries CORS headers,\nwhether a trace ID exists when auth logs, and whether timing sees exceptions. Starlette also pins\n`ServerErrorMiddleware` outermost and `ExceptionMiddleware` innermost, which explains several surprises.","status":"ok"},{"id":"async-endpoints","key":"fastapi-for-ai/async-endpoints","module":"fastapi-for-ai","name":"Async endpoints","taxonomy_name":"async endpoints","kind":"concept","difficulty":"core","est_minutes":14,"related":["python-for-ai/async-await","python-for-ai/asyncio","python-for-ai/gil","python-for-ai/asyncio-vs-threads-vs-multiprocessing","fastapi-for-ai/shared-httpx-asyncclient","fastapi-for-ai/concurrency-limits","fastapi-for-ai/cancellation-on-client-disconnect","serving-inference/batching-and-concurrency-limits"],"tldr":"FastAPI runs `async def` endpoints on the single event loop and plain `def` endpoints in a worker thread\npool. An `async def` handler that awaits I/O (an LLM API, a database, Redis) lets one process hold\nhundreds of in-flight requests; an `async def` handler that *blocks* (a sync SDK call, a local model\nforward pass) freezes every request in the process. The rule for AI services: await remote models,\nthread or offload local ones, and never mix the two up.","status":"ok"},{"id":"pydantic-request-response-models","key":"fastapi-for-ai/pydantic-request-response-models","module":"fastapi-for-ai","name":"Pydantic request / response models","taxonomy_name":"Pydantic request / response models","kind":"pattern","difficulty":"core","est_minutes":14,"related":["python-for-ai/pydantic","fastapi-for-ai/response-model","fastapi-for-ai/openapi-docs","fastapi-for-ai/httpexception-handling","prompting/structured-outputs-json-mode","agents/tool-schemas-and-argument-validation","backend-fundamentals/rest-graphql-api-design","backend-fundamentals/api-versioning-and-backward-compatibility"],"tldr":"A FastAPI endpoint declares its request body and its response as Pydantic models. The framework\nvalidates inbound JSON against the request model (rejecting bad input with a 422 that names the field)\nand validates, filters and documents outbound data against the response model. For AI APIs this is the\ncontract that stops malformed messages, out-of-range sampling parameters and oversized prompts before\nthey cost money, and stops internal fields (system prompts, costs, raw provider payloads) from leaking\nout.","status":"ok"},{"id":"response-model","key":"fastapi-for-ai/response-model","module":"fastapi-for-ai","name":"response_model","taxonomy_name":"response_model","kind":"concept","difficulty":"core","est_minutes":11,"related":["fastapi-for-ai/pydantic-request-response-models","python-for-ai/pydantic","fastapi-for-ai/openapi-docs","fastapi-for-ai/openapi-contract-testing","fastapi-for-ai/streamingresponse","safety-security/output-validation","backend-fundamentals/api-versioning-and-backward-compatibility"],"tldr":"`response_model` (or the endpoint's return annotation) tells FastAPI the exact shape a route may\nreturn. The framework validates the returned data against it, serialises *through* it so only declared\nfields leave the process, and publishes it in OpenAPI. It exists because what a handler happens to\nreturn is not a contract; a declared output schema is. For AI services it is the cheapest guarantee\nthat internal fields and raw provider payloads never reach a client.","status":"ok"},{"id":"dependency-injection","key":"fastapi-for-ai/dependency-injection","module":"fastapi-for-ai","name":"Dependency injection (Depends)","taxonomy_name":"dependency injection (Depends)","kind":"pattern","difficulty":"core","est_minutes":15,"related":["python-for-ai/dependency-injection-and-interface-boundaries","fastapi-for-ai/request-scoped-vs-application-scoped-resources","fastapi-for-ai/lifespan","fastapi-for-ai/api-keys-oauth2-jwt","fastapi-for-ai/testclient-plus-pytest-asyncio","python-for-ai/test-doubles-mocks-fixtures","python-for-ai/context-managers-resource-cleanup","fastapi-for-ai/async-database-access-and-connection-pooling"],"tldr":"`Depends` lets an endpoint declare what it needs — an authenticated principal, a DB session, the LLM\nclient, a tenant's config — as typed parameters. FastAPI resolves them per request, caches each within\nthe request, runs their cleanup after the handler, and lets tests swap any of them with\n`dependency_overrides`. It replaces global singletons and copy-pasted auth checks with a tree of small\ncallables, which is what makes an AI service testable without calling the real model.","status":"ok"},{"id":"request-scoped-vs-application-scoped-resources","key":"fastapi-for-ai/request-scoped-vs-application-scoped-resources","module":"fastapi-for-ai","name":"Request-scoped vs application-scoped resources","taxonomy_name":"request-scoped vs application-scoped resources","kind":"decision","difficulty":"core","est_minutes":13,"related":["fastapi-for-ai/lifespan","fastapi-for-ai/dependency-injection","fastapi-for-ai/shared-httpx-asyncclient","fastapi-for-ai/async-database-access-and-connection-pooling","fastapi-for-ai/uvicorn-gunicorn-workers","fastapi-for-ai/redis-caching","python-for-ai/context-managers-resource-cleanup","python-for-ai/race-conditions-and-synchronization-primitives"],"tldr":"Every object in a FastAPI process has a scope. Application-scoped things (model weights, tokenizer,\nprovider client with its connection pool, DB engine, vector index, settings) are built once per worker\nin lifespan and shared by all requests; request-scoped things (DB session, transaction, auth principal,\nrequest ID, budget, trace span) are built by a dependency and die with the request. Wrong in one\ndirection wastes seconds and sockets per request; wrong in the other leaks one user's state into\nanother's.","status":"ok"},{"id":"lifespan","key":"fastapi-for-ai/lifespan","name":"lifespan (load model / client once)","module":"fastapi-for-ai","status":"missing"},{"id":"streamingresponse","key":"fastapi-for-ai/streamingresponse","module":"fastapi-for-ai","name":"StreamingResponse","taxonomy_name":"StreamingResponse","kind":"pattern","difficulty":"core","est_minutes":14,"related":["fastapi-for-ai/server-sent-events","fastapi-for-ai/websockets","fastapi-for-ai/async-endpoints","fastapi-for-ai/cancellation-on-client-disconnect","fastapi-for-ai/backpressure","fastapi-for-ai/timeouts","serving-inference/streaming","serving-inference/ttft"],"tldr":"`StreamingResponse` lets an endpoint hand the server an iterator instead of a finished body, so bytes\nleave the process as soon as each chunk exists. For LLM endpoints that turns the wait the user feels\nfrom \"the whole generation\" into \"time to first token\", and it stops the server holding entire\nresponses in memory. The price: status and headers are frozen at the first byte, so mid-stream errors\nmust be signalled inside the body, and nothing between the generator and the browser may buffer.","status":"ok"},{"id":"server-sent-events","key":"fastapi-for-ai/server-sent-events","module":"fastapi-for-ai","name":"Server-Sent Events","taxonomy_name":"Server-Sent Events","kind":"concept","difficulty":"core","est_minutes":15,"related":["fastapi-for-ai/streamingresponse","fastapi-for-ai/websockets","fastapi-for-ai/cancellation-on-client-disconnect","fastapi-for-ai/timeouts","serving-inference/streaming","agent-reliability/structured-event-streams"],"tldr":"Server-Sent Events (SSE) is a one-directional, text-based streaming format carried in an ordinary HTTP\nresponse of type `text/event-stream`: events are blocks of `field: value` lines separated by a blank\nline. It exists because a raw chunked body has no message boundaries and WebSockets are a heavier,\nstateful protocol for what is usually a one-way token flow. Browsers reconnect automatically and resend\n`Last-Event-ID`, which is why LLM vendor APIs and most chat UIs stream tokens over SSE.","status":"ok"},{"id":"websockets","key":"fastapi-for-ai/websockets","module":"fastapi-for-ai","name":"WebSockets","taxonomy_name":"WebSockets","kind":"concept","difficulty":"core","est_minutes":16,"related":["fastapi-for-ai/server-sent-events","fastapi-for-ai/streamingresponse","fastapi-for-ai/api-keys-oauth2-jwt","fastapi-for-ai/backpressure","fastapi-for-ai/cancellation-on-client-disconnect","fastapi-for-ai/uvicorn-gunicorn-workers","serving-inference/cancellation"],"tldr":"A WebSocket upgrades one HTTP connection into a persistent, full-duplex channel that carries framed\ntext or binary messages in both directions. Reach for it when the client must talk *while* the server\nis streaming: interrupting a generation, two-way voice audio, agent sessions with mid-run approvals.\nThe price is state: the connection is pinned to one process, authentication, reconnection and resume\nare hand-rolled, and every load balancer in the path must understand long-lived upgrades. For one-way\ntoken streaming, SSE is simpler.","status":"ok"},{"id":"backgroundtasks","key":"fastapi-for-ai/backgroundtasks","module":"fastapi-for-ai","name":"BackgroundTasks","taxonomy_name":"BackgroundTasks","kind":"pattern","difficulty":"core","est_minutes":12,"related":["fastapi-for-ai/job-queues-and-durable-workers","fastapi-for-ai/dependency-injection","fastapi-for-ai/request-scoped-vs-application-scoped-resources","fastapi-for-ai/graceful-shutdown-and-worker-draining","fastapi-for-ai/async-endpoints","backend-fundamentals/background-jobs-durable-workers"],"tldr":"`BackgroundTasks` runs functions *after* the response has been sent, in the same process and event\nloop, with no persistence, no retry and no status. It exists so a handler can answer quickly while\ndoing cheap follow-up work (write a trace, bump a usage counter, fire a webhook) without standing up a\nqueue. Use it for work you can afford to lose when the process dies; anything that must happen, or\nthat takes more than a few seconds, belongs in a durable job queue.","status":"ok"},{"id":"job-queues-and-durable-workers","key":"fastapi-for-ai/job-queues-and-durable-workers","module":"fastapi-for-ai","name":"Job queues & durable workers (Celery / ARQ + job-status endpoint)","taxonomy_name":"job queues & durable workers (Celery / ARQ + job-status endpoint)","kind":"pattern","difficulty":"core","est_minutes":18,"related":["backend-fundamentals/background-jobs-durable-workers","backend-fundamentals/message-queues","backend-fundamentals/redis","fastapi-for-ai/backgroundtasks","fastapi-for-ai/idempotency-keys","node-ts-for-ai/bullmq-and-durable-jobs","reliability/durable-workflow-execution","system-design/synchronous-vs-asynchronous-execution"],"tldr":"A job queue moves slow or must-complete work (batch summarisation, embedding a corpus, a long agent\nrun) out of the request into worker processes, after recording the job's existence somewhere durable,\nso the API can answer `202 Accepted` with a job id and the client learns the outcome from a job-status\nendpoint. Celery is the mature, sync-first, multi-broker option; ARQ is a small asyncio-native queue on\nRedis. Both deliver at-least-once, so every job body must be idempotent.","status":"ok"},{"id":"async-database-access-and-connection-pooling","key":"fastapi-for-ai/async-database-access-and-connection-pooling","module":"fastapi-for-ai","name":"Async database access & connection pooling","taxonomy_name":"async database access & connection pooling","kind":"concept","difficulty":"core","est_minutes":16,"related":["fastapi-for-ai/sqlalchemy-sqlmodel","fastapi-for-ai/async-endpoints","fastapi-for-ai/lifespan","fastapi-for-ai/request-scoped-vs-application-scoped-resources","fastapi-for-ai/uvicorn-gunicorn-workers","fastapi-for-ai/concurrency-limits","backend-fundamentals/postgresql-transactions-and-isolation-levels","python-for-ai/asyncio"],"tldr":"An `async def` endpoint must never block the event loop, so database calls either go through an\nasync driver (asyncpg, psycopg 3, aiosqlite) behind SQLAlchemy's `AsyncEngine`, or stay in `def`\nendpoints that run on the thread pool. Opening a Postgres connection costs a server-side process plus\nTLS and authentication, and the server caps connections (100 by default), so each process keeps a\nbounded pool and `processes × (pool_size + max_overflow)` must fit. The AI-specific rule: never hold a\npooled connection across a model call.","status":"ok"},{"id":"sqlalchemy-sqlmodel","key":"fastapi-for-ai/sqlalchemy-sqlmodel","module":"fastapi-for-ai","name":"SQLAlchemy / SQLModel","taxonomy_name":"SQLAlchemy / SQLModel","kind":"tool","difficulty":"core","est_minutes":16,"related":["fastapi-for-ai/async-database-access-and-connection-pooling","fastapi-for-ai/alembic-migrations","fastapi-for-ai/pydantic-request-response-models","python-for-ai/pydantic","backend-fundamentals/sql","backend-fundamentals/database-design"],"tldr":"SQLAlchemy is Python's standard SQL toolkit: Core builds and executes SQL expressions safely, the ORM\nmaps classes to tables and tracks changes in a unit of work. SQLModel wraps SQLAlchemy's declarative\nmodels in Pydantic so one class can be both a table and an API schema, which is why FastAPI projects\nreach for it. Use SQLModel when the storage and API shapes agree; drop to plain SQLAlchemy 2.0 when\nyou need its full feature set or when the two shapes diverge, which they eventually do.","status":"ok"},{"id":"alembic-migrations","key":"fastapi-for-ai/alembic-migrations","name":"Alembic migrations","module":"fastapi-for-ai","status":"missing"},{"id":"timeouts","key":"fastapi-for-ai/timeouts","name":"timeouts","module":"fastapi-for-ai","status":"missing"},{"id":"idempotency-keys","key":"fastapi-for-ai/idempotency-keys","name":"idempotency keys","module":"fastapi-for-ai","status":"missing"},{"id":"cors","key":"fastapi-for-ai/cors","name":"CORS","module":"fastapi-for-ai","status":"missing"},{"id":"api-keys-oauth2-jwt","key":"fastapi-for-ai/api-keys-oauth2-jwt","name":"API keys / OAuth2 / JWT","module":"fastapi-for-ai","status":"missing"},{"id":"rate-limiting","key":"fastapi-for-ai/rate-limiting","name":"rate limiting (slowapi)","module":"fastapi-for-ai","status":"missing"},{"id":"request-size-limits-and-upload-security","key":"fastapi-for-ai/request-size-limits-and-upload-security","name":"request-size limits & upload security","module":"fastapi-for-ai","status":"missing"},{"id":"uploadfile","key":"fastapi-for-ai/uploadfile","name":"UploadFile","module":"fastapi-for-ai","status":"missing"},{"id":"httpexception-handling","key":"fastapi-for-ai/httpexception-handling","name":"HTTPException handling","module":"fastapi-for-ai","status":"missing"},{"id":"routers","key":"fastapi-for-ai/routers","name":"routers","module":"fastapi-for-ai","status":"missing"},{"id":"openapi-docs","key":"fastapi-for-ai/openapi-docs","name":"OpenAPI docs","module":"fastapi-for-ai","status":"missing"},{"id":"openapi-contract-testing","key":"fastapi-for-ai/openapi-contract-testing","name":"OpenAPI contract testing","module":"fastapi-for-ai","status":"missing"},{"id":"uvicorn-gunicorn-workers","key":"fastapi-for-ai/uvicorn-gunicorn-workers","name":"uvicorn / gunicorn workers","module":"fastapi-for-ai","status":"missing"},{"id":"graceful-shutdown-and-worker-draining","key":"fastapi-for-ai/graceful-shutdown-and-worker-draining","name":"graceful shutdown & worker draining","module":"fastapi-for-ai","status":"missing"},{"id":"health-readiness-endpoints","key":"fastapi-for-ai/health-readiness-endpoints","name":"health / readiness endpoints","module":"fastapi-for-ai","status":"missing"},{"id":"structured-logging","key":"fastapi-for-ai/structured-logging","name":"structured logging","module":"fastapi-for-ai","status":"missing"},{"id":"opentelemetry-instrumentation","key":"fastapi-for-ai/opentelemetry-instrumentation","name":"OpenTelemetry instrumentation","module":"fastapi-for-ai","status":"missing"},{"id":"redis-caching","key":"fastapi-for-ai/redis-caching","name":"Redis caching","module":"fastapi-for-ai","status":"missing"},{"id":"shared-httpx-asyncclient","key":"fastapi-for-ai/shared-httpx-asyncclient","name":"shared httpx AsyncClient","module":"fastapi-for-ai","status":"missing"},{"id":"testclient-plus-pytest-asyncio","key":"fastapi-for-ai/testclient-plus-pytest-asyncio","name":"TestClient + pytest-asyncio","module":"fastapi-for-ai","status":"missing"},{"id":"integration-tests-with-real-dependencies","key":"fastapi-for-ai/integration-tests-with-real-dependencies","name":"integration tests with real dependencies","module":"fastapi-for-ai","status":"missing"},{"id":"concurrency-limits","key":"fastapi-for-ai/concurrency-limits","name":"concurrency limits (semaphores)","module":"fastapi-for-ai","status":"missing"},{"id":"backpressure","key":"fastapi-for-ai/backpressure","name":"backpressure","module":"fastapi-for-ai","status":"missing"},{"id":"cancellation-on-client-disconnect","key":"fastapi-for-ai/cancellation-on-client-disconnect","name":"cancellation on client disconnect","module":"fastapi-for-ai","status":"missing"}]},{"id":"node-ts-for-ai","tier":1,"order":15,"title":"Node.js / TypeScript for AI","intro":null,"topics":[{"id":"typescript-strict-mode-and-advanced-types","key":"node-ts-for-ai/typescript-strict-mode-and-advanced-types","module":"node-ts-for-ai","name":"TypeScript strict mode & advanced types","taxonomy_name":"TypeScript strict mode & advanced types","kind":"concept","difficulty":"core","est_minutes":15,"related":["node-ts-for-ai/runtime-schema-validation","node-ts-for-ai/promises-and-async-error-propagation","python-for-ai/type-hints","python-for-ai/protocols-generics-structural-typing","agents/typed-tool-contracts","backend-fundamentals/node-js-typescript"],"tldr":"TypeScript types are erased before the code runs, so they only protect you if the compiler is allowed\nto be strict. `strict` turns on null checks, bans implicit `any` and makes function types sound; the\nadvanced features (discriminated unions, constrained generics, conditional/mapped/template-literal\ntypes, `satisfies`, `unknown`) let you encode the shapes AI code actually handles — stream events, tool\ncontracts, provider responses — so mismatches fail at compile time instead of as `undefined` crashes\nin the middle of a streamed answer.","status":"ok"},{"id":"event-loop-and-microtask-queue","key":"node-ts-for-ai/event-loop-and-microtask-queue","module":"node-ts-for-ai","name":"Event loop & microtask queue","taxonomy_name":"event loop & microtask queue","kind":"concept","difficulty":"core","est_minutes":14,"related":["node-ts-for-ai/promises-and-async-error-propagation","node-ts-for-ai/worker-threads-for-cpu-bound-tasks","node-ts-for-ai/streams-and-backpressure","python-for-ai/asyncio","python-for-ai/async-await","serving-inference/streaming"],"tldr":"Node runs your JavaScript on one thread and multiplexes thousands of in-flight I/O operations through\nthe event loop: libuv waits on sockets and files, and the loop runs callbacks in phases. Promise\ncallbacks and `process.nextTick` go on separate microtask queues that are drained completely after\nevery callback, before the loop advances. That is why an AI gateway can hold 5,000 open model streams\ncheaply, and also why one 200 ms synchronous computation stalls every one of them.","status":"ok"},{"id":"promises-and-async-error-propagation","key":"node-ts-for-ai/promises-and-async-error-propagation","module":"node-ts-for-ai","name":"Promises & async error propagation","taxonomy_name":"promises & async error propagation","kind":"concept","difficulty":"core","est_minutes":14,"related":["node-ts-for-ai/event-loop-and-microtask-queue","node-ts-for-ai/abortcontroller-and-cancellation","node-ts-for-ai/api-clients-with-retries-and-circuit-breakers","python-for-ai/async-cancellation-and-exception-propagation","python-for-ai/exceptions-and-custom-exception-hierarchies","serving-inference/retry-strategies"],"tldr":"A promise is a one-shot result that is either fulfilled or rejected, and `await` turns a rejection back\ninto a thrown exception at the awaiting site, so errors travel up the async call chain just like\nsynchronous ones. The failure modes are promises nobody awaits (rejections vanish or crash the process),\ncombinators that hide which call failed, and error objects that lose their cause. Getting this right is\nwhat makes a multi-provider LLM call fail loudly, precisely and recoverably.","status":"ok"},{"id":"streams-and-backpressure","key":"node-ts-for-ai/streams-and-backpressure","module":"node-ts-for-ai","name":"Streams & backpressure","taxonomy_name":"streams & backpressure","kind":"concept","difficulty":"core","est_minutes":15,"related":["node-ts-for-ai/abortcontroller-and-cancellation","node-ts-for-ai/event-loop-and-microtask-queue","serving-inference/streaming","serving-inference/backpressure","fastapi-for-ai/streamingresponse","reliability/backpressure-and-load-shedding","agent-reliability/structured-event-streams"],"tldr":"A stream processes data in chunks as it arrives instead of buffering everything, which is how a\ntoken-by-token model response reaches a browser with sub-second first-token latency. Backpressure is\nthe flow-control rule that makes this safe: when the consumer is slower than the producer, the\nproducer is told to pause, so memory stays bounded. Node has two stream APIs (classic `node:stream`\nand WHATWG Web Streams, used by `fetch`), and `pipeline`/`pipeTo` are what wire them together with\nerror propagation and backpressure intact.","status":"ok"},{"id":"worker-threads-for-cpu-bound-tasks","key":"node-ts-for-ai/worker-threads-for-cpu-bound-tasks","module":"node-ts-for-ai","name":"Worker threads for CPU-bound tasks","taxonomy_name":"worker threads for CPU-bound tasks","kind":"concept","difficulty":"core","est_minutes":14,"related":["node-ts-for-ai/event-loop-and-microtask-queue","node-ts-for-ai/bullmq-and-durable-jobs","python-for-ai/asyncio-vs-threads-vs-multiprocessing","python-for-ai/gil","serving-inference/batching-and-concurrency-limits"],"tldr":"The event loop runs all your JavaScript on one thread, so a CPU-heavy step freezes every concurrent\nrequest. `worker_threads` run JavaScript in separate V8 isolates on other OS threads, communicating by\nmessage passing (structured clone, or zero-copy transfer of `ArrayBuffer`s and shared memory via\n`SharedArrayBuffer`). Use a pool of them for sustained computation such as tokenizing, parsing large\ndocuments or vector math; use them sparingly, because each worker is a separate heap with its own\nstartup cost, and messages are copied unless transferred.","status":"ok"},{"id":"abortcontroller-and-cancellation","key":"node-ts-for-ai/abortcontroller-and-cancellation","module":"node-ts-for-ai","name":"AbortController & cancellation","taxonomy_name":"AbortController & cancellation","kind":"concept","difficulty":"core","est_minutes":14,"related":["node-ts-for-ai/promises-and-async-error-propagation","node-ts-for-ai/streams-and-backpressure","serving-inference/cancellation","serving-inference/timeouts","fastapi-for-ai/cancellation-on-client-disconnect","python-for-ai/async-cancellation-and-exception-propagation"],"tldr":"Promises cannot be cancelled, so JavaScript cancels cooperatively: an `AbortController` owns an\n`AbortSignal`, the signal is passed down to every operation that should stop together, and calling\n`abort()` makes `fetch`, timers, streams and your own code reject with an `AbortError`. In AI services\nthis is what stops a model from generating billed tokens after the user closed the tab, and what\nturns a 30-second timeout into a real stop rather than a promise you merely stopped waiting for.","status":"ok"},{"id":"runtime-schema-validation","key":"node-ts-for-ai/runtime-schema-validation","module":"node-ts-for-ai","name":"Runtime schema validation (Zod)","taxonomy_name":"runtime schema validation (Zod)","kind":"practice","difficulty":"core","est_minutes":15,"related":["node-ts-for-ai/typescript-strict-mode-and-advanced-types","node-ts-for-ai/openai-anthropic-node-sdks","python-for-ai/pydantic","agents/tool-schemas-and-argument-validation","prompting/structured-outputs-json-mode","safety-security/output-validation","fastapi-for-ai/pydantic-request-response-models"],"tldr":"TypeScript types vanish at compile time, so nothing checks the JSON that arrives from an HTTP client, a\nwebhook, an environment variable or a language model. Runtime schema validation defines the shape once\nas a value (a Zod schema), derives the static type from it, and parses untrusted input into a typed\nvalue or a structured list of errors. The same schema becomes the JSON Schema sent to the model for\ntool calling, so the contract the model follows is the contract you enforce.","status":"ok"},{"id":"dependency-injection","key":"node-ts-for-ai/dependency-injection","module":"node-ts-for-ai","name":"Dependency injection","taxonomy_name":"dependency injection","kind":"pattern","difficulty":"core","est_minutes":13,"related":["node-ts-for-ai/vitest-jest-and-integration-testing","node-ts-for-ai/typescript-strict-mode-and-advanced-types","node-ts-for-ai/openai-anthropic-node-sdks","node-ts-for-ai/api-clients-with-retries-and-circuit-breakers","agent-runtime-architecture/secrets-and-credential-isolation","agent-runtime-architecture/multi-tenant-state-isolation"],"tldr":"Dependency injection means a module receives its collaborators (LLM client, database pool, cache, clock,\nconfig) from the caller instead of importing or constructing them itself. AI services are mostly glue\naround expensive, non-deterministic, credentialed external calls; code that hard-wires those calls cannot\nbe tested without the network, cannot vary per tenant, and cannot swap providers without a rewrite. In\nTypeScript the pattern needs no framework: a typed `Deps` object and one composition root cover most\nservices.","status":"ok"},{"id":"postgresql-transactions-and-migrations","key":"node-ts-for-ai/postgresql-transactions-and-migrations","module":"node-ts-for-ai","name":"PostgreSQL transactions & migrations","taxonomy_name":"PostgreSQL transactions & migrations","kind":"practice","difficulty":"core","est_minutes":16,"related":["backend-fundamentals/postgresql-transactions-and-isolation-levels","backend-fundamentals/sql","fastapi-for-ai/alembic-migrations","fastapi-for-ai/async-database-access-and-connection-pooling","system-design/outbox-inbox-patterns","node-ts-for-ai/bullmq-and-durable-jobs","node-ts-for-ai/docker-ci-cd-deployment"],"tldr":"An AI backend's Postgres rows (conversations, agent runs, tool results, token budgets, embeddings)\nchange in groups, and the schema changes every sprint. Transactions make a group of writes atomic and\nlet concurrent agents contend safely; in Node the trap is that a pool hands out a different connection\nper query, so a transaction must pin one client. Migrations version the schema as ordered, recorded,\nforward-only scripts so every environment reaches the same state and a deploy never locks a live table\nfor minutes.","status":"ok"},{"id":"redis","key":"node-ts-for-ai/redis","module":"node-ts-for-ai","name":"Redis","taxonomy_name":"Redis","kind":"tool","difficulty":"core","est_minutes":14,"related":["backend-fundamentals/redis","fastapi-for-ai/redis-caching","system-design/caching-strategy-and-cache-invalidation","node-ts-for-ai/bullmq-and-durable-jobs","serving-inference/rate-limiting","agents/agent-memory","node-ts-for-ai/graceful-shutdown"],"tldr":"Redis is an in-memory data-structure server that executes commands one at a time, so each command is\natomic and sub-millisecond. In a Node AI service it is the shared, fast, expiring state a stateless\nreplica set needs: completion cache, rate limiter, provider-concurrency semaphore, short-lived session\nstate, distributed locks, pub/sub for streaming across instances, and the store behind BullMQ. The\nfundamentals live in the backend module; this lesson covers Node usage and what goes wrong.","status":"ok"},{"id":"bullmq-and-durable-jobs","key":"node-ts-for-ai/bullmq-and-durable-jobs","module":"node-ts-for-ai","name":"BullMQ & durable jobs","taxonomy_name":"BullMQ & durable jobs","kind":"tool","difficulty":"core","est_minutes":15,"related":["node-ts-for-ai/redis","node-ts-for-ai/graceful-shutdown","backend-fundamentals/background-jobs-durable-workers","fastapi-for-ai/job-queues-and-durable-workers","agent-reliability/durable-execution-and-checkpointing","agent-reliability/idempotent-tool-execution","reliability/durable-workflow-execution","system-design/outbox-inbox-patterns"],"tldr":"BullMQ is a Redis-backed job queue for Node: producers add jobs, workers process them with concurrency,\nretries with backoff, rate limits, delays, priorities and parent/child flows, and job state survives\nprocess restarts because it lives in Redis, not in a promise. An HTTP request is the wrong unit of work\nfor a minutes-long agent run or a 10,000-document embedding batch. Delivery is at-least-once, so\nhandlers must be idempotent, and the queue is only as durable as the Redis behind it.","status":"ok"},{"id":"api-clients-with-retries-and-circuit-breakers","key":"node-ts-for-ai/api-clients-with-retries-and-circuit-breakers","module":"node-ts-for-ai","name":"API clients with retries & circuit breakers","taxonomy_name":"API clients with retries & circuit breakers","kind":"pattern","difficulty":"core","est_minutes":15,"related":["serving-inference/retry-strategies","reliability/circuit-breakers","serving-inference/timeouts","serving-inference/idempotency","node-ts-for-ai/abortcontroller-and-cancellation","node-ts-for-ai/openai-anthropic-node-sdks","serving-inference/rate-limiting","enterprise-integration/retry-deduplication-reconciliation"],"tldr":"LLM and tool APIs fail transiently (429, 5xx, resets) far more than internal services, so every\noutbound call needs a per-attempt timeout, a retry policy that retries only retryable errors with\nexponential backoff and jitter, and a total deadline. A circuit breaker sits above that: when a\ndependency is down it stops sending traffic for a cooling period, so your service fails fast instead of\npiling up waiting requests and hammering a recovering provider. Vendor SDKs already retry; you add\ntimeouts, idempotency, breakers and bulkheads.","status":"ok"},{"id":"opentelemetry-instrumentation","key":"node-ts-for-ai/opentelemetry-instrumentation","module":"node-ts-for-ai","name":"OpenTelemetry instrumentation","taxonomy_name":"OpenTelemetry instrumentation","kind":"practice","difficulty":"core","est_minutes":15,"related":["observability/opentelemetry","observability/tracing","observability/spans","observability/distributed-tracing-across-services","observability/token-cost-tracking","fastapi-for-ai/opentelemetry-instrumentation","node-ts-for-ai/bullmq-and-durable-jobs","observability/langfuse"],"tldr":"OpenTelemetry (OTel) is the vendor-neutral standard for traces, metrics and logs. In a Node AI service\nyou install the SDK once at process start, let auto-instrumentation wrap HTTP, `fetch`, Postgres, Redis\nand your web framework, and add your own spans around agent steps carrying tenant, run id and prompt\nversion. Context follows `await` through `AsyncLocalStorage` and crosses services in the W3C\n`traceparent` header, so one request's path from API to queue to LLM to database becomes a single\nqueryable tree.","status":"ok"},{"id":"graceful-shutdown","key":"node-ts-for-ai/graceful-shutdown","module":"node-ts-for-ai","name":"Graceful shutdown","taxonomy_name":"graceful shutdown","kind":"practice","difficulty":"core","est_minutes":14,"related":["fastapi-for-ai/graceful-shutdown-and-worker-draining","deployment/health-checks","fastapi-for-ai/health-readiness-endpoints","backend-fundamentals/kubernetes","node-ts-for-ai/bullmq-and-durable-jobs","node-ts-for-ai/abortcontroller-and-cancellation","node-ts-for-ai/docker-ci-cd-deployment","node-ts-for-ai/opentelemetry-instrumentation"],"tldr":"Processes are killed constantly: deploys, autoscaling, node drains, out-of-memory kills. Graceful\nshutdown is the sequence a Node service runs on SIGTERM so nothing in flight is lost: stop advertising\nreadiness, stop accepting new requests and jobs, let in-flight work finish within a deadline shorter\nthan the orchestrator's grace period, flush telemetry, close pools, then exit. Without it, every deploy\ntruncates streamed LLM responses, re-runs queue jobs and leaks half-done writes.","status":"ok"},{"id":"vitest-jest-and-integration-testing","key":"node-ts-for-ai/vitest-jest-and-integration-testing","module":"node-ts-for-ai","name":"Vitest / Jest & integration testing","taxonomy_name":"Vitest / Jest & integration testing","kind":"practice","difficulty":"core","est_minutes":15,"related":["node-ts-for-ai/dependency-injection","node-ts-for-ai/openai-anthropic-node-sdks","node-ts-for-ai/docker-ci-cd-deployment","node-ts-for-ai/abortcontroller-and-cancellation","python-for-ai/pytest","python-for-ai/test-doubles-mocks-fixtures","python-for-ai/integration-and-end-to-end-testing","evals/regression-tests"],"tldr":"A model call is slow, billed and non-deterministic, so it cannot sit inside a test that must pass on\nevery commit. The working split is three layers: unit tests with an injected fake model, integration\ntests that run the real SDK, database and queue against intercepted or containerised dependencies, and\nevals that call the real model and are *scored*, not asserted. Vitest and Jest are the runners that\nmake the first two layers fast; the design that makes them possible is injecting the model client.","status":"ok"},{"id":"docker-ci-cd-deployment","key":"node-ts-for-ai/docker-ci-cd-deployment","module":"node-ts-for-ai","name":"Docker / CI/CD deployment","taxonomy_name":"Docker / CI/CD deployment","kind":"practice","difficulty":"core","est_minutes":16,"related":["backend-fundamentals/docker","backend-fundamentals/ci-cd","backend-fundamentals/kubernetes","backend-fundamentals/secrets-management","node-ts-for-ai/graceful-shutdown","node-ts-for-ai/vitest-jest-and-integration-testing","deployment/health-checks","llmops-platform/canary-shadow-deployments"],"tldr":"The general Docker and CI/CD lessons live in backend-fundamentals; this one covers what a Node/TypeScript\nAI service needs from them. Build the image in stages so the runtime layer holds compiled JavaScript\nand production dependencies only, run Node as PID 1 in exec form so `SIGTERM` can drain in-flight\nmodel streams, inject provider keys at runtime rather than baking them in, and gate the pipeline on\ntypecheck, deterministic tests and a commit-tagged build, with real-model evals beside the gate, not\ninside it.","status":"ok"},{"id":"vercel-ai-sdk","key":"node-ts-for-ai/vercel-ai-sdk","module":"node-ts-for-ai","name":"Vercel AI SDK","taxonomy_name":"Vercel AI SDK","kind":"tool","difficulty":"core","est_minutes":14,"related":["node-ts-for-ai/openai-anthropic-node-sdks","node-ts-for-ai/streams-and-backpressure","node-ts-for-ai/runtime-schema-validation","node-ts-for-ai/abortcontroller-and-cancellation","serving-inference/streaming","prompting/function-tool-calling","prompting/structured-outputs-json-mode","agents/frameworks"],"tldr":"The Vercel AI SDK (`ai` on npm) is a provider-agnostic TypeScript layer with two halves: a core API\n(`generateText`, `streamText`, `generateObject`, `tool`, `embed`) that maps one call shape onto OpenAI,\nAnthropic, Google and others through small provider packages, and a UI half (`useChat`) that streams\ntext, tool calls and structured data to the browser over a defined protocol. Swapping a model becomes\none line and browser streaming stops being a hand-rolled parser; the price is that provider-specific\nfeatures sit behind an escape hatch.","status":"ok"},{"id":"openai-anthropic-node-sdks","key":"node-ts-for-ai/openai-anthropic-node-sdks","module":"node-ts-for-ai","name":"OpenAI / Anthropic Node SDKs","taxonomy_name":"OpenAI / Anthropic Node SDKs","kind":"tool","difficulty":"core","est_minutes":16,"related":["node-ts-for-ai/api-clients-with-retries-and-circuit-breakers","node-ts-for-ai/abortcontroller-and-cancellation","node-ts-for-ai/runtime-schema-validation","node-ts-for-ai/vercel-ai-sdk","python-for-ai/openai-sdk","python-for-ai/anthropic-sdk","prompting/function-tool-calling","prompting/prompt-caching"],"tldr":"`openai` and `@anthropic-ai/sdk` are typed, generated clients over each provider's REST API with the\nsame bones: a client that reads the key from the environment, resource methods that return typed\nobjects, automatic retries with backoff on transient failures, millisecond timeouts, `AbortSignal`\nsupport, streaming as async iterables, and typed error classes. They differ where the APIs differ:\nmessage and tool-call shapes, how tool results are sent back, explicit versus automatic prompt\ncaching. Learn the shared mechanics once, then the two wire shapes.","status":"ok"},{"id":"mcp-typescript-sdk","key":"node-ts-for-ai/mcp-typescript-sdk","module":"node-ts-for-ai","name":"MCP TypeScript SDK","taxonomy_name":"MCP TypeScript SDK","kind":"tool","difficulty":"core","est_minutes":15,"related":["agents/model-context-protocol","agents/mcp-authentication-authorization-transport-security","python-for-ai/mcp-python-sdk","node-ts-for-ai/runtime-schema-validation","node-ts-for-ai/openai-anthropic-node-sdks","node-ts-for-ai/streams-and-backpressure","agents/typed-tool-contracts","agent-reliability/tool-permissions-and-least-privilege"],"tldr":"`@modelcontextprotocol/sdk` is the reference TypeScript implementation of the Model Context Protocol:\na server side that turns Zod-typed handlers into `tools/list`, `tools/call`, resource and prompt\nendpoints over JSON-RPC, and a client side that connects to any server, discovers its capabilities\nand calls them. Transports are pluggable: stdio for local subprocesses, Streamable HTTP for remote\nservers. The protocol lesson in the agents module explains *why* MCP exists; this one is about what\nthe SDK does for you and where it bites.","status":"ok"}]},{"id":"system-design","tier":2,"order":16,"title":"System design","intro":null,"topics":[{"id":"ai-solution-architecture","key":"system-design/ai-solution-architecture","module":"system-design","name":"AI / solution architecture","taxonomy_name":"AI / solution architecture","kind":"concept","difficulty":"core","est_minutes":16,"related":["system-design/reference-architectures","system-design/nfrs","system-design/trade-off-analysis","system-design/c4-diagrams","system-design/adrs","system-design/rag-architecture","system-design/agentic-architecture","scoping/ai-use-case-discovery"],"tldr":"An AI solution architecture is the design of everything around the model call: how a request becomes\ncontext, which model runs, what validates the output, what is logged, and how quality and cost are\nmeasured. It exists because a model is a probabilistic, expensive, stateless, rented dependency, and\nnothing about correctness, safety, cost or enterprise integration is solved by the call itself. The\narchitect's job is to put deterministic engineering where it belongs and leave the model only the\npart it is uniquely good at.","review":"fact-checked","status":"ok"},{"id":"reference-architectures","key":"system-design/reference-architectures","module":"system-design","name":"Reference architectures","taxonomy_name":"reference architectures","kind":"pattern","difficulty":"intro","est_minutes":14,"related":["system-design/ai-solution-architecture","system-design/rag-architecture","system-design/agentic-architecture","system-design/workflow-orchestration","system-design/ai-gateway","system-design/c4-diagrams","system-design/adrs","agents/workflows-vs-agents"],"tldr":"A reference architecture is a validated, reusable blueprint for a recurring system shape: its\ncomponents, their responsibilities, the interfaces between them, the default non-functional\nrequirements, and the known failure modes. In AI systems a handful of shapes recur constantly (RAG\nassistant, extraction pipeline, tool-using agent, multi-step workflow, platform gateway). Starting from\nthe matching blueprint means you deviate deliberately instead of rediscovering the same missing pieces\nafter launch.","review":"fact-checked","status":"ok"},{"id":"model-selection","key":"system-design/model-selection","module":"system-design","name":"Model selection","taxonomy_name":"model selection","kind":"decision","difficulty":"core","est_minutes":16,"related":["evals/model-evaluation","evals/benchmarking","evals/golden-dataset","evals/dataset-contamination","infra-capacity-economics/quality-latency-cost-optimization","system-design/model-portfolio","system-design/model-routing-cascading","system-design/slm-vs-llm-trade-offs"],"tldr":"Model selection is choosing, per task, the cheapest and fastest model that clears a quality bar you\nhave measured on your own data, after filtering by hard constraints such as modality, context length,\ndeployment location, licensing and tool support. It is a funnel, not a leaderboard lookup, because\npublic benchmarks measure a different distribution from your traffic, and because quality has a\nthreshold (\"good enough for this task\") while cost and latency are paid linearly on every call.","review":"fact-checked","status":"ok"},{"id":"model-portfolio","key":"system-design/model-portfolio","module":"system-design","name":"Model portfolio","taxonomy_name":"model portfolio","kind":"pattern","difficulty":"core","est_minutes":15,"related":["system-design/model-selection","system-design/model-routing-cascading","system-design/multi-model-architecture","system-design/ai-gateway","system-design/model-fallback-strategies","llmops-platform/model-lifecycle-and-deprecation-policy","llmops-platform/model-registry","security-governance-compliance/vendor-exit-strategy"],"tldr":"A model portfolio is a deliberately small, governed set of models, each with a role: a frontier tier\nfor hard reasoning, a workhorse for the bulk, small fast models for classification and routing,\nembeddings and rerankers, plus specialised and fine-tuned variants. Each entry has an owner, eval\nbaselines, a cost card, approved data classes and a retirement plan. It exists because one model\neverywhere overpays on easy work and underdelivers on hard work, while unmanaged per-team choices\ncreate sprawl nobody can evaluate, secure or exit.","review":"fact-checked","status":"ok"},{"id":"slm-vs-llm-trade-offs","key":"system-design/slm-vs-llm-trade-offs","module":"system-design","name":"SLM vs LLM trade-offs","taxonomy_name":"SLM vs LLM trade-offs","kind":"decision","difficulty":"core","est_minutes":16,"related":["model-internals/small-language-models","model-internals/scaling-laws","training-adaptation/knowledge-distillation","training-adaptation/quantization","system-design/model-routing-cascading","system-design/self-host-vs-api","infra-capacity-economics/edge-ai-deployment","system-design/model-selection"],"tldr":"Small language models (roughly up to the low tens of billions of parameters, runnable on one GPU or a\nlaptop; a fuzzy, moving boundary) trade breadth for cost, latency and deployability. On narrow,\nin-distribution tasks, especially after fine-tuning, an SLM often matches a large model; on open-ended\nreasoning, long-horizon tool use and broad world knowledge it does not. The decision turns on the\ntask's shape: how narrow, what a tail error costs, and where the data may go.","review":"fact-checked","status":"ok"},{"id":"build-vs-buy","key":"system-design/build-vs-buy","module":"system-design","name":"Build vs buy","taxonomy_name":"build vs buy","kind":"decision","difficulty":"core","est_minutes":16,"related":["strategy/vendor-evaluation","security-governance-compliance/vendor-exit-strategy","scoping/roi-model","infra-capacity-economics/tco","system-design/self-host-vs-api","system-design/open-weight-vs-proprietary","strategy/platform-strategy","delivery-ownership/productizing-repeated-customer-solutions"],"tldr":"Build versus buy in AI is not one decision but one per layer of the stack: model, serving, gateway,\norchestration, retrieval, evaluation and observability, guardrails, and the application itself. Buy\nwhat is commodity and fast-moving, build what differentiates and touches your data most intimately,\nand keep a thin seam you own at every boundary so the decision can be reversed. It exists because the\nAI stack changes faster than build cycles, and both \"build everything\" and \"buy everything\" fail in\npredictable ways.","review":"fact-checked","status":"ok"},{"id":"open-weight-vs-proprietary","key":"system-design/open-weight-vs-proprietary","module":"system-design","name":"Open-weight vs proprietary","taxonomy_name":"open-weight vs proprietary","kind":"decision","difficulty":"core","est_minutes":16,"related":["system-design/self-host-vs-api","system-design/build-vs-buy","security-governance-compliance/vendor-exit-strategy","security-governance-compliance/data-residency","llmops-platform/model-lifecycle-and-deprecation-policy","training-adaptation/peft","safety-security/supply-chain-security-for-models-and-datasets","serving-inference/engines"],"tldr":"Open-weight models publish their parameters so you can download, run, inspect, modify and fine-tune\nthem under a licence; proprietary models are reachable only through a provider's API. The choice\ndecides who controls the model's lifecycle, where data goes, what you can change, and how cost scales.\nIt is a control-and-licensing axis, not a deployment one: open weights can be rented through an API\nand proprietary models can run in private endpoints, so decide it separately from self-host versus API.","review":"fact-checked","status":"ok"},{"id":"self-host-vs-api","key":"system-design/self-host-vs-api","module":"system-design","name":"Self-host vs API","taxonomy_name":"self-host vs API","kind":"decision","difficulty":"core","est_minutes":15,"related":["system-design/build-vs-buy","system-design/open-weight-vs-proprietary","system-design/model-selection","infra-capacity-economics/break-even-analysis","infra-capacity-economics/tco","serving-inference/engines","security-governance-compliance/data-residency","security-governance-compliance/vendor-exit-strategy"],"tldr":"A hosted model API buys capability, elasticity and zero operations at a per-token price; self-hosting\nopen-weight models buys control, data locality and a lower *marginal* cost per token, but only once the\nGPUs are busy enough to amortise their fixed cost and the people who run them. It is a utilisation and\nconstraints decision, not a price-list comparison: start on the API unless a hard constraint (residency,\nair gap, customisation, sustained volume) forces hosting, and re-run the numbers as traffic grows.","review":"fact-checked","status":"ok"},{"id":"model-routing-cascading","key":"system-design/model-routing-cascading","module":"system-design","name":"Model routing / cascading","taxonomy_name":"model routing / cascading","kind":"pattern","difficulty":"core","est_minutes":15,"related":["system-design/model-selection","system-design/slm-vs-llm-trade-offs","system-design/multi-model-architecture","system-design/ai-gateway","system-design/model-fallback-strategies","infra-capacity-economics/quality-latency-cost-optimization","evals/llm-as-a-judge","infra-capacity-economics/cost-modeling"],"tldr":"Requests vary enormously in difficulty, so sending everything to the strongest model overpays and\nsending everything to the cheapest underdelivers. Routing picks a model per request *before* the call,\nusing rules, a classifier or a learned router; cascading calls the cheap model first and escalates only\nwhen a quality check fails. Both trade some router or check error and extra tail latency for large cost\nsavings, and both are only as good as the quality signal that drives them.","review":"fact-checked","status":"ok"},{"id":"multi-model-architecture","key":"system-design/multi-model-architecture","module":"system-design","name":"Multi-model architecture","taxonomy_name":"multi-model architecture","kind":"pattern","difficulty":"core","est_minutes":14,"related":["system-design/model-portfolio","system-design/model-routing-cascading","system-design/rag-architecture","system-design/agentic-architecture","rag-retrieval/reranking","evals/llm-as-a-judge","infra-capacity-economics/latency-budgets","observability/tracing"],"tldr":"No single model is the best embedder, reranker, classifier, generator, vision model and judge at once,\nand the best model for each job is rarely the cheapest. A multi-model architecture decomposes the system\ninto stages, each served by the model that fits that stage's quality, latency and cost budget, joined by\nexplicit typed contracts. The price is coupling: every stage's output is the next stage's input\ndistribution, so models have to be versioned and evaluated together, not one at a time.","review":"fact-checked","status":"ok"},{"id":"ai-gateway","key":"system-design/ai-gateway","module":"system-design","name":"AI gateway (LiteLLM proxy, Portkey)","taxonomy_name":"AI gateway (LiteLLM proxy, Portkey)","kind":"tool","difficulty":"core","est_minutes":14,"related":["python-for-ai/litellm","system-design/model-fallback-strategies","system-design/model-routing-cascading","system-design/caching-strategy-and-cache-invalidation","observability/token-cost-tracking","infra-capacity-economics/cost-allocation-by-tenant-and-feature","serving-inference/rate-limiting","security-governance-compliance/pii-protection-dlp"],"tldr":"An AI gateway is a proxy that every model call passes through: one OpenAI-style API in front of many\nproviders, with key custody, budgets, rate limits, routing, fallbacks, caching and logging handled once\ninstead of re-implemented in every application. LiteLLM's proxy is the open-source, Python,\nconfig-file-driven option you run yourself; Portkey is a hosted gateway driven by declarative JSON\nconfigs, with an open-source core. Both buy control and visibility at the price of an extra hop and a\nnew single point of failure.","review":"fact-checked","status":"ok"},{"id":"model-fallback-strategies","key":"system-design/model-fallback-strategies","module":"system-design","name":"Model fallback strategies","taxonomy_name":"model fallback strategies","kind":"pattern","difficulty":"core","est_minutes":15,"related":["serving-inference/fallbacks","serving-inference/retry-strategies","serving-inference/timeouts","reliability/circuit-breakers","system-design/graceful-degradation","system-design/ai-gateway","infra-capacity-economics/api-provider-quotas-and-regional-limits","agent-reliability/idempotent-tool-execution"],"tldr":"Every model endpoint fails sometimes: outages, 429 throttling, latency spikes, regional capacity limits,\ndeprecated model ids. A fallback strategy decides in advance what to call instead, in what order, and on\nwhich errors, so a provider's bad hour does not become your outage. Fallbacks are not free: the\nsubstitute behaves differently, retries can amplify an incident, and an untested fallback is a second\nfailure waiting behind the first.","review":"fact-checked","status":"ok"},{"id":"graceful-degradation","key":"system-design/graceful-degradation","module":"system-design","name":"Graceful degradation","taxonomy_name":"graceful degradation","kind":"pattern","difficulty":"core","est_minutes":14,"related":["system-design/model-fallback-strategies","reliability/backpressure-and-load-shedding","reliability/circuit-breakers","reliability/bulkheads","reliability/slas-slos","system-design/nfrs","llmops-platform/rollback","agent-reliability/max-step-budgets"],"tldr":"When the AI path is failing, slow, over budget or overloaded, the product should step down to a\ncheaper, simpler and honestly labelled version of itself rather than fall over. Graceful degradation is a\ndesigned ladder (full → reduced → cached → non-AI → clear unavailability) with explicit triggers,\nhysteresis, labelled output and degraded paths that are exercised so they still work when needed.\nFallbacks keep the function by changing the provider; degradation keeps the user moving by changing the\nfunction.","review":"fact-checked","status":"ok"},{"id":"caching-strategy-and-cache-invalidation","key":"system-design/caching-strategy-and-cache-invalidation","module":"system-design","name":"Caching strategy & cache invalidation","taxonomy_name":"caching strategy & cache invalidation","kind":"pattern","difficulty":"core","est_minutes":16,"related":["serving-inference/caching","prompting/prompt-caching","serving-inference/prefix-caching","model-internals/kv-cache","fastapi-for-ai/redis-caching","rag-retrieval/freshness-document-deletion-index-consistency","system-design/multi-tenancy","system-design/ai-gateway"],"tldr":"Model calls are the slowest, most expensive step in an AI system, and much of what they process repeats:\nthe same system prompt, documents and questions. Caching happens at several layers, prefix caching of\ncomputation, exact and semantic response caches, embedding and retrieval caches, each with its own key\nand its own way of going stale. The design question is always the key: what must be identical for a\ncached result to still be correct, and how you find out when it no longer is.","review":"fact-checked","status":"ok"},{"id":"rag-architecture","key":"system-design/rag-architecture","module":"system-design","name":"RAG architecture","taxonomy_name":"RAG architecture","kind":"pattern","difficulty":"core","est_minutes":16,"related":["rag-retrieval/chunking-strategies","rag-retrieval/hybrid-search","rag-retrieval/reranking","rag-retrieval/acl-aware-retrieval","rag-retrieval/freshness-document-deletion-index-consistency","rag-retrieval/long-context-vs-rag","data-architecture/vector-database-architecture","system-design/caching-strategy-and-cache-invalidation"],"tldr":"RAG is two pipelines joined by an index: an offline path that turns documents into searchable chunks,\nand an online path that retrieves the few chunks relevant to a query and hands them to the model with\ninstructions to answer from them. It exists because model weights are frozen, general and\npermission-blind, while the facts a product needs are changing, private and access-controlled. The\narchitecture decisions are about where each pipeline runs, what the index stores, and how failures are\nmeasured.","review":"fact-checked","status":"ok"},{"id":"agentic-architecture","key":"system-design/agentic-architecture","module":"system-design","name":"Agentic architecture","taxonomy_name":"agentic architecture","kind":"pattern","difficulty":"core","est_minutes":16,"related":["agents/agent-loop","agents/workflows-vs-agents","agents/tool-calling","agents/approval-gates-for-consequential-actions","agent-reliability/durable-execution-and-checkpointing","agent-reliability/max-step-budgets","agent-runtime-architecture/agent-runtime-and-orchestration-layer","system-design/synchronous-vs-asynchronous-execution"],"tldr":"An agentic architecture is a system in which a model chooses the next action at runtime, observes the\nresult, and repeats until a stopping condition. The system-design job is to wrap that loop in boundaries\nthe model does not control: a typed tool layer with least privilege, externalized state so runs survive\ncrashes, step and cost budgets, approval gates for consequential actions, and tracing. The model owns\njudgment; the architecture owns guarantees.","review":"fact-checked","status":"ok"},{"id":"multi-agent-systems","key":"system-design/multi-agent-systems","module":"system-design","name":"Multi-agent systems","taxonomy_name":"multi-agent systems","kind":"pattern","difficulty":"advanced","est_minutes":16,"related":["agents/multi-agent-patterns","agents/task-decomposition","agents/a2a-protocol","agents/tool-selection-accuracy","system-design/agent-orchestration","agent-runtime-architecture/policy-enforcement-across-agents-and-tools","agent-reliability/audit-logs-execution-traces","observability/distributed-tracing-across-services"],"tldr":"A multi-agent system splits a task across several model-driven loops, each with its own instructions,\ntools and context, coordinated by a topology (supervisor–workers, pipeline, parallel fan-out, critic).\nIt exists because a single agent's context, tool list and privileges do not scale with task breadth.\nThe price is coordination: duplicated context, compounding errors, harder tracing and higher cost, so a\nsplit must buy isolation, parallelism or specialization you can name.","review":"fact-checked","status":"ok"},{"id":"agent-orchestration","key":"system-design/agent-orchestration","module":"system-design","name":"Agent orchestration","taxonomy_name":"agent orchestration","kind":"pattern","difficulty":"core","est_minutes":15,"related":["agents/workflows-vs-agents","agents/state-machines","agents/frameworks","agents/human-in-the-loop","agent-reliability/durable-execution-and-checkpointing","agent-reliability/structured-event-streams","agent-runtime-architecture/agent-runtime-and-orchestration-layer","system-design/workflow-orchestration"],"tldr":"Agent orchestration is the control layer that decides what runs next in an LLM application: which model\ncall, tool, sub-agent or human step, with what state, and what happens on failure. It exists because\nonce a system has more than one model call plus tools, ordering, state, retries, concurrency and\ninterruption need an owner. The core design choice is how much of that control flow is deterministic\ncode and how much is left to the model.","review":"fact-checked","status":"ok"},{"id":"workflow-orchestration","key":"system-design/workflow-orchestration","module":"system-design","name":"Workflow orchestration (Temporal, Prefect, Airflow)","taxonomy_name":"workflow orchestration (Temporal, Prefect, Airflow)","kind":"tool","difficulty":"core","est_minutes":17,"related":["reliability/durable-workflow-execution","agent-reliability/durable-execution-and-checkpointing","backend-fundamentals/background-jobs-durable-workers","backend-fundamentals/message-queues","data-architecture/ingestion-pipelines","system-design/agent-orchestration","system-design/saga-pattern-and-distributed-transactions","system-design/exactly-once-processing-limitations"],"tldr":"Workflow orchestrators run multi-step processes reliably outside a single request: they persist\nprogress, retry steps, schedule work and show where each run is. Airflow schedules batch DAGs of data\ntasks; Prefect orchestrates dynamic Python dataflows with less ceremony; Temporal provides durable\nexecution, replaying workflow code from an event history so long-running stateful processes survive\ncrashes. For AI systems: indexing pipelines fit Airflow or Prefect; long-lived agent runs and\napproval flows fit Temporal-style engines.","review":"fact-checked","status":"ok"},{"id":"memory-architecture","key":"system-design/memory-architecture","module":"system-design","name":"Memory architecture","taxonomy_name":"memory architecture","kind":"concept","difficulty":"core","est_minutes":16,"related":["agents/agent-memory","agents/memory-retrieval-update-deletion-policies","agents/context-compaction-summarization","prompting/context-engineering","agent-reliability/state-persistence-and-conversation-recovery","agent-runtime-architecture/multi-tenant-state-isolation","data-architecture/data-retention-and-deletion-architecture","system-design/rag-architecture"],"tldr":"Models are stateless and context windows are finite, so anything an application must \"remember\" across\nturns, sessions or users has to be stored outside the model and brought back selectively. Memory\narchitecture is the design of those stores and the policies that write, read, update and delete them:\nworking memory in the context, session state in a database, long-term episodic and semantic memory in\nretrievable stores, each scoped to a user and tenant. The hard decisions are what to remember and what\nto forget.","review":"fact-checked","status":"ok"},{"id":"domain-driven-design-and-bounded-contexts","key":"system-design/domain-driven-design-and-bounded-contexts","module":"system-design","name":"Domain-driven design & bounded contexts","taxonomy_name":"domain-driven design & bounded contexts","kind":"concept","difficulty":"core","est_minutes":16,"related":["system-design/modular-monolith-vs-microservices","system-design/event-driven-architecture","system-design/saga-pattern-and-distributed-transactions","system-design/data-consistency","system-design/c4-diagrams","enterprise-integration/data-mapping-and-canonical-schemas","agents/typed-tool-contracts","agent-reliability/tool-adapters-service-interfaces"],"tldr":"Domain-driven design splits a large system along the meanings of its business language, not along\ntechnical layers: each bounded context owns one consistent model and vocabulary, and contexts talk\nthrough explicit contracts instead of a shared schema. It exists because words like \"customer\" mean\ndifferent things in different parts of a business, and forcing one model onto all of them produces\nsystems nobody can change. For AI systems, bounded contexts decide tool boundaries, data ownership and\nwho translates meaning for the agent.","review":"fact-checked","status":"ok"},{"id":"event-driven-architecture","key":"system-design/event-driven-architecture","module":"system-design","name":"Event-driven architecture","taxonomy_name":"event-driven architecture","kind":"pattern","difficulty":"core","est_minutes":15,"related":["system-design/synchronous-vs-asynchronous-execution","system-design/outbox-inbox-patterns","system-design/exactly-once-processing-limitations","system-design/saga-pattern-and-distributed-transactions","system-design/domain-driven-design-and-bounded-contexts","backend-fundamentals/message-queues","agent-reliability/structured-event-streams","observability/distributed-tracing-across-services"],"tldr":"In an event-driven architecture a service records that something happened (\"DocumentUploaded\",\n\"RunCompleted\") as an immutable event on a broker, and any number of consumers react on their own\nschedule. The producer no longer knows or waits for its consumers, which is what lets you add a billing\nmeter, an eval sampler and an audit log to an agent pipeline without touching the agent. The price is\neventual consistency, at-least-once delivery and a flow of control that no single stack trace shows.","review":"fact-checked","status":"ok"},{"id":"synchronous-vs-asynchronous-execution","key":"system-design/synchronous-vs-asynchronous-execution","module":"system-design","name":"Synchronous vs asynchronous execution","taxonomy_name":"synchronous vs asynchronous execution","kind":"decision","difficulty":"core","est_minutes":14,"related":["system-design/event-driven-architecture","fastapi-for-ai/job-queues-and-durable-workers","backend-fundamentals/background-jobs-durable-workers","serving-inference/streaming","fastapi-for-ai/server-sent-events","fastapi-for-ai/timeouts","reliability/backpressure-and-load-shedding","infra-capacity-economics/queueing-theory","python-for-ai/asyncio"],"tldr":"Synchronous execution means the caller holds a connection open until the result arrives; asynchronous\nexecution means the caller gets an acknowledgement (a job id) and the result arrives later by polling,\npush or callback. LLM calls take seconds and agent runs take minutes, which is longer than load\nbalancers, mobile networks and humans will wait, so most AI workloads need the asynchronous shape, with\nstreaming as the middle ground when a person is watching.","review":"fact-checked","status":"ok"},{"id":"saga-pattern-and-distributed-transactions","key":"system-design/saga-pattern-and-distributed-transactions","module":"system-design","name":"Saga pattern & distributed transactions","taxonomy_name":"saga pattern & distributed transactions","kind":"pattern","difficulty":"advanced","est_minutes":17,"related":["system-design/outbox-inbox-patterns","system-design/event-driven-architecture","system-design/data-consistency","system-design/workflow-orchestration","reliability/durable-workflow-execution","agent-reliability/idempotent-tool-execution","agents/approval-gates-for-consequential-actions","backend-fundamentals/postgresql-transactions-and-isolation-levels"],"tldr":"A business operation spanning several services cannot be one ACID transaction, and two-phase commit\nblocks under coordinator failure and is unavailable across external APIs. A saga replaces it with a\nsequence of local transactions, each paired with a compensating action that undoes it. Sagas give\natomicity and durability but not isolation, so you must order steps around the irreversible pivot, mark\nin-flight state and make every step idempotent. An agent calling several tools in sequence is a saga.","review":"fact-checked","status":"ok"},{"id":"outbox-inbox-patterns","key":"system-design/outbox-inbox-patterns","module":"system-design","name":"Outbox / inbox patterns","taxonomy_name":"outbox / inbox patterns","kind":"pattern","difficulty":"core","est_minutes":15,"related":["system-design/event-driven-architecture","system-design/exactly-once-processing-limitations","system-design/saga-pattern-and-distributed-transactions","backend-fundamentals/postgresql-transactions-and-isolation-levels","backend-fundamentals/message-queues","enterprise-integration/incremental-synchronization-and-cdc","enterprise-integration/retry-deduplication-reconciliation","fastapi-for-ai/idempotency-keys"],"tldr":"A service cannot atomically commit a database row and publish a message. The **outbox** pattern writes\nthe message into a table inside the same transaction as the business change and lets a relay publish it,\nso a message exists if and only if the change committed. The **inbox** pattern records each processed\nmessage id inside the consumer's transaction, so redeliveries become no-ops. Together they turn an\nat-least-once broker into effectively-once processing between two databases.","review":"fact-checked","status":"ok"},{"id":"exactly-once-processing-limitations","key":"system-design/exactly-once-processing-limitations","module":"system-design","name":"Exactly-once processing limitations","taxonomy_name":"exactly-once processing limitations","kind":"concept","difficulty":"advanced","est_minutes":15,"related":["system-design/outbox-inbox-patterns","system-design/event-driven-architecture","system-design/distributed-systems","agent-reliability/idempotent-tool-execution","agent-reliability/durable-execution-and-checkpointing","serving-inference/idempotency","fastapi-for-ai/idempotency-keys","enterprise-integration/retry-deduplication-reconciliation"],"tldr":"Exactly-once *delivery* over an unreliable network is impossible: a sender without an acknowledgement\ncannot tell whether the message or the ack was lost, so it must risk a duplicate or a loss. What you can\nbuild is exactly-once *effect*: at-least-once delivery plus deduplication or idempotent processing, with\nthe dedupe state committed together with the effect. Every \"exactly-once\" feature, Kafka transactions\nincluded, stops at that boundary; external API calls and LLM invocations beyond it are not covered.","review":"fact-checked","status":"ok"},{"id":"distributed-systems","key":"system-design/distributed-systems","module":"system-design","name":"Distributed systems","taxonomy_name":"distributed systems","kind":"concept","difficulty":"core","est_minutes":17,"related":["system-design/data-consistency","system-design/exactly-once-processing-limitations","system-design/event-driven-architecture","reliability/fault-tolerance","reliability/high-availability","reliability/multi-region-architecture","reliability/circuit-breakers","observability/distributed-tracing-across-services","serving-inference/retry-strategies"],"tldr":"A distributed system is several machines cooperating over a network, and its defining property is\n**partial failure**: any node or link can fail or stall while the rest continue, and no observer can tell\n\"slow\" from \"dead\" except by waiting. Every AI product is one, because model API, vector store, queue,\nagent workers and customer tools are separate machines. The discipline is a short list: timeouts with\nbudgets, idempotent retries, quorums, leases with fencing, consensus where agreement is required, and\ntracing.","review":"fact-checked","status":"ok"},{"id":"data-consistency","key":"system-design/data-consistency","module":"system-design","name":"Data consistency","taxonomy_name":"data consistency","kind":"concept","difficulty":"core","est_minutes":17,"related":["system-design/distributed-systems","system-design/saga-pattern-and-distributed-transactions","system-design/outbox-inbox-patterns","system-design/caching-strategy-and-cache-invalidation","backend-fundamentals/postgresql-transactions-and-isolation-levels","rag-retrieval/freshness-document-deletion-index-consistency","reliability/multi-region-architecture","data-architecture/data-contracts"],"tldr":"\"Consistency\" names two things: invariants inside one database (the C in ACID, enforced by constraints\nand isolation levels) and the guarantee about *which* value a read may return when copies exist\n(linearizable down to eventual). Strong guarantees cost coordination and latency, so good designs make a\nfew invariants strong (permissions, quotas, idempotency keys) and let everything else lag, visibly. In AI\nsystems the usual victims are the search index, the cache and the agent's memory, all copies of a source\nof truth.","review":"fact-checked","status":"ok"},{"id":"modular-monolith-vs-microservices","key":"system-design/modular-monolith-vs-microservices","module":"system-design","name":"Modular monolith vs microservices","taxonomy_name":"modular monolith vs microservices","kind":"decision","difficulty":"core","est_minutes":16,"related":["system-design/domain-driven-design-and-bounded-contexts","system-design/event-driven-architecture","system-design/saga-pattern-and-distributed-transactions","system-design/outbox-inbox-patterns","system-design/distributed-systems","system-design/adrs","system-design/trade-off-analysis","observability/distributed-tracing-across-services"],"tldr":"The real decision is where your *deployment and ownership* boundaries go, not how your code is\norganised. A modular monolith is one deployable whose internal modules have enforced public APIs and\nown their data; microservices turn those same boundaries into network boundaries, buying independent\ndeployment, scaling and failure isolation at the price of distributed-systems problems (partial failure,\neventual consistency, operational surface). Start modular, and split a boundary only when it has a\nproven, independent reason to exist: a different scaling profile, a different team, or a different blast\nradius.","review":"fact-checked","status":"ok"},{"id":"multi-tenancy","key":"system-design/multi-tenancy","module":"system-design","name":"Multi-tenancy","taxonomy_name":"multi-tenancy","kind":"concept","difficulty":"core","est_minutes":16,"related":["system-design/tenant-isolation","reliability/tenant-level-quotas-and-noisy-neighbor-isolation","infra-capacity-economics/cost-allocation-by-tenant-and-feature","infra-capacity-economics/shared-vs-isolated-model-serving-infrastructure","enterprise-integration/tenant-specific-configuration-and-feature-flags","agent-runtime-architecture/multi-tenant-state-isolation","safety-security/cross-tenant-data-leakage","deployment/customer-vpc-on-prem-air-gapped"],"tldr":"Multi-tenancy is one running system serving many customers (tenants) while keeping each one's data,\nconfiguration, quotas and bill separate. It exists because one deployment per customer does not scale in\ncost or operations. The mechanism is a tenant identity established at the edge and carried through every\nlayer, plus a deliberate choice per resource of how much is shared (pool), partitioned (bridge) or\ndedicated (silo). In AI systems that identity must also reach the retrieval index, the prompt, the caches\nand the token meter.","review":"fact-checked","status":"ok"},{"id":"tenant-isolation","key":"system-design/tenant-isolation","module":"system-design","name":"Tenant isolation","taxonomy_name":"tenant isolation","kind":"pattern","difficulty":"advanced","est_minutes":17,"related":["system-design/multi-tenancy","safety-security/cross-tenant-data-leakage","rag-retrieval/acl-aware-retrieval","rag-retrieval/metadata-filtering","agent-runtime-architecture/multi-tenant-state-isolation","agent-runtime-architecture/secrets-and-credential-isolation","reliability/tenant-level-quotas-and-noisy-neighbor-isolation","security-governance-compliance/data-residency"],"tldr":"Tenant isolation is the set of controls that make the \"each tenant is alone\" promise of multi-tenancy\ntrue even when application code is wrong. It layers independent mechanisms, scoped credentials,\ndatabase-enforced row policies, partitioned indexes and caches, per-tenant quotas and tenant-tagged\ntelemetry, so that a single bug cannot leak data or performance across tenants. In AI systems the\nprompt is a new exfiltration path: anything retrieved, remembered or cached under the wrong tenant key\nis read out loud by the model.","review":"fact-checked","status":"ok"},{"id":"c4-diagrams","key":"system-design/c4-diagrams","module":"system-design","name":"C4 diagrams","taxonomy_name":"C4 diagrams","kind":"practice","difficulty":"intro","est_minutes":11,"related":["system-design/ai-solution-architecture","system-design/reference-architectures","system-design/adrs","system-design/domain-driven-design-and-bounded-contexts","delivery-ownership/technical-documentation","deployment/security-and-architecture-reviews","strategy/stakeholder-alignment"],"tldr":"C4 is a small set of conventions for architecture diagrams at four nested zoom levels, System Context,\nContainer, Component and Code, where every box states its name, type, technology and purpose and every\narrow states its intent. It exists because ad-hoc boxes-and-arrows mix abstraction levels and leave\nreaders guessing what a box is and which way data flows. For AI systems it is the quickest way to show\nwhere the model, the customer's data and the trust boundaries actually sit.","review":"fact-checked","status":"ok"},{"id":"adrs","key":"system-design/adrs","module":"system-design","name":"ADRs (architecture decision records)","taxonomy_name":"ADRs","kind":"practice","difficulty":"intro","est_minutes":12,"related":["system-design/trade-off-analysis","system-design/nfrs","system-design/c4-diagrams","system-design/build-vs-buy","system-design/model-selection","delivery-ownership/technical-documentation","deployment/security-and-architecture-reviews","strategy/stakeholder-alignment"],"tldr":"An architecture decision record is a short, numbered, immutable document that captures one significant\ndecision: the context that forced it, the options considered, the choice, and its consequences. It\nexists because decisions outlive the people, meetings and chat threads that made them, and without the\nrecord teams either cargo-cult old choices or reverse them blindly. In AI systems, where model, vendor\nand retrieval choices churn monthly, a good ADR also records the evidence at decision time and the\ntrigger for revisiting.","review":"fact-checked","status":"ok"},{"id":"nfrs","key":"system-design/nfrs","module":"system-design","name":"NFRs (non-functional requirements)","taxonomy_name":"NFRs","kind":"concept","difficulty":"core","est_minutes":14,"related":["system-design/trade-off-analysis","system-design/adrs","reliability/slas-slos","infra-capacity-economics/latency-budgets","infra-capacity-economics/capacity-planning","observability/latency-percentiles","scoping/success-metrics-kpis","scoping/requirements-traceability"],"tldr":"Non-functional requirements (quality attribute requirements) state how well a system must do what it\ndoes: latency, availability, cost, security, privacy, maintainability and, for AI systems, answer\nquality, safety and freshness. They exist because architecture is shaped by these constraints rather\nthan by the feature list, and because adjectives like \"fast\" and \"accurate\" cannot be tested. A usable\nNFR is a measurable scenario, a stimulus under a stated condition with a numeric response measure,\ntraced to a test, an SLO or an evaluation gate.","review":"fact-checked","status":"ok"},{"id":"trade-off-analysis","key":"system-design/trade-off-analysis","module":"system-design","name":"Trade-off analysis","taxonomy_name":"trade-off analysis","kind":"practice","difficulty":"core","est_minutes":15,"related":["system-design/nfrs","system-design/adrs","system-design/build-vs-buy","system-design/self-host-vs-api","system-design/slm-vs-llm-trade-offs","infra-capacity-economics/quality-latency-cost-optimization","infra-capacity-economics/break-even-analysis","serving-inference/throughput-vs-latency"],"tldr":"Trade-off analysis is the disciplined way to choose between architectural options when none dominates:\nframe the decision and its hard constraints, enumerate real options, score them against the NFRs that\nmatter using evidence rather than opinion, find the sensitivity points where the ranking flips, weigh\nreversibility, then decide and record. It exists because every architectural choice gives something up\nand \"best practice\" hides what. In AI systems the usual battleground is quality against latency against\ncost, with vendor risk as the fourth corner.","review":"fact-checked","status":"ok"}]},{"id":"reliability","tier":2,"order":17,"title":"Reliability","intro":null,"topics":[{"id":"high-availability","key":"reliability/high-availability","module":"reliability","name":"High availability","taxonomy_name":"high availability","kind":"concept","difficulty":"core","est_minutes":14,"related":["reliability/fault-tolerance","reliability/multi-region-architecture","reliability/disaster-recovery","reliability/slas-slos","reliability/backpressure-and-load-shedding","deployment/health-checks","system-design/model-fallback-strategies","fastapi-for-ai/graceful-shutdown-and-worker-draining"],"tldr":"High availability (HA) is the property that a system keeps answering requests through the failure of\nany single component, measured as the fraction of time or requests for which it works. You get it by\nremoving single points of failure with redundancy, detecting failures quickly with health checks, and\nmoving traffic automatically (failover). It costs money and complexity because every redundant part\nmust be kept consistent and exercised, and an AI product's availability is capped by its least\navailable dependency, which is usually the model provider.","review":"fact-checked","status":"ok"},{"id":"fault-tolerance","key":"reliability/fault-tolerance","module":"reliability","name":"Fault tolerance","taxonomy_name":"fault tolerance","kind":"concept","difficulty":"core","est_minutes":15,"related":["reliability/high-availability","reliability/circuit-breakers","reliability/bulkheads","reliability/fmea","serving-inference/retry-strategies","serving-inference/timeouts","system-design/graceful-degradation","agent-reliability/idempotent-tool-execution"],"tldr":"Fault tolerance is a system's ability to keep delivering correct, or explicitly degraded, service while\nsome of its components are failing. It combines redundancy with mechanisms that contain a fault before\nit becomes a user-visible failure: timeouts, bounded retries, idempotency, circuit breakers, bulkheads,\nfallbacks and replicated state. The design question is never \"how do we avoid faults\" but \"which faults\ndo we tolerate, how do we detect them, and what does the system do in the window before recovery\".","review":"fact-checked","status":"ok"},{"id":"multi-region-architecture","key":"reliability/multi-region-architecture","module":"reliability","name":"Multi-region architecture","taxonomy_name":"multi-region architecture","kind":"pattern","difficulty":"advanced","est_minutes":16,"related":["reliability/high-availability","reliability/disaster-recovery","reliability/durable-workflow-execution","reliability/backpressure-and-load-shedding","system-design/data-consistency","system-design/distributed-systems","security-governance-compliance/data-residency","infra-capacity-economics/api-provider-quotas-and-regional-limits"],"tldr":"A multi-region architecture runs a system in two or more geographically separate cloud regions to\nsurvive a whole-region outage, cut latency for distant users, and satisfy data-residency rules. The\nhard part is not duplicating compute but deciding where each piece of state lives and how it is\nreplicated: synchronous replication taxes every write with a cross-region round trip, asynchronous\nreplication loses recent writes on failover. Start multi-AZ in one region; go multi-region only for\na reason you can name.","review":"fact-checked","status":"ok"},{"id":"disaster-recovery","key":"reliability/disaster-recovery","module":"reliability","name":"Disaster recovery (RPO / RTO)","taxonomy_name":"disaster recovery (RPO / RTO)","kind":"concept","difficulty":"core","est_minutes":14,"related":["reliability/business-continuity","reliability/high-availability","reliability/multi-region-architecture","deployment/runbooks","data-architecture/vector-database-architecture","data-architecture/embedding-versioning-re-indexing-strategy","llmops-platform/rollback","security-governance-compliance/vendor-exit-strategy"],"tldr":"Disaster recovery (DR) is the plan and machinery for restoring service after a failure that redundancy\ncannot mask: a region loss, a deleted database, corrupted data, a compromised account. Two numbers\ndefine it. **RPO** (recovery point objective) is how much data, measured in time, you may lose. **RTO**\n(recovery time objective) is how long service may be down. Every DR design is a trade of cost against\nthose two numbers, and a DR plan that has not been rehearsed is a hypothesis, not a plan.","review":"fact-checked","status":"ok"},{"id":"business-continuity","key":"reliability/business-continuity","module":"reliability","name":"Business continuity","taxonomy_name":"business continuity","kind":"practice","difficulty":"core","est_minutes":12,"related":["reliability/disaster-recovery","reliability/fmea","reliability/slas-slos","delivery-ownership/incident-severity-and-escalation","deployment/runbooks","security-governance-compliance/vendor-exit-strategy","security-governance-compliance/ai-incident-response","system-design/model-fallback-strategies"],"tldr":"Business continuity (BC) is the practice of keeping the organisation's critical functions running\nthrough a disruption, whatever its cause: a cloud outage, a vendor failure, a model deprecation, a\nsecurity incident, or the one person who understands the prompts leaving. Disaster recovery is its\ntechnical subset. BC starts from a business impact analysis that ranks functions and sets tolerable\ndowntime, then builds plans, workarounds, roles and rehearsals around that ranking, because during a\nreal disruption nobody has time to decide what matters.","review":"fact-checked","status":"ok"},{"id":"durable-workflow-execution","key":"reliability/durable-workflow-execution","module":"reliability","name":"Durable workflow execution","taxonomy_name":"durable workflow execution","kind":"pattern","difficulty":"advanced","est_minutes":16,"related":["agent-reliability/durable-execution-and-checkpointing","agent-reliability/state-and-checkpoint-stores","agent-reliability/idempotent-tool-execution","system-design/workflow-orchestration","system-design/saga-pattern-and-distributed-transactions","system-design/exactly-once-processing-limitations","backend-fundamentals/background-jobs-durable-workers","reliability/fault-tolerance"],"tldr":"Durable workflow execution makes a long, multi-step process survive crashes, deploys and\ndays-long waits by persisting its progress as an append-only event history and replaying that history\nto resume exactly where it stopped. The orchestration code must be deterministic so replay is faithful;\nevery side effect lives in a retried, idempotent *activity*. It replaces hand-built state machines in\ndatabase columns and cron jobs, and it is the natural runtime for agent loops whose steps are slow,\nflaky and expensive to redo.","review":"fact-checked","status":"ok"},{"id":"backpressure-and-load-shedding","key":"reliability/backpressure-and-load-shedding","module":"reliability","name":"Backpressure & load shedding","taxonomy_name":"backpressure & load shedding","kind":"pattern","difficulty":"core","est_minutes":14,"related":["fastapi-for-ai/backpressure","serving-inference/backpressure","node-ts-for-ai/streams-and-backpressure","infra-capacity-economics/queueing-theory","reliability/bulkheads","reliability/circuit-breakers","reliability/tenant-level-quotas-and-noisy-neighbor-isolation","serving-inference/rate-limiting"],"tldr":"When requests arrive faster than a system can serve them, queues grow without bound, latency climbs\npast every timeout, clients retry, and throughput collapses. **Backpressure** pushes the \"slow down\"\nsignal upstream through bounded queues, blocking producers and explicit 429/503 responses so the\nsource stops sending. **Load shedding** deliberately rejects some work, cheaply and early, so the\nrest completes within its latency budget. Both exist because an overloaded system that tries to serve\neveryone serves no one.","review":"fact-checked","status":"ok"},{"id":"tenant-level-quotas-and-noisy-neighbor-isolation","key":"reliability/tenant-level-quotas-and-noisy-neighbor-isolation","module":"reliability","name":"Tenant-level quotas & noisy-neighbor isolation","taxonomy_name":"tenant-level quotas & noisy-neighbor isolation","kind":"pattern","difficulty":"core","est_minutes":15,"related":["reliability/bulkheads","reliability/backpressure-and-load-shedding","system-design/tenant-isolation","serving-inference/rate-limiting","infra-capacity-economics/api-provider-quotas-and-regional-limits","infra-capacity-economics/cost-allocation-by-tenant-and-feature","fastapi-for-ai/concurrency-limits","safety-security/cross-tenant-data-leakage"],"tldr":"In a multi-tenant AI service every tenant draws on the same scarce pools: provider tokens-per-minute,\nGPU concurrency, workers, connections. A noisy neighbor is one tenant whose burst (a backfill, a looping\nagent, a retry storm) fills a pool so everyone else's latency and errors rise. Tenant-level quotas cap\nwhat each tenant may consume; isolation mechanisms (per-tenant lanes, fair queuing, separate pools)\nensure a tenant hitting its cap degrades only itself. The goal is to turn a shared failure into a local one.","review":"fact-checked","status":"ok"},{"id":"circuit-breakers","key":"reliability/circuit-breakers","module":"reliability","name":"Circuit breakers","taxonomy_name":"circuit breakers","kind":"pattern","difficulty":"core","est_minutes":14,"related":["reliability/bulkheads","reliability/fault-tolerance","reliability/backpressure-and-load-shedding","serving-inference/retry-strategies","serving-inference/timeouts","serving-inference/fallbacks","system-design/model-fallback-strategies","node-ts-for-ai/api-clients-with-retries-and-circuit-breakers"],"tldr":"When an LLM provider, vector database or tool API starts failing or timing out, every caller that keeps\ntrying ties up threads and connections waiting for answers that will not come, and the retries make\nrecovery harder. A circuit breaker counts recent failures and, past a threshold, fails fast for a\ncooling-off period, then lets a few trial calls through to test recovery. It trades a few wrongly\nrejected requests for keeping the caller alive and giving the dependency room to heal.","review":"fact-checked","status":"ok"},{"id":"bulkheads","key":"reliability/bulkheads","module":"reliability","name":"Bulkheads","taxonomy_name":"bulkheads","kind":"pattern","difficulty":"core","est_minutes":13,"related":["reliability/circuit-breakers","reliability/tenant-level-quotas-and-noisy-neighbor-isolation","reliability/fault-tolerance","reliability/backpressure-and-load-shedding","fastapi-for-ai/concurrency-limits","fastapi-for-ai/async-database-access-and-connection-pooling","infra-capacity-economics/shared-vs-isolated-model-serving-infrastructure","infra-capacity-economics/queueing-theory"],"tldr":"A ship's hull is divided into watertight compartments so one breach floods one section, not the vessel.\nA software bulkhead partitions a shared resource (worker threads, connections, semaphores, queues, pods)\nper dependency, workload class or tenant, so exhaustion in one compartment cannot drain what the others\nneed. Where a circuit breaker reacts after it detects failure, a bulkhead bounds the damage in advance,\nwhether or not anything detects it. The price is capacity that cannot be borrowed across compartments.","review":"fact-checked","status":"ok"},{"id":"fmea","key":"reliability/fmea","module":"reliability","name":"FMEA (Failure Mode and Effects Analysis)","taxonomy_name":"FMEA","kind":"practice","difficulty":"core","est_minutes":15,"related":["reliability/chaos-engineering-and-resilience-testing","reliability/fault-tolerance","reliability/slas-slos","delivery-ownership/failure-analysis","delivery-ownership/root-cause-analysis-and-postmortems","security-governance-compliance/threat-modeling","security-governance-compliance/ai-risk-management","scoping/dependency-and-risk-management"],"tldr":"FMEA is a structured, tabular way to enumerate how each part of a system can fail (failure modes), what\nhappens when it does (effects), why (causes), how you would notice (detection), and to rank each by\nSeverity × Occurrence × Detection so the worst risks are fixed first. It comes from safety engineering.\nFor AI systems it is the cheapest way to find the failures nobody is monitoring: confident wrong answers,\nsilently stale retrieval, tool calls that succeed against the wrong record. It is a postmortem written\nbefore the incident.","review":"fact-checked","status":"ok"},{"id":"chaos-engineering-and-resilience-testing","key":"reliability/chaos-engineering-and-resilience-testing","module":"reliability","name":"Chaos engineering & resilience testing","taxonomy_name":"chaos engineering & resilience testing","kind":"practice","difficulty":"core","est_minutes":15,"related":["reliability/fmea","reliability/circuit-breakers","reliability/bulkheads","reliability/fault-tolerance","reliability/disaster-recovery","serving-inference/fallbacks","deployment/runbooks","delivery-ownership/root-cause-analysis-and-postmortems"],"tldr":"Resilience mechanisms (fallbacks, breakers, retries, failover) run rarely and rot silently, so you do\nnot know whether they work until they are needed. Resilience testing exercises them deliberately in\npre-production: fault injection, load, stress and soak tests, failover drills, game days. Chaos\nengineering extends this to controlled experiments on real systems: state a steady-state hypothesis,\ninject a realistic fault with a bounded blast radius, measure whether it held. For AI systems the faults\ninclude provider 429s and latency, tool failures, stale retrieval and malformed model output.","review":"fact-checked","status":"ok"},{"id":"slas-slos","key":"reliability/slas-slos","module":"reliability","name":"SLAs / SLOs (and SLIs, error budgets)","taxonomy_name":"SLAs / SLOs","kind":"concept","difficulty":"core","est_minutes":16,"related":["reliability/high-availability","reliability/fmea","delivery-ownership/slas","delivery-ownership/incident-severity-and-escalation","observability/latency-percentiles","observability/monitoring","scoping/success-metrics-kpis","infra-capacity-economics/latency-budgets"],"tldr":"An SLI measures behavior users care about: the fraction of requests answered correctly within two\nseconds. An SLO is the internal target for that SLI over a window (99.5 percent over 30 days). An SLA\nis the external contract attaching consequences to a looser target. The gap between 100 percent and\nthe SLO is the error budget: reliability as a quantity you can spend on shipping. For AI systems the\nhard part is choosing SLIs that capture \"the answer was useful\", not just \"the request returned 200\".","review":"fact-checked","status":"ok"}]},{"id":"agent-runtime-architecture","tier":2,"order":18,"title":"Agent runtime architecture","intro":null,"topics":[{"id":"agent-runtime-and-orchestration-layer","key":"agent-runtime-architecture/agent-runtime-and-orchestration-layer","module":"agent-runtime-architecture","name":"Agent runtime & orchestration layer","taxonomy_name":"agent runtime & orchestration layer","kind":"concept","difficulty":"core","est_minutes":16,"related":["agents/agent-loop","agents/state-machines","agent-reliability/durable-execution-and-checkpointing","agent-reliability/structured-event-streams","agent-reliability/idempotent-tool-execution","system-design/agent-orchestration","llmops-platform/ai-control-plane-vs-data-plane","agent-runtime-architecture/policy-enforcement-across-agents-and-tools"],"tldr":"An agent is a loop: call the model, execute what it asked for, feed the result back. The runtime owns that\nloop as a long-lived, crash-safe, policy-checked unit of work instead of a function in a request handler;\nthe orchestration layer above it coordinates many runs (sub-agents, handoffs, queues, budgets). Both exist\nbecause loop state must outlive any process, tool calls have side effects, and every cross-cutting rule\n(approval, tenancy, secrets) needs one enforcement point.","review":"fact-checked","status":"ok"},{"id":"approval-and-authorization-boundaries","key":"agent-runtime-architecture/approval-and-authorization-boundaries","module":"agent-runtime-architecture","name":"Approval & authorization boundaries","taxonomy_name":"approval & authorization boundaries","kind":"pattern","difficulty":"core","est_minutes":15,"related":["agents/human-in-the-loop","agents/approval-gates-for-consequential-actions","agent-reliability/tool-permissions-and-least-privilege","safety-security/excessive-agency","safety-security/tool-privilege-escalation","backend-fundamentals/authentication-vs-authorization","backend-fundamentals/oauth-2-0-oidc","agent-runtime-architecture/policy-enforcement-across-agents-and-tools"],"tldr":"Authorization answers \"may this principal perform this action at all\"; approval answers \"does a human need\nto confirm this particular instance\". Both must be decided by the runtime at the tool-dispatch boundary,\noutside the model's influence, because model output is untrusted input: a prompt-injected or hallucinated\ntool call carries exactly as much authority as a legitimate one. The agent acts with the *intersection* of\nthe user's rights and its own delegated scope, and an approval is bound to the exact arguments it approved.","review":"fact-checked","status":"ok"},{"id":"policy-enforcement-across-agents-and-tools","key":"agent-runtime-architecture/policy-enforcement-across-agents-and-tools","module":"agent-runtime-architecture","name":"Policy enforcement across agents & tools","taxonomy_name":"policy enforcement across agents & tools","kind":"pattern","difficulty":"advanced","est_minutes":16,"related":["agent-runtime-architecture/approval-and-authorization-boundaries","agents/mcp-authentication-authorization-transport-security","agents/multi-agent-patterns","security-governance-compliance/zero-trust","security-governance-compliance/prompt-injection-defense","safety-security/tool-privilege-escalation","system-design/ai-gateway","customer-data-evaluation/per-customer-guardrails"],"tldr":"Once a system has several agents, several tool servers and several entry points, rules written into each\nagent's prompt or code drift apart and are bypassed by whichever path forgot them. The fix is the classic\nsplit between a single policy decision point and many enforcement points: every hop (runtime dispatch,\ntool gateway, model gateway, egress) asks the same engine, passes the same signed run context, and a child\nagent's authority is only ever attenuated from its parent's, never widened.","review":"fact-checked","status":"ok"},{"id":"multi-tenant-state-isolation","key":"agent-runtime-architecture/multi-tenant-state-isolation","module":"agent-runtime-architecture","name":"Multi-tenant state isolation","taxonomy_name":"multi-tenant state isolation","kind":"pattern","difficulty":"core","est_minutes":16,"related":["system-design/multi-tenancy","system-design/tenant-isolation","safety-security/cross-tenant-data-leakage","reliability/tenant-level-quotas-and-noisy-neighbor-isolation","agents/agent-memory","agents/sandboxing","agent-reliability/state-and-checkpoint-stores","data-architecture/data-retention-and-deletion-architecture"],"tldr":"An agent runtime scatters tenant data across far more places than a CRUD app does: step logs, long-term\nmemory, retrieval indexes, uploaded files, code sandboxes, semantic and tool caches, traces and queues.\nCross-tenant leakage happens in whichever of those a filter was forgotten. Isolation therefore has to be\nstructural: tenant identity derived from authentication and carried in the run context, never from model\noutput, and enforced at the storage layer of every surface rather than remembered in application code.","review":"fact-checked","status":"ok"},{"id":"secrets-and-credential-isolation","key":"agent-runtime-architecture/secrets-and-credential-isolation","module":"agent-runtime-architecture","name":"Secrets & credential isolation","taxonomy_name":"secrets & credential isolation","kind":"pattern","difficulty":"core","est_minutes":15,"related":["backend-fundamentals/secrets-management","backend-fundamentals/oauth-2-0-oidc","agents/sandboxing","agents/mcp-authentication-authorization-transport-security","safety-security/data-leakage","safety-security/prompt-injection","security-governance-compliance/zero-trust","agent-runtime-architecture/multi-tenant-state-isolation"],"tldr":"Treat the model as an untrusted component that will eventually repeat anything in its context. Secrets\ntherefore never enter the context window, the sandbox, or model-filled tool arguments. The model names a\nconnection; a tool executor in a separate process resolves that name to a short-lived, narrowly scoped\ncredential at call time from a vault or token broker, uses it, and never returns it. Credentials are stored\nand minted per tenant and per user, so one tenant's token can never serve another's run.","review":"fact-checked","status":"ok"},{"id":"cross-language-api-contracts","key":"agent-runtime-architecture/cross-language-api-contracts","module":"agent-runtime-architecture","name":"Cross-language API contracts","taxonomy_name":"cross-language API contracts","kind":"pattern","difficulty":"core","est_minutes":15,"related":["agents/typed-tool-contracts","agents/tool-schemas-and-argument-validation","agents/model-context-protocol","python-for-ai/pydantic","node-ts-for-ai/runtime-schema-validation","fastapi-for-ai/openapi-contract-testing","python-for-ai/contract-testing","backend-fundamentals/api-versioning-and-backward-compatibility"],"tldr":"Agent systems are polyglot by construction: Python for the loop, TypeScript for the product and tool\nservers, Go or Java behind them, and the model itself consuming JSON Schema. Tool definitions, event streams\nand run state cross those boundaries constantly. A contract is one machine-readable schema every side\ngenerates its types and runtime validators from, with explicit rules for what JSON leaves ambiguous (64-bit\nintegers, dates, null versus absent, unknown enum values) and for evolving without breaking old consumers.","review":"fact-checked","status":"ok"}]},{"id":"data-architecture","tier":2,"order":19,"title":"Data architecture","intro":null,"topics":[{"id":"ingestion-pipelines","key":"data-architecture/ingestion-pipelines","module":"data-architecture","name":"Ingestion pipelines","taxonomy_name":"ingestion pipelines","kind":"pattern","difficulty":"core","est_minutes":15,"related":["data-architecture/etl-elt-for-rag","data-architecture/document-processing-pipelines","data-architecture/data-contracts","data-architecture/data-lineage","rag-retrieval/freshness-document-deletion-index-consistency","rag-retrieval/acl-aware-retrieval","enterprise-integration/data-ingestion-from-client-systems","enterprise-integration/retry-deduplication-reconciliation"],"tldr":"An ingestion pipeline is the path from source systems (databases, SaaS tools, file shares, event streams)\ninto a durable, replayable landing store that your AI system can transform from. The design that survives\nproduction is incremental change capture (including deletes), an immutable raw copy keyed by source\nidentity and content hash, and idempotent stages with a committed watermark, because sources change\ncontinuously and every downstream choice (parser, chunker, embedding model) will be redone more than once.","status":"ok"},{"id":"etl-elt-for-rag","key":"data-architecture/etl-elt-for-rag","module":"data-architecture","name":"ETL / ELT for RAG","taxonomy_name":"ETL / ELT for RAG","kind":"pattern","difficulty":"core","est_minutes":15,"related":["data-architecture/ingestion-pipelines","data-architecture/document-processing-pipelines","data-architecture/embedding-versioning-re-indexing-strategy","data-architecture/lakehouse","rag-retrieval/embedding-pipelines","rag-retrieval/chunking-strategies","rag-retrieval/contextual-retrieval","system-design/rag-architecture"],"tldr":"ETL transforms data before loading it into the target; ELT loads raw data first and transforms inside or\nbeside the target. For RAG the right shape is ELT into a lake or landing store followed by a staged\ntransformation DAG (parse → clean → chunk → enrich → embed → index) whose stages are materialized,\ncontent-addressed tables, because the transformations change far more often than the sources do and\nre-transforming from raw is the operation you will run most. The vector index is a derived, rebuildable\nserving structure, never the system of record.","status":"ok"},{"id":"training-data-pipelines","key":"data-architecture/training-data-pipelines","module":"data-architecture","name":"Training data pipelines","taxonomy_name":"training data pipelines","kind":"pattern","difficulty":"core","est_minutes":16,"related":["training-adaptation/data-curation","training-adaptation/synthetic-data-generation","training-adaptation/supervised-fine-tuning","training-adaptation/data-labeling","evals/dataset-contamination","data-architecture/model-and-dataset-provenance","data-architecture/lakehouse","model-internals/tokenization"],"tldr":"A training data pipeline turns raw sources into versioned, deduplicated, decontaminated, token-ready\nshards with full provenance. Its architecture matters because what you *remove* (duplicates, eval\nleakage, junk, PII) shapes the model at least as much as what you add, because every run must be\nreproducible from a dataset hash, and because tokenization and shuffling done at training time starve the\nGPUs. This lesson covers the pipeline; the curation, labeling and synthetic-data lessons in Training &\nadaptation cover what makes an individual example good.","status":"ok"},{"id":"lakehouse","key":"data-architecture/lakehouse","module":"data-architecture","name":"Lakehouse","taxonomy_name":"lakehouse","kind":"concept","difficulty":"core","est_minutes":14,"related":["data-architecture/etl-elt-for-rag","data-architecture/training-data-pipelines","data-architecture/data-lineage","data-architecture/data-retention-and-deletion-architecture","data-architecture/model-and-dataset-provenance","backend-fundamentals/database-design","system-design/data-consistency","security-governance-compliance/data-residency"],"tldr":"A lakehouse is a transactional table layer (Delta Lake, Apache Iceberg, Apache Hudi) over open columnar\nfiles (Parquet) in object storage. It keeps the cheap, engine-agnostic storage of a data lake and adds\nwhat a lake lacks: atomic commits, snapshot isolation, schema enforcement and evolution, time travel and\nreal deletes. For AI systems it is the natural home for raw documents, chunk and embedding tables, training\ndatasets and trace logs, because many different engines need the same data and none of them should own it.","status":"ok"},{"id":"document-processing-pipelines","key":"data-architecture/document-processing-pipelines","module":"data-architecture","name":"Document processing pipelines","taxonomy_name":"document processing pipelines","kind":"pattern","difficulty":"core","est_minutes":15,"related":["rag-retrieval/document-parsing","multimodal/ocr","multimodal/document-understanding","enterprise-integration/client-document-parsing","data-architecture/ingestion-pipelines","data-architecture/etl-elt-for-rag","rag-retrieval/chunking-strategies","rag-retrieval/parent-document-retrieval"],"tldr":"A document processing pipeline turns heterogeneous files (PDF, Office, HTML, email, scans, images) into\none canonical structured representation: ordered blocks with type, text, page, position and hierarchy,\nplus tables as cells. The architecture is a tiered router: detect what each document really is, send it\nto the cheapest extractor that preserves its structure, score the output, and escalate (native text →\nOCR → layout model or vision LLM) only when the score fails, because extraction quality bounds every\ndownstream step and the expensive extractors cannot be run on everything.","status":"ok"},{"id":"vector-database-architecture","key":"data-architecture/vector-database-architecture","module":"data-architecture","name":"Vector database architecture","taxonomy_name":"vector database architecture","kind":"concept","difficulty":"advanced","est_minutes":16,"related":["rag-retrieval/vector-databases","rag-retrieval/ann-indexes","rag-retrieval/metadata-filtering","rag-retrieval/acl-aware-retrieval","rag-retrieval/hybrid-search","data-architecture/vector-store-sizing","data-architecture/embedding-versioning-re-indexing-strategy","rag-retrieval/freshness-document-deletion-index-consistency"],"tldr":"A vector database is three things bolted together: an approximate-nearest-neighbour index, a document\nstore for ids and payload, and a query planner that combines similarity with filters. The hard problems\nare not the distance math but mutability (graph indexes hate updates and deletes), filtered search\n(selective filters break \"find top-k then filter\"), memory residency (graph traversal is random access,\nso the index lives in RAM or on an SSD-aware design) and distribution. Understand those four and the\nvendor comparison in the RAG module becomes a checklist.","status":"ok"},{"id":"vector-store-sizing","key":"data-architecture/vector-store-sizing","module":"data-architecture","name":"Vector store sizing","taxonomy_name":"vector store sizing","kind":"practice","difficulty":"core","est_minutes":14,"related":["data-architecture/vector-database-architecture","data-architecture/embedding-versioning-re-indexing-strategy","rag-retrieval/ann-indexes","rag-retrieval/embedding-dimension-and-normalization","rag-retrieval/chunking-strategies","infra-capacity-economics/capacity-planning","infra-capacity-economics/cost-modeling","serving-inference/kv-cache-memory-estimation"],"tldr":"Vector store cost is set by RAM-resident bytes: `vectors × (dim × bytes_per_dim + graph_overhead +\npayload)`, multiplied by replicas and a headroom factor for index builds. Every input is knowable\nbefore you pick a vendor tier: vector count from documents and chunking, dimension and precision from the\nembedding model and quantization, payload from what you choose to store beside the vector. Do the\narithmetic first; it routinely flips the decision between pgvector on an existing database and a\ndedicated cluster, and it is the same discipline as KV-cache sizing in serving.","status":"ok"},{"id":"embedding-versioning-re-indexing-strategy","key":"data-architecture/embedding-versioning-re-indexing-strategy","module":"data-architecture","name":"Embedding versioning / re-indexing strategy","taxonomy_name":"embedding versioning / re-indexing strategy","kind":"pattern","difficulty":"core","est_minutes":16,"related":["rag-retrieval/embedding-models","rag-retrieval/embedding-pipelines","rag-retrieval/embedding-dimension-and-normalization","rag-retrieval/freshness-document-deletion-index-consistency","data-architecture/vector-database-architecture","data-architecture/vector-store-sizing","data-architecture/etl-elt-for-rag","evals/retrieval-evaluation"],"tldr":"A vector is only meaningful relative to the model that produced it: two embedding models, or two\nversions of one, put the same text at unrelated points in space. So the model, its settings and the\nchunker are part of the index's identity, and changing any of them means re-embedding everything. The\nstrategy: version that identity explicitly, build the new index beside the old, evaluate, swap atomically,\nand hash content so routine runs re-embed only changed chunks.","status":"ok"},{"id":"knowledge-management","key":"data-architecture/knowledge-management","module":"data-architecture","name":"Knowledge management","taxonomy_name":"knowledge management","kind":"practice","difficulty":"core","est_minutes":14,"related":["data-architecture/document-processing-pipelines","data-architecture/ingestion-pipelines","rag-retrieval/freshness-document-deletion-index-consistency","rag-retrieval/acl-aware-retrieval","rag-retrieval/metadata-filtering","rag-retrieval/retrieval-failure-diagnosis","enterprise-integration/data-ingestion-from-client-systems","rag-retrieval/citations-grounding"],"tldr":"A retrieval system cannot answer better than the corpus it searches, and most enterprise corpora are\nstale, duplicated, contradictory and unowned. Knowledge management is the practice of deciding which\nsources are canonical, who owns each, how documents enter, age and leave the index, and what metadata\ntravels with them, so that the retriever is choosing among correct candidates. Most \"the model\nhallucinated\" reports in RAG trace back to this layer, not to the model.","status":"ok"},{"id":"data-lineage","key":"data-architecture/data-lineage","module":"data-architecture","name":"Data lineage","taxonomy_name":"data lineage","kind":"concept","difficulty":"core","est_minutes":15,"related":["data-architecture/model-and-dataset-provenance","data-architecture/data-contracts","data-architecture/data-retention-and-deletion-architecture","data-architecture/etl-elt-for-rag","data-architecture/training-data-pipelines","observability/tracing","security-governance-compliance/audit-trails","rag-retrieval/citations-grounding"],"tldr":"Data lineage is the recorded graph of where every dataset, chunk, feature and model came from: which\ninputs, which job, which code version, which run. It exists because the questions that matter in\nproduction (\"why did this answer change\", \"which indexes contain this customer's data\", \"what was this\nmodel trained on\") are graph traversals, and without a recorded graph the only way to answer them is to\nread code and guess. In AI systems, lineage is what makes deletion, debugging and reproducibility\npossible at all.","status":"ok"},{"id":"data-contracts","key":"data-architecture/data-contracts","module":"data-architecture","name":"Data contracts","taxonomy_name":"data contracts","kind":"pattern","difficulty":"core","est_minutes":14,"related":["data-architecture/ingestion-pipelines","data-architecture/data-lineage","enterprise-integration/data-mapping-and-canonical-schemas","enterprise-integration/data-profiling-and-quality-assessment","backend-fundamentals/api-versioning-and-backward-compatibility","node-ts-for-ai/runtime-schema-validation","python-for-ai/contract-testing","agents/typed-tool-contracts"],"tldr":"A data contract is an explicit, versioned, machine-checked agreement between the team that produces a\ndataset and the teams that consume it: schema, meaning, quality guarantees, freshness and ownership. It\nexists because AI pipelines are the most fragile consumers in the company: a renamed column or a changed\nunit does not crash an embedding job or a training run, it quietly produces a worse model or index. The\ncontract moves the failure to the producer's side, at write time, where it is loud and cheap.","status":"ok"},{"id":"model-and-dataset-provenance","key":"data-architecture/model-and-dataset-provenance","module":"data-architecture","name":"Model & dataset provenance","taxonomy_name":"model & dataset provenance","kind":"practice","difficulty":"core","est_minutes":15,"related":["data-architecture/data-lineage","data-architecture/training-data-pipelines","llmops-platform/model-registry","security-governance-compliance/model-cards","security-governance-compliance/model-governance","safety-security/supply-chain-security-for-models-and-datasets","evals/dataset-contamination","training-adaptation/data-curation"],"tldr":"Provenance is the verifiable record of where a model or dataset came from: the exact bytes it was built\nfrom, the code and parameters that built it, who built it, under which licence, and the evaluations that\nwere run on it. It exists because a model file is opaque: nothing in a checkpoint tells you what data it\nsaw, whether that data was licensed or contained your eval set, or whether the file is even the one you\nthink it is. Provenance turns \"trust me\" into hashes, manifests and signatures.","status":"ok"},{"id":"data-retention-and-deletion-architecture","key":"data-architecture/data-retention-and-deletion-architecture","module":"data-architecture","name":"Data retention & deletion architecture","taxonomy_name":"data retention & deletion architecture","kind":"pattern","difficulty":"core","est_minutes":16,"related":["data-architecture/data-lineage","rag-retrieval/freshness-document-deletion-index-consistency","agents/memory-retrieval-update-deletion-policies","security-governance-compliance/data-classification","security-governance-compliance/compliance-architecture","security-governance-compliance/data-residency","safety-security/pii-redaction","serving-inference/caching"],"tldr":"An LLM application copies user data into far more places than a conventional service: prompt logs,\ntraces, vector indexes, caches, eval sets, fine-tuning data, vendor-side logs and model weights. Retention\nand deletion architecture is the design that knows every one of those places, assigns each a retention\nclass and a time-to-live, and can execute a deletion request across all of them with proof. It has to be\ndesigned in, because a deletion you cannot propagate is a promise you cannot keep.","status":"ok"},{"id":"feature-stores","key":"data-architecture/feature-stores","module":"data-architecture","name":"Feature stores (hybrid ML only)","taxonomy_name":"feature stores (hybrid ML only)","kind":"concept","difficulty":"core","est_minutes":14,"related":["ml-fundamentals/train-test-leakage","data-architecture/training-data-pipelines","data-architecture/lakehouse","data-architecture/data-contracts","data-architecture/data-lineage","llmops-platform/drift","llmops-platform/model-registry","system-design/data-consistency"],"tldr":"Caveat first: feature stores matter only in hybrid systems that train and serve classical ML models\n(ranking, fraud, churn, routing classifiers) alongside LLM components; pure LLM-application roles can skim\nthis and move on. A feature store is the layer that computes model input features once, serves the same\nvalues to training (historically, point-in-time correct) and to inference (now, at low latency), and\nversions their definitions, because training/serving skew and time leakage are the two bugs that quietly\nruin tabular models.","caveat":"hybrid ML only; drop for LLM-app roles","status":"ok"}]},{"id":"infra-capacity-economics","tier":2,"order":20,"title":"Infra, capacity & economics","intro":null,"topics":[{"id":"gpu-infrastructure","key":"infra-capacity-economics/gpu-infrastructure","module":"infra-capacity-economics","name":"GPU infrastructure","taxonomy_name":"GPU infrastructure","kind":"concept","difficulty":"intro","est_minutes":12,"related":["infra-capacity-economics/gpu-sizing","infra-capacity-economics/gpu-utilization-and-memory-bandwidth","infra-capacity-economics/a100-h100-l4-selection","infra-capacity-economics/inference-clusters","infra-capacity-economics/hybrid-on-prem","backend-fundamentals/kubernetes","serving-inference/engines"],"tldr":"A GPU deployment is a stack, not a card: the accelerator and its memory, the host around it, the\ndriver and CUDA libraries, the container runtime that exposes the device, the scheduler that assigns\nit, and the procurement model that pays for it. Each layer fails differently, and most \"the GPU is\nslow\" tickets are really host, driver or scheduling problems. This lesson is the map; sizing,\nbandwidth, card selection, serverless and autoscaling each have their own lesson.","status":"ok"},{"id":"gpu-sizing","key":"infra-capacity-economics/gpu-sizing","module":"infra-capacity-economics","name":"GPU sizing (VRAM math)","taxonomy_name":"GPU sizing (VRAM math)","kind":"concept","difficulty":"core","est_minutes":16,"related":["model-internals/kv-cache","serving-inference/kv-cache-memory-estimation","serving-inference/gpu-memory-optimization","serving-inference/tensor-parallelism-at-inference","training-adaptation/quantization","training-adaptation/distributed-training","infra-capacity-economics/a100-h100-l4-selection"],"tldr":"GPU memory for inference is weights + KV cache + activations/workspace + runtime overhead; for\ntraining it is weights + gradients + optimizer state + activations, about 16 bytes per parameter with\nmixed-precision Adam before activations are counted. The arithmetic takes a minute and decides the\ncard, the card count, the precision and the concurrency you can promise. Skipping it is how both\nout-of-memory crashes and half-empty 80 GB cards happen.","status":"ok"},{"id":"gpu-utilization-and-memory-bandwidth","key":"infra-capacity-economics/gpu-utilization-and-memory-bandwidth","module":"infra-capacity-economics","name":"GPU utilization & memory bandwidth","taxonomy_name":"GPU utilization & memory bandwidth","kind":"concept","difficulty":"core","est_minutes":16,"related":["serving-inference/prefill-vs-decode","serving-inference/continuous-batching","serving-inference/throughput-vs-latency","serving-inference/tpot","model-internals/flashattention","model-internals/kv-cache","infra-capacity-economics/gpu-sizing"],"tldr":"The \"GPU-Util\" number in `nvidia-smi` only says a kernel was running, not that the chip was busy.\nReal throughput is bounded by the roofline: for every byte moved from GPU memory the chip can do a\nfixed number of floating-point operations, roughly 150 on an A100 and 300 on an H100 at bf16. LLM\ndecode does about two operations per weight byte per sequence, so small batches are\nmemory-bandwidth-bound and the fix is batching, fewer bytes or faster memory, not more FLOPs.","status":"ok"},{"id":"a100-h100-l4-selection","key":"infra-capacity-economics/a100-h100-l4-selection","module":"infra-capacity-economics","name":"A100 / H100 / L4 selection","taxonomy_name":"A100 / H100 / L4 selection","kind":"decision","difficulty":"core","est_minutes":15,"related":["infra-capacity-economics/gpu-sizing","infra-capacity-economics/gpu-utilization-and-memory-bandwidth","infra-capacity-economics/cost-modeling","infra-capacity-economics/tco","serving-inference/tensor-parallelism-at-inference","serving-inference/quantization-quality-evaluation","training-adaptation/quantization"],"tldr":"Choose a card by the constraint that binds first: does the model fit (memory capacity), is per-stream\ndecode fast enough (memory bandwidth), and what does a token cost at the utilisation you will\nactually run (price ÷ throughput ceiling). The L4 is a cheap, 24 GB, low-bandwidth card for small\nmodels and light traffic; the A100 is the mature 40/80 GB workhorse without FP8; the H100 is the\n80 GB, ~3.35 TB/s, FP8-capable card that wins per token at high load and for training.","status":"ok"},{"id":"serverless-gpus","key":"infra-capacity-economics/serverless-gpus","module":"infra-capacity-economics","name":"Serverless GPUs","taxonomy_name":"serverless GPUs","kind":"pattern","difficulty":"core","est_minutes":14,"related":["infra-capacity-economics/keda-autoscaling","infra-capacity-economics/break-even-analysis","infra-capacity-economics/cost-modeling","infra-capacity-economics/capacity-planning","infra-capacity-economics/latency-budgets","serving-inference/ttft","serving-inference/model-serving"],"tldr":"Serverless GPUs bill per second of actual use and scale to zero, so a bursty or low-volume workload\npays only for busy seconds instead of for a card that idles most of the day. The price is a cold start\nof tens of seconds to minutes (pull the image, load weights into VRAM, warm the engine) and a\nper-second rate above on-demand hourly pricing. Decide on utilisation break-even shifted by cold-start\noverhead, gated by whether your latency SLO can absorb a cold start at all.","status":"ok"},{"id":"keda-autoscaling","key":"infra-capacity-economics/keda-autoscaling","name":"KEDA autoscaling","module":"infra-capacity-economics","status":"missing"},{"id":"ray-kuberay","key":"infra-capacity-economics/ray-kuberay","name":"Ray / KubeRay","module":"infra-capacity-economics","status":"missing"},{"id":"inference-clusters","key":"infra-capacity-economics/inference-clusters","module":"infra-capacity-economics","name":"Inference clusters","taxonomy_name":"inference clusters","kind":"concept","difficulty":"core","est_minutes":16,"related":["infra-capacity-economics/gpu-infrastructure","infra-capacity-economics/ray-kuberay","infra-capacity-economics/keda-autoscaling","infra-capacity-economics/capacity-planning","serving-inference/continuous-batching","serving-inference/tensor-parallelism-at-inference","serving-inference/prefix-caching","serving-inference/engines"],"tldr":"An inference cluster is a fleet of model-server replicas (vLLM, TGI, TensorRT-LLM, Triton) behind a\nrouter, scheduled onto GPU nodes, scaled on LLM-specific signals. It exists because a single GPU box\ncaps out on memory and bandwidth long before real traffic does, and because LLM requests are\nlong-lived, variable-length and stateful (the KV cache), which breaks the stateless web-tier playbook\nof round-robin load balancing and CPU-based autoscaling.","status":"ok"},{"id":"shared-vs-isolated-model-serving-infrastructure","key":"infra-capacity-economics/shared-vs-isolated-model-serving-infrastructure","module":"infra-capacity-economics","name":"Shared vs isolated model-serving infrastructure","taxonomy_name":"shared vs isolated model-serving infrastructure","kind":"decision","difficulty":"core","est_minutes":15,"related":["infra-capacity-economics/inference-clusters","infra-capacity-economics/cost-allocation-by-tenant-and-feature","system-design/multi-tenancy","system-design/tenant-isolation","reliability/tenant-level-quotas-and-noisy-neighbor-isolation","reliability/bulkheads","serving-inference/continuous-batching","safety-security/cross-tenant-data-leakage"],"tldr":"Shared serving puts every tenant's or team's traffic through one pool of model replicas; isolated\nserving gives a tenant its own replicas, nodes, cluster or account. Sharing wins on cost because\ncontinuous batching needs many concurrent requests to fill a GPU and because tenants' peaks rarely\ncoincide. Isolation wins when a tenant can hurt others (noisy neighbour), must be protected from\nothers (compliance, data separation) or needs a different model configuration. The decision is a\nspectrum, not a switch, and most platforms end up with both.","status":"ok"},{"id":"cloud-ai-architecture","key":"infra-capacity-economics/cloud-ai-architecture","module":"infra-capacity-economics","name":"Cloud AI architecture (AWS Bedrock, Azure OpenAI, Vertex AI)","taxonomy_name":"cloud AI architecture (AWS Bedrock, Azure OpenAI, Vertex AI)","kind":"concept","difficulty":"core","est_minutes":17,"related":["infra-capacity-economics/api-provider-quotas-and-regional-limits","infra-capacity-economics/hybrid-on-prem","system-design/self-host-vs-api","system-design/ai-gateway","system-design/open-weight-vs-proprietary","deployment/private-endpoints","security-governance-compliance/data-residency","security-governance-compliance/vendor-exit-strategy"],"tldr":"Bedrock, Azure OpenAI and Vertex AI are one idea on three clouds: frontier and open-weight models\nserved as a managed API *inside* your cloud account's identity, network, logging and billing\nperimeter. Enterprises pick them over a vendor's public API because procurement, compliance and\nnetworking are already solved there, and pay with model lag, per-region quotas and a second layer\nof lock-in. The architecture work is placing the endpoint inside that perimeter and planning\ncapacity per region.","status":"ok"},{"id":"api-provider-quotas-and-regional-limits","key":"infra-capacity-economics/api-provider-quotas-and-regional-limits","module":"infra-capacity-economics","name":"API provider quotas & regional limits","taxonomy_name":"API provider quotas & regional limits","kind":"concept","difficulty":"core","est_minutes":15,"related":["infra-capacity-economics/cloud-ai-architecture","infra-capacity-economics/capacity-planning","serving-inference/rate-limiting","serving-inference/retry-strategies","serving-inference/fallbacks","reliability/multi-region-architecture","reliability/circuit-breakers","system-design/ai-gateway"],"tldr":"Hosted model APIs are shared pools, so every provider caps what one account may take: requests and\ntokens per minute (often input and output separately), per model, per region, per account, rising\nwith spend tier. Exceed them and you get 429s; when the pool itself is full you get overload errors\nregardless of quota. Capacity planning on an API is therefore quota planning: measure demand in the\nprovider's units, keep headroom, spread across regions where residency allows, and reserve capacity\nfor the base load.","status":"ok"},{"id":"hybrid-on-prem","key":"infra-capacity-economics/hybrid-on-prem","module":"infra-capacity-economics","name":"Hybrid / on-prem","taxonomy_name":"hybrid / on-prem","kind":"pattern","difficulty":"core","est_minutes":15,"related":["infra-capacity-economics/cloud-ai-architecture","infra-capacity-economics/gpu-infrastructure","infra-capacity-economics/break-even-analysis","infra-capacity-economics/tco","system-design/self-host-vs-api","system-design/model-routing-cascading","deployment/customer-vpc-on-prem-air-gapped","security-governance-compliance/data-residency"],"tldr":"Hybrid AI infrastructure runs some inference on hardware you control (your datacenter, a colo, a\ncustomer's VPC or an air-gapped site) and the rest on hosted model APIs, with a gateway routing each\nrequest by data classification, latency need and model need. It exists because some data cannot\nleave, some sites lack connectivity, and high steady volume can be cheaper on owned GPUs,\nwhile on-prem alone loses frontier models and elasticity. The hard parts are the routing policy, a\nuniform API surface, and keeping fixed capacity busy.","status":"ok"},{"id":"edge-ai-deployment","key":"infra-capacity-economics/edge-ai-deployment","module":"infra-capacity-economics","name":"Edge AI deployment","taxonomy_name":"edge AI deployment","kind":"concept","difficulty":"core","est_minutes":15,"related":["infra-capacity-economics/hybrid-on-prem","infra-capacity-economics/gpu-utilization-and-memory-bandwidth","model-internals/small-language-models","training-adaptation/quantization","training-adaptation/knowledge-distillation","system-design/slm-vs-llm-trade-offs","serving-inference/quantization-quality-evaluation","serving-inference/engines"],"tldr":"Edge AI runs the model on the device that has the data: a phone, laptop, browser, vehicle, factory\ncontroller or retail box. It exists for latency with no network round trip, operation when offline,\nprivacy because the data never leaves, and cost because the user's hardware does the compute. The\nprice is a hard budget on memory, bandwidth, power and model size, so edge means small or\ncompressed models on a device-specific runtime, usually with a cloud fallback for what the small\nmodel cannot do.","status":"ok"},{"id":"capacity-planning","key":"infra-capacity-economics/capacity-planning","name":"capacity planning (tokens/sec, requests/sec, concurrent sessions)","module":"infra-capacity-economics","status":"missing"},{"id":"queueing-theory","key":"infra-capacity-economics/queueing-theory","name":"queueing theory","module":"infra-capacity-economics","status":"missing"},{"id":"latency-budgets","key":"infra-capacity-economics/latency-budgets","name":"latency budgets","module":"infra-capacity-economics","status":"missing"},{"id":"scalability","key":"infra-capacity-economics/scalability","name":"scalability","module":"infra-capacity-economics","status":"missing"},{"id":"cost-optimization","key":"infra-capacity-economics/cost-optimization","name":"cost optimization","module":"infra-capacity-economics","status":"missing"},{"id":"cost-modeling","key":"infra-capacity-economics/cost-modeling","name":"cost modeling (cost per request, token economics)","module":"infra-capacity-economics","status":"missing"},{"id":"unit-economics-per-successful-task","key":"infra-capacity-economics/unit-economics-per-successful-task","name":"unit economics per successful task","module":"infra-capacity-economics","status":"missing"},{"id":"cost-allocation-by-tenant-and-feature","key":"infra-capacity-economics/cost-allocation-by-tenant-and-feature","name":"cost allocation by tenant & feature","module":"infra-capacity-economics","status":"missing"},{"id":"quality-latency-cost-optimization","key":"infra-capacity-economics/quality-latency-cost-optimization","module":"infra-capacity-economics","name":"Quality–latency–cost optimization","taxonomy_name":"quality–latency–cost optimization","kind":"practice","difficulty":"core","est_minutes":15,"related":["system-design/model-routing-cascading","system-design/model-selection","prompting/prompt-caching","infra-capacity-economics/latency-budgets","infra-capacity-economics/unit-economics-per-successful-task","infra-capacity-economics/cost-optimization","training-adaptation/knowledge-distillation"],"tldr":"Every LLM feature lives in a three-dimensional space: how good the answers are, how long the user waits,\nand what each request costs. The levers that improve one axis almost always degrade another, so you cannot\nmaximize all three. The practice is to measure all three per task, throw away every configuration that is\nworse on every axis, and choose from the remaining Pareto frontier under the product's hard constraints.\nThis is what separates features that scale from features that get switched off when the invoice arrives.","status":"ok"},{"id":"break-even-analysis","key":"infra-capacity-economics/break-even-analysis","module":"infra-capacity-economics","name":"Break-even analysis (hosted API vs self-hosting)","taxonomy_name":"break-even analysis (hosted API vs self-hosting)","kind":"decision","difficulty":"core","est_minutes":16,"related":["system-design/self-host-vs-api","system-design/open-weight-vs-proprietary","infra-capacity-economics/tco","infra-capacity-economics/gpu-sizing","infra-capacity-economics/capacity-planning","infra-capacity-economics/cost-modeling","serving-inference/throughput-vs-latency","infra-capacity-economics/api-provider-quotas-and-regional-limits"],"tldr":"A hosted API is pure variable cost: you pay per token and nothing when idle. Self-hosting is mostly fixed:\nGPUs and the people who run them are paid for whether or not tokens flow. Break-even is the monthly volume\nwhere the two curves cross. It depends far more on achievable utilization and team cost than on GPU list\nprice, which is why most teams cross it much later than per-token arithmetic suggests, and why an API price\ncut can push the crossover to infinity.","status":"ok"},{"id":"finops","key":"infra-capacity-economics/finops","module":"infra-capacity-economics","name":"FinOps","taxonomy_name":"FinOps","kind":"practice","difficulty":"core","est_minutes":14,"related":["observability/token-cost-tracking","infra-capacity-economics/cost-allocation-by-tenant-and-feature","infra-capacity-economics/unit-economics-per-successful-task","infra-capacity-economics/cost-optimization","infra-capacity-economics/tco","system-design/ai-gateway","infra-capacity-economics/cost-modeling"],"tldr":"FinOps is the operating practice that makes variable cloud and AI spend visible, attributable and owned by\nthe teams that cause it, so cost becomes an engineering signal like latency rather than a quarterly\nsurprise. For LLM systems it means metering every call at the point where it is made, allocating spend to\ntenant and feature, tracking cost per successful task, and running a continuous inform–optimize–operate\nloop instead of a one-off cost-cutting project.","status":"ok"},{"id":"tco","key":"infra-capacity-economics/tco","name":"TCO","module":"infra-capacity-economics","status":"missing"}]},{"id":"llmops-platform","tier":2,"order":21,"title":"LLMOps & AI platform","intro":null,"topics":[{"id":"ci-cd-for-prompts-and-models","key":"llmops-platform/ci-cd-for-prompts-and-models","module":"llmops-platform","name":"CI/CD for prompts and models","taxonomy_name":"CI/CD for prompts and models","kind":"practice","difficulty":"core","est_minutes":16,"related":["backend-fundamentals/ci-cd","llmops-platform/evaluation-gates-for-production-releases","llmops-platform/prompt-registry","llmops-platform/model-registry","llmops-platform/canary-shadow-deployments","evals/regression-tests","prompting/prompt-versioning","evals/eval-driven-development"],"tldr":"Classic CI/CD assumes behaviour is a deterministic function of code and ships one artifact. An LLM\napplication ships three — code, prompts and configuration, and model weights or model IDs — and any one\ncan change behaviour without touching the others. CI/CD for prompts and models adds eval-based tests\nsized to each stage's blast radius, content-addressed caching so those evals stay affordable, and\npromotion of one immutable, tested bundle instead of a rebuild, because a green unit suite says nothing\nabout whether answers got worse.","status":"ok"},{"id":"prompt-registry","key":"llmops-platform/prompt-registry","module":"llmops-platform","name":"Prompt registry","taxonomy_name":"prompt registry","kind":"pattern","difficulty":"core","est_minutes":14,"related":["prompting/prompt-versioning","prompting/prompt-templates","llmops-platform/ci-cd-for-prompts-and-models","llmops-platform/model-registry","llmops-platform/rollback","observability/langfuse","enterprise-integration/tenant-specific-configuration-and-feature-flags","llmops-platform/evaluation-gates-for-production-releases"],"tldr":"A prompt registry is a versioned store of prompt templates and their model settings, with immutable\nnumbered versions, mutable environment labels such as `production` or `canary`, and a runtime fetch API\nthat caches and falls back safely. It exists because prompts are behaviour-defining configuration edited\nby people who do not ship code, and a hard-coded string gives you neither a record of which prompt\nproduced which answer nor a rollback that does not require a deploy.","status":"ok"},{"id":"model-registry","key":"llmops-platform/model-registry","module":"llmops-platform","name":"Model registry","taxonomy_name":"model registry","kind":"pattern","difficulty":"core","est_minutes":15,"related":["llmops-platform/experiment-tracking","llmops-platform/prompt-registry","data-architecture/model-and-dataset-provenance","security-governance-compliance/model-cards","python-for-ai/hugging-face","llmops-platform/model-lifecycle-and-deprecation-policy","llmops-platform/rollback","safety-security/supply-chain-security-for-models-and-datasets"],"tldr":"A model registry is the system of record that maps a model name to immutable, numbered versions, each\npointing at exact weights or a provider snapshot plus adapters and serving config, with lineage to the\nrun and data that produced it, attached evaluation evidence, and mutable aliases such as `champion`\nthat deployments resolve at startup. It exists so that \"which model is in production\" has exactly one\nanswer and promotion or rollback is a pointer move rather than a file copy done by hand.","status":"ok"},{"id":"experiment-tracking","key":"llmops-platform/experiment-tracking","module":"llmops-platform","name":"Experiment tracking (MLflow, W&B)","taxonomy_name":"experiment tracking (MLflow, W&B)","kind":"tool","difficulty":"core","est_minutes":14,"related":["llmops-platform/model-registry","llmops-platform/reproducible-evaluations","training-adaptation/supervised-fine-tuning","data-architecture/model-and-dataset-provenance","observability/langfuse","llmops-platform/evaluation-frameworks","evals/error-analysis"],"tldr":"Experiment tracking records every run of a training or evaluation job — fixed parameters, code and data\nversions, step-indexed metrics and output artifacts — in a queryable store so runs can be compared,\nreproduced and promoted. MLflow and Weights & Biases are the two common tools; they share the same data\nmodel and differ mainly in hosting (self-hosted open source versus SaaS-first), UI depth, and ecosystem\n(MLflow's registry and model packaging; W&B's sweeps, artifact lineage graph and Weave for LLM traces).","status":"ok"},{"id":"evaluation-frameworks","key":"llmops-platform/evaluation-frameworks","module":"llmops-platform","name":"Evaluation frameworks","taxonomy_name":"evaluation frameworks","kind":"concept","difficulty":"core","est_minutes":15,"related":["evals/eval-harness","evals/tooling","llmops-platform/golden-dataset-strategy","llmops-platform/reproducible-evaluations","llmops-platform/evaluation-gates-for-production-releases","evals/llm-as-a-judge","observability/langfuse","evals/benchmarking"],"tldr":"An evaluation framework turns \"run the eval\" from a script one engineer owns into a shared service with\nfive fixed interfaces: versioned datasets, a target adapter that calls the real application, versioned\nscorers (deterministic, model-graded, human), a runner that pins configuration and stores every raw\noutput, and a results store that diffs any two runs item by item. It exists because a harness per team\nproduces numbers nobody else can compare; the framework makes an eval score a currency the whole\norganisation accepts.","status":"ok"},{"id":"golden-dataset-strategy","key":"llmops-platform/golden-dataset-strategy","module":"llmops-platform","name":"Golden dataset strategy","taxonomy_name":"golden dataset strategy","kind":"practice","difficulty":"core","est_minutes":15,"related":["evals/golden-dataset","evals/dataset-contamination","evals/error-analysis","evals/inter-annotator-agreement","llmops-platform/evaluation-frameworks","llmops-platform/evaluation-gates-for-production-releases","training-adaptation/data-labeling","data-architecture/model-and-dataset-provenance"],"tldr":"The `evals/golden-dataset` lesson covers what a golden item is and how it is labeled. This is the\nplatform view: a golden dataset is a portfolio of tiered, versioned sets (smoke, full, slice, regression,\nadversarial, sealed holdout), each with an owner, an admission workflow fed from production failures, and\na size derived from the smallest regression it must detect. The strategy exists because a single static\nset goes stale, leaks into prompts, and is either too small to trust or too expensive to run on every\nchange.","status":"ok"},{"id":"reproducible-evaluations","key":"llmops-platform/reproducible-evaluations","module":"llmops-platform","name":"Reproducible evaluations","taxonomy_name":"reproducible evaluations","kind":"practice","difficulty":"core","est_minutes":14,"related":["llmops-platform/experiment-tracking","llmops-platform/evaluation-frameworks","llmops-platform/evaluation-gates-for-production-releases","evals/eval-harness","llmops-platform/model-registry","llmops-platform/prompt-registry","evals/judge-calibration-and-bias","python-for-ai/lockfiles-and-dependency-pinning"],"tldr":"A reproducible evaluation is one anyone can re-run from a recorded manifest and reach the same\nconclusion: same dataset version, same bundle (model snapshot, prompt version, decoding parameters,\nindex), same scorer versions (judge model and rubric), same code and environment, with raw outputs stored\nand residual sampling noise measured rather than assumed away. It exists because an LLM eval has many\nsilently drifting parts, so an unpinned comparison across weeks compares two different systems and blames\nthe wrong cause.","status":"ok"},{"id":"evaluation-gates-for-production-releases","key":"llmops-platform/evaluation-gates-for-production-releases","module":"llmops-platform","name":"Evaluation gates for production releases","taxonomy_name":"evaluation gates for production releases","kind":"practice","difficulty":"core","est_minutes":16,"related":["llmops-platform/ci-cd-for-prompts-and-models","llmops-platform/canary-shadow-deployments","llmops-platform/rollback","llmops-platform/reproducible-evaluations","llmops-platform/golden-dataset-strategy","evals/regression-tests","evals/task-specific-acceptance-criteria","evals/offline-vs-online-evaluation"],"tldr":"An evaluation gate is an automated policy that decides, from eval results rather than a green unit\nsuite, whether a candidate bundle (code, prompt, model, parameters, index) may move to the next stage. It\ncombines absolute floors (safety, schema validity, regression items), a paired non-inferiority test\nagainst the champion with a confidence interval, per-slice floors and cost/latency budgets, and returns\npass, block or needs-review with every override recorded. It exists because sampled outputs make\nexact-match tests flake and one aggregate hides the slice that broke.","status":"ok"},{"id":"canary-shadow-deployments","key":"llmops-platform/canary-shadow-deployments","module":"llmops-platform","name":"Canary / shadow deployments","taxonomy_name":"canary / shadow deployments","kind":"pattern","difficulty":"core","est_minutes":15,"related":["llmops-platform/rollback","llmops-platform/evaluation-gates-for-production-releases","llmops-platform/ci-cd-for-prompts-and-models","evals/a-b-testing","evals/offline-vs-online-evaluation","customer-data-evaluation/shadow-mode-validation","deployment/rollout-criteria-and-rollback-triggers","system-design/ai-gateway"],"tldr":"Offline evals tell you a new model, prompt or agent version is *probably* better on a few hundred\ncurated cases; they cannot tell you what it does on live traffic. A **shadow** deployment runs the\ncandidate on a copy of real requests without serving its answers, so you can compare it to the\nincumbent at zero user risk. A **canary** serves the candidate to a small, sticky slice of users and\nramps up only while guard metrics hold. Together they turn \"ship and hope\" into a measured exposure.","status":"ok"},{"id":"rollback","key":"llmops-platform/rollback","module":"llmops-platform","name":"Rollback","taxonomy_name":"rollback","kind":"practice","difficulty":"core","est_minutes":13,"related":["llmops-platform/canary-shadow-deployments","llmops-platform/model-registry","llmops-platform/prompt-registry","llmops-platform/model-lifecycle-and-deprecation-policy","deployment/rollout-criteria-and-rollback-triggers","data-architecture/embedding-versioning-re-indexing-strategy","deployment/runbooks","security-governance-compliance/ai-incident-response"],"tldr":"Rollback is returning production to a previously validated version of the whole AI bundle (model,\nprompt, parameters, tools, index, guardrails) in minutes, by repointing an alias rather than rebuilding\nanything. It matters more for AI systems than for ordinary services because \"fix forward\" means\nshipping a new, untested prompt under incident pressure, and because several components (re-embedded\nindexes, replaced fine-tunes, retired vendor models) are only reversible if you planned for it.","status":"ok"},{"id":"model-monitoring","key":"llmops-platform/model-monitoring","module":"llmops-platform","name":"Model monitoring","taxonomy_name":"model monitoring","kind":"practice","difficulty":"core","est_minutes":14,"related":["llmops-platform/drift","llmops-platform/observability-stack","observability/monitoring","observability/token-cost-tracking","evals/llm-as-a-judge","evals/offline-vs-online-evaluation","customer-data-evaluation/production-feedback-classification","reliability/slas-slos"],"tldr":"A deployed model can be up, fast and returning 200s while giving steadily worse answers, because\ncorrectness is not a status code. Model monitoring layers three kinds of signal over live traffic:\noperational (latency, errors, tokens, cost), behavioural proxies computable on every request without\nlabels (refusals, schema failures, output length, tool-call mix), and quality signals that arrive late\nand sparse (judge scores on a sample, user feedback, business outcomes). Sliced by version and tenant,\nthey turn silent regressions into alerts with examples attached.","status":"ok"},{"id":"drift","key":"llmops-platform/drift","module":"llmops-platform","name":"Drift","taxonomy_name":"drift","kind":"concept","difficulty":"core","est_minutes":15,"related":["llmops-platform/model-monitoring","llmops-platform/golden-dataset-strategy","llmops-platform/model-lifecycle-and-deprecation-policy","llmops-platform/rollback","data-architecture/embedding-versioning-re-indexing-strategy","evals/judge-calibration-and-bias","observability/monitoring","customer-data-evaluation/production-feedback-classification"],"tldr":"A system validated on one distribution is deployed into a world that keeps moving. Drift is any change\nbetween the conditions you validated under and the ones you now serve: inputs change (data drift), the\nright answer for an input changes (concept drift), or, specific to LLM applications, the model, prompt,\ncorpus, embedder or judge changes underneath an unchanged system. Detection compares traffic windows\nagainst a reference; the decision is always whether the shift changed outcomes, and what to re-validate.","status":"ok"},{"id":"model-lifecycle-and-deprecation-policy","key":"llmops-platform/model-lifecycle-and-deprecation-policy","module":"llmops-platform","name":"Model lifecycle & deprecation policy","taxonomy_name":"model lifecycle & deprecation policy","kind":"practice","difficulty":"core","est_minutes":14,"related":["llmops-platform/model-registry","llmops-platform/ci-cd-for-prompts-and-models","llmops-platform/rollback","llmops-platform/evaluation-gates-for-production-releases","security-governance-compliance/model-governance","security-governance-compliance/vendor-exit-strategy","backend-fundamentals/api-versioning-and-backward-compatibility","data-architecture/data-retention-and-deletion-architecture"],"tldr":"A model version is registered, validated, promoted, superseded and eventually switched off, and each\nstep changes what callers may rely on. A lifecycle policy names the states, who may move a version\nbetween them and what evidence each move needs. A deprecation policy is the exit half: how far ahead\na retirement is announced, when new pins are frozen, how consumers are found and migrated with\nevaluation, and what is archived afterwards. Without it, every provider sunset becomes an unplanned\nmigration on someone else's calendar.","status":"ok"},{"id":"observability-stack","key":"llmops-platform/observability-stack","module":"llmops-platform","name":"Observability stack","taxonomy_name":"observability stack","kind":"pattern","difficulty":"core","est_minutes":14,"related":["observability/tracing","observability/opentelemetry","observability/distributed-tracing-across-services","observability/token-cost-tracking","observability/langfuse","observability/langsmith","observability/arize-phoenix","llmops-platform/model-monitoring"],"tldr":"An observability stack is the pipeline that turns every AI request into something you can query\nlater: instrumentation that emits traces carrying LLM-specific attributes, a collector that redacts\nand samples, separate stores for traces, metrics and payloads, an analysis layer where scores and\nevaluations attach to traces, and alerting on top. It is a stack because each layer has a different\nowner, retention rule and cost. The deep topics live in the Observability module; this lesson is how\nthey fit together as a platform.","status":"ok"},{"id":"ai-control-plane-vs-data-plane","key":"llmops-platform/ai-control-plane-vs-data-plane","module":"llmops-platform","name":"AI control plane vs data plane","taxonomy_name":"AI control plane vs data plane","kind":"concept","difficulty":"core","est_minutes":14,"related":["system-design/ai-gateway","llmops-platform/model-registry","llmops-platform/prompt-registry","llmops-platform/canary-shadow-deployments","llmops-platform/rollback","llmops-platform/centralized-vs-federated-ai-platform","agent-runtime-architecture/policy-enforcement-across-agents-and-tools","reliability/tenant-level-quotas-and-noisy-neighbor-isolation"],"tldr":"Split an AI platform into a data plane, the per-request path (gateway, routing, model call,\nretrieval, guardrails, caching) that must be fast and stay up, and a control plane, the low-volume\nsystem of record for what the data plane should do (registries, aliases, rollout percentages,\npolicies, budgets, keys, audit). The data plane reads versioned config snapshots and keeps serving\nthe last one if the control plane is down; the control plane changes behaviour by publishing a new\nsnapshot, never by redeploying the data plane.","status":"ok"},{"id":"centralized-vs-federated-ai-platform","key":"llmops-platform/centralized-vs-federated-ai-platform","module":"llmops-platform","name":"Centralized vs federated AI platform","taxonomy_name":"centralized vs federated AI platform","kind":"decision","difficulty":"core","est_minutes":14,"related":["strategy/platform-strategy","llmops-platform/ai-control-plane-vs-data-plane","system-design/ai-gateway","security-governance-compliance/model-governance","security-governance-compliance/ai-inventory-and-use-case-risk-classification","infra-capacity-economics/cost-allocation-by-tenant-and-feature","infra-capacity-economics/shared-vs-isolated-model-serving-infrastructure","adoption/change-management"],"tldr":"Centralized: one platform team owns model access, registries, evaluation infrastructure,\nobservability and governance, and product teams consume them. Federated: each team runs its own AI\nstack under shared standards. Pure centralization becomes a ticket queue; pure federation becomes\nseven gateways, no inventory and duplicated spend. For most organisations the answer is a thin\nmandatory core (identity, model access, budgets, audit, telemetry) with federated ownership of\nprompts, evals, corpora and agents, with the line moved as team count and regulatory load grow.","status":"ok"}]},{"id":"security-governance-compliance","tier":2,"order":22,"title":"Security, governance & compliance","intro":null,"topics":[{"id":"ai-security","key":"security-governance-compliance/ai-security","module":"security-governance-compliance","name":"AI security","taxonomy_name":"AI security","kind":"concept","difficulty":"intro","est_minutes":13,"related":["security-governance-compliance/threat-modeling","security-governance-compliance/prompt-injection-defense","security-governance-compliance/zero-trust","safety-security/owasp-top-10-for-llms","safety-security/prompt-injection","safety-security/excessive-agency","safety-security/supply-chain-security-for-models-and-datasets","agent-reliability/tool-permissions-and-least-privilege"],"tldr":"AI security is ordinary application security plus one new component: a model that follows instructions\nfound in its data, cannot be patched the way a parser can, and is increasingly handed credentials and\ntools. The attack surface therefore moves from syntax (SQL, HTML) to semantics (any text the model\nreads), and from the model to everything around it. The controls that hold are the old ones applied to\nthe model as an untrusted interpreter: least privilege, isolation, output handling, approval gates and\nmonitoring, not cleverer prompts.","status":"ok"},{"id":"threat-modeling","key":"security-governance-compliance/threat-modeling","module":"security-governance-compliance","name":"Threat modeling","taxonomy_name":"threat modeling","kind":"practice","difficulty":"core","est_minutes":16,"related":["security-governance-compliance/ai-security","security-governance-compliance/zero-trust","security-governance-compliance/ai-risk-management","safety-security/owasp-top-10-for-llms","safety-security/excessive-agency","safety-security/tool-privilege-escalation","system-design/c4-diagrams","evals/red-teaming"],"tldr":"Threat modeling is a structured answer to four questions: what are we building, what can go wrong, what\nwill we do about it, and did we do a good job. It exists because controls chosen without a model are\nchosen at random. For AI systems the diagram must mark every flow of untrusted text into a model's\ncontext and every flow of model output into an action, because those are the trust boundaries a\nclassical review never draws.","status":"ok"},{"id":"prompt-injection-defense","key":"security-governance-compliance/prompt-injection-defense","name":"prompt injection defense","module":"security-governance-compliance","status":"missing"},{"id":"pii-protection-dlp","key":"security-governance-compliance/pii-protection-dlp","name":"PII protection / DLP","module":"security-governance-compliance","status":"missing"},{"id":"data-classification","key":"security-governance-compliance/data-classification","name":"data classification","module":"security-governance-compliance","status":"missing"},{"id":"zero-trust","key":"security-governance-compliance/zero-trust","name":"zero trust","module":"security-governance-compliance","status":"missing"},{"id":"data-residency","key":"security-governance-compliance/data-residency","name":"data residency","module":"security-governance-compliance","status":"missing"},{"id":"model-governance","key":"security-governance-compliance/model-governance","name":"model governance","module":"security-governance-compliance","status":"missing"},{"id":"model-cards","key":"security-governance-compliance/model-cards","name":"model cards","module":"security-governance-compliance","status":"missing"},{"id":"audit-trails","key":"security-governance-compliance/audit-trails","name":"audit trails","module":"security-governance-compliance","status":"missing"},{"id":"ai-inventory-and-use-case-risk-classification","key":"security-governance-compliance/ai-inventory-and-use-case-risk-classification","name":"AI inventory & use-case risk classification","module":"security-governance-compliance","status":"missing"},{"id":"responsible-ai","key":"security-governance-compliance/responsible-ai","name":"responsible AI","module":"security-governance-compliance","status":"missing"},{"id":"ai-risk-management","key":"security-governance-compliance/ai-risk-management","name":"AI risk management","module":"security-governance-compliance","status":"missing"},{"id":"ai-incident-response","key":"security-governance-compliance/ai-incident-response","name":"AI incident response","module":"security-governance-compliance","status":"missing"},{"id":"vendor-exit-strategy","key":"security-governance-compliance/vendor-exit-strategy","name":"vendor exit strategy","module":"security-governance-compliance","status":"missing"},{"id":"compliance-architecture","key":"security-governance-compliance/compliance-architecture","name":"compliance architecture (GDPR, SOC 2, HIPAA, ISO 42001, EU AI Act, DPDP Act)","module":"security-governance-compliance","status":"missing"}]},{"id":"strategy","tier":2,"order":23,"title":"Strategy","intro":null,"topics":[{"id":"ai-roadmap","key":"strategy/ai-roadmap","name":"AI roadmap","module":"strategy","status":"missing"},{"id":"platform-strategy","key":"strategy/platform-strategy","name":"platform strategy","module":"strategy","status":"missing"},{"id":"vendor-evaluation","key":"strategy/vendor-evaluation","name":"vendor evaluation","module":"strategy","status":"missing"},{"id":"technical-due-diligence","key":"strategy/technical-due-diligence","name":"technical due diligence","module":"strategy","status":"missing"},{"id":"stakeholder-alignment","key":"strategy/stakeholder-alignment","name":"stakeholder alignment","module":"strategy","status":"missing"}]},{"id":"scoping","tier":3,"order":24,"title":"Scoping","intro":null,"topics":[{"id":"customer-discovery","key":"scoping/customer-discovery","name":"customer discovery","module":"scoping","status":"missing"},{"id":"ai-use-case-discovery","key":"scoping/ai-use-case-discovery","name":"AI use-case discovery","module":"scoping","status":"missing"},{"id":"problem-decomposition","key":"scoping/problem-decomposition","name":"problem decomposition","module":"scoping","status":"missing"},{"id":"workflow-analysis","key":"scoping/workflow-analysis","name":"workflow analysis","module":"scoping","status":"missing"},{"id":"domain-modeling","key":"scoping/domain-modeling","name":"domain modeling","module":"scoping","status":"missing"},{"id":"data-access-and-permissions-discovery","key":"scoping/data-access-and-permissions-discovery","name":"data access & permissions discovery","module":"scoping","status":"missing"},{"id":"success-metrics-kpis","key":"scoping/success-metrics-kpis","name":"success metrics / KPIs","module":"scoping","status":"missing"},{"id":"baseline-measurement-before-deployment","key":"scoping/baseline-measurement-before-deployment","name":"baseline measurement before deployment","module":"scoping","status":"missing"},{"id":"roi-model","key":"scoping/roi-model","name":"ROI model","module":"scoping","status":"missing"},{"id":"statement-of-work","key":"scoping/statement-of-work","name":"statement of work","module":"scoping","status":"missing"},{"id":"requirements-traceability","key":"scoping/requirements-traceability","name":"requirements traceability","module":"scoping","status":"missing"},{"id":"dependency-and-risk-management","key":"scoping/dependency-and-risk-management","name":"dependency & risk management","module":"scoping","status":"missing"},{"id":"timeboxing","key":"scoping/timeboxing","name":"timeboxing","module":"scoping","status":"missing"},{"id":"demos","key":"scoping/demos","name":"demos","module":"scoping","status":"missing"},{"id":"rapid-prototyping-poc","key":"scoping/rapid-prototyping-poc","name":"rapid prototyping / PoC","module":"scoping","status":"missing"},{"id":"pilot-to-production-plan","key":"scoping/pilot-to-production-plan","name":"pilot → production plan","module":"scoping","status":"missing"},{"id":"productionization","key":"scoping/productionization","name":"productionization","module":"scoping","status":"missing"}]},{"id":"enterprise-integration","tier":3,"order":25,"title":"Enterprise integration","intro":null,"topics":[{"id":"enterprise-connectors","key":"enterprise-integration/enterprise-connectors","name":"enterprise connectors (Salesforce, SAP, ServiceNow, SharePoint, Confluence, Jira, Slack, Teams)","module":"enterprise-integration","status":"missing"},{"id":"legacy-system-integration","key":"enterprise-integration/legacy-system-integration","name":"legacy system integration","module":"enterprise-integration","status":"missing"},{"id":"sso-iam-integration","key":"enterprise-integration/sso-iam-integration","name":"SSO / IAM integration (Okta, Entra ID)","module":"enterprise-integration","status":"missing"},{"id":"saml-sso","key":"enterprise-integration/saml-sso","name":"SAML SSO","module":"enterprise-integration","status":"missing"},{"id":"scim-provisioning","key":"enterprise-integration/scim-provisioning","name":"SCIM provisioning","module":"enterprise-integration","status":"missing"},{"id":"rbac-abac-mapping-to-customer-identity","key":"enterprise-integration/rbac-abac-mapping-to-customer-identity","name":"RBAC / ABAC mapping to customer identity","module":"enterprise-integration","status":"missing"},{"id":"webhooks","key":"enterprise-integration/webhooks","name":"webhooks","module":"enterprise-integration","status":"missing"},{"id":"incremental-synchronization-and-cdc","key":"enterprise-integration/incremental-synchronization-and-cdc","name":"incremental synchronization & CDC","module":"enterprise-integration","status":"missing"},{"id":"retry-deduplication-reconciliation","key":"enterprise-integration/retry-deduplication-reconciliation","module":"enterprise-integration","name":"Retry / deduplication / reconciliation","taxonomy_name":"retry / deduplication / reconciliation","kind":"pattern","difficulty":"core","est_minutes":15,"related":["enterprise-integration/webhooks","enterprise-integration/incremental-synchronization-and-cdc","serving-inference/retry-strategies","serving-inference/idempotency","system-design/outbox-inbox-patterns","system-design/exactly-once-processing-limitations","agent-reliability/idempotent-tool-execution","backend-fundamentals/message-queues"],"tldr":"An integration with a customer's systems crosses a boundary you do not control: calls fail, writes\nsucceed without telling you, and events never arrive. **Retry** handles the first, **deduplication**\nmakes retries safe against the second, and **reconciliation**, the scheduled comparison of source and\ntarget, catches the third. Each covers a failure the other two cannot see, which is why mature\nintegrations run all three and treat the reconciliation job's repair count as the health metric of the\nwhole pipeline.","status":"ok"},{"id":"sandbox-vs-production-environments","key":"enterprise-integration/sandbox-vs-production-environments","module":"enterprise-integration","name":"Sandbox vs production environments","taxonomy_name":"sandbox vs production environments","kind":"practice","difficulty":"core","est_minutes":13,"related":["enterprise-integration/enterprise-connectors","enterprise-integration/tenant-specific-configuration-and-feature-flags","enterprise-integration/data-onboarding","llmops-platform/canary-shadow-deployments","customer-data-evaluation/shadow-mode-validation","deployment/uat","deployment/rollout-criteria-and-rollback-triggers","backend-fundamentals/secrets-management"],"tldr":"Customer systems come in pairs: a production instance with real data and real side effects, and\nsandboxes (Salesforce sandboxes, SAP development and quality systems, ServiceNow sub-production\ninstances) that resemble it but differ in data, configuration, integrations and limits. An AI\nintegration is built and verified against the sandbox, promoted to production deliberately, and\nprevented by hard guards from mixing the two, because a system that reads stale sandbox data behaves\ndifferently from one reading production, and one that writes to production by mistake is an incident.","status":"ok"},{"id":"tenant-specific-configuration-and-feature-flags","key":"enterprise-integration/tenant-specific-configuration-and-feature-flags","name":"tenant-specific configuration & feature flags","module":"enterprise-integration","status":"missing"},{"id":"data-onboarding","key":"enterprise-integration/data-onboarding","name":"data onboarding","module":"enterprise-integration","status":"missing"},{"id":"data-ingestion-from-client-systems","key":"enterprise-integration/data-ingestion-from-client-systems","name":"data ingestion from client systems","module":"enterprise-integration","status":"missing"},{"id":"data-mapping-and-canonical-schemas","key":"enterprise-integration/data-mapping-and-canonical-schemas","name":"data mapping & canonical schemas (schema mapping)","module":"enterprise-integration","status":"missing"},{"id":"data-profiling-and-quality-assessment","key":"enterprise-integration/data-profiling-and-quality-assessment","name":"data profiling & quality assessment","module":"enterprise-integration","status":"missing"},{"id":"client-document-parsing","key":"enterprise-integration/client-document-parsing","name":"client document parsing (PDF, scans, OCR)","module":"enterprise-integration","status":"missing"}]},{"id":"customer-data-evaluation","tier":3,"order":26,"title":"Customer data & evaluation","intro":null,"topics":[{"id":"domain-prompt-engineering","key":"customer-data-evaluation/domain-prompt-engineering","name":"domain prompt engineering","module":"customer-data-evaluation","status":"missing"},{"id":"golden-dataset-creation-with-client-smes","key":"customer-data-evaluation/golden-dataset-creation-with-client-smes","name":"golden dataset creation with client SMEs","module":"customer-data-evaluation","status":"missing"},{"id":"representative-test-case-sampling","key":"customer-data-evaluation/representative-test-case-sampling","name":"representative test-case sampling","module":"customer-data-evaluation","status":"missing"},{"id":"sme-review-and-annotation-guidelines","key":"customer-data-evaluation/sme-review-and-annotation-guidelines","name":"SME review & annotation guidelines","module":"customer-data-evaluation","status":"missing"},{"id":"labeling-sessions","key":"customer-data-evaluation/labeling-sessions","name":"labeling sessions","module":"customer-data-evaluation","status":"missing"},{"id":"eval-review-loops","key":"customer-data-evaluation/eval-review-loops","name":"eval review loops","module":"customer-data-evaluation","status":"missing"},{"id":"acceptance-testing-against-customer-kpis","key":"customer-data-evaluation/acceptance-testing-against-customer-kpis","name":"acceptance testing against customer KPIs","module":"customer-data-evaluation","status":"missing"},{"id":"customer-specific-regression-suites","key":"customer-data-evaluation/customer-specific-regression-suites","name":"customer-specific regression suites","module":"customer-data-evaluation","status":"missing"},{"id":"shadow-mode-validation","key":"customer-data-evaluation/shadow-mode-validation","name":"shadow-mode validation","module":"customer-data-evaluation","status":"missing"},{"id":"per-customer-guardrails","key":"customer-data-evaluation/per-customer-guardrails","name":"per-customer guardrails","module":"customer-data-evaluation","status":"missing"},{"id":"fine-tuning-pipelines-on-client-data","key":"customer-data-evaluation/fine-tuning-pipelines-on-client-data","name":"fine-tuning pipelines on client data","module":"customer-data-evaluation","status":"missing"},{"id":"model-integration","key":"customer-data-evaluation/model-integration","name":"model integration","module":"customer-data-evaluation","status":"missing"},{"id":"production-feedback-classification","key":"customer-data-evaluation/production-feedback-classification","name":"production feedback classification","module":"customer-data-evaluation","status":"missing"},{"id":"feedback-loops-to-product","key":"customer-data-evaluation/feedback-loops-to-product","name":"feedback loops to product","module":"customer-data-evaluation","status":"missing"}]},{"id":"deployment","tier":3,"order":27,"title":"Deployment","intro":null,"topics":[{"id":"customer-vpc-on-prem-air-gapped","key":"deployment/customer-vpc-on-prem-air-gapped","module":"deployment","name":"Customer VPC / on-prem / air-gapped deployment","taxonomy_name":"customer VPC / on-prem / air-gapped","kind":"pattern","difficulty":"core","est_minutes":18,"related":["deployment/private-endpoints","deployment/vpn","deployment/terraform","deployment/compliance-constraints","infra-capacity-economics/hybrid-on-prem","infra-capacity-economics/cloud-ai-architecture","llmops-platform/ai-control-plane-vs-data-plane","safety-security/supply-chain-security-for-models-and-datasets"],"tldr":"Three deployment targets where the customer, not you, owns the perimeter: in a **customer VPC** your\nsoftware runs inside their cloud account; **on-prem** it runs on their hardware and their Kubernetes;\n**air-gapped** it runs with no network path to the outside at all. They exist because some data may\nnot leave the customer's custody. Each step inward trades your operability (telemetry, upgrades,\nhosted frontier models) for their control, so the engineering job becomes making the product\ninstallable, verifiable and upgradable without the network you are used to.","status":"ok"},{"id":"private-endpoints","key":"deployment/private-endpoints","name":"private endpoints","module":"deployment","status":"missing"},{"id":"vpn","key":"deployment/vpn","name":"VPN","module":"deployment","status":"missing"},{"id":"terraform","key":"deployment/terraform","name":"Terraform (IaC)","module":"deployment","status":"missing"},{"id":"security-questionnaires","key":"deployment/security-questionnaires","name":"security questionnaires","module":"deployment","status":"missing"},{"id":"security-and-architecture-reviews","key":"deployment/security-and-architecture-reviews","name":"security & architecture reviews","module":"deployment","status":"missing"},{"id":"compliance-constraints","key":"deployment/compliance-constraints","name":"compliance constraints","module":"deployment","status":"missing"},{"id":"deployment-readiness-reviews","key":"deployment/deployment-readiness-reviews","name":"deployment readiness reviews","module":"deployment","status":"missing"},{"id":"uat","key":"deployment/uat","name":"UAT","module":"deployment","status":"missing"},{"id":"rollout-criteria-and-rollback-triggers","key":"deployment/rollout-criteria-and-rollback-triggers","name":"rollout criteria & rollback triggers","module":"deployment","status":"missing"},{"id":"runbooks","key":"deployment/runbooks","name":"runbooks","module":"deployment","status":"missing"},{"id":"health-checks","key":"deployment/health-checks","name":"health checks","module":"deployment","status":"missing"},{"id":"hypercare","key":"deployment/hypercare","name":"hypercare","module":"deployment","status":"missing"}]},{"id":"delivery-ownership","tier":3,"order":28,"title":"Delivery & ownership","intro":null,"topics":[{"id":"production-debugging","key":"delivery-ownership/production-debugging","name":"production debugging","module":"delivery-ownership","status":"missing"},{"id":"failure-analysis","key":"delivery-ownership/failure-analysis","name":"failure analysis","module":"delivery-ownership","status":"missing"},{"id":"incident-severity-and-escalation","key":"delivery-ownership/incident-severity-and-escalation","name":"incident severity & escalation","module":"delivery-ownership","status":"missing"},{"id":"root-cause-analysis-and-postmortems","key":"delivery-ownership/root-cause-analysis-and-postmortems","name":"root-cause analysis & postmortems","module":"delivery-ownership","status":"missing"},{"id":"operational-ownership-and-support-boundaries","key":"delivery-ownership/operational-ownership-and-support-boundaries","name":"operational ownership & support boundaries","module":"delivery-ownership","status":"missing"},{"id":"slas","key":"delivery-ownership/slas","name":"SLAs","module":"delivery-ownership","status":"missing"},{"id":"system-reliability","key":"delivery-ownership/system-reliability","name":"system reliability","module":"delivery-ownership","status":"missing"},{"id":"technical-documentation","key":"delivery-ownership/technical-documentation","name":"technical documentation","module":"delivery-ownership","status":"missing"},{"id":"productizing-repeated-customer-solutions","key":"delivery-ownership/productizing-repeated-customer-solutions","name":"productizing repeated customer solutions","module":"delivery-ownership","status":"missing"}]},{"id":"adoption","tier":3,"order":29,"title":"Adoption","intro":null,"topics":[{"id":"change-management","key":"adoption/change-management","name":"change management","module":"adoption","status":"missing"},{"id":"user-training","key":"adoption/user-training","name":"user training","module":"adoption","status":"missing"},{"id":"workshops","key":"adoption/workshops","name":"workshops","module":"adoption","status":"missing"},{"id":"stakeholder-management","key":"adoption/stakeholder-management","name":"stakeholder management","module":"adoption","status":"missing"},{"id":"exec-communication","key":"adoption/exec-communication","name":"exec communication","module":"adoption","status":"missing"},{"id":"usage-analytics","key":"adoption/usage-analytics","name":"usage analytics","module":"adoption","status":"missing"},{"id":"adoption-and-value-realization-measurement","key":"adoption/adoption-and-value-realization-measurement","name":"adoption & value-realization measurement","module":"adoption","status":"missing"},{"id":"continuous-improvement","key":"adoption/continuous-improvement","name":"continuous improvement","module":"adoption","status":"missing"},{"id":"handoff-to-customer-teams","key":"adoption/handoff-to-customer-teams","name":"handoff to customer teams","module":"adoption","status":"missing"},{"id":"feature-request-triage","key":"adoption/feature-request-triage","name":"feature-request triage","module":"adoption","status":"missing"}]}]};
